    enforce_expected_treated_gate = TRUE,
    expected_complete_cesd_n = 14660L,
    expected_final_n = 13500L,
    expected_exposure_cutpoint = 22,
    expected_treated_n = 1342L,
    expected_cluster_n = 132L,
    expected_strata_n = 4L,
