# Explicit rules precede heuristic inference. Storing the complete map in cfg
# makes the existing Wave-I/main/fold cache fingerprints detect every edit.
cfg$preprocessing$codebook_missing_overrides <- local({
  rules <- list()
  add <- function(vars, general = numeric(0), skip = numeric(0),
                  as_factor = NULL, source) {
    for (v in vars) {
      if (!is.null(rules[[v]])) stop("Duplicate codebook rule: ", v)
      rules[[v]] <<- list(general = general, skip = skip,
                          as_factor = as_factor, source = source)
    }
  }
  
  # Official County Health codebook, pp. 2-7.
  # https://addhealth.cpc.unc.edu/wp-content/uploads/docs/data/codebooks/Wave-I-Health-Codebook.pdf
  health <- "Wave-I-Health-Codebook.pdf, pp. 2-7"
  add(c("C1LE001", "C1LE004", "C1LE005", "C1LE006"),
      general = 98, as_factor = FALSE, source = health)
  add(c("C1LE002", "C1LE003", "S1CT001",
        as.vector(outer(sprintf("C1DI%03d", 1:5), c("T", "M", "F"), paste0)),
        as.vector(outer(c("C1DR001", "C1DR003", "C1SM001", "C1SM002"),
                        c("T", "M", "F"), paste0)),
        as.vector(outer(c("C1OP001", "C1OP002"), c("M", "F"), paste0)),
        "C1EC003T"), general = 8, as_factor = FALSE, source = health)
  add(c("C1EC001", "C1EC003M", "C1EC003F", "C1EC004"),
      general = c(2, 8), as_factor = FALSE, source = health)
  add("C1EC002", general = c(92, 98), as_factor = FALSE, source = health)
  
  # Official state-characteristics codebook, pp. 3-11; exact widths differ.
  # https://addhealth.cpc.unc.edu/wp-content/uploads/docs/data/codebooks/Wave-I-State-Characteristics-Exclusionary-Indices-and-Inclusionary-Indices-Codebook.pdf
  state <- "State-Characteristics-Codebook.pdf, pp. 3-11"
  add(sprintf("STC95%02d", c(1:5, 20, 21)),
      general = 8, as_factor = FALSE, source = state)
  add(sprintf("STC95%02d", c(8, 11:17, 19, 22, 23)),
      general = 98, as_factor = FALSE, source = state)
  add(sprintf("STC95%02d", c(6, 7, 10, 24)),
      general = 999998, as_factor = FALSE, source = state)
  add("STC9509", general = 99998, as_factor = FALSE, source = state)
  
  # Official political-context codebook, Appendix B, pp. 12-26.
  # https://addhealth.cpc.unc.edu/wp-content/uploads/docs/data/codebooks/W1POLCON.pdf
  political <- "W1POLCON.pdf, Appendix B"
  add("W1PCA195", general = 8, as_factor = TRUE, source = political)
  add("W1PCA295", general = 98, as_factor = FALSE, source = political)
  add("W1PCC290", general = 98, as_factor = TRUE, source = political)
  add(c("W1PCC190", "W1PCG195", "W1PCG295", "W1PCG395",
        "W1PCP192", "W1PCP292", "W1PCP392"),
      general = 8, as_factor = FALSE, source = political)
  add(c("W1PCS192", "W1PCS292", "W1PCS392",
        "W1PCS194", "W1PCS294", "W1PCS394"),
      general = 8, skip = 7, as_factor = FALSE, source = political)
  
  # Use the detailed birth codebook's RPDA003-RPDA007 names, not the
  # differently numbered user-guide summary. All 14 fields are categorical.
  # https://addhealth.cpc.unc.edu/wp-content/uploads/docs/data/codebooks/Birth_Records_Database_Codebook.pdf
  birth <- "Birth_Records_Database_Codebook.pdf, pp. 2-9"
  add(c("RIWA001", "RIDA002", "RPDA004", "RPDA005"),
      general = 98, as_factor = TRUE, source = birth)
  add("RIWA002", general = c(995, 996, 998), as_factor = TRUE, source = birth)
  add("RIWA003", general = c(996, 998), as_factor = TRUE, source = birth)
  add(c("RIWA004", "RIDA001", "RPDA001", "RPDA002", "RPDA003",
        "RPDA006", "RPDA007", "RMMA001"),
      general = c(96, 98), as_factor = TRUE, source = birth)
  
  # In-home sections 1, 3, 11-13, 28, 32B, 38 and 40.
  # These documented codes must not be suppressed by the percentage heuristic.
  # https://addhealth.cpc.unc.edu/wp-content/uploads/docs/data/codebooks/Wave-I-In-Home-Interview-Data.zip
  inhome <- "Wave-I-In-Home-Interview-Data.zip; variable-specific codebooks"
  add(c("H1GI3", "H1GH51", "H1TO10", "H1IR16"),
      general = c(96, 98, 99), source = inhome)
  add(c("H1TO5", "H1FP5D", "H1NF8", "H1NF9", paste0("H1HR10", LETTERS[1:20])),
      general = c(96, 98, 99), skip = 97, source = inhome)
  add(c("H1TO11", "H1TO14", "H1NM3", "H1NM8"),
      general = c(96, 98), skip = 97, source = inhome)
  add("H1NF3", general = 98, skip = 97, source = inhome)
  add("H1NM9", general = c(98, 99), skip = 97, source = inhome)
  
  # Introductory Guide documents genuine value/reserve-code collisions.
  # Preserve those ambiguous values, but restore separately identifiable skips.
  add(c("H1TO7", "H1TO16"), skip = 97, source = inhome)
  add(c("H1EE5", "H1EE7"), skip = 997, source = inhome)
  add(paste0("H1IR8", LETTERS[1:4]), skip = 7, source = inhome)
  add("H1IR13", general = 99, skip = 97, source = inhome)
  rules
})

# =============================================================================
# 1) PACKAGE LOADING AND CONFIG VALIDATION
# =============================================================================
# Plain-English role: Make sure the packages needed for the enabled stages
# are installed, then attach them. Validate the cfg object so that impossible
# settings (e.g., no learners enabled, or no screening reaches the final
# estimator) stop the pipeline loudly before any expensive work begins.

`%||%` <- function(x, y) if (is.null(x)) y else x

count_enabled_learners <- function(lib_cfg) {
  toggles <- c("use_mean","use_glm","use_glmnet","use_glmnet_h1fs",
               "use_glmnet_A_unpenalized","use_ranger",
               "use_glmnet_control_arm","use_ranger_control_arm",
               "use_xgboost_control_arm",
               "use_xgboost","use_xgboost_rich","use_earth","use_gam",
               "use_svm","use_nnet")
  sum(vapply(intersect(toggles, names(lib_cfg)),
             function(nm) isTRUE(lib_cfg[[nm]]), logical(1)))
}

validate_runtime_environment <- function(cfg, required_packages) {
  rt <- cfg$runtime %||% list()
  if (isTRUE(rt$enforce_exact_R_version %||% FALSE)) {
    found_R <- paste(R.version$major, R.version$minor, sep = ".")
    expected_R <- as.character(rt$required_R_version %||% "")
    if (!nzchar(expected_R) || !identical(found_R, expected_R))
      stop(sprintf("Production R version mismatch: required %s, found %s.",
                   expected_R, found_R), call. = FALSE)
  }
  if (isTRUE(rt$enforce_exact_package_versions %||% FALSE)) {
    expected <- rt$required_package_versions %||% character(0)
    if (is.null(names(expected)) || any(!nzchar(names(expected))))
      stop("runtime$required_package_versions must be a named character vector.",
           call. = FALSE)
    check <- intersect(required_packages, names(expected))
    missing_expectations <- setdiff(required_packages, names(expected))
    if (length(missing_expectations))
      stop("No frozen production version was configured for required package(s): ",
           paste(missing_expectations, collapse = ", "), call. = FALSE)
    found <- vapply(check, function(pkg)
      as.character(utils::packageVersion(pkg)), character(1))
    bad <- check[found != unname(expected[check])]
    if (length(bad)) {
      detail <- paste(sprintf("%s required=%s found=%s", bad,
                              unname(expected[bad]), found[bad]), collapse = "; ")
      stop("Production package-version mismatch: ", detail, call. = FALSE)
    }
  }
  invisible(TRUE)
}

# Hard family/wave scope. This is deliberately separate from the configurable
# verification override: unsupported waves cannot be enabled by setting
# allow_unverified_outcome_specs=TRUE.
supported_outcome_waves <- function(family) {
  switch(as.character(family),
         EducationalAttainment = c(3L, 4L),
         HealthStatus = c(3L, 4L),
         Compensation = 4L,
         LaborForceParticipation = 4L,
         HoursWorked = 4L,
         PassThrough = 4L,
         UsualHours = integer(0),
         MentalHealth = integer(0),
         SubstanceUse = integer(0),
         integer(0))
}

# Production-verification gate for outcome constructors. This prevents a
# placeholder or illustrative constructor from producing plausible-looking
# results merely because it returns nonmissing values. The supported mappings
# below are exact, codebook-locked specifications. PassThrough is allowed only
# when its source is explicitly named because it performs no guessed recoding.
is_verified_outcome_spec <- function(cfg, family, wave) {
  wave <- as.integer(wave)
  fam_cfg <- cfg$outcome$families[[family]]
  if (is.null(fam_cfg)) return(FALSE)
  
  if (identical(family, "Compensation")) {
    src <- fam_cfg$sources[[as.character(wave)]]
    return(
      identical(wave, 4L) && is.list(src) &&
        identical(as.character(src$exact_var), "H4EC2") &&
        identical(as.character(src$bracket_var), "H4EC3") &&
        isTRUE(all.equal(as.numeric(fam_cfg$exact_valid_min), 0)) &&
        isTRUE(all.equal(as.numeric(fam_cfg$exact_valid_max), 999995)) &&
        setequal(as.numeric(fam_cfg$exact_missing_codes), c(9999996, 9999998)) &&
        setequal(as.numeric(fam_cfg$bracket_valid_codes), 1:12) &&
        setequal(as.numeric(fam_cfg$bracket_missing_codes), c(96, 97, 98)) &&
        isTRUE(all.equal(
          as.numeric(fam_cfg$bracket_map[as.character(1:12)]),
          c(2500, 7500, 12500, 17500, 22500, 27500,
            35000, 45000, 62500, 87500, 125000, 175000)))
    )
  }
  
  if (identical(family, "EducationalAttainment")) {
    src <- fam_cfg$sources[[as.character(wave)]]
    expected_members <- c("at_least_hs", "at_least_some_college",
                          "at_least_college_grad")
    members_ok <- identical(names(fam_cfg$members), expected_members) &&
      all(vapply(fam_cfg$members, function(z) isTRUE(z$primary), logical(1)))
    if (!members_ok) return(FALSE)
    if (identical(wave, 3L)) {
      return(is.character(src) &&
               identical(unname(src["highest_grade"]), "H3ED1") &&
               identical(unname(src["high_school_equivalency"]), "H3ED2") &&
               identical(unname(src["high_school_diploma"]), "H3ED3") &&
               identical(unname(src["college_graduate"]), "H3ED5") &&
               setequal(fam_cfg$drop_from_candidates_by_wave[["3"]],
                        c("H3ED1", "H3ED2", "H3ED3", "H3ED5")))
    }
    if (identical(wave, 4L)) {
      return(is.character(src) && length(src) == 1L &&
               identical(unname(src), "H4ED2") &&
               identical(unname(fam_cfg$drop_from_candidates_by_wave[["4"]]), "H4ED2"))
    }
    return(FALSE)
  }
  
  if (identical(family, "HealthStatus")) {
    src <- fam_cfg$sources[[as.character(wave)]]
    members_ok <- identical(names(fam_cfg$members), "at_least_good") &&
      isTRUE(fam_cfg$members$at_least_good$primary)
    return(members_ok && wave %in% c(3L, 4L) && is.character(src) &&
             length(src) == 1L && identical(unname(src), paste0("H", wave, "GH1")))
  }
  
  if (identical(family, "LaborForceParticipation")) {
    src <- fam_cfg$sources[[as.character(wave)]]
    if (identical(wave, 4L)) {
      return(is.character(src) &&
               identical(unname(src["first_job_current"]), "H4LM6") &&
               identical(unname(src["current_work"]), "H4LM11") &&
               identical(unname(src["current_status"]), "H4LM14"))
    }
    return(FALSE)
  }
  
  if (identical(family, "HoursWorked")) {
    src <- fam_cfg$sources[[as.character(wave)]]
    if (identical(wave, 4L)) {
      return(is.character(src) &&
               identical(unname(src["first_job_current"]), "H4LM6") &&
               identical(unname(src["current_work"]), "H4LM11") &&
               identical(unname(src["current_jobs"]), "H4LM12") &&
               identical(unname(src["total_hours"]), "H4LM13") &&
               identical(unname(src["primary_job_hours"]), "H4LM19") &&
               isTRUE(all.equal(as.numeric(fam_cfg$cap_hours), 120)))
    }
    return(FALSE)
  }
  
  if (identical(family, "PassThrough")) {
    src <- fam_cfg$source_var
    return(is.character(src) && length(src) == 1L && !is.na(src) && nzchar(src) &&
             (fam_cfg$type %||% "continuous") %in% c("continuous", "binary_single"))
  }
  
  FALSE
}

resolve_mortality_spec <- function(cfg, wave = NULL) {
  base <- cfg$mortality_sensitivity %||% list(enabled = FALSE)
  if (is.null(wave)) wave <- cfg$outcome$current_wave %||% NULL
  if (is.null(wave) || length(wave) != 1L || !is.finite(as.numeric(wave)))
    stop("resolve_mortality_spec requires one explicit outcome wave.", call. = FALSE)
  wave <- as.integer(wave)
  spec <- (base$wave_specs %||% list())[[as.character(wave)]]
  enabled_waves <- as.integer(base$enabled_waves %||% integer(0))
  enabled_here <- isTRUE(base$enabled %||% FALSE) && wave %in% enabled_waves
  common_names <- setdiff(names(base), c("wave_specs", "enabled_waves"))
  out <- base[common_names]
  if (!is.null(spec)) out <- utils::modifyList(out, spec)
  
  out$enabled <- enabled_here
  out$outcome_wave <- wave
  out
}

mortality_timing_rule_text <- function(mort) {
  mode <- as.character(mort$timing_mode %||% "fixed_window")
  if (identical(mode, "fixed_window")) {
    return(sprintf(
      "%s fixed year-window %d-%d inclusive",
      mort$source_var %||% "NDIDD19Y",
      as.integer(mort$death_year_start), as.integer(mort$death_year_end)))
  }
  if (identical(mode, "interview_month")) {
    return(sprintf(
      paste0("%s/%s month-timed before %s/%s for interviewed respondents; ",
             "no-interview deaths on or before the latest complete interview ",
             "month in the wave file are classified before the fieldwork endpoint"),
      mort$source_var %||% "NDIDD19Y",
      mort$source_month_var %||% "NDIDD19M",
      mort$interview_year_var %||% "interview_year",
      mort$interview_month_var %||% "interview_month"))
  }
  stop("Unknown mortality timing mode: ", mode, call. = FALSE)
}

mortality_enabled_for_wave <- function(cfg, wave = NULL) {
  if (is.null(wave)) wave <- cfg$outcome$current_wave %||% NULL
  if (is.null(wave) || length(wave) != 1L) return(FALSE)
  isTRUE(resolve_mortality_spec(cfg, wave)$enabled)
}

validate_cfg <- function(cfg) {
  rule <- cfg$final_tmle$g_lower_rule %||% "fixed"
  if (length(rule)!=1L || is.na(rule) || !rule %in% c("fixed","sample_size"))
    stop("g_lower_rule must be fixed or sample_size.")
  if (isTRUE(cfg$final_tmle$broad_Q_candidate)) {
    for (nm in c("broad_Q_max_raw","broad_Q_max_processed")) {
      z <- cfg$final_tmle[[nm]]
      if (length(z)!=1L || !is.numeric(z) || !is.finite(z) || z<1 || z!=as.integer(z))
        stop("Invalid broader-Q budget: ",nm)
    }
  }
  if (isTRUE(cfg$final_tmle$residual_Q_candidate)) {
    for (nm in c("residual_Q_pilot_max_raw","residual_Q_add_max_raw","residual_Q_max_processed")) {
      z <- cfg$final_tmle[[nm]]
      if (length(z)!=1L || !is.numeric(z) || !is.finite(z) || z<1 || z!=as.integer(z))
        stop("Invalid residual-Q budget: ",nm)
    }
    if (!isTRUE(cfg$learners$Q$use_glmnet)) stop("Residual-Q requires Q glmnet enabled.")
    if (is.null(cfg$final_tmle$prespecified_W) && !isTRUE(cfg$final_tmle$broad_Q_candidate))
      stop("The v8.42 residual-Q route requires broad_Q_candidate=TRUE.", call. = FALSE)
  }
  if (isTRUE(cfg$safety$require_publication_ready_marker) && !isTRUE(cfg$global$save_stage_csvs))
    stop("Production artifact validation requires global$save_stage_csvs=TRUE; the previous FALSE default omitted required outputs.", call. = FALSE)
  # ---- Diagnostic-driven toggles: validate before anything expensive --------
  pm <- cfg$analysis$protected_W_mode %||% "items"
  if (length(pm) != 1L || is.na(pm) || !pm %in% c("items", "summary", "both"))
    stop("cfg$analysis$protected_W_mode must be one of items, summary, both.",
         call. = FALSE)
  for (nm in c("calibrate_g", "calibrate_pi", "restrict_wave1_depressed",
               "adaptive_g_truncation", "adaptive_g_truncation_apply", "enable_dsp4_audit",
               "auto_military_prison_status")) {
    z <- cfg$analysis[[nm]] %||% FALSE
    if (!is.logical(z) || length(z) != 1L || is.na(z))
      stop("cfg$analysis$", nm, " must be a single TRUE or FALSE.", call. = FALSE)
  }
  for (target in c("g", "pi")) {
    method <- cfg$analysis[[paste0(target, "_calibration_method")]] %||% "platt"
    if (length(method) != 1L || is.na(method) || !method %in% c("select", "platt", "isotonic"))
      stop(target, "_calibration_method must be select, platt or isotonic.", call. = FALSE)
    cand <- cfg$analysis[[paste0(target, "_calibration_candidates")]] %||% c("identity", "platt")
    if (!is.character(cand) || !length(cand) || anyNA(cand) || anyDuplicated(cand) ||
        !all(cand %in% c("identity", "platt", "isotonic")))
      stop(target, "_calibration_candidates must be unique names from identity, platt, isotonic.",
           call. = FALSE)
  }
  cut <- cfg$analysis$wave1_depression_cutpoint %||% 22
  if (!is.numeric(cut) || length(cut) != 1L || !is.finite(cut) || cut < 0 || cut > 57)
    stop("wave1_depression_cutpoint must be in [0,57].", call. = FALSE)
  validate_exposure_mode_cfg(cfg)
  dm <- resolve_status_mode(cfg)
  if (length(dm) != 1L || is.na(dm) || !dm %in% c("audit_only", "composite", "exclude_sensitivity"))
    stop("Invalid dsp4_mode.", call. = FALSE)
  zf <- as.character(cfg$analysis$dsp4_structural_zero_families %||% character(0))
  if (length(zf) && !all(zf %in% names(cfg$outcome$families)))
    stop("cfg$analysis$dsp4_structural_zero_families names an unknown family: ",
         paste(setdiff(zf, names(cfg$outcome$families)), collapse = ", "),
         call. = FALSE)
  if (length(zf) && !all(zf %in% c("HoursWorked", "LaborForceParticipation")))
    stop("Disposition recoding is supported only for Wave-IV hours/LFP, never annual earnings.", call. = FALSE)
  if (459L %in% (cfg$analysis$dsp4_structural_zero_codes %||% integer(0)))
    stop("DSP4 death code 459 is audit-only: use dated mortality adjudication for composite zeros.", call. = FALSE)
  if (!identical(dm, "audit_only")) {
    if (!cfg$outcome$family %in% zf || !identical(as.integer(cfg$outcome$current_wave %||% cfg$outcome$waves), 4L))
      stop("Active status recoding requires a supported Wave-IV labor outcome.", call. = FALSE)
    p <- cfg$paths$verified_labor_status
    if (!isTRUE(cfg$analysis$auto_military_prison_status) &&
        (is.null(p) || length(p) != 1L || is.na(p) || !nzchar(p) || !file.exists(p)))
      stop("Active status recoding requires an existing verified_labor_status CSV; see its documented schema.", call. = FALSE)
  }
  if (isTRUE(cfg$analysis$adaptive_g_truncation) &&
      length(cfg$analysis$adaptive_g_truncation_grid %||% numeric(0)) < 2L)
    stop("adaptive_g_truncation needs at least two candidate bounds.",
         call. = FALSE)
  grid <- cfg$analysis$adaptive_g_truncation_grid %||% c(0.005, 0.01)
  if (!is.numeric(grid) || any(!is.finite(grid) | grid <= 0 | grid >= 0.5))
    stop("Every comparison g floor must be finite and in (0,0.5).", call. = FALSE)
  if (isTRUE(cfg$analysis$adaptive_g_truncation_apply))
    stop(paste0("Automatic selection using final ATT/SE is unsupported: the previous MSE proxy ",
                "did not estimate bias and its selection uncertainty was absent. Use a fixed-bound ",
                "sensitivity or training-only calibration instead."), call. = FALSE)
  # --- Rough-screen helper settings -----------------------------------------
  if (!cfg$rough_prescreen$cutoff_rule %in% c("positive","knee","topk"))
    stop("rough_prescreen$cutoff_rule must be one of 'positive', 'knee', 'topk'.", call. = FALSE)
  if (!isTRUE(cfg$rough_prescreen$cluster_aware_folds))
    stop("rough_prescreen$cluster_aware_folds must remain TRUE; row-level screening folds are disabled.", call. = FALSE)
  if (!identical(tolower(cfg$final_tmle$att_estimator %||% "tmle"), "tmle"))
    stop(paste0(
      "final_tmle$att_estimator must be 'tmle'. The one-step AIPTW estimate ",
      "is retained as a diagnostic comparator but is not a supported headline option."),
      call. = FALSE)
  if (!is.null(cfg$final_tmle$primary_estimand) &&
      !cfg$final_tmle$primary_estimand %in% c("ate", "trimmed", "att"))
    stop("final_tmle$primary_estimand must be one of 'ate', 'trimmed', 'att'.", call. = FALSE)
  if (identical(cfg$final_tmle$primary_estimand, "att") && !isTRUE(cfg$final_tmle$report_att))
    stop("final_tmle$primary_estimand='att' requires report_att=TRUE.", call. = FALSE)
  if (cfg$rough_prescreen$folds < 2L || cfg$final_tmle$vfolds < 2L ||
      cfg$final_tmle$internal_superlearner_folds < 2L ||
      cfg$final_tmle$rough_folds < 2L)
    stop("All rough/final fold counts must be at least 2.", call. = FALSE)
  
  # --- Causal-variable governance -----------------------------------------
  denied_sources <- cfg$causal_governance$excluded_candidate_sources %||% "birth_records"
  if (!is.character(denied_sources) || anyNA(denied_sources) ||
      any(!nzchar(trimws(denied_sources))) || anyDuplicated(tolower(trimws(denied_sources))))
    stop("excluded_candidate_sources must be unique nonblank source names.", call. = FALSE)
  if (!"birth_records" %in% tolower(trimws(denied_sources)))
    stop("This release requires birth_records excluded from candidate W.", call. = FALSE)
  mandatory_W <- get_mandatory_W(cfg)
  if (anyDuplicated(canonical_role_key(mandatory_W)))
    stop("Mandatory W names are duplicated after canonical join-suffix removal.", call. = FALSE)
  excluded_keys <- canonical_role_key(cfg$analysis$extra_exclude_from_candidates %||% character(0))
  conflict_mandatory <- mandatory_W[canonical_role_key(mandatory_W) %in% excluded_keys]
  if (length(conflict_mandatory))
    stop("Mandatory W variable(s) are also configured for exclusion: ",
         paste(conflict_mandatory, collapse = ", "), call. = FALSE)
  if (!isTRUE(cfg$final_tmle$mandatory_W_bypass_screening %||% FALSE))
    stop("mandatory_W_bypass_screening must remain TRUE.", call. = FALSE)
  
  transform <- tolower(cfg$outcome$compensation_transform %||% "identity")
  if (!transform %in% c("identity", "log1p", "asinh"))
    stop("outcome$compensation_transform must be identity, log1p, or asinh.", call. = FALSE)
  if (isTRUE(cfg$outcome$log_transform %||% FALSE))
    stop("Legacy outcome$log_transform must remain FALSE; use compensation_transform.", call. = FALSE)
  if (!is.finite(cfg$outcome$compensation_asinh_scale %||% NA_real_) ||
      cfg$outcome$compensation_asinh_scale <= 0)
    stop("outcome$compensation_asinh_scale must be positive and finite.", call. = FALSE)
  if (!is.logical(cfg$outcome$compensation_exact_only) ||
      length(cfg$outcome$compensation_exact_only) != 1L)
    stop("outcome$compensation_exact_only must be a single logical value.", call. = FALSE)
  policy_components <- cfg$policy$enable_policy_components %||% TRUE
  policy_translation <- cfg$policy$enable_att_prevalence_translation %||% TRUE
  policy_fail <- cfg$policy$fail_on_policy_component_checks %||% TRUE
  if (!is.logical(policy_components) || length(policy_components) != 1L || is.na(policy_components) ||
      !is.logical(policy_translation) || length(policy_translation) != 1L || is.na(policy_translation) ||
      !is.logical(policy_fail) || length(policy_fail) != 1L || is.na(policy_fail))
    stop("Policy component, translation, and failure controls must each be one nonmissing logical value.", call. = FALSE)
  if (isTRUE(policy_translation) && !isTRUE(policy_components))
    stop("policy$enable_att_prevalence_translation=TRUE requires enable_policy_components=TRUE.", call. = FALSE)
  if (isTRUE(policy_translation) &&
      length(cfg$policy$relative_prevalence_reductions %||% numeric(0)) &&
      (any(!is.finite(cfg$policy$relative_prevalence_reductions)) ||
       any(cfg$policy$relative_prevalence_reductions <= 0) ||
       any(cfg$policy$relative_prevalence_reductions > 1)))
    stop("Policy relative prevalence reductions must lie in (0,1].", call. = FALSE)
  q_clip_bounds <- c(cfg$final_tmle$Q_clip_warning_fraction,
                     cfg$final_tmle$Q_clip_review_fraction)
  if (any(!is.finite(q_clip_bounds)) || any(q_clip_bounds < 0) ||
      any(q_clip_bounds > 1) || q_clip_bounds[1] > q_clip_bounds[2])
    stop("Q clipping warning/review fractions must be ordered in [0,1].", call. = FALSE)
  completion_toggle <- cfg$diagnostics$enable_wave2_completion_diagnostic %||% TRUE
  mnar_toggle <- cfg$diagnostics$enable_mnar_pattern_mixture %||% TRUE
  evalue_toggle <- cfg$diagnostics$enable_evalue %||% FALSE
  diagnostic_toggles <- list(
    enable_wave2_completion_diagnostic = completion_toggle,
    enable_mnar_pattern_mixture = mnar_toggle,
    enable_mnar_two_part = cfg$diagnostics$enable_mnar_two_part %||% TRUE,
    enable_evalue = evalue_toggle)
  bad_diagnostic_toggles <- names(diagnostic_toggles)[!vapply(
    diagnostic_toggles,
    function(z) is.logical(z) && length(z) == 1L && !is.na(z),
    logical(1))]
  if (length(bad_diagnostic_toggles))
    stop("Diagnostic toggles must each be one nonmissing logical value: ",
         paste(bad_diagnostic_toggles, collapse = ", "), ".", call. = FALSE)
  balance_progress_every <- cfg$diagnostics$balance_progress_every %||% 500L
  if (!is.numeric(balance_progress_every) || length(balance_progress_every) != 1L ||
      is.na(balance_progress_every) || !is.finite(balance_progress_every) ||
      balance_progress_every < 1 ||
      abs(balance_progress_every - round(balance_progress_every)) > 1e-8)
    stop("diagnostics$balance_progress_every must be one positive integer.", call. = FALSE)
  if (isTRUE(cfg$diagnostics$enable_mnar_pattern_mixture %||% TRUE)) {
    mnar_grid <- as.numeric(cfg$diagnostics$mnar_shift_sd_grid %||% numeric(0))
    if (!length(mnar_grid) || any(!is.finite(mnar_grid)) || !any(mnar_grid == 0))
      stop("Enabled MNAR diagnostics require a finite shift grid containing zero.", call. = FALSE)
  }
  
  if (isTRUE(cfg$diagnostics$enable_mnar_two_part %||% TRUE)) {
    zg <- cfg$diagnostics$mnar_two_part_zero_grid %||% c(0,0.05,0.10,0.20)
    dg <- cfg$diagnostics$mnar_two_part_delta_grid
    if (!is.numeric(zg) || !length(zg) || any(!is.finite(zg)) ||
        any(zg<0 | zg>1) || !any(zg==0))
      stop("Two-part MNAR zero grid must lie in [0,1] and include zero.",call.=FALSE)
    if (!is.null(dg) && (!is.numeric(dg) || !length(dg) ||
        any(!is.finite(dg)) || !any(dg==0)))
      stop("Two-part MNAR delta grid must be NULL or finite and include zero.",call.=FALSE)
    if (length(unique(zg))^2*(if(is.null(dg)) 5L else length(unique(dg)))^2>10000L)
      stop("Two-part MNAR grid exceeds 10000 scenarios.",call.=FALSE)
  }

  mort_base <- cfg$mortality_sensitivity %||% list(enabled = FALSE)
  mortality_enabled <- mort_base$enabled %||% FALSE
  if (!is.logical(mortality_enabled) || length(mortality_enabled) != 1L ||
      is.na(mortality_enabled))
    stop("mortality_sensitivity$enabled must be one nonmissing logical value.", call. = FALSE)
  enabled_waves <- as.integer(mort_base$enabled_waves %||% integer(0))
  if (anyNA(enabled_waves) || any(!enabled_waves %in% c(3L, 4L)) || anyDuplicated(enabled_waves))
    stop("mortality_sensitivity$enabled_waves must contain unique Wave III/IV integers only.", call. = FALSE)
  if (isTRUE(mortality_enabled) && !setequal(enabled_waves, c(3L, 4L)))
    stop("Production mortality must be enabled for both supported outcome waves III and IV.",
         call. = FALSE)
  if (isTRUE(mortality_enabled) && length(enabled_waves)) {
    if (!is.character(cfg$paths$mortality) || length(cfg$paths$mortality) != 1L ||
        is.na(cfg$paths$mortality) || !nzchar(trimws(cfg$paths$mortality)))
      stop("Enabled mortality sensitivity requires cfg$paths$mortality.", call. = FALSE)
    if (!is.character(mort_base$source_var) || length(mort_base$source_var) != 1L ||
        is.na(mort_base$source_var) || !nzchar(trimws(mort_base$source_var)))
      stop("Enabled mortality sensitivity requires one nonblank source_var.", call. = FALSE)
    if (!is.character(mort_base$source_month_var) || length(mort_base$source_month_var) != 1L ||
        is.na(mort_base$source_month_var) || !nzchar(trimws(mort_base$source_month_var)))
      stop("Enabled mortality sensitivity requires one nonblank source_month_var.", call. = FALSE)
    month_limits <- suppressWarnings(as.integer(c(
      mort_base$valid_month_min, mort_base$valid_month_max)))
    if (length(month_limits) != 2L || anyNA(month_limits) ||
        !identical(month_limits, c(1L, 12L)))
      stop("Mortality valid month limits must be exactly 1 through 12.", call. = FALSE)
    invalid_month_codes <- suppressWarnings(as.integer(
      mort_base$invalid_month_codes %||% integer(0)))
    if (anyNA(invalid_month_codes) || anyDuplicated(invalid_month_codes) ||
        !997L %in% invalid_month_codes)
      stop("Mortality invalid_month_codes must be unique integers and include 997.", call. = FALSE)
    common_gates <- c("native_missing_means_no_death", "fail_on_unrecognized_codes",
                      "require_complete_linkage", "fail_on_death_with_observed_original_outcome",
                      "composite_zero_at_death")
    for (nm in common_gates) {
      z <- mort_base[[nm]]
      if (!is.logical(z) || length(z) != 1L || is.na(z))
        stop("Mortality gate control must be one nonmissing logical: ", nm, call. = FALSE)
    }
    for (w in enabled_waves) {
      mort <- resolve_mortality_spec(cfg, w)
      scalar_text <- c("derived_death_year_var", "derived_death_month_var",
                       "death_in_window_var", "death_before_outcome_var",
                       "timing_status_var", "linkage_audit_csv",
                       "interview_timing_audit_csv", "contradiction_audit_csv",
                       "output_csv")
      for (nm in scalar_text) {
        z <- mort[[nm]] %||% NULL
        if (!is.character(z) || length(z) != 1L || is.na(z) || !nzchar(trimws(z)))
          stop(sprintf("Enabled Wave %d mortality requires one nonblank %s.", w, nm), call. = FALSE)
      }
      yr <- as.integer(c(mort$death_year_start, mort$death_year_end,
                         mort$valid_year_min, mort$valid_year_max))
      if (length(yr) != 4L || anyNA(yr) || yr[1L] > yr[2L] ||
          yr[3L] > yr[1L] || yr[4L] < yr[2L])
        stop(sprintf("Wave %d mortality year-window and valid-year limits are inconsistent.", w), call. = FALSE)
      raw_spec <- (mort_base$wave_specs %||% list())[[as.character(w)]] %||% list()
      mode <- as.character(mort$timing_mode %||% "fixed_window")
      if (length(mode) != 1L || is.na(mode) ||
          !mode %in% c("fixed_window", "interview_month"))
        stop(sprintf("Wave %d mortality timing_mode is invalid.", w), call. = FALSE)
      expected_end <- c(`3` = 2002L, `4` = 2009L)[as.character(w)]
      if (!identical(mode, "interview_month") ||
          !identical(as.integer(mort$death_year_end), as.integer(expected_end)))
        stop(sprintf(
          "Wave %d mortality must use interview_month timing through %d.",
          w, as.integer(expected_end)), call. = FALSE)
      if (!is.null(raw_spec$timing_mode_by_family) ||
          !is.null(raw_spec$death_year_end_by_family))
        stop(sprintf(
          "Wave %d mortality must use one harmonized timing_mode and endpoint across supported outcome families.",
          w), call. = FALSE)
      mortality_roles <- canonical_role_key(c(
        cfg$analysis$id_var, cfg$analysis$cluster_var, cfg$analysis$strata_var,
        cfg$analysis$weight_var, cfg$analysis$exposure_var,
        cfg$analysis$outcome_var, cfg$analysis$outcome_observed_var))
      role_vars <- unique(c(mort$source_var, mort$source_month_var,
                            mort$derived_death_year_var, mort$derived_death_month_var,
                            mort$death_in_window_var, mort$death_before_outcome_var,
                            mort$timing_status_var, mort$interview_year_var %||% character(0),
                            mort$interview_month_var %||% character(0)))
      if (anyDuplicated(canonical_role_key(role_vars)))
        stop(sprintf("Wave %d mortality role variables are not unique after canonicalization.", w),
             call. = FALSE)
      if (any(canonical_role_key(role_vars) %in% mortality_roles))
        stop("Mortality role variable conflicts with a core analysis variable.", call. = FALSE)
      
      if (identical(mode, "interview_month")) {
        iy <- mort$interview_year_var %||% NULL
        im <- mort$interview_month_var %||% NULL
        for (z in list(iy, im)) {
          if (!is.character(z) || length(z) != 1L || is.na(z) || !nzchar(trimws(z)))
            stop(sprintf("Wave %d interview-month mortality requires nonblank interview year/month variables.", w),
                 call. = FALSE)
        }
        iy_lim <- suppressWarnings(as.integer(c(
          mort$interview_year_valid_min, mort$interview_year_valid_max)))
        im_lim <- suppressWarnings(as.integer(c(
          mort$interview_month_valid_min, mort$interview_month_valid_max)))
        if (length(iy_lim) != 2L || anyNA(iy_lim) || iy_lim[1L] > iy_lim[2L])
          stop(sprintf("Wave %d mortality interview-year limits are invalid.", w), call. = FALSE)
        if (length(im_lim) != 2L || anyNA(im_lim) ||
            !identical(im_lim, c(1L, 12L)))
          stop(sprintf("Wave %d mortality interview-month limits must be 1 through 12.", w),
               call. = FALSE)
      }
    }
  }
  
  # --- v6 outcome-family validation ---------------------------------------
  allowed_families <- c("EducationalAttainment","LaborForceParticipation","HoursWorked","UsualHours",
                        "Compensation","HealthStatus","MentalHealth","SubstanceUse",
                        "PassThrough")   # pass-through negative-control outcome family
  if (!cfg$outcome$family %in% allowed_families)
    stop(sprintf("cfg$outcome$family must be one of: %s.",
                 paste(allowed_families, collapse = ", ")), call. = FALSE)
  fam_cfg <- cfg$outcome$families[[cfg$outcome$family]]
  if (is.null(fam_cfg))
    stop(sprintf("cfg$outcome$families$%s is missing.", cfg$outcome$family), call. = FALSE)
  if (identical(fam_cfg$type, "binary_nested")) {
    if (!is.null(cfg$outcome$family_member) &&
        !(cfg$outcome$family_member %in% names(fam_cfg$members)))
      stop(sprintf("cfg$outcome$family_member '%s' not in %s$members.",
                   cfg$outcome$family_member, cfg$outcome$family), call. = FALSE)
  } else if (!is.null(cfg$outcome$family_member)) {
    warning(sprintf("family_member ignored for non-nested family '%s'.", cfg$outcome$family))
  }
  
  waves <- cfg$outcome$waves
  if (identical(waves, "all")) {
    waves <- supported_outcome_waves(cfg$outcome$family)
  }
  if (!is.numeric(waves) || any(!waves %in% 3:5))
    stop("cfg$outcome$waves must be integer(s) in 3:5 (post-exposure waves) ",
         "or the string 'all'.", call. = FALSE)
  
  supported <- supported_outcome_waves(cfg$outcome$family)
  if (!length(supported))
    stop(sprintf(
      "Outcome family '%s' is hard-blocked in this production program.",
      cfg$outcome$family), call. = FALSE)
  unsupported <- setdiff(as.integer(waves), supported)
  if (length(unsupported))
    stop(sprintf(
      "Outcome family '%s' is not supported at wave(s) %s; supported wave(s): %s.",
      cfg$outcome$family, paste(unsupported, collapse = ", "),
      paste(supported, collapse = ", ")), call. = FALSE)
  
  verified <- vapply(as.integer(waves), function(w)
    is_verified_outcome_spec(cfg, cfg$outcome$family, w), logical(1))
  if (any(!verified)) {
    bad_waves <- paste(as.integer(waves)[!verified], collapse = ", ")
    msg_txt <- sprintf(
      paste0("Outcome specification is not production-verified: family='%s', wave(s)=%s. ",
             "Only production-verified family/wave mappings and explicitly configured PassThrough outcomes ",
             "are allowed by default. Verify the codebook mapping, then set ",
             "cfg$safety$allow_unverified_outcome_specs=TRUE deliberately."),
      cfg$outcome$family, bad_waves)
    if (!isTRUE(cfg$safety$allow_unverified_outcome_specs %||% FALSE))
      stop(msg_txt, call. = FALSE)
    warning(msg_txt, call. = FALSE)
  }
  invisible(TRUE)
}

load_required_packages <- function(cfg) {
  required <- c("haven", "dplyr", "purrr")
  need_modeling <- isTRUE(cfg$stages$run_final_cv_tmle) ||
    isTRUE(cfg$stages$run_preflight_unit_test)
  if (need_modeling) {
    required <- c(required, "SuperLearner", "glmnet", "survey")
    use_ranger <- any(vapply(cfg$learners[c("Q", "g", "pi")],
                             function(x) isTRUE(x$use_ranger) ||
                               isTRUE(x$use_ranger_control_arm), logical(1)))
    use_xgb <- any(vapply(cfg$learners[c("Q", "g", "pi")],
                          function(x) isTRUE(x$use_xgboost) ||
                            isTRUE(x$use_xgboost_control_arm) ||
                            isTRUE(x$use_xgboost_rich), logical(1)))
    use_earth <- any(vapply(cfg$learners[c("Q", "g", "pi")],
                            function(x) isTRUE(x$use_earth), logical(1)))
    use_gam <- any(vapply(cfg$learners[c("Q", "g", "pi")],
                          function(x) isTRUE(x$use_gam), logical(1)))
    use_nnet <- any(vapply(cfg$learners[c("Q", "g", "pi")],
                           function(x) isTRUE(x$use_nnet), logical(1)))
    use_svm <- any(vapply(cfg$learners[c("Q", "g", "pi")],
                          function(x) isTRUE(x$use_svm), logical(1)))
    if (use_ranger) required <- c(required, "ranger")
    if (use_xgb) required <- c(required, "xgboost", "Matrix")
    if (use_earth) required <- c(required, "earth")
    if (use_gam) required <- c(required, "mgcv")
    if (use_nnet) required <- c(required, "nnet")
    if (use_svm) required <- c(required, "e1071")
  }
  required <- unique(required)
  missing_pkgs <- required[!vapply(required, requireNamespace, logical(1), quietly = TRUE)]
  if (length(missing_pkgs) > 0L)
    stop("Please install required package(s): ",
         paste(missing_pkgs, collapse = ", "), call. = FALSE)
  if ("survey" %in% required && utils::packageVersion("survey") < package_version("4.1.0"))
    stop("Package 'survey' version 4.1.0 or newer is required for the declared weighted Hyndman-Fan quantile rules.", call. = FALSE)
  validate_runtime_environment(cfg, required)
  suppressPackageStartupMessages({
    library(haven); library(dplyr); library(purrr)
    if ("SuperLearner" %in% required) library(SuperLearner)
    if ("glmnet" %in% required) library(glmnet)
    if ("survey" %in% required) library(survey)
    if ("ranger" %in% required) library(ranger)
    if ("xgboost" %in% required) library(xgboost)
    if ("Matrix" %in% required) library(Matrix)
    if ("earth" %in% required) library(earth)
    if ("mgcv" %in% required) library(mgcv)
    if ("nnet" %in% required) library(nnet)
    if ("e1071" %in% required) library(e1071)
  })
}


# Deliberately do not validate or attach packages at source time. This file is
# safe to source with autorun_pipeline=FALSE so the analyst can resolve the
# explicit restricted-codebook decisions in cfg. Every executable entry point
# validates the complete configuration and loads exactly the packages required
# by the enabled learners before reading data or fitting models.

# =============================================================================
# 2) SMALL UTILITIES
# =============================================================================

msg <- function(..., cfg) { if (isTRUE(cfg$global$verbose)) message(...) }

seed_for <- function(cfg, offset = 0L) as.integer(cfg$global$pipeline_seed + offset)

with_local_seed <- function(seed, value) {
  had_seed <- exists(".Random.seed", envir = .GlobalEnv, inherits = FALSE)
  old_seed <- if (had_seed) get(".Random.seed", envir = .GlobalEnv, inherits = FALSE) else NULL
  on.exit({
    if (had_seed) assign(".Random.seed", old_seed, envir = .GlobalEnv)
    else if (exists(".Random.seed", envir = .GlobalEnv, inherits = FALSE))
      rm(".Random.seed", envir = .GlobalEnv)
  }, add = TRUE)
  set.seed(as.integer(seed))
  force(value)
}

ensure_output_dir <- function(path_dir, cfg = NULL, test_write = FALSE) {
  if (is.null(path_dir) || length(path_dir) != 1L || is.na(path_dir) ||
      !nzchar(trimws(as.character(path_dir))))
    stop("Output directory must be one nonblank path.", call. = FALSE)
  path_dir <- as.character(path_dir)
  if (!dir.exists(path_dir)) {
    ok <- dir.create(path_dir, recursive = TRUE, showWarnings = TRUE)
    if (!isTRUE(ok) && !dir.exists(path_dir))
      stop("Could not create output directory: ", path_dir, call. = FALSE)
  }
  if (!dir.exists(path_dir))
    stop("Output directory does not exist after creation attempt: ", path_dir,
         call. = FALSE)
  if (!is.null(cfg)) assert_path_length_safe(path_dir, cfg, "output directory")
  if (isTRUE(test_write)) {
    canary <- tempfile(pattern = ".addhealth_canary_", tmpdir = path_dir,
                       fileext = ".txt")
    on.exit(if (file.exists(canary)) unlink(canary, force = TRUE), add = TRUE)
    write_ok <- tryCatch({
      writeLines("addhealth_write_test", canary, useBytes = TRUE)
      identical(readLines(canary, warn = FALSE), "addhealth_write_test")
    }, error = function(e) FALSE)
    if (!isTRUE(write_ok) || !file.exists(canary))
      stop("Output directory is not reliably writable/readable: ", path_dir,
           call. = FALSE)
    if (!isTRUE(unlink(canary, force = TRUE) == 0L) && file.exists(canary))
      stop("Output directory canary could not be removed: ", canary, call. = FALSE)
  }
  invisible(path_dir)
}

assert_path_length_safe <- function(path, cfg, label = "path") {
  if (.Platform$OS.type != "windows") return(invisible(TRUE))
  limit <- as.integer(cfg$safety$windows_max_path %||% 259L)
  if (!is.finite(limit) || limit < 100L)
    stop("safety$windows_max_path must be a sensible positive integer.", call. = FALSE)
  n <- nchar(as.character(path), type = "chars")
  if (n > limit)
    stop(sprintf("%s exceeds the configured Windows path limit (%d > %d): %s",
                 label, n, limit, path), call. = FALSE)
  invisible(TRUE)
}

atomic_commit_file <- function(temp_path, final_path, overwrite = FALSE) {
  if (!file.exists(temp_path))
    stop("Atomic write temporary file does not exist: ", temp_path, call. = FALSE)
  ensure_output_dir(dirname(final_path), test_write = FALSE)
  backup <- NULL
  if (file.exists(final_path)) {
    if (!isTRUE(overwrite))
      stop("Refusing to overwrite existing output: ", final_path, call. = FALSE)
    backup <- tempfile(pattern = paste0(".", basename(final_path), ".bak_"),
                       tmpdir = dirname(final_path), fileext = ".tmp")
    if (!file.rename(final_path, backup))
      stop("Could not move existing file aside for atomic replacement: ", final_path,
           call. = FALSE)
  }
  committed <- file.rename(temp_path, final_path)
  if (!isTRUE(committed)) {
    restored <- TRUE
    if (!is.null(backup) && file.exists(backup))
      restored <- isTRUE(file.rename(backup, final_path))
    if (!isTRUE(restored))
      stop(paste0(
        "Atomic rename failed and the previous file could not be restored. ",
        "Temporary file: ", temp_path, "; backup: ", backup,
        "; destination: ", final_path), call. = FALSE)
    stop("Atomic rename failed for: ", final_path, call. = FALSE)
  }
  if (!is.null(backup) && file.exists(backup)) {
    removed <- unlink(backup, force = TRUE)
    if (!identical(as.integer(removed), 0L) && file.exists(backup))
      warning("Atomic replacement succeeded, but its backup could not be removed: ",
              backup, call. = FALSE)
  }
  if (!file.exists(final_path))
    stop("Atomic replacement reported success but the destination is absent: ",
         final_path, call. = FALSE)
  invisible(final_path)
}

atomic_save_rds <- function(object, path, overwrite = TRUE, version = 2L,
                            verify = TRUE,
                            full_readback_max_bytes = 128 * 1024^2) {
  ensure_output_dir(dirname(path), test_write = FALSE)
  if (!is.numeric(full_readback_max_bytes) ||
      length(full_readback_max_bytes) != 1L ||
      is.na(full_readback_max_bytes) ||
      !is.finite(full_readback_max_bytes) ||
      full_readback_max_bytes < 0)
    stop("full_readback_max_bytes must be one nonnegative finite number.",
         call. = FALSE)
  tf <- tempfile(pattern = paste0(".", basename(path), "_"),
                 tmpdir = dirname(path), fileext = ".tmp")
  on.exit(if (file.exists(tf)) unlink(tf, force = TRUE), add = TRUE)
  saveRDS(object, tf, version = version)
  temp_info <- file.info(tf)
  if (!file.exists(tf) || !is.finite(temp_info$size) || temp_info$size <= 0)
    stop("RDS serialization did not produce a nonempty temporary file for: ",
         path, call. = FALSE)
  # Full read-back is valuable for ordinary outputs but can double peak memory
  # for the large Wave-I/main-data caches. Large files are therefore verified
  # by successful serialization plus nonzero/stable byte size across the atomic
  # rename; smaller files are additionally deserialized before commit.
  if (isTRUE(verify) && temp_info$size <= full_readback_max_bytes) {
    chk <- tryCatch(readRDS(tf), error = function(e) e)
    if (inherits(chk, "error"))
      stop("RDS verification failed before commit for ", path, ": ",
           conditionMessage(chk), call. = FALSE)
  }
  expected_size <- as.numeric(temp_info$size)
  atomic_commit_file(tf, path, overwrite = overwrite)
  final_info <- file.info(path)
  if (!file.exists(path) || !is.finite(final_info$size) ||
      as.numeric(final_info$size) != expected_size)
    stop("RDS byte-size verification failed after atomic commit for: ", path,
         call. = FALSE)
  invisible(path)
}

atomic_write_plain_csv <- function(x, path, row.names = FALSE, overwrite = FALSE,
                                   verify = TRUE) {
  xx <- as.data.frame(x)
  if (ncol(xx) < 1L)
    stop("Refusing to write a zero-column CSV artifact: ", path, call. = FALSE)
  ensure_output_dir(dirname(path), test_write = FALSE)
  tf <- tempfile(pattern = paste0(".", basename(path), "_"),
                 tmpdir = dirname(path), fileext = ".tmp")
  on.exit(if (file.exists(tf)) unlink(tf, force = TRUE), add = TRUE)
  utils::write.csv(xx, tf, row.names = row.names, na = "")
  if (isTRUE(verify)) {
    chk <- tryCatch(utils::read.csv(tf, stringsAsFactors = FALSE,
                                    check.names = FALSE), error = function(e) e)
    if (inherits(chk, "error") || nrow(chk) != nrow(xx) ||
        ncol(chk) != ncol(xx))
      stop("CSV verification failed before commit for: ", path, call. = FALSE)
  }
  atomic_commit_file(tf, path, overwrite = overwrite)
}

assert_fresh_output_dir <- function(path_dir, cfg, allowed_basenames = NULL) {
  if (!isTRUE(cfg$safety$require_fresh_primary_output_dir %||% TRUE) ||
      isTRUE(cfg$global$resume_mode %||% FALSE)) return(invisible(TRUE))
  ensure_output_dir(path_dir, cfg = cfg, test_write = TRUE)
  allowed <- if (is.null(allowed_basenames))
    cfg$safety$fresh_output_allowed_basenames %||% character(0) else
      allowed_basenames
  if (!is.character(allowed) || anyNA(allowed) || any(!nzchar(trimws(allowed))) ||
      any(basename(allowed) != allowed))
    stop("Fresh-output allowlist must contain nonblank base filenames only.",
         call. = FALSE)
  existing <- list.files(path_dir, all.files = TRUE, no.. = TRUE, full.names = FALSE)
  existing <- setdiff(existing, unique(allowed))
  if (length(existing))
    stop("Fresh-run safety gate: output directory is not empty: ", path_dir,
         ". Existing entries: ", paste(head(existing, 20L), collapse = ", "),
         call. = FALSE)
  invisible(TRUE)
}

assert_planned_output_paths <- function(cfg, extra_filenames = character(0)) {
  scalar_strings <- unlist(cfg, recursive = TRUE, use.names = FALSE)
  file_names <- unique(c(
    scalar_strings[grepl("\\.(csv|rds|png|txt)$", scalar_strings, ignore.case = TRUE)],
    extra_filenames))
  if (!length(file_names)) return(invisible(TRUE))
  tag <- build_run_tag(cfg)
  candidates <- unlist(lapply(file_names, function(f) {
    b <- basename(f)
    c(build_unique_path(cfg, b),
      build_unique_diag_path(cfg,
                             file.path(cfg$global$output_dir, cfg$diagnostics$diagnostics_dir), b),
      file.path(cfg$global$output_dir, paste0("sens_", tag), b))
  }), use.names = FALSE)
  for (p in candidates) assert_path_length_safe(p, cfg, "planned output path")
  invisible(TRUE)
}


# v6: Build a unique, self-describing filename for an output file.
# The filename includes the base name, a tag summarizing the run (family,
# wave, family_member, run_label), and an optional timestamp so
# repeat runs never overwrite each other.
# Example: "cv_tmle_results__HealthStatus__wave3__at_least_good__2026-04-23_143205.csv"
short_name_hash <- function(x) {
  ints <- utf8ToInt(enc2utf8(as.character(x)))
  h <- 0
  for (z in ints) h <- (h * 131 + z) %% 2147483647
  sprintf("%08x", as.integer(h))
}

compact_output_basename <- function(base_filename, cfg) {
  if (!isTRUE(cfg$global$short_file_names %||% FALSE)) return(base_filename)
  ext_match <- regexpr("\\.[A-Za-z0-9]+$", base_filename)
  if (ext_match > 0L) {
    stem <- substr(base_filename, 1L, ext_match - 1L)
    ext <- substr(base_filename, ext_match, nchar(base_filename))
  } else { stem <- base_filename; ext <- "" }
  repl <- c(
    "cv_tmle_results"="tmle", "pipeline_timings"="time",
    "sample_flow"="flow", "analysis_sample_audit"="sample",
    "diagnostic_status"="status", "manuscript_summary"="msum",
    "diagnostic_fit_bundle"="fit", "variable_selection_consistency"="sel_cons",
    "learner_weight_summary"="lw_sum", "learner_weight_long"="lw",
    "nuisance_outer_validation_summary"="nuis_val", "effective_sample_size"="ess",
    "positivity_summary"="pos", "att_inference_robustness"="att_inf",
    "att_positivity_control_weights"="att_pos", "protected_h1fs_att_balance"="h1_bal",
    "dsp4_outcome_audit"="dsp4", "g_calibration_audit"="gcal",
    "prognostic_score_balance"="prog_bal", "ovb_robustness_values"="ovb",
    "adaptive_truncation_selection"="adtrunc",
    "att_g_pi_clip_sensitivity"="clip", "att_mnar_breakdown_point"="mnar_bd",
    "att_mnar_calibrated_sensitivity"="mnar_cal",
    "att_fixed_nuisance_extreme_mean_bounds"="mnar_ext",
    "balance_treatment_loveplot_data"="bal_a", "balance_factor_levels_treatment"="bal_lev",
    "missing_outcome_audit"="miss", "earnings_tail_cap_audit"="tail",
    "earnings_construction_audit"="earn_build", "outcome_construction_audit"="y_build",
    "wave2_completion_model"="w2_comp", "mortality_composite_zero_at_death_audit"="mort_zero"
  )
  if (stem %in% names(repl)) stem <- unname(repl[stem])
  stem <- gsub("variable_selection", "sel", stem, fixed = TRUE)
  stem <- gsub("sensitivity", "sens", stem, fixed = TRUE)
  stem <- gsub("diagnostic", "diag", stem, fixed = TRUE)
  stem <- gsub("mortality", "mort", stem, fixed = TRUE)
  stem <- gsub("treatment", "trt", stem, fixed = TRUE)
  stem <- gsub("missingness", "miss", stem, fixed = TRUE)
  stem <- gsub("inference", "inf", stem, fixed = TRUE)
  stem <- gsub("balance", "bal", stem, fixed = TRUE)
  stem <- gsub("calibrated", "cal", stem, fixed = TRUE)
  stem <- gsub("construction", "build", stem, fixed = TRUE)
  stem <- gsub("completion", "comp", stem, fixed = TRUE)
  stem <- gsub("_+", "_", stem)
  maxn <- as.integer(cfg$global$max_output_stem_chars %||% 30L)
  if (!is.finite(maxn) || maxn < 16L) maxn <- 30L
  if (nchar(stem) > maxn) {
    hx <- short_name_hash(stem)
    keep <- max(6L, maxn - 10L)
    stem <- paste0(substr(stem, 1L, keep), "_", hx)
  }
  paste0(stem, ext)
}

build_run_tag <- function(cfg) {
  parts <- character(0)
  fam <- cfg$outcome$family %||% NULL
  if (!is.null(fam)) {
    fmap <- cfg$global$family_tag_map %||% character(0)
    ftag <- if (fam %in% names(fmap)) unname(fmap[fam]) else fam
    parts <- c(parts, ftag)
  }
  if (!is.null(cfg$outcome$current_wave)) parts <- c(parts, sprintf("w%d", cfg$outcome$current_wave))
  member_tag <- c(at_least_hs="hs", at_least_some_college="sc", at_least_college_grad="ba", at_least_good="good")
  if (!is.null(cfg$outcome$family_member)) {
    mt <- unname(member_tag[cfg$outcome$family_member])
    parts <- c(parts, if (is.na(mt)) cfg$outcome$family_member else mt)
  }
  if (!is.null(cfg$global$run_label) && nzchar(cfg$global$run_label)) parts <- c(parts, cfg$global$run_label)
  if (!length(parts)) parts <- "run"
  tag <- paste(parts, collapse = "_")
  gsub("[^A-Za-z0-9._=-]+", "_", tag)
}

ensure_run_id <- function(cfg) {
  if (is.null(cfg$global$run_id) || !nzchar(as.character(cfg$global$run_id))) {
    cfg$global$run_id <- paste0(format(Sys.time(), "%Y-%m-%d_%H%M%S"), "__pid", Sys.getpid())
  }
  cfg
}

runtime_provenance <- function() {
  pkgs <- c("haven", "dplyr", "purrr", "SuperLearner", "glmnet", "survey",
            "ranger", "xgboost", "Matrix", "earth", "mgcv", "nnet", "e1071")
  installed <- pkgs[vapply(pkgs, requireNamespace, logical(1), quietly = TRUE)]
  versions <- if (length(installed)) {
    paste(sprintf("%s=%s", installed,
                  vapply(installed, function(pkg) as.character(utils::packageVersion(pkg)), character(1))),
          collapse = ";")
  } else ""
  list(
    R_version = paste(R.version$major, R.version$minor, sep = "."),
    platform = R.version$platform,
    packages = versions)
}

build_unique_diag_path <- function(cfg, out_dir, base_filename) {
  base_filename <- compact_output_basename(base_filename, cfg)
  # Same naming scheme as build_unique_path but rooted under a custom
  # subdirectory (e.g., the diagnostics folder).
  ext_match <- regexpr("\\.[A-Za-z0-9]+$", base_filename)
  if (ext_match > 0L) {
    stem <- substr(base_filename, 1L, ext_match - 1L)
    ext  <- substr(base_filename, ext_match, nchar(base_filename))
  } else {
    stem <- base_filename; ext <- ""
  }
  tag <- build_run_tag(cfg)
  ts  <- if (isTRUE(cfg$global$append_timestamp_to_outputs))
    as.character(cfg$global$run_id %||% format(Sys.time(), "%Y-%m-%d_%H%M%S")) else NULL
  pieces <- c(stem, tag, ts); pieces <- pieces[nzchar(pieces)]
  fname  <- paste0(paste(pieces, collapse = "__"), ext)
  file.path(out_dir, fname)
}

build_unique_path <- function(cfg, base_filename) {
  base_filename <- compact_output_basename(base_filename, cfg)
  ext_match <- regexpr("\\.[A-Za-z0-9]+$", base_filename)
  if (ext_match > 0L) {
    stem <- substr(base_filename, 1L, ext_match - 1L)
    ext  <- substr(base_filename, ext_match, nchar(base_filename))
  } else {
    stem <- base_filename; ext <- ""
  }
  tag <- build_run_tag(cfg)
  ts  <- if (isTRUE(cfg$global$append_timestamp_to_outputs))
    as.character(cfg$global$run_id %||% format(Sys.time(), "%Y-%m-%d_%H%M%S")) else NULL
  pieces <- c(stem, tag, ts)
  pieces <- pieces[nzchar(pieces)]
  fname  <- paste0(paste(pieces, collapse = "__"), ext)
  file.path(cfg$global$output_dir, fname)
}

configured_outcome_definition <- function(cfg) {
  wave <- cfg$outcome$current_wave %||% cfg$outcome$waves
  mort <- if (length(wave) == 1L && is.numeric(wave)) resolve_mortality_spec(cfg, wave) else list(enabled = FALSE)
  mortality_txt <- if (isTRUE(mort$enabled) && isTRUE(mort$composite_zero_at_death)) {
    paste0("mortality-inclusive outcome; ", mortality_timing_rule_text(mort),
           " assigned observed zero when classified pre-outcome")
  } else "ordinary configured outcome"
  fam <- cfg$outcome$family %||% "unknown"
  fam_cfg <- cfg$outcome$families[[fam]] %||% list()
  def <- if (!is.null(fam_cfg$definition_by_wave) && length(wave) == 1L)
    unname(fam_cfg$definition_by_wave[as.character(wave)]) else NA_character_
  if (fam %in% c("HoursWorked", "UsualHours"))
    def <- sprintf("unconditional current weekly hours in questionnaire-qualifying jobs (>=10 h/week), capped at %g", fam_cfg$cap_hours %||% 120)
  if (identical(fam, "Compensation")) {
    cap_q <- cfg$outcome$continuous_upper_quantile %||% NA_real_
    cap_txt <- if (is.finite(cap_q) && cap_q < 1) sprintf("weighted upper cap q=%.4f", cap_q) else "no quantile cap"
    return(paste(mortality_txt, "nominal past-year personal earnings", cap_txt, sep = "; "))
  }
  if (identical(fam, "EducationalAttainment")) {
    member <- cfg$outcome$family_member %||% "all three primary nested thresholds"
    timing <- if (length(wave) == 1L && identical(as.integer(wave), 3L))
      "attainment-to-date" else "attainment"
    return(paste(mortality_txt, timing, member, sep = "; "))
  }
  if (identical(fam, "HealthStatus"))
    return(paste(mortality_txt, "at least good self-rated health", sep = "; "))
  status_txt <- if (identical(resolve_status_mode(cfg), "composite"))
    "US-resident civilian noninstitutional contribution; documented nonresident/institution/military/death zeros; unresolved contributions missing; fixed cohort, not BLS LFPR" else
    if (identical(cfg$analysis$dsp4_mode, "exclude_sensitivity"))
        "verified noncivilian/nonresident statuses excluded; post-exposure-selected population" else NULL
  paste(na.omit(c(mortality_txt, if (is.character(def) && nzchar(def)) def else fam, status_txt)), collapse = "; ")
}


# The function name is retained for backward compatibility. It now governs
# ratio translations for every verified outcome family whose configured scale
# has a meaningful positive component-mean denominator.
compensation_ratio_translation_enabled <- function(cfg) {
  family <- cfg$outcome$family %||% NA_character_
  fam_cfg <- if (!is.null(family) && family %in% names(cfg$outcome$families))
    cfg$outcome$families[[family]] else list()
  if (!family %in% names(cfg$outcome$families) ||
      !length(supported_outcome_waves(family)) ||
      !isTRUE(fam_cfg$report_ratio_translations %||% FALSE)) return(FALSE)
  if (identical(family, "Compensation"))
    return(identical(tolower(cfg$outcome$compensation_transform %||% "identity"),
                     "identity"))
  family %in% c("EducationalAttainment", "HealthStatus",
                "LaborForceParticipation", "HoursWorked")
}

configured_outcome_scale <- function(cfg, outcome_type = NULL) {
  if (!is.null(outcome_type) && identical(outcome_type, "binary"))
    return("binary_probability")
  if (identical(cfg$outcome$family, "Compensation")) {
    tr <- tolower(cfg$outcome$compensation_transform %||% "identity")
    if (identical(tr, "identity")) return("raw_dollars")
    return(paste0("compensation_", tr))
  }
  "continuous_original_units"
}

archive_existing_path <- function(path, label = "ARCHIVED") {
  if (!file.exists(path) && !dir.exists(path)) return(invisible(NA_character_))
  stamp <- format(Sys.time(), "%Y%m%d_%H%M%S")
  dest <- paste0(path, "__", sanitize_piece(label), "__", stamp,
                 "__pid", Sys.getpid())
  k <- 0L
  while (file.exists(dest) || dir.exists(dest)) {
    k <- k + 1L
    dest <- paste0(path, "__", sanitize_piece(label), "__", stamp,
                   "__pid", Sys.getpid(), "_", k)
  }
  if (!file.rename(path, dest))
    stop("Could not archive existing path before a fresh write: ", path,
         call. = FALSE)
  invisible(dest)
}

strip_runtime_config_state <- function(cfg, analysis_only = FALSE) {
  z <- cfg
  if (!is.null(z$preprocessing)) {
    z$preprocessing$global_missing_dictionary <- NULL
    z$preprocessing$variable_source_registry <- NULL
  }
  if (!is.null(z$final_tmle)) {
    z$final_tmle$screen_y_lower <- NULL
    z$final_tmle$screen_y_upper <- NULL
    if (!is.null(z$final_tmle$g_lower_runtime) &&
        isTRUE(all.equal(z$final_tmle$g_lower,z$final_tmle$g_lower_runtime$value)))
      z$final_tmle$g_lower <- z$final_tmle$g_lower_configured
    z$final_tmle$g_lower_runtime <- NULL
    z$final_tmle$g_lower_configured <- NULL
  }
  if (!is.null(z$provenance)) z$provenance <- NULL
  if (isTRUE(analysis_only)) {
    if (!is.null(z$global)) {
      runtime_global_fields <- c(
        "output_dir", "run_id", "run_label", "checkpoint_subdir",
        "pipeline_source_path", "append_timestamp_to_outputs",
        "resume_mode")
      for (nm in runtime_global_fields) z$global[[nm]] <- NULL
    }
    # Software versions and file-handling controls are frozen provenance and
    # execution safeguards, not features of the causal estimand or nuisance
    # specification. Keep them in resolved_run_config_md5, but exclude them
    # from analysis_spec_md5 so an operational resume setting cannot masquerade
    # as an analytical change.
    z$runtime <- NULL
    if (!is.null(z$safety)) {
      runtime_safety_fields <- c(
        "require_fresh_primary_output_dir", "fresh_output_allowed_basenames",
        "allow_output_overwrite", "verify_atomic_writes",
        "windows_max_path", "require_publication_ready_marker")
      for (nm in runtime_safety_fields) z$safety[[nm]] <- NULL
    }
  }
  z
}

freeze_run_provenance <- function(cfg) {
  cfg$policy$outcome_scale_label <- configured_outcome_definition(cfg)
  if (is.null(cfg$global$run_label) || !nzchar(trimws(as.character(cfg$global$run_label))))
    cfg$global$run_label <- "primary"
  source_fp <- pipeline_script_fingerprint(
    cfg, strict = isTRUE(cfg$global$require_script_md5 %||% FALSE))
  cfg$provenance <- list(
    analysis_spec_md5 = object_md5(strip_runtime_config_state(cfg, analysis_only = TRUE)),
    resolved_run_config_md5 = object_md5(strip_runtime_config_state(cfg, analysis_only = FALSE)),
    outcome_definition = configured_outcome_definition(cfg),
    source_fingerprint = source_fp,
    source_files = lapply(cfg$paths, file_fingerprint),
    runtime = runtime_provenance(),
    frozen_at = format(Sys.time(), "%Y-%m-%d %H:%M:%S %Z"))
  cfg
}

get_frozen_source_fingerprint <- function(cfg) {
  fp <- cfg$provenance$source_fingerprint %||% list()
  if (!isTRUE(fp$exists) || is.null(fp$md5) || is.na(fp$md5) || !nzchar(fp$md5))
    stop("Run provenance does not contain a valid frozen source fingerprint.",
         call. = FALSE)
  fp
}

verify_frozen_source_unchanged <- function(cfg) {
  frozen <- get_frozen_source_fingerprint(cfg)
  current <- file_fingerprint(frozen$path)
  if (!isTRUE(current$exists) || !identical(current$md5, frozen$md5) ||
      !identical(as.numeric(current$size), as.numeric(frozen$size)))
    stop("The pipeline source changed after run provenance was frozen. The run is invalid.",
         call. = FALSE)
  invisible(TRUE)
}


get_frozen_config_hash <- function(cfg, which = c("resolved", "analysis")) {
  which <- match.arg(which)
  p <- cfg$provenance %||% list()
  if (which == "analysis") p$analysis_spec_md5 %||% NA_character_ else
    p$resolved_run_config_md5 %||% NA_character_
}

# v6: wrapper around write.csv that uses build_unique_path and writes a
# metadata header describing the run configuration. This makes every CSV
# self-identifying when emailed or stored outside the run folder.
provenance_metadata_lines <- function(cfg, path, base_filename) {
  fp <- get_frozen_source_fingerprint(cfg)
  rt <- cfg$provenance$runtime %||% runtime_provenance()
  c(
    sprintf("# File:          %s", basename(path)),
    sprintf("# Generated:     %s", format(Sys.time(), "%Y-%m-%d %H:%M:%S %Z")),
    sprintf("# Base name:     %s", base_filename),
    sprintf("# Outcome:       family=%s, wave=%s, member=%s",
            cfg$outcome$family %||% "NA",
            as.character(cfg$outcome$current_wave %||% "NA"),
            cfg$outcome$family_member %||% "NA"),
    sprintf("# Run ID:        %s", cfg$global$run_id %||% ""),
    sprintf("# Pipeline seed: %s", cfg$global$pipeline_seed),
    sprintf("# Pipeline ver.: %s", cfg$global$version %||% ""),
    sprintf("# Script MD5:    %s", fp$md5),
    sprintf("# Analysis spec: %s", get_frozen_config_hash(cfg, "analysis")),
    sprintf("# Run config:    %s", get_frozen_config_hash(cfg, "resolved")),
    sprintf("# Run label:     %s", cfg$global$run_label %||% "NA"),
    sprintf("# Outcome def:   %s", cfg$provenance$outcome_definition %||%
              configured_outcome_definition(cfg)),
    sprintf("# R version:     %s", rt$R_version %||% runtime_provenance()$R_version),
    sprintf("# Package vers.: %s", rt$packages %||% runtime_provenance()$packages))
}

write_provenance_csv_at_path <- function(x, cfg, path, base_filename,
                                         row.names = FALSE, overwrite = NULL) {
  xx <- as.data.frame(x)
  if (ncol(xx) < 1L)
    stop("Refusing to write a zero-column provenance CSV artifact: ", path,
         call. = FALSE)
  assert_path_length_safe(path, cfg, "CSV output path")
  ensure_output_dir(dirname(path), cfg = cfg, test_write = FALSE)
  if (is.null(overwrite)) overwrite <- isTRUE(cfg$safety$allow_output_overwrite %||% FALSE)
  tf <- tempfile(pattern = paste0(".", basename(path), "_"),
                 tmpdir = dirname(path), fileext = ".tmp")
  on.exit(if (file.exists(tf)) unlink(tf, force = TRUE), add = TRUE)
  writeLines(provenance_metadata_lines(cfg, path, base_filename), con = tf,
             useBytes = TRUE)
  suppressWarnings(utils::write.table(
    xx, file = tf, sep = ",", row.names = row.names,
    col.names = TRUE, append = TRUE, qmethod = "double", na = ""))
  if (isTRUE(cfg$safety$verify_atomic_writes %||% TRUE)) {
    chk <- tryCatch(utils::read.csv(tf, stringsAsFactors = FALSE,
                                    check.names = FALSE, comment.char = "#"), error = function(e) e)
    if (inherits(chk, "error") || nrow(chk) != nrow(xx) || ncol(chk) != ncol(xx))
      stop("CSV verification failed before commit for: ", path, call. = FALSE)
  }
  atomic_commit_file(tf, path, overwrite = overwrite)
}

write_run_csv <- function(x, cfg, base_filename, row.names = FALSE) {
  path <- build_unique_path(cfg, base_filename)
  write_provenance_csv_at_path(x, cfg, path, base_filename,
                               row.names = row.names)
  invisible(path)
}


assert_file_exists <- function(path) {
  if (!file.exists(path)) stop("Required file does not exist: ", path, call. = FALSE)
}

assert_required_columns <- function(df, cols, df_name = deparse(substitute(df))) {
  missing_cols <- setdiff(cols, names(df))
  if (length(missing_cols) > 0L)
    stop(df_name, " is missing required column(s): ",
         paste(missing_cols, collapse = ", "), call. = FALSE)
}

# Lightweight stopwatch used by the pipeline runner to report per-stage time.
make_timer_log <- function() {
  e <- new.env(parent = emptyenv()); e$starts <- list(); e$elapsed <- list()
  list(
    start = function(label) { e$starts[[label]] <- proc.time()[3]; invisible(NULL) },
    stop  = function(label) {
      if (is.null(e$starts[[label]])) return(invisible(NULL))
      dt <- proc.time()[3] - e$starts[[label]]
      e$elapsed[[label]] <- (e$elapsed[[label]] %||% 0) + dt
      e$starts[[label]]  <- NULL; invisible(dt)
    },
    get = function() {
      if (length(e$elapsed) == 0L)
        return(data.frame(stage = character(0), seconds = numeric(0)))
      data.frame(stage = names(e$elapsed), seconds = unlist(e$elapsed), row.names = NULL)
    }
  )
}

to_num <- function(x) {
  x_chr <- as.character(x); x_chr <- gsub("[, ]", "", x_chr)
  suppressWarnings(as.numeric(x_chr))
}


# Convert numeric-coded vectors without using factor level numbers. For a
# factor, as.numeric(factor) returns internal level indices; converting through
# character preserves the actual Add Health values.
to_numeric_codes <- function(x) {
  if (is.factor(x) || is.character(x))
    return(suppressWarnings(as.numeric(as.character(x))))
  suppressWarnings(as.numeric(x))
}


normalize_positive_weights <- function(w, n = NULL, label = "weights") {
  if (is.null(w)) {
    if (is.null(n)) stop(label, ": n is required when weights are NULL.", call. = FALSE)
    return(rep(1, n))
  }
  w <- as.numeric(w)
  if (!is.null(n) && length(w) != n)
    stop(label, ": length mismatch.", call. = FALSE)
  if (any(!is.finite(w)) || any(w <= 0))
    stop(label, ": weights must be positive and finite.", call. = FALSE)
  mw <- mean(w)
  if (!is.finite(mw) || mw <= 0)
    stop(label, ": invalid mean weight.", call. = FALSE)
  w / mw
}

matches_any_regex <- function(x, patterns) {
  if (is.null(x) || length(x) != 1L || is.na(x) || !nzchar(x) ||
      is.null(patterns) || !length(patterns)) return(FALSE)
  any(vapply(patterns, function(p) isTRUE(grepl(p, x, perl = TRUE)), logical(1)))
}

is_forced_factor_name <- function(variable_name, cfg_pre) {
  if (is.null(variable_name) || length(variable_name) != 1L || is.na(variable_name)) return(FALSE)
  variable_name %in% (cfg_pre$long_factors %||% character(0)) ||
    any(vapply(cfg_pre$force_factor_prefixes %||% character(0),
               function(p) startsWith(variable_name, p), logical(1)))
}

is_questionnaire_source_name <- function(variable_name, cfg_pre) {
  if (is.null(variable_name) || length(variable_name) != 1L || is.na(variable_name) || !nzchar(variable_name))
    return(FALSE)
  if (variable_name %in% (cfg_pre$explicit_questionnaire_vars %||% character(0))) return(TRUE)
  if (variable_name %in% (cfg_pre$nonquestionnaire_long_factors %||% character(0))) return(FALSE)
  if (matches_any_regex(variable_name, cfg_pre$questionnaire_name_exclude_patterns %||% character(0))) return(FALSE)
  matches_any_regex(variable_name, cfg_pre$questionnaire_name_patterns %||% character(0))
}

# Generate exact conventional Add Health-style special-code families. There is
# deliberately NO suffix matching: 196 is not code 96, and 22,198 is not 98.
conventional_special_code_families <- function(cfg_pre) {
  max_digits <- as.integer(cfg_pre$auto_special_code_max_digits %||% 7L)
  max_digits <- max(2L, min(max_digits, 7L))
  out <- list(
    list(name = "low_1_digit",
         skip = as.numeric(cfg_pre$factor_skip_code_low %||% 7L),
         general = as.numeric(cfg_pre$factor_refusal_codes_low %||% c(6L, 8L, 9L)),
         digits = 1L),
    list(name = "high_2_digit",
         skip = as.numeric(cfg_pre$factor_skip_code_high %||% 97L),
         general = as.numeric(cfg_pre$factor_refusal_codes_high %||% c(96L, 98L, 99L)),
         digits = 2L)
  )
  if (max_digits >= 3L) {
    for (d in 3L:max_digits) {
      prefix <- paste(rep("9", d - 2L), collapse = "")
      codes <- suppressWarnings(as.numeric(paste0(prefix, 96:99)))
      out[[length(out) + 1L]] <- list(
        name = paste0("high_", d, "_digit"),
        skip = codes[2L], general = codes[c(1L, 3L, 4L)], digits = d)
    }
  }
  out
}

# Native missingness includes NA for every storage type and blank/whitespace-only
# values for character or factor fields. Blank text is not a substantive factor
# level and must remain missing throughout dictionary construction and fold recipes.
character_native_missing_mask <- function(x) {
  if (is.factor(x) || is.character(x)) {
    xc <- trimws(as.character(x))
    return(is.na(x) | is.na(xc) | !nzchar(xc))
  }
  if (is.numeric(x) || is.integer(x))
    return(is.na(x) | !is.finite(as.numeric(x)))
  is.na(x)
}

canonicalize_factor_text <- function(x) {
  xc <- trimws(as.character(x))
  xc[character_native_missing_mask(x)] <- NA_character_
  xc
}

assert_reserved_factor_labels_safe <- function(x, general_mask, skip_mask,
                                               reserved_labels, variable_name,
                                               context) {
  xc <- canonicalize_factor_text(x)
  substantive <- !(general_mask | skip_mask) & !is.na(xc)
  collision <- sort(unique(xc[substantive & xc %in% reserved_labels]))
  if (length(collision)) {
    stop(sprintf(
      "%s: raw variable '%s' contains substantive value(s) reserved for generated factor states: %s. Change the configured labels or explicitly recode the raw field before modeling.",
      context, variable_name, paste(collision, collapse = ", ")), call. = FALSE)
  }
  invisible(TRUE)
}

# Validate that derived numeric missingness-indicator names cannot overwrite or
# be overwritten by raw variables. The check runs before both the rough-screen
# and final-W recipes create any *_missA or *_miss97 columns.
assert_no_missing_indicator_name_collisions <- function(raw_names, numeric_names,
                                                        context = "missingness preprocessing") {
  raw_names <- unique(as.character(raw_names))
  numeric_names <- unique(intersect(as.character(numeric_names), raw_names))
  derived <- unlist(lapply(numeric_names, function(nm)
    c(paste0(nm, "_missA"), paste0(nm, "_miss97"))), use.names = FALSE)
  duplicate_derived <- unique(derived[duplicated(derived)])
  colliding_raw <- intersect(derived, raw_names)
  if (length(duplicate_derived) || length(colliding_raw)) {
    details <- c(
      if (length(colliding_raw)) paste0("raw/derived collisions: ", paste(colliding_raw, collapse = ", ")),
      if (length(duplicate_derived)) paste0("duplicate derived names: ", paste(duplicate_derived, collapse = ", "))
    )
    stop(sprintf(
      "%s cannot safely create numeric missingness indicators (%s). Rename or explicitly exclude the colliding raw variable(s).",
      context, paste(details, collapse = "; ")), call. = FALSE)
  }
  invisible(TRUE)
}

# Learn an exact-code rule from the complete outcome-blind Wave I support.
# The rule is source-informed but automated: questionnaire variable-name structure and the
# analyst's existing long-factor declarations determine where Add Health's
# questionnaire code conventions are plausible; observed support chooses the
# low (6/7/8/9), high (96/97/98/99), or wider exact family. Frequency is never
# used to reject a code, because legitimate skips can be the majority of rows.
learn_conservative_missing_rule <- function(x, cfg_pre, variable_name = NULL) {
  key <- if (length(variable_name) == 1L && !is.na(variable_name))
    canonical_role_key(variable_name) else NA_character_
  exact <- if (!is.na(key)) cfg_pre$codebook_missing_overrides[[key]] else NULL
  if (!is.null(exact)) {
    # Retain existing type inference unless the codebook specifies a type.
    fallback_cfg <- cfg_pre
    fallback_cfg$codebook_missing_overrides <- NULL
    rule <- learn_conservative_missing_rule(x, fallback_cfg, variable_name)
    if (!isTRUE(rule$numeric_coded) && any(!character_native_missing_mask(x)))
      stop("Codebook rule requires numeric codes for ", variable_name, call. = FALSE)
    rule$numeric_coded <- TRUE
    rule$general_codes <- sort(unique(as.numeric(exact$general)))
    rule$skip_codes <- sort(unique(as.numeric(exact$skip)))
    if (length(intersect(rule$general_codes, rule$skip_codes)))
      stop("Overlapping general/skip codebook codes for ", variable_name, call. = FALSE)
    if (!is.null(exact$as_factor)) rule$as_factor <- isTRUE(exact$as_factor)
    rule$recognized_families <- "codebook_exact"
    rule$scheme_decision <- "codebook_exact_override"
    rule$reason <- paste0("verified_variable_specific_codes;", exact$source)
    masks <- missing_masks_from_rule(x, rule)
    rule$n_unique_substantive <- length(unique(
      masks$numeric[!(masks$general | masks$skip)]))
    return(rule)
  }
  raw_missing <- character_native_missing_mask(x)
  x_for_parse <- x
  if (is.factor(x_for_parse) || is.character(x_for_parse)) {
    x_for_parse <- trimws(as.character(x_for_parse))
    x_for_parse[raw_missing] <- NA_character_
  }
  z <- to_numeric_codes(x_for_parse)
  nonmissing <- !raw_missing
  parsed <- nonmissing & is.finite(z)
  original_factor <- is.factor(x) || is.character(x)
  forced_factor <- is_forced_factor_name(variable_name, cfg_pre)
  questionnaire_source <- is_questionnaire_source_name(variable_name, cfg_pre)
  
  # Fully nonnumeric character/factor variables are valid categorical fields.
  # They use native NA only because numeric Add Health reserve-code families
  # cannot be inferred from text labels. A mixture of numeric and nonnumeric
  # nonmissing values is treated as a malformed field and stops loudly.
  if (any(nonmissing) && !any(parsed)) {
    vals <- trimws(as.character(x[nonmissing]))
    return(list(
      classifier = "global_source_informed_exact_v1", numeric_coded = FALSE,
      support_type = "nonnumeric_categorical", questionnaire_source = questionnaire_source,
      forced_factor = forced_factor, questionnaire_like = questionnaire_source,
      categorical_questionnaire = questionnaire_source, percentage_like = FALSE,
      dense_small_count = FALSE, as_factor = TRUE,
      general_codes = numeric(0), skip_codes = numeric(0),
      recognized_families = character(0), scheme_decision = "text_native_missing_only",
      reason = "nonnumeric_labels_native_missing_only", n_observed_raw = sum(nonmissing),
      n_finite = sum(nonmissing), n_unique_finite = length(unique(vals)),
      n_unique_substantive = length(unique(vals)), integer_like_prop = NA_real_))
  }
  bad_parse <- nonmissing & !is.finite(z)
  if (any(bad_parse)) {
    examples <- unique(as.character(x[bad_parse]))
    examples <- examples[seq_len(min(length(examples), 5L))]
    stop(sprintf(
      "Missing-code dictionary: variable %s mixes numeric codes with %d nonnumeric nonmissing value(s) (examples: %s). Exclude or explicitly transform this malformed mixed-type field.",
      variable_name %||% "<unnamed>", sum(bad_parse), paste(examples, collapse = ", ")),
      call. = FALSE)
  }
  
  empty_rule <- list(
    classifier = "global_source_informed_exact_v1",
    numeric_coded = !(original_factor && !any(nonmissing)),
    support_type = "all_missing", questionnaire_source = questionnaire_source,
    forced_factor = forced_factor, questionnaire_like = FALSE,
    categorical_questionnaire = FALSE, percentage_like = FALSE,
    dense_small_count = FALSE, as_factor = forced_factor || original_factor,
    general_codes = numeric(0), skip_codes = numeric(0),
    recognized_families = character(0), scheme_decision = "none",
    reason = "no_exact_special_code_family", n_observed_raw = sum(nonmissing),
    n_finite = sum(parsed), n_unique_finite = 0L, n_unique_substantive = 0L,
    integer_like_prop = NA_real_)
  if (!any(parsed)) return(empty_rule)
  
  zf <- z[parsed]
  tol <- cfg_pre$auto_integer_tolerance %||% 1e-8
  integer_like <- abs(zf - round(zf)) <= tol * pmax(1, abs(zf))
  integer_like_prop <- mean(integer_like)
  n_unique <- length(unique(zf))
  
  families <- conventional_special_code_families(cfg_pre)
  low_fam <- families[[1L]]
  high_fam <- families[[2L]]
  all_candidate_codes <- unique(unlist(lapply(families, function(f) c(f$general, f$skip))))
  substantive_all <- zf[!(zf %in% all_candidate_codes)]
  n_unique_substantive <- length(unique(substantive_all))
  unique_prop_substantive <- if (length(substantive_all))
    n_unique_substantive / length(substantive_all) else 0
  
  wide_codes <- unique(unlist(lapply(
    families[vapply(families, function(f) f$digits >= 3L, logical(1))],
    function(f) c(f$general, f$skip))))
  z_no_wide <- zf[!(zf %in% wide_codes)]
  pct_min <- if (length(z_no_wide)) min(z_no_wide) else NA_real_
  pct_max <- if (length(z_no_wide)) max(z_no_wide) else NA_real_
  pct_n_unique <- length(unique(z_no_wide))
  percentage_like <-
    integer_like_prop >= (cfg_pre$auto_integer_like_min_prop %||% 0.99) &&
    is.finite(pct_min) && is.finite(pct_max) && pct_min >= 0 && pct_max <= 100 &&
    pct_n_unique >= (cfg_pre$auto_percentage_min_unique %||% 20L) &&
    (pct_max - pct_min) >= (cfg_pre$auto_percentage_min_span %||% 50)
  
  z_unique_int <- sort(unique(round(zf[integer_like])))
  dense_small_count <- FALSE
  if (length(z_unique_int)) {
    lo <- min(z_unique_int); hi <- max(z_unique_int)
    dense_small_count <- lo >= 0 &&
      hi <= (cfg_pre$auto_dense_small_count_max_value %||% 20L) &&
      length(z_unique_int) >= (cfg_pre$auto_dense_small_count_min_unique %||% 8L) &&
      identical(z_unique_int, seq.int(lo, hi))
  }
  
  max_abs_substantive <- if (length(substantive_all)) max(abs(substantive_all)) else 0
  auto_categorical <-
    integer_like_prop >= (cfg_pre$auto_integer_like_min_prop %||% 0.99) &&
    max_abs_substantive <= (cfg_pre$auto_categorical_max_abs_value %||% 100) &&
    (n_unique_substantive <= (cfg_pre$factor_unique_threshold %||% 10L) ||
       (n_unique_substantive <= (cfg_pre$auto_questionnaire_max_unique %||% 30L) &&
          unique_prop_substantive <= (cfg_pre$auto_questionnaire_max_unique_prop %||% 0.01)))
  if (dense_small_count && !questionnaire_source && !forced_factor && !original_factor)
    auto_categorical <- FALSE
  
  categorical_questionnaire <-
    (questionnaire_source && (forced_factor || original_factor || auto_categorical)) ||
    (forced_factor && !(variable_name %in% (cfg_pre$nonquestionnaire_long_factors %||% character(0))))
  questionnaire_like <- questionnaire_source || categorical_questionnaire
  as_factor <- forced_factor || original_factor || auto_categorical
  
  general_codes <- numeric(0); skip_codes <- numeric(0)
  recognized <- character(0); reasons <- character(0)
  scheme_decision <- "none"
  
  obs_low <- intersect(unique(zf), c(low_fam$general, low_fam$skip))
  obs_high <- intersect(unique(zf), c(high_fam$general, high_fam$skip))
  
  # Wider exact field-width families take precedence. Only the exact family is
  # considered: 19,996 is never treated as code 9,996.
  wide_families <- families[vapply(families, function(f) f$digits >= 3L, logical(1))]
  observed_wide_families <- wide_families[vapply(
    wide_families, function(f) any(zf %in% c(f$general, f$skip)), logical(1))]
  chosen_wide <- NULL
  if ((questionnaire_source || categorical_questionnaire) && length(observed_wide_families)) {
    observed_wide_families <- observed_wide_families[
      order(vapply(observed_wide_families, function(f) f$digits, integer(1)), decreasing = TRUE)]
    for (fam in observed_wide_families) {
      fam_codes <- c(fam$general, fam$skip)
      ordinary_without_family <- zf[!(zf %in% fam_codes)]
      # A variable can be entirely skipped/nonresponding in the complete Wave I
      # support. In that case an observed exact family is still a supported
      # semantic family; there need not be an ordinary value below it.
      if (!length(ordinary_without_family) ||
          max(ordinary_without_family) < min(fam_codes)) {
        chosen_wide <- fam
        break
      }
    }
  }
  has_supported_wide <- !is.null(chosen_wide)
  
  # For low-versus-high inference, 7/8/9 are decisive evidence for the
  # low scheme. Exact 6 alone is not: Add Health items with substantive category
  # 6 use 96-99 for nonresponse, so 6 is retained when 7/8/9 are absent.
  obs_low_decisive <- intersect(unique(zf), c(7, 8, 9))
  base_low_high <- zf[!(zf %in% c(7, 8, 9,
                                  high_fam$general, high_fam$skip))]
  max_base <- if (length(base_low_high)) max(base_low_high) else NA_real_
  chosen <- NULL
  bounded_measure_protected <- percentage_like && !forced_factor && !original_factor
  if (!has_supported_wide && categorical_questionnaire && !bounded_measure_protected) {
    if (length(obs_high)) {
      chosen <- high_fam
      scheme_decision <- "high_observed_96_99"
    } else if (length(obs_low_decisive)) {
      chosen <- low_fam
      scheme_decision <- "low_observed_7_8_9"
    } else if (is.finite(max_base) && max_base <= 5) {
      chosen <- low_fam
      scheme_decision <- "low_inferred_substantive_max_le_5"
    } else if (is.finite(max_base)) {
      chosen <- high_fam
      scheme_decision <- "high_inferred_substantive_category_6_or_higher"
    }
  } else if (!has_supported_wide && questionnaire_source &&
             !percentage_like && length(obs_high)) {
    ordinary_without_high <- zf[!(zf %in% c(high_fam$general, high_fam$skip))]
    if (length(ordinary_without_high) && max(ordinary_without_high) < 96) {
      chosen <- high_fam
      scheme_decision <- "high_numeric_field_width_above_ordinary_support"
    }
  }
  if (!is.null(chosen)) {
    general_codes <- c(general_codes, chosen$general)
    skip_codes <- c(skip_codes, chosen$skip)
    recognized <- c(recognized, chosen$name)
    reasons <- c(reasons, scheme_decision)
  }
  if (!is.null(chosen_wide)) {
    general_codes <- c(general_codes, chosen_wide$general)
    skip_codes <- c(skip_codes, chosen_wide$skip)
    recognized <- c(recognized, chosen_wide$name)
    reasons <- c(reasons, paste0(chosen_wide$name, "_widest_observed_above_ordinary_support"))
  }
  
  if (!is.null(variable_name) &&
      variable_name %in% (cfg_pre$known_codebook_overlap_vars %||% character(0)) &&
      identical(cfg_pre$known_overlap_policy %||% "preserve_as_substantive",
                "preserve_as_substantive")) {
    general_codes <- numeric(0)
    skip_codes <- numeric(0)
    recognized <- character(0)
    scheme_decision <- "known_overlap_preserved"
    reasons <- c(reasons, "known_codebook_overlap_preserved_as_substantive")
  }
  
  support_type <- if (categorical_questionnaire) "categorical_questionnaire" else
    if (questionnaire_source) "questionnaire_numeric_or_count" else
      "continuous_contextual_or_other"
  
  list(
    classifier = "global_source_informed_exact_v1", numeric_coded = TRUE,
    support_type = support_type, questionnaire_source = questionnaire_source,
    forced_factor = forced_factor, questionnaire_like = questionnaire_like,
    categorical_questionnaire = categorical_questionnaire,
    percentage_like = percentage_like, dense_small_count = dense_small_count,
    as_factor = as_factor,
    general_codes = sort(unique(general_codes)),
    skip_codes = sort(unique(skip_codes)),
    recognized_families = unique(recognized), scheme_decision = scheme_decision,
    reason = if (length(reasons)) paste(unique(reasons), collapse = ";") else
      "no_exact_special_code_family",
    n_observed_raw = sum(!raw_missing), n_finite = length(zf),
    n_unique_finite = n_unique, n_unique_substantive = n_unique_substantive,
    integer_like_prop = integer_like_prop)
}


make_native_only_missing_rule <- function(x, variable_name = NULL, reason = "derived_or_unregistered_variable") {
  raw_missing <- character_native_missing_mask(x)
  x_for_parse <- x
  if (is.factor(x_for_parse) || is.character(x_for_parse)) {
    x_for_parse <- trimws(as.character(x_for_parse))
    x_for_parse[raw_missing] <- NA_character_
  }
  z <- to_numeric_codes(x_for_parse)
  nonmissing <- !raw_missing
  parsed <- nonmissing & is.finite(z)
  mixed <- any(parsed) && any(nonmissing & !is.finite(z))
  if (mixed)
    stop("Native-only missing rule received a mixed numeric/nonnumeric field for ",
         variable_name %||% "<unnamed>", ".", call. = FALSE)
  numeric_coded <- !any(nonmissing) || any(parsed)
  vals <- if (numeric_coded) z[parsed] else trimws(as.character(x[nonmissing]))
  list(
    classifier = "global_source_informed_exact_v1", numeric_coded = numeric_coded,
    support_type = "derived_or_unregistered", questionnaire_source = FALSE,
    forced_factor = FALSE, questionnaire_like = FALSE,
    categorical_questionnaire = FALSE, percentage_like = FALSE,
    dense_small_count = FALSE, as_factor = !numeric_coded || is.factor(x) || is.character(x),
    general_codes = numeric(0), skip_codes = numeric(0),
    recognized_families = character(0), scheme_decision = "none",
    reason = reason, n_observed_raw = sum(nonmissing),
    n_finite = length(vals), n_unique_finite = length(unique(vals)),
    n_unique_substantive = length(unique(vals)),
    integer_like_prop = if (numeric_coded && length(vals))
      mean(abs(vals - round(vals)) <= 1e-8 * pmax(1, abs(vals))) else NA_real_)
}

build_global_missing_code_dictionary <- function(df, vars, cfg_pre) {
  vars <- unique(vars[vars %in% names(df)])
  if (!length(vars)) stop("Global missing-code dictionary has no variables.", call. = FALSE)
  out <- setNames(vector("list", length(vars)), vars)
  for (i in seq_along(vars)) {
    nm <- vars[[i]]
    out[[nm]] <- learn_conservative_missing_rule(df[[nm]], cfg_pre, variable_name = nm)
  }
  attr(out, "dictionary_version") <- "global_source_informed_exact_v1_blank_aware"
  attr(out, "n_rows_used") <- nrow(df)
  out
}

get_missing_rule <- function(x, cfg_pre, variable_name = NULL) {
  dict <- cfg_pre$global_missing_dictionary
  if (!is.null(dict)) {
    if (!is.null(variable_name) && variable_name %in% names(dict))
      return(dict[[variable_name]])
    native_patterns <- cfg_pre$global_missing_dictionary_native_only_patterns %||% character(0)
    is_derived_native <- !is.null(variable_name) &&
      matches_any_regex(variable_name, native_patterns)
    if (is_derived_native) {
      return(make_native_only_missing_rule(
        x, variable_name,
        reason = "explicit_derived_variable_native_missing_only"))
    }
    if (isTRUE(cfg_pre$global_missing_dictionary_required %||% TRUE)) {
      stop(
        "Frozen missing-code dictionary has no rule for Wave I candidate '",
        variable_name %||% "<unnamed>",
        "'. Rebuild the Wave I/main-data caches; do not learn semantic codes inside a fold.",
        call. = FALSE)
    }
    return(make_native_only_missing_rule(
      x, variable_name,
      reason = "unregistered_variable_native_missing_only"))
  }
  # Synthetic unit-test fallback only. Production runner injects the frozen
  # dictionary before any prefilter, screen, or final-W recipe is created.
  learn_conservative_missing_rule(x, cfg_pre, variable_name = variable_name)
}

missing_dictionary_to_data_frame <- function(dictionary, df = NULL) {
  if (is.null(dictionary) || !length(dictionary)) return(data.frame())
  rows <- lapply(names(dictionary), function(nm) {
    r <- dictionary[[nm]]
    x <- if (!is.null(df) && nm %in% names(df)) df[[nm]] else NULL
    masks <- if (!is.null(x)) missing_masks_from_rule(x, r) else NULL
    data.frame(
      variable = nm,
      classifier = r$classifier %||% NA_character_,
      support_type = r$support_type %||% NA_character_,
      as_factor = isTRUE(r$as_factor),
      questionnaire_source = isTRUE(r$questionnaire_source),
      forced_factor = isTRUE(r$forced_factor),
      percentage_like = isTRUE(r$percentage_like),
      dense_small_count = isTRUE(r$dense_small_count),
      recognized_families = paste(r$recognized_families %||% character(0), collapse = ";"),
      exact_general_codes = paste(r$general_codes %||% numeric(0), collapse = ";"),
      exact_skip_codes = paste(r$skip_codes %||% numeric(0), collapse = ";"),
      scheme_decision = r$scheme_decision %||% NA_character_,
      reason = r$reason %||% NA_character_,
      n_rows_dictionary = attr(dictionary, "n_rows_used") %||% NA_integer_,
      n_observed_raw = r$n_observed_raw %||% NA_integer_,
      n_unique_finite = r$n_unique_finite %||% NA_integer_,
      n_unique_substantive = r$n_unique_substantive %||% NA_integer_,
      n_general_flagged = if (is.null(masks)) NA_integer_ else sum(masks$general),
      n_skip_flagged = if (is.null(masks)) NA_integer_ else sum(masks$skip),
      stringsAsFactors = FALSE)
  })
  do.call(rbind, rows)
}

missing_masks_from_rule <- function(x, rule) {
  native_missing <- character_native_missing_mask(x)
  x_for_parse <- x
  if (is.factor(x_for_parse) || is.character(x_for_parse)) {
    x_for_parse <- trimws(as.character(x_for_parse))
    x_for_parse[native_missing] <- NA_character_
  }
  z <- to_numeric_codes(x_for_parse)
  if (isTRUE(rule$numeric_coded)) native_missing <- native_missing | !is.finite(z)
  finite_code <- isTRUE(rule$numeric_coded) & is.finite(z)
  miss_skip <- finite_code & z %in% (rule$skip_codes %||% numeric(0))
  miss_general <- native_missing |
    (finite_code & z %in% (rule$general_codes %||% numeric(0)))
  list(general = as.logical(miss_general), skip = as.logical(miss_skip), numeric = z)
}

compute_simple_impute <- function(x, method = c("median","mean")) {
  method <- match.arg(method)
  x <- suppressWarnings(as.numeric(x)); x_ok <- x[is.finite(x)]
  if (!length(x_ok)) return(0)
  val <- if (method == "median") stats::median(x_ok, na.rm = TRUE) else mean(x_ok, na.rm = TRUE)
  if (!is.finite(val)) 0 else val
}

scale_numeric_train_valid <- function(train_df, valid_df) {
  common   <- intersect(names(train_df), names(valid_df))
  num_cols <- common[vapply(train_df[common], is.numeric, logical(1))]
  if (!length(num_cols)) return(list(train = train_df, valid = valid_df))
  for (nm in num_cols) {
    mu <- mean(train_df[[nm]], na.rm = TRUE); s <- stats::sd(train_df[[nm]], na.rm = TRUE)
    if (!is.finite(mu)) mu <- 0
    if (!is.finite(s) || s <= 0) s <- 1
    train_df[[nm]] <- (train_df[[nm]] - mu) / s
    valid_df[[nm]] <- (valid_df[[nm]] - mu) / s
  }
  list(train = train_df, valid = valid_df)
}

read_xpt_df <- function(path) {
  assert_file_exists(path)
  data.frame(haven::read_xpt(path), check.names = FALSE)
}

coerce_join_key <- function(df, key, label = deparse(substitute(df)),
                            require_complete = FALSE) {
  if (!key %in% names(df)) stop(label, " is missing join key ", key, ".", call. = FALSE)
  raw <- df[[key]]
  raw_chr <- trimws(as.character(raw))
  was_missing <- is.na(raw) | is.na(raw_chr) | raw_chr == ""
  converted <- if (is.numeric(raw) || is.integer(raw)) {
    suppressWarnings(as.numeric(raw))
  } else {
    suppressWarnings(as.numeric(raw_chr))
  }
  newly_invalid <- !was_missing & (!is.finite(converted) | is.na(converted))
  if (any(newly_invalid)) {
    examples <- unique(raw_chr[newly_invalid])
    examples <- examples[seq_len(min(length(examples), 5L))]
    stop(sprintf(
      "Join-key coercion failed: %s has %d nonmissing %s value(s) that are not finite numeric keys (examples: %s).",
      label, sum(newly_invalid), key, paste(examples, collapse = ", ")), call. = FALSE)
  }
  converted[was_missing] <- NA_real_
  df[[key]] <- converted
  if (isTRUE(require_complete) && anyNA(df[[key]])) {
    stop(sprintf("Join-cardinality check failed: master table %s has %d missing %s value(s).",
                 label, sum(is.na(df[[key]])), key), call. = FALSE)
  }
  df
}

assert_unique_key <- function(df, key, label = deparse(substitute(df)),
                              require_complete = FALSE) {
  if (!key %in% names(df)) stop(label, " is missing join key ", key, ".", call. = FALSE)
  if (isTRUE(require_complete) && anyNA(df[[key]])) {
    stop(sprintf("Join-cardinality check failed: master table %s has %d missing %s value(s).",
                 label, sum(is.na(df[[key]])), key), call. = FALSE)
  }
  key_nonmissing <- df[[key]][!is.na(df[[key]])]
  dup_n <- sum(duplicated(key_nonmissing) |
                 duplicated(key_nonmissing, fromLast = TRUE))
  if (dup_n > 0L) {
    stop(sprintf("Join-cardinality check failed: %s has %d rows with duplicated nonmissing %s values.",
                 label, dup_n, key), call. = FALSE)
  }
  invisible(TRUE)
}

left_join_unique <- function(x, y, key, x_label = "left table", y_label = "right table",
                             require_complete_x = TRUE, require_complete_y = FALSE) {
  x <- coerce_join_key(x, key, x_label, require_complete = require_complete_x)
  y <- coerce_join_key(y, key, y_label, require_complete = require_complete_y)
  assert_unique_key(x, key, x_label, require_complete = require_complete_x)
  assert_unique_key(y, key, y_label, require_complete = require_complete_y)
  n_before <- nrow(x)
  out <- dplyr::left_join(x, y, by = key, na_matches = "never")
  out_nonmissing <- out[[key]][!is.na(out[[key]])]
  if (nrow(out) != n_before || anyDuplicated(out_nonmissing) > 0L) {
    stop(sprintf("Join-cardinality check failed for %s <- %s on %s: rows %d -> %d or duplicate nonmissing keys created.",
                 x_label, y_label, key, n_before, nrow(out)), call. = FALSE)
  }
  message(sprintf("  [join audit] %s <- %s on %s (one-to-one): %d rows, %d nonmissing unique keys, %d missing left keys, %d missing right keys; no row multiplication.",
                  x_label, y_label, key, nrow(out), length(unique(out_nonmissing)),
                  sum(is.na(out[[key]])), sum(is.na(y[[key]]))))
  out
}

left_join_many_to_one <- function(x, y, key, x_label = "left table", y_label = "right table",
                                  row_id = NULL) {
  x <- coerce_join_key(x, key, x_label, require_complete = FALSE)
  y <- coerce_join_key(y, key, y_label, require_complete = FALSE)
  assert_unique_key(y, key, y_label, require_complete = FALSE)
  n_before <- nrow(x)
  if (!is.null(row_id)) {
    if (!row_id %in% names(x)) stop(x_label, " is missing row identifier ", row_id, ".", call. = FALSE)
    x <- coerce_join_key(x, row_id, x_label, require_complete = TRUE)
    assert_unique_key(x, row_id, x_label, require_complete = TRUE)
    row_order <- x[[row_id]]
  } else {
    row_order <- seq_len(n_before)
    x$.join_row_order_internal <- row_order
  }
  out <- dplyr::left_join(x, y, by = key, na_matches = "never")
  if (nrow(out) != n_before) {
    stop(sprintf("Join-cardinality check failed for %s <- %s on %s: rows %d -> %d.",
                 x_label, y_label, key, n_before, nrow(out)), call. = FALSE)
  }
  out_order <- if (!is.null(row_id)) out[[row_id]] else out$.join_row_order_internal
  if (!identical(as.character(out_order), as.character(row_order)))
    stop(sprintf("Join-cardinality check failed for %s <- %s on %s: left-row order changed.",
                 x_label, y_label, key), call. = FALSE)
  if (is.null(row_id)) out$.join_row_order_internal <- NULL
  message(sprintf("  [join audit] %s <- %s on %s (many-to-one): %d left rows, %d nonmissing left key values, %d missing left keys, %d nonmissing right keys, %d missing right keys; no row multiplication.",
                  x_label, y_label, key, nrow(out),
                  length(unique(x[[key]][!is.na(x[[key]])])), sum(is.na(x[[key]])),
                  length(unique(y[[key]][!is.na(y[[key]])])), sum(is.na(y[[key]]))))
  out
}

merge_by_key <- function(dfs, key, labels = NULL) {
  if (length(dfs) == 0L) stop("merge_by_key requires at least one data frame.", call. = FALSE)
  if (is.null(labels)) labels <- paste0("table_", seq_along(dfs))
  if (length(labels) != length(dfs)) stop("merge_by_key labels length mismatch.", call. = FALSE)
  out <- coerce_join_key(dfs[[1L]], key, labels[[1L]], require_complete = TRUE)
  assert_unique_key(out, key, labels[[1L]], require_complete = TRUE)
  if (length(dfs) > 1L) {
    for (i in 2:length(dfs)) {
      out <- left_join_unique(
        out, dfs[[i]], key,
        x_label = paste(labels[seq_len(i - 1L)], collapse = "+"),
        y_label = labels[[i]],
        require_complete_x = TRUE,
        require_complete_y = FALSE)
    }
  }
  out
}

# Safely resolve dplyr .x/.y collisions. Agreeing pairs are coalesced;
# conflicting, type-mismatched, orphan, and no-overlap pairs are retained.
join_value_observed <- function(x) {
  if (is.numeric(x) || is.integer(x)) return(is.finite(as.numeric(x)))
  !character_native_missing_mask(x)
}

join_pair_conflicts <- function(x, y, overlap, tol = 0) {
  out <- rep(FALSE, length(overlap))
  if (!any(overlap)) return(out)
  if ((is.numeric(x) || is.integer(x)) && (is.numeric(y) || is.integer(y))) {
    xv <- as.numeric(x); yv <- as.numeric(y)
    scale <- pmax(1, abs(xv), abs(yv))
    out[overlap] <- abs(xv[overlap] - yv[overlap]) > tol * scale[overlap]
  } else {
    xv <- trimws(as.character(x))
    yv <- trimws(as.character(y))
    out[overlap] <- xv[overlap] != yv[overlap]
    out[is.na(out)] <- TRUE
  }
  out
}

coalesce_join_pair <- function(x, y, fill_from_y) {
  if (!any(fill_from_y)) return(x)
  if ((is.numeric(x) || is.integer(x)) && (is.numeric(y) || is.integer(y))) {
    out <- as.numeric(x); out[fill_from_y] <- as.numeric(y)[fill_from_y]; return(out)
  }
  if (is.character(x) && is.character(y)) {
    out <- x; out[fill_from_y] <- y[fill_from_y]; return(out)
  }
  if (is.logical(x) && is.logical(y)) {
    out <- x; out[fill_from_y] <- y[fill_from_y]; return(out)
  }
  if (is.factor(x) && is.factor(y)) {
    out <- as.character(x); out[fill_from_y] <- as.character(y)[fill_from_y]
    lev <- unique(c(levels(x), levels(y), out[!is.na(out)]))
    return(factor(out, levels = lev))
  }
  NULL
}

resolve_join_suffix_collisions <- function(df, tol = 0) {
  y_cols <- grep("\\.y$", names(df), value = TRUE)
  audit_rows <- list(); drop_cols <- character(0)
  if (!length(y_cols)) return(list(data = df, audit = data.frame()))
  for (y_nm in y_cols) {
    base_nm <- sub("\\.y$", "", y_nm)
    x_nm <- paste0(base_nm, ".x")
    action <- "retained_orphan_y"
    n_x_obs <- n_y_obs <- n_overlap <- n_conflict <- n_y_only <- n_filled <- 0L
    examples <- ""
    if (x_nm %in% names(df)) {
      x <- df[[x_nm]]; y <- df[[y_nm]]
      obs_x <- join_value_observed(x); obs_y <- join_value_observed(y)
      overlap <- obs_x & obs_y
      conflict <- join_pair_conflicts(x, y, overlap, tol = tol)
      n_x_obs <- sum(obs_x); n_y_obs <- sum(obs_y)
      n_overlap <- sum(overlap); n_conflict <- sum(conflict)
      fill_from_y <- !obs_x & obs_y; n_y_only <- sum(fill_from_y)
      if (n_conflict > 0L) {
        ex_idx <- which(conflict)[seq_len(min(n_conflict, 5L))]
        examples <- paste(sprintf("row%s:%s!=%s", ex_idx,
                                  as.character(x[ex_idx]), as.character(y[ex_idx])),
                          collapse = " | ")
        action <- "retained_conflicting_pair"
      } else if (n_y_obs == 0L) {
        drop_cols <- c(drop_cols, y_nm); action <- "dropped_all_missing_y"
      } else if (n_x_obs == 0L) {
        merged <- coalesce_join_pair(x, y, fill_from_y)
        if (is.null(merged)) action <- "retained_type_mismatch" else {
          df[[x_nm]] <- merged; drop_cols <- c(drop_cols, y_nm)
          n_filled <- n_y_only
          action <- "replaced_all_missing_x_from_y"
        }
      } else if (n_overlap > 0L) {
        merged <- coalesce_join_pair(x, y, fill_from_y)
        if (is.null(merged)) action <- "retained_type_mismatch" else {
          df[[x_nm]] <- merged; drop_cols <- c(drop_cols, y_nm)
          n_filled <- n_y_only
          action <- "coalesced_agreeing_pair"
        }
      } else {
        action <- "retained_no_overlap_to_verify"
      }
    } else {
      n_y_obs <- sum(join_value_observed(df[[y_nm]]))
    }
    audit_rows[[length(audit_rows) + 1L]] <- data.frame(
      base_name = base_nm, x_column = if (x_nm %in% names(df)) x_nm else NA_character_,
      y_column = y_nm, n_x_observed = n_x_obs, n_y_observed = n_y_obs,
      n_overlap = n_overlap, n_conflicts = n_conflict,
      n_y_only = n_y_only, n_filled_from_y = n_filled, action = action,
      conflict_examples = examples, stringsAsFactors = FALSE)
  }
  if (length(drop_cols)) df <- df[, !names(df) %in% unique(drop_cols), drop = FALSE]
  list(data = df, audit = do.call(rbind, audit_rows))
}

safe_remove_cols <- function(df, pattern) {
  idx <- grep(pattern, names(df))
  if (length(idx) > 0L) df <- df[, -idx, drop = FALSE]
  df
}

remove_constant_columns <- function(df, tol = 1e-10, verbose = TRUE) {
  if (ncol(df) == 0L) return(df)
  is_constant <- vapply(df, function(col) {
    col_clean <- col[!is.na(col)]
    if (length(col_clean) < 2L) return(TRUE)
    if (is.factor(col_clean)) return(length(unique(col_clean)) < 2L)
    if (is.numeric(col_clean) || is.integer(col_clean)) {
      vv <- stats::var(as.numeric(col_clean))
      return(!is.finite(vv) || vv < tol)
    }
    length(unique(col_clean)) < 2L
  }, logical(1))
  n_const <- sum(is_constant)
  if (n_const > 0L && isTRUE(verbose))
    message(sprintf("[Safety] Removing %d constant columns", n_const))
  df[, !is_constant, drop = FALSE]
}

safe_scale <- function(x, eps = 1e-12) {
  if (!(is.numeric(x) || is.integer(x))) return(x)
  x <- as.numeric(x); x[!is.finite(x)] <- NA_real_
  s <- stats::sd(x, na.rm = TRUE)
  if (is.na(s) || s < eps) return(rep(0, length(x)))
  (x - mean(x, na.rm = TRUE)) / s
}

# Keep only letters, digits, and underscores in a single atomic string piece.
sanitize_piece <- function(x) {
  x <- as.character(x); x[is.na(x)] <- "NA"
  x <- gsub("[^A-Za-z0-9]+", "_", x); x <- gsub("^_+|_+$", "", x)
  x[x == ""] <- "blank"; x
}

# Sanitizes processed design-matrix column names. Special characters in
# column names (dots, spaces, parens) otherwise leak into SL formulas and
# produce inscrutable errors.
sanitize_column_names <- function(df) {
  clean_names <- gsub("[^A-Za-z0-9_]", "_", names(df))
  clean_names <- make.unique(clean_names)
  old_to_new  <- setNames(clean_names, names(df))
  names(df)   <- clean_names
  list(data = df, old_to_new = old_to_new)
}

# v5.1: Convert all factor columns to dummy (indicator) variables so that
# every learner in the SuperLearner library receives pure numeric input.
# Without this, as.matrix on a mixed data.frame coerces the entire matrix
# to character, which crashes xgboost and inflates memory by ~10x.
# Factors are expanded one column at a time rather than via a single
# model.matrix(~ ., data) call, because the latter overflows R's protect
# stack when the data.frame has hundreds of factor columns.
expand_factors_to_numeric <- function(df) {
  fac_cols <- names(df)[vapply(df, is.factor, logical(1))]
  if (length(fac_cols) == 0L) return(df)
  num_part <- df[, !names(df) %in% fac_cols, drop = FALSE]
  dummy_parts <- list()
  for (fn in fac_cols) {
    f <- df[[fn]]
    levs <- levels(f)
    if (length(levs) < 2L) next
    # Treatment coding: drop first level as reference to avoid collinearity
    # in GLM-based learners. Tree-based learners (ranger, xgboost) are
    # unaffected by the choice of reference level.
    mm_full <- stats::model.matrix(~ f, data = data.frame(f = f), na.action = stats::na.pass)
    if (nrow(mm_full) != length(f)) stop(sprintf("expand_factors_to_numeric(): factor '%s' produced %d rows but expected %d.", fn, nrow(mm_full), length(f)), call. = FALSE)
    mm <- mm_full[, -1L, drop = FALSE]
    colnames(mm) <- paste0(fn, "_", levs[-1L])
    dummy_parts[[fn]] <- mm
  }
  if (length(dummy_parts) == 0L) return(num_part)
  # v6: ensure data.frame return type. cbind(data.frame, matrix) can return
  # a matrix under R's method dispatch, which crashes earth's formula path.
  out <- cbind(num_part, do.call(cbind, dummy_parts))
  if (!is.data.frame(out)) out <- as.data.frame(out, stringsAsFactors = FALSE)
  out
}

compute_earnings <- function(h4ec2, h4ec3, cfg_outcome) {
  if (length(h4ec2) != length(h4ec3))
    stop("Exact and bracket earnings variables must have the same length.", call. = FALSE)
  exact   <- suppressWarnings(as.numeric(as.character(h4ec2)))
  bracket <- suppressWarnings(as.numeric(as.character(h4ec3)))
  
  valid_exact <- is.finite(exact) &
    exact >= (cfg_outcome$exact_valid_min %||% 0) &
    exact <= (cfg_outcome$exact_valid_max %||% 999995)
  known_exact_missing <- is.na(exact) | exact %in% (cfg_outcome$exact_missing_codes %||% numeric(0))
  unexpected_exact <- sort(unique(exact[is.finite(exact) & !valid_exact & !known_exact_missing]))
  if (length(unexpected_exact) > 0L) {
    stop("Unexpected finite exact-earnings code(s): ",
         paste(unexpected_exact, collapse = ", "), call. = FALSE)
  }
  
  valid_bracket_codes <- as.numeric(cfg_outcome$bracket_valid_codes %||% names(cfg_outcome$bracket_map))
  valid_bracket <- is.finite(bracket) & bracket %in% valid_bracket_codes
  known_bracket_missing <- is.na(bracket) |
    bracket %in% (cfg_outcome$bracket_missing_codes %||% numeric(0))
  unexpected_bracket <- sort(unique(bracket[is.finite(bracket) & !valid_bracket & !known_bracket_missing]))
  if (length(unexpected_bracket) > 0L) {
    stop("Unexpected finite bracket-earnings code(s): ",
         paste(unexpected_bracket, collapse = ", "), call. = FALSE)
  }
  
  out <- rep(NA_real_, length(exact))
  source <- rep("missing_both", length(exact))
  out[valid_exact] <- exact[valid_exact]
  source[valid_exact] <- "exact"
  use_bracket <- !valid_exact & valid_bracket
  out[use_bracket] <- unname(cfg_outcome$bracket_map[as.character(bracket[use_bracket])])
  source[use_bracket] <- "bracket_midpoint"
  source[!valid_exact & !valid_bracket & known_exact_missing] <- "exact_missing_no_valid_bracket"
  
  audit <- data.frame(
    metric = c("n_total", "n_exact_valid", "n_zero_exact", "n_exact_missing_code",
               "n_bracket_substituted", "n_missing_after_both", "n_top_open_bracket"),
    value = c(length(out), sum(valid_exact), sum(valid_exact & exact == 0),
              sum(is.finite(exact) & exact %in% (cfg_outcome$exact_missing_codes %||% numeric(0))),
              sum(use_bracket), sum(!is.finite(out)),
              sum(use_bracket & bracket == max(valid_bracket_codes, na.rm = TRUE))),
    stringsAsFactors = FALSE)
  bracket_counts <- as.data.frame(table(factor(bracket[use_bracket], levels = valid_bracket_codes)))
  names(bracket_counts) <- c("bracket_code", "value")
  bracket_counts$metric <- paste0("n_bracket_code_", bracket_counts$bracket_code)
  audit <- rbind(audit, bracket_counts[, c("metric", "value")])
  list(earnings = out, source = source, audit = audit,
       exact = exact, bracket = bracket)
}

detect_binary01 <- function(x) {
  missing <- character_native_missing_mask(x)
  if (all(missing)) return(FALSE)
  if (is.logical(x)) return(TRUE)
  z <- to_num(x)
  if (any(!missing & !is.finite(z))) return(FALSE)
  ux <- sort(unique(as.numeric(z[!missing & is.finite(z)])))
  identical(ux, c(0, 1))
}

infer_variable_type <- function(x, requested = "auto", name = "variable") {
  if (!requested %in% c("auto","binary","continuous"))
    stop("Requested type for ", name, " must be 'auto', 'binary', or 'continuous'.", call. = FALSE)
  if (requested != "auto") return(requested)
  if (detect_binary01(x)) "binary" else "continuous"
}

normalize_binary_var <- function(x, name = "variable", require_both = TRUE) {
  missing <- character_native_missing_mask(x)
  if (any(missing))
    stop(name, " contains missing or blank values; binary variable must be fully observed here.", call. = FALSE)
  z <- if (is.logical(x)) as.integer(x) else to_num(x)
  if (any(!is.finite(z)))
    stop(name, " must be explicitly coded numeric 0/1; arbitrary text-level ordering is not allowed.", call. = FALSE)
  ux <- sort(unique(as.numeric(z)))
  if (!length(ux) || any(!ux %in% c(0, 1)) ||
      (isTRUE(require_both) && !identical(ux, c(0, 1)))) {
    requirement <- if (isTRUE(require_both)) "contain both explicitly coded values 0 and 1" else
      "contain only explicitly coded values 0 and/or 1"
    stop(name, " must ", requirement, ".", call. = FALSE)
  }
  as.integer(z)
}

normalize_binary_allow_missing <- function(x, name = "variable") {
  missing <- character_native_missing_mask(x)
  out <- rep(NA_integer_, length(x))
  keep <- !missing
  if (!any(keep)) return(out)
  # Binary outcomes and observation indicators may legitimately be constant in
  # the full data (for example, a completely observed outcome). Coding validity
  # is separate from the later learner-specific requirement for both classes.
  out[keep] <- normalize_binary_var(x[keep], name, require_both = FALSE)
  out
}

make_observed_mask <- function(x) {
  if (is.numeric(x) || is.integer(x)) is.finite(x) else !character_native_missing_mask(x)
}

prepare_modeled_outcome <- function(x, requested = "auto", name = "outcome") {
  type <- infer_variable_type(x, requested, name)
  if (identical(type, "binary")) {
    values <- normalize_binary_allow_missing(x, name)
  } else {
    missing <- character_native_missing_mask(x)
    values <- to_num(x)
    bad <- !missing & !is.finite(values)
    if (any(bad)) {
      examples <- unique(trimws(as.character(x[bad])))
      examples <- examples[seq_len(min(length(examples), 5L))]
      stop(sprintf("%s contains %d observed nonnumeric value(s) (examples: %s).",
                   name, sum(bad), paste(examples, collapse = ", ")), call. = FALSE)
    }
    values[missing | !is.finite(values)] <- NA_real_
  }
  list(values = values, type = type, observed = make_observed_mask(values))
}

# Identify the "knee" in a ranked score curve - the point of diminishing
# returns, used as the rough-prescreen cutoff.
make_knee_cutoff <- function(scores) {
  s <- sort(scores, decreasing = TRUE, na.last = NA)
  if (length(s) == 0L) stop("Cannot compute knee cutoff from empty score vector.", call. = FALSE)
  if (length(s) == 1L || isTRUE(all.equal(max(s), min(s))))
    return(list(sorted_scores = s, rank = 1L, value = s[1L]))
  x  <- seq_along(s)
  xn <- (x - x[1]) / (x[length(x)] - x[1])
  yn <- (s - s[length(s)]) / (s[1] - s[length(s)])
  d  <- abs(yn - (1 - xn)) / sqrt(2)
  knee_rank <- which.max(d)
  list(sorted_scores = s, rank = knee_rank, value = s[knee_rank])
}

plot_knee_curve <- function(knee_obj, label_y = "Score") {
  s <- knee_obj$sorted_scores
  plot(s, type = "l", xlab = "Rank best -> worst", ylab = label_y)
  text(knee_obj$rank, knee_obj$value + 0.02,
       labels = sprintf("Cutoff = %.4f (rank %d)", knee_obj$value, knee_obj$rank),
       pos = 4, xpd = NA)
}

# v5.1: Harmonize cutoff_rule and the legacy use_knee_cutoff toggle.
# Precedence: explicit cutoff_rule wins; otherwise fall back to legacy toggle.
resolve_cutoff_rule <- function(rp_cfg) {
  if (!is.null(rp_cfg$cutoff_rule)) return(rp_cfg$cutoff_rule)
  if (isTRUE(rp_cfg$use_knee_cutoff))  return("knee")
  if (identical(rp_cfg$use_knee_cutoff, FALSE)) {
    warning("use_knee_cutoff = FALSE is ambiguous; defaulting to cutoff_rule = 'positive'. ",
            "Set cfg$rough_prescreen$cutoff_rule explicitly to silence this.")
    return("positive")
  }
  "knee"
}

# v5.1: Unified cutoff application for the rough prescreen.
# "positive" keeps variables that beat the null model (score > min_score).
# "knee" uses the geometric knee on the sorted-score curve.
# "topk" keeps the top max_keep variables by score.
# max_keep is applied as a safety cap regardless of rule.
apply_cutoff <- function(scores, knee, rule, min_score = 0, max_keep = 2000L) {
  s <- sort(scores[is.finite(scores)], decreasing = TRUE)
  kept <- switch(rule,
                 "knee"     = s[s >= knee$value],
                 "positive" = s[s >  min_score],
                 "topk"     = s[seq_len(min(length(s), max_keep))],
                 s[s >= knee$value])
  if (length(kept) > max_keep) kept <- kept[seq_len(max_keep)]
  kept
}


# =============================================================================
# 3) BASE DATA CONSTRUCTION
# =============================================================================
# Plain-English role: read the Add Health .xpt files, join them on AID/PSUSCID,
# then build the exposure (depression) and outcome (raw annual earnings) from raw
# items. Everything downstream starts from the single main_df produced here.

canonical_join_variable_name <- function(x) {
  x <- trimws(as.character(x))
  sub("(?:\\.[xy])+$", "", x, perl = TRUE)
}

canonical_role_key <- function(x) {
  toupper(canonical_join_variable_name(x))
}

empty_variable_source_registry <- function() {
  data.frame(
    source = character(0),
    raw_variable = character(0),
    canonical_variable = character(0),
    derived_from = character(0),
    stringsAsFactors = FALSE)
}

validate_variable_source_registry <- function(registry, label = "variable source registry") {
  required <- names(empty_variable_source_registry())
  if (!is.data.frame(registry))
    stop(label, " must be a data frame.", call. = FALSE)
  missing_cols <- setdiff(required, names(registry))
  if (length(missing_cols))
    stop(label, " is missing required column(s): ",
         paste(missing_cols, collapse = ", "), call. = FALSE)
  registry <- registry[, required, drop = FALSE]
  if (!nrow(registry)) return(registry)
  
  for (nm in required) registry[[nm]] <- as.character(registry[[nm]])
  if (anyNA(registry$source) || any(!nzchar(trimws(registry$source))) ||
      anyNA(registry$raw_variable) || any(!nzchar(trimws(registry$raw_variable))) ||
      anyNA(registry$canonical_variable) ||
      any(!nzchar(trimws(registry$canonical_variable))))
    stop(label, " contains missing or blank required values.", call. = FALSE)
  
  expected_canonical <- canonical_join_variable_name(registry$raw_variable)
  bad_canonical <- which(toupper(registry$canonical_variable) != toupper(expected_canonical))
  if (length(bad_canonical)) {
    ii <- head(bad_canonical, 8L)
    stop(sprintf(
      "%s has canonical-name mismatches, for example: %s.",
      label, paste(sprintf("%s->%s (expected %s)",
                           registry$raw_variable[ii], registry$canonical_variable[ii],
                           expected_canonical[ii]), collapse = "; ")), call. = FALSE)
  }
  
  key <- paste(toupper(trimws(registry$source)),
               toupper(trimws(registry$raw_variable)), sep = "::")
  duplicate_keys <- unique(key[duplicated(key)])
  if (length(duplicate_keys)) {
    for (kk in duplicate_keys) {
      d <- registry[key == kk, , drop = FALSE]
      signatures <- paste(d$canonical_variable,
                          ifelse(is.na(d$derived_from), "", d$derived_from), sep = "|")
      if (length(unique(signatures)) > 1L)
        stop(label, " contains conflicting duplicate source/raw-variable records for ",
             kk, ".", call. = FALSE)
    }
    registry <- registry[!duplicated(key), , drop = FALSE]
    rownames(registry) <- NULL
  }
  registry
}

get_variable_source_registry <- function(df, cfg, required = TRUE) {
  registry <- attr(df, "variable_source_registry")
  if (is.null(registry)) registry <- cfg$preprocessing$variable_source_registry %||% NULL
  if (is.null(registry)) {
    if (isTRUE(required))
      stop("The descriptive variable-source registry is absent; rebuild the cache with this pipeline version.",
           call. = FALSE)
    return(empty_variable_source_registry())
  }
  validate_variable_source_registry(registry)
}

# Resolves cfg$final_tmle$protected_W through cfg$analysis$protected_W_mode.
# "items" = H1FS1-19 (status quo); "summary" = MHSum_W1; "both" = union.
# Returning a non-empty vector in every mode keeps the raw-variable provenance
# audits populated, which is why no mode yields character(0).
resolve_protected_W <- function(cfg) {
  mode <- cfg$analysis$protected_W_mode %||% "items"
  if (!mode %in% c("items", "summary", "both"))
    stop("cfg$analysis$protected_W_mode must be items, summary or both.",
         call. = FALSE)
  items <- as.character(cfg$final_tmle$protected_W_items %||% paste0("H1FS", 1:19))
  summ  <- as.character(cfg$final_tmle$protected_W_summary %||% "MHSum_W1")
  switch(mode, items = items, summary = summ, both = unique(c(items, summ)))
}

get_mandatory_W <- function(cfg) {
  additional <- trimws(as.character(
    cfg$causal_governance$additional_mandatory_W %||% character(0)))
  additional <- additional[!is.na(additional) & nzchar(additional)]
  unique(c(as.character(resolve_protected_W(cfg)), additional))
}

score_wave1_cesd <- function(df) {
  items <- paste0("H1FS", 1:19)
  assert_required_columns(df, items, "Wave-I CES-D scoring")
  x <- vapply(items, function(nm) to_numeric_codes(df[[nm]]), numeric(nrow(df)))
  x <- matrix(x, nrow = nrow(df), ncol = 19L)
  x[!is.finite(x) | !x %in% 0:3] <- NA_real_
  x[, c(4L, 8L, 11L, 15L)] <- 3 - x[, c(4L, 8L, 11L, 15L), drop = FALSE]
  rowSums(x, na.rm = FALSE)
}


# =============================================================================
# v8.44 EXPOSURE-SCOPE MODES (Wave-III bridge and durable comparison group)
# =============================================================================
exposure_scope_mode <- function(cfg) cfg$exposure$exposure_mode %||% "wave2_only"

validate_exposure_mode_cfg <- function(cfg) {
  mode <- exposure_scope_mode(cfg)
  if (!is.character(mode) || length(mode) != 1L || is.na(mode) ||
      !mode %in% c("wave2_only", "wave3_complete", "durable_control"))
    stop("exposure$exposure_mode must be wave2_only, wave3_complete or durable_control.",
         call. = FALSE)
  if (identical(mode, "wave2_only")) return(invisible(TRUE))
  ex <- cfg$exposure
  items <- ex$wave3_cesd_items; rv <- ex$wave3_cesd_reverse_items
  miss <- ex$wave3_cesd_missing_codes; cut <- ex$wave3_cesd_cutpoint
  if (!is.character(items) || length(items) < 2L || anyNA(items) ||
      any(!nzchar(items)) || anyDuplicated(items))
    stop("exposure$wave3_cesd_items must be unique nonblank item names.", call. = FALSE)
  if (!is.character(rv) || anyNA(rv) || anyDuplicated(rv) || !all(rv %in% items))
    stop("exposure$wave3_cesd_reverse_items must be a subset of wave3_cesd_items.", call. = FALSE)
  if (!is.numeric(miss) || any(!is.finite(miss)) || any(miss %in% 0:3))
    stop("exposure$wave3_cesd_missing_codes must be finite reserve codes outside 0:3.", call. = FALSE)
  if (!is.numeric(cut) || length(cut) != 1L || !is.finite(cut) ||
      cut < 1 || cut > 3 * length(items))
    stop("exposure$wave3_cesd_cutpoint is outside the scale range.", call. = FALSE)
  if (is.null(cfg$paths$wave3_inhome) || !nzchar(cfg$paths$wave3_inhome))
    stop("exposure_mode '", mode, "' requires cfg$paths$wave3_inhome.", call. = FALSE)
  if (!all(items %in% (ex$drop_from_candidates %||% character(0))))
    stop("Wave-III exposure items must be listed in exposure$drop_from_candidates.", call. = FALSE)
  # Prevalence in the restricted sample is not the population prevalence, so a
  # prevalence elasticity computed here would be mislabelled.
  if (isTRUE(cfg$policy$enable_att_prevalence_translation %||% TRUE))
    stop("exposure_mode '", mode, "' requires policy$enable_att_prevalence_translation=FALSE; ",
         "the prevalence-based policy translation belongs to the wave2_only analysis.",
         call. = FALSE)
  invisible(TRUE)
}

# Complete-scale Wave-III indicator aligned to `ids`. NA = not interviewed at
# Wave III or any item missing/refused; no item is prorated or imputed.
score_wave3_depression <- function(ids, w3, cfg) {
  id <- cfg$analysis$id_var
  items <- as.character(cfg$exposure$wave3_cesd_items)
  assert_required_columns(w3, c(id, items), "Wave-III Feelings Scale")
  w3 <- w3[, c(id, items), drop = FALSE]
  w3 <- coerce_join_key(w3, id, "Wave-III Feelings Scale", require_complete = TRUE)
  assert_unique_key(w3, id, "Wave-III Feelings Scale", require_complete = TRUE)
  key <- coerce_join_key(stats::setNames(data.frame(ids, stringsAsFactors = FALSE), id),
                         id, "exposure-scope analytic sample", require_complete = TRUE)[[id]]
  if (anyDuplicated(key)) stop("Exposure-scope analytic IDs are duplicated.", call. = FALSE)
  ix <- match(key, w3[[id]])
  known <- c(0:3, as.numeric(cfg$exposure$wave3_cesd_missing_codes))
  x <- vapply(items, function(nm) {
    assert_only_known_codes(w3[[nm]], known, nm)
    to_numeric_codes(w3[[nm]])[ix]
  }, numeric(length(key)))
  x <- matrix(x, nrow = length(key), ncol = length(items), dimnames = list(NULL, items))
  x[!is.finite(x) | !x %in% 0:3] <- NA_real_
  rv <- as.character(cfg$exposure$wave3_cesd_reverse_items)
  if (length(rv)) x[, rv] <- 3 - x[, rv, drop = FALSE]
  total <- rowSums(x, na.rm = FALSE)
  list(interviewed = !is.na(ix), total = total,
       positive = as.integer(total >= as.numeric(cfg$exposure$wave3_cesd_cutpoint)))
}

# Restrict the analytic sample for a non-default exposure scope. The Wave-II
# exposure column is returned unchanged; no Wave-III value is kept in the data.
apply_exposure_mode_scope <- function(df, cfg, w3 = NULL) {
  mode <- exposure_scope_mode(cfg)
  if (identical(mode, "wave2_only")) return(list(data = df, audit = NULL))
  if (!mode %in% c("wave3_complete", "durable_control"))
    stop("Unknown exposure_mode.", call. = FALSE)
  id <- cfg$analysis$id_var; av <- cfg$analysis$exposure_var; wv <- cfg$analysis$weight_var
  assert_required_columns(df, c(id, av, wv), "exposure-scope analytic sample")
  if (is.null(w3)) w3 <- read_wave_inhome(3L, cfg)
  sc <- score_wave3_depression(df[[id]], w3, cfg)
  a2 <- normalize_binary_var(df[[av]], "Wave-II exposure")
  d3 <- sc$positive
  complete <- !is.na(d3)
  # is.na() is tested explicitly in BOTH arms: an unknown Wave-III status can
  # never be kept in one arm and dropped from the other.
  keep <- if (identical(mode, "durable_control")) complete & (a2 == 1L | d3 == 0L) else complete
  w <- suppressWarnings(as.numeric(df[[wv]]))
  if (any(!is.finite(w) | w <= 0)) stop("Exposure scope requires valid survey weights.", call. = FALSE)
  cell <- function(a, d) sum(complete & a2 == a & d3 == d)
  out <- df[keep, , drop = FALSE]
  a_out <- a2[keep]
  audit <- data.frame(
    exposure_mode = mode,
    wave3_items = paste(cfg$exposure$wave3_cesd_items, collapse = ";"),
    wave3_cutpoint = as.numeric(cfg$exposure$wave3_cesd_cutpoint),
    n_before = nrow(df), exposed_before = sum(a2 == 1L), comparison_before = sum(a2 == 0L),
    n_wave3_interviewed = sum(sc$interviewed),
    n_wave3_scale_complete = sum(complete),
    n_wave3_scale_incomplete_exposed = sum(!complete & a2 == 1L),
    n_wave3_scale_incomplete_comparison = sum(!complete & a2 == 0L),
    n_w2pos_w3pos = cell(1L, 1L), n_w2pos_w3neg = cell(1L, 0L),
    n_w2neg_w3neg = cell(0L, 0L), n_w2neg_w3pos = cell(0L, 1L),
    weighted_wave3_positive_among_complete =
      if (any(complete)) sum(w[complete] * d3[complete]) / sum(w[complete]) else NA_real_,
    n_retained = nrow(out), exposed_retained = sum(a_out == 1L),
    comparison_retained = sum(a_out == 0L),
    exposure_reassigned = FALSE,
    scope_note = if (identical(mode, "durable_control"))
      "comparison arm conditioned on a post-exposure Wave-III measurement; secondary contrast" else
      "Wave-III scale completers; exposure contrast unchanged (bridge)",
    stringsAsFactors = FALSE)
  # Arithmetic gates: the exposed arm can only lose Wave-III non-completers,
  # and the durable comparison arm must be exactly the negative-negative cell.
  if (audit$exposed_retained != audit$n_w2pos_w3pos + audit$n_w2pos_w3neg ||
      audit$comparison_retained != audit$n_w2neg_w3neg +
        (if (identical(mode, "wave3_complete")) audit$n_w2neg_w3pos else 0L) ||
      audit$exposed_retained > audit$exposed_before ||
      !identical(as.integer(out[[av]]), as.integer(a_out)))
    stop("Exposure-scope restriction failed its cell-count reconciliation.", call. = FALSE)
  if (audit$exposed_retained < 1L || audit$comparison_retained < 1L)
    stop("Exposure-scope restriction left an empty exposure arm.", call. = FALSE)
  if (any(names(out) %in% cfg$exposure$wave3_cesd_items))
    stop("Wave-III exposure items must not be stored in the analytic data.", call. = FALSE)
  list(data = out, audit = audit)
}

run_exposure_mode_self_test <- function(cfg_template) {
  fail <- function(expr) inherits(try(force(expr), silent = TRUE), "try-error")
  # Independent of the scope requested for the surrounding run.
  cfg_template$exposure$exposure_mode <- "wave2_only"
  cc <- cfg_template
  id <- cc$analysis$id_var; av <- cc$analysis$exposure_var; wv <- cc$analysis$weight_var
  items <- cc$exposure$wave3_cesd_items
  stopifnot(identical(exposure_scope_mode(cc), "wave2_only"))
  validate_exposure_mode_cfg(cc)
  d <- data.frame(id = as.character(1:10), a = c(1L,1L,1L,1L,0L,0L,0L,0L,0L,1L),
                  w = c(2,1,1,1,3,1,1,1,1,1), keepme = 101:110, stringsAsFactors = FALSE)
  names(d)[1:3] <- c(id, av, wv)
  stopifnot(identical(apply_exposure_mode_scope(d, cc, w3 = NULL)$data, d))
  # Wave-III rows: IDs 4 and 9 not interviewed; ID 3 and 8 have one missing item.
  mk <- function(total_per_row) {
    z <- as.data.frame(matrix(0, length(total_per_row), length(items)))
    names(z) <- items
    # reverse-keyed items are stored reversed: stored 3 scores 0
    rv <- cc$exposure$wave3_cesd_reverse_items
    for (r in rv) z[[r]] <- 3
    plain <- setdiff(items, rv)
    for (i in seq_along(total_per_row)) {
      left <- total_per_row[i]; j <- 1L
      while (left > 0) { add <- min(3, left); z[i, plain[j]] <- add; left <- left - add; j <- j + 1L }
    }
    z
  }
  ids3 <- c(1, 2, 3, 5, 6, 7, 8, 10)
  w3 <- cbind(stats::setNames(data.frame(as.character(ids3)), id),
              mk(c(20, 0, 15, 0, 12, 11, 0, 12)))
  w3[w3[[id]] == "3", items[1L]] <- 8      # don't know -> incomplete
  w3[w3[[id]] == "8", items[2L]] <- NA     # native missing -> incomplete
  sc <- score_wave3_depression(d[[id]], w3[nrow(w3):1, , drop = FALSE], cc)
  stopifnot(identical(sc$positive, c(1L, 0L, NA, NA, 0L, 1L, 0L, NA, NA, 1L)),
            identical(sc$interviewed, c(TRUE,TRUE,TRUE,FALSE,TRUE,TRUE,TRUE,TRUE,FALSE,TRUE)))
  # cutpoint boundary: 11 is negative, 12 positive
  stopifnot(sc$total[7L] == 11, sc$total[6L] == 12)
  cc$policy$enable_att_prevalence_translation <- FALSE
  cc$exposure$exposure_mode <- "durable_control"
  validate_exposure_mode_cfg(cc)
  z <- apply_exposure_mode_scope(d, cc, w3)
  # exposed 1,2,10 kept (3,4 incomplete); comparison 5,7 kept; 6 Wave-III-only dropped;
  # 8 incomplete and 9 not interviewed dropped from the comparison arm too.
  stopifnot(identical(z$data[[id]], c("1", "2", "5", "7", "10")),
            identical(z$data[[av]], c(1L, 1L, 0L, 0L, 1L)),
            identical(z$data$keepme, c(101L, 102L, 105L, 107L, 110L)),
            z$audit$n_w2pos_w3pos == 2L, z$audit$n_w2pos_w3neg == 1L,
            z$audit$n_w2neg_w3neg == 2L, z$audit$n_w2neg_w3pos == 1L,
            z$audit$n_wave3_scale_incomplete_exposed == 2L,
            z$audit$n_wave3_scale_incomplete_comparison == 2L,
            z$audit$exposed_retained == 3L, z$audit$comparison_retained == 2L,
            !any(items %in% names(z$data)))
  cc$exposure$exposure_mode <- "wave3_complete"
  b <- apply_exposure_mode_scope(d, cc, w3)
  stopifnot(identical(b$data[[id]], c("1", "2", "5", "6", "7", "10")),
            b$audit$comparison_retained == 3L, b$audit$exposed_retained == 3L)
  # same exposed arm in the bridge and the durable analysis, by construction
  stopifnot(identical(b$data[[id]][b$data[[av]] == 1L], z$data[[id]][z$data[[av]] == 1L]))
  # row order of the Wave-III file cannot matter; unknown codes and duplicates stop
  stopifnot(identical(apply_exposure_mode_scope(d, cc, w3[rev(seq_len(nrow(w3))), , drop = FALSE])$data, b$data))
  bad <- w3; bad[1L, items[3L]] <- 5
  stopifnot(fail(apply_exposure_mode_scope(d, cc, bad)),
            fail(apply_exposure_mode_scope(d, cc, rbind(w3, w3[1L, , drop = FALSE]))))
  # configuration guards
  g <- cc; g$policy$enable_att_prevalence_translation <- TRUE
  stopifnot(fail(validate_exposure_mode_cfg(g)))
  g <- cc; g$exposure$drop_from_candidates <- setdiff(g$exposure$drop_from_candidates, items[1L])
  stopifnot(fail(validate_exposure_mode_cfg(g)))
  g <- cc; g$exposure$exposure_mode <- "wave3_only"
  stopifnot(fail(validate_exposure_mode_cfg(g)))
  # Wave-III items can never be candidate confounders, even if a column survives
  leak <- d; leak[[items[1L]]] <- 0
  leak_reg <- unique(c("keepme", get_mandatory_W(cc)))
  for (m in setdiff(leak_reg, names(leak))) leak[[m]] <- seq_len(nrow(leak))
  attr(leak, "variable_source_registry") <- validate_variable_source_registry(data.frame(
    source = "synthetic_wave1", raw_variable = leak_reg,
    canonical_variable = canonical_join_variable_name(leak_reg),
    derived_from = NA_character_, stringsAsFactors = FALSE))
  leak_candidates <- get_candidate_vars(leak, cc)
  stopifnot("keepme" %in% leak_candidates, !any(items %in% leak_candidates))
  # switching scope must invalidate the cached analytic dataset
  f0 <- make_main_dataset_cache_fingerprint(cfg_template)
  for (m in c("wave3_complete", "durable_control")) {
    h <- cfg_template; h$exposure$exposure_mode <- m
    stopifnot(!identical(f0, make_main_dataset_cache_fingerprint(h)))
  }
  h <- cfg_template; h$exposure$wave3_cesd_cutpoint <- 13
  stopifnot(!identical(f0, make_main_dataset_cache_fingerprint(h)))
  message("v8.44 exposure-scope (Wave-III bridge / durable comparison) tests passed.")
  invisible(TRUE)
}

configured_target_population <- function(cfg) {
  txt <- "Wave-I probability-sample adolescents with complete Wave-II Feelings Scale"
  if (isTRUE(cfg$analysis$restrict_wave1_depressed))
    txt <- paste0(txt, "; complete Wave-I CES-D >= ", cfg$analysis$wave1_depression_cutpoint %||% 22)
  if (identical(cfg$analysis$dsp4_mode, "exclude_sensitivity"))
    txt <- paste0(txt, "; excludes verified post-exposure noncivilian/nonresident statuses (selected-population sensitivity)")
  if (identical(exposure_scope_mode(cfg), "wave3_complete"))
    txt <- paste0(txt, "; restricted to complete Wave-III 9-item Feelings Scale (bridge; exposure contrast unchanged)")
  if (identical(exposure_scope_mode(cfg), "durable_control"))
    txt <- paste0(txt, "; complete Wave-III 9-item Feelings Scale; comparison arm restricted to ",
                  "Wave-II-negative AND Wave-III-negative (post-exposure-selected comparison group; secondary contrast)")
  txt
}

# Learn a survey-weighted map entirely inside an OUTER training fold. The
# incoming scores are the Super Learner mixture of its INNER held-out base
# predictions; its mixture weights are learned within the outer training data.
# This is ordinary probability calibration, not the IC-IPW inverse-weight loss.
fit_probability_calibrator <- function(p, y, w, method = c("platt", "isotonic", "identity")) {
  method <- match.arg(method)
  p <- as.numeric(p); y <- as.numeric(y); w <- as.numeric(w)
  if (!length(p) || length(y) != length(p) || length(w) != length(p) ||
      any(!is.finite(p) | p < 0 | p > 1) || any(!y %in% 0:1) ||
      any(!is.finite(w) | w <= 0))
    stop("Invalid calibration training scores, labels, or survey weights.", call. = FALSE)
  # Identity leaves the Super Learner probability unchanged (no calibration).
  if (method == "identity") return(list(method = "identity", n = length(p)))
  w <- w / mean(w)
  if (length(unique(y)) == 1L || length(unique(p)) == 1L)
    return(list(method = "constant", requested_method = method,
                probability = sum(w * y) / sum(w), n = length(p)))
  if (method == "platt") {
    z <- stats::qlogis(pmin(pmax(p, 1e-6), 1 - 1e-6))
    fit <- stats::glm.fit(cbind(1, z), y, weights = w,
                          family = stats::quasibinomial(),
                          control = stats::glm.control(maxit = 100L))
    if (!isTRUE(fit$converged) || any(!is.finite(fit$coefficients)))
      stop("Platt calibration failed to converge; no silent fallback is allowed.", call. = FALSE)
    return(list(method = method, coefficients = unname(fit$coefficients), n = length(p)))
  }
  # Weighted PAVA with equal-score aggregation. This is permutation invariant
  # for ties and does not rely on stats::isoreg's unweighted/sorted internals.
  xs <- sort(unique(p)); k <- match(p, xs)
  sw <- as.numeric(rowsum(w, k, reorder = TRUE))
  sy <- as.numeric(rowsum(w * y, k, reorder = TRUE))
  n <- length(xs); bw <- by <- numeric(n); lo <- hi <- integer(n); top <- 0L
  for (j in seq_len(n)) {
    top <- top + 1L; bw[top] <- sw[j]; by[top] <- sy[j]; lo[top] <- hi[top] <- j
    while (top > 1L && by[top - 1L] / bw[top - 1L] > by[top] / bw[top]) {
      bw[top - 1L] <- bw[top - 1L] + bw[top]
      by[top - 1L] <- by[top - 1L] + by[top]
      hi[top - 1L] <- hi[top]; top <- top - 1L
    }
  }
  fitted <- numeric(n)
  for (j in seq_len(top)) fitted[lo[j]:hi[j]] <- by[j] / bw[j]
  list(method = method, x = xs, fitted = fitted, n_blocks = top, n = length(p))
}

predict_probability_calibrator <- function(object, p) {
  p <- as.numeric(p)
  if (any(!is.finite(p) | p < 0 | p > 1))
    stop("Invalid calibration prediction scores.", call. = FALSE)
  if (object$method == "identity") return(p)
  if (object$method == "constant") return(rep(object$probability, length(p)))
  if (object$method == "platt") {
    z <- stats::qlogis(pmin(pmax(p, 1e-6), 1 - 1e-6))
    return(stats::plogis(object$coefficients[1L] + object$coefficients[2L] * z))
  }
  # Linear interpolation between distinct training scores; constant extension
  # beyond the training range. Bounds used in targeting are applied afterward.
  as.numeric(stats::approx(object$x, object$fitted, xout = p,
                           method = "linear", rule = 2, ties = "ordered")$y)
}

# Survey-weighted log-loss of each candidate calibration map, cross-validated
# over the SAME inner whole-PSU folds that produced the training scores. Maps
# are fitted on the other inner folds and scored on the held-out inner fold;
# probabilities are scored after the bounds that the estimator itself applies.
# Inputs are training-fold exposure/response labels only: no outcome, no
# outer-validation label and no effect estimate can influence the choice.
select_probability_calibrator <- function(score, y, w, valid_rows, bounds,
                                          methods = c("identity", "platt")) {
  n <- length(score)
  if (!is.list(valid_rows) || length(valid_rows) < 2L)
    stop("Calibrator selection requires the inner validation partition.", call. = FALSE)
  all_rows <- unlist(valid_rows, use.names = FALSE)
  if (length(all_rows) != n || any(!is.finite(all_rows)) ||
      any(tabulate(as.integer(all_rows), nbins = n) != 1L))
    stop("Calibrator selection folds do not partition the training rows.", call. = FALSE)
  if (length(bounds) != 2L || any(!is.finite(bounds)) || bounds[1L] <= 0 ||
      bounds[2L] > 1 || bounds[1L] >= bounds[2L])
    stop("Calibrator selection requires valid probability bounds.", call. = FALSE)
  w <- as.numeric(w) / mean(w)
  loss <- stats::setNames(rep(NA_real_, length(methods)), methods)
  for (m in methods) {
    p_cv <- rep(NA_real_, n)
    for (ii in valid_rows) {
      learn <- setdiff(seq_len(n), ii)
      map <- fit_probability_calibrator(score[learn], y[learn], w[learn], m)
      p_cv[ii] <- predict_probability_calibrator(map, score[ii])
    }
    if (any(!is.finite(p_cv))) stop("Calibrator selection produced invalid probabilities.", call. = FALSE)
    # The exact one is treated like the estimator treats it; the scoring floor
    # only prevents log(0) when a configured upper bound equals one.
    p_cv <- pmin(pmax(p_cv, max(bounds[1L], 1e-12)), min(bounds[2L], 1 - 1e-12))
    loss[m] <- -sum(w * (y * log(p_cv) + (1 - y) * log(1 - p_cv))) / sum(w)
  }
  if (any(!is.finite(loss))) stop("Calibrator selection produced a nonfinite loss.", call. = FALSE)
  # Ties resolve to the first-listed, least-flexible map.
  list(method = methods[which.min(loss)], loss = loss)
}

calibrate_outer_predictions <- function(fit, y_train, w_train, p_valid, method, fold, target,
                                        bounds = c(1e-6, 1 - 1e-6),
                                        candidates = c("identity", "platt")) {
  Z <- as.matrix(fit$Z); beta <- as.numeric(fit$coef)
  if (nrow(Z) != length(y_train) || ncol(Z) != length(beta) ||
      any(!is.finite(beta)) || any(beta < -1e-10) || abs(sum(beta) - 1) > 1e-6 ||
      any(!is.finite(Z)))
    stop("Calibration requires complete inner held-out predictions and convex SL coefficients.", call. = FALSE)
  train_score <- pmin(pmax(as.numeric(Z %*% beta), 0), 1)
  requested_method <- method
  cv_loss <- c(identity = NA_real_, platt = NA_real_, isotonic = NA_real_)
  if (identical(method, "select")) {
    sel <- select_probability_calibrator(train_score, y_train, w_train, fit$validRows, bounds,
                                         methods = candidates)
    method <- sel$method; cv_loss[names(sel$loss)] <- sel$loss
  }
  object <- fit_probability_calibrator(train_score, y_train, w_train, method)
  object$requested_method <- requested_method
  object$cv_logloss <- cv_loss
  pred <- predict_probability_calibrator(object, p_valid)
  list(prediction = pred, object = object, audit = data.frame(
    fold = fold, target = target, requested_method = requested_method, fitted_method = object$method,
    cv_logloss_identity = unname(cv_loss["identity"]),
    cv_logloss_platt = unname(cv_loss["platt"]),
    cv_logloss_isotonic = unname(cv_loss["isotonic"]),
    selection_candidates = if (identical(requested_method, "select"))
      paste(candidates, collapse = ";") else NA_character_,
    selection_bound_lower = bounds[1L], selection_bound_upper = bounds[2L],
    n_train = length(y_train), n_predictions = length(p_valid),
    train_weight_sum = sum(w_train), n_distinct_training_scores = length(unique(train_score)),
    platt_intercept = if (object$method == "platt") object$coefficients[1L] else NA_real_,
    platt_slope = if (object$method == "platt") object$coefficients[2L] else NA_real_,
    n_isotonic_blocks = object$n_blocks %||% NA_integer_,
    valid_pre_min = min(p_valid), valid_pre_max = max(p_valid),
    valid_post_min = min(pred), valid_post_max = max(pred),
    max_abs_change = max(abs(pred - p_valid)),
    calibration_labels = "outer_training_only", stringsAsFactors = FALSE))
}

# The status file is an adjudicated input, NOT a mapping from missing interviews
# to zeros. Required columns: AID (or configured ID), wave, family, status_zero
# (0/1), reference_verified (0/1), reason, reference_period, evidence_source.
# Unresolved rows: status_zero=0, reference_verified=0, reason="unresolved".
# Unknown nonzero contributions are missing; observed zeros remain zeros. Counts are audited.
# One row per eligible analytic respondent for the chosen wave/family is required.
# A zero flag means verified exclusion from the explicitly defined current US
# civilian noninstitutional resident labor-supply composite. It must cover
# interviewees and noninterviewees consistently. Deaths cannot be flagged here.
# Recorded Wave-IV status defines zeros for the current contribution outcome.
# Codebook: secta (PRISON4), sect10 (C_ACTIDUTY), final DSP4 dispositions.
# Interview status takes precedence over final disposition for retained interviews.
# Unknown/conflicting status is never converted into a structural zero.
build_documented_military_prison_status <- function(m, cfg, w, dsp) {
  stopifnot(cfg$outcome$family %in% c("HoursWorked", "LaborForceParticipation"))
  id <- cfg$analysis$id_var
  need <- c(id, "PRISON4", "H4MI1", "H4MI3", "H4MI6A", "H4MI6B", "H4MI6C", "H4MI7")
  assert_required_columns(w, need, "Wave-IV interview status")
  assert_required_columns(dsp, c(id, "DSP4"), "Wave-IV disposition status")
  m <- coerce_join_key(m, id, "status analytic sample", require_complete=TRUE)
  w <- coerce_join_key(w, id, "status interviews", require_complete=TRUE)
  dsp <- coerce_join_key(dsp, id, "status dispositions", require_complete=TRUE)
  assert_unique_key(m, id, "status analytic sample", require_complete=TRUE)
  assert_unique_key(w, id, "status interviews", require_complete=TRUE)
  assert_unique_key(dsp, id, "status dispositions", require_complete=TRUE)
  w <- w[match(m[[id]], w[[id]]), need, drop=FALSE]
  p <- to_numeric_codes(dsp$DSP4[match(m[[id]], dsp[[id]])])
  interviewed <- !is.na(w[[id]])
  for (nm in setdiff(need, id)) w[[nm]] <- to_numeric_codes(w[[nm]])
  active <- with(w, H4MI3 %in% 1 & (H4MI7 %in% 1 |
    (H4MI7 %in% c(7, NA) & H4MI6A %in% 1 &
     H4MI6B %in% 0 & H4MI6C %in% 0)))
  inactive <- with(w, H4MI1 %in% 0 | H4MI3 %in% 0 |
    (H4MI3 %in% 1 & (H4MI7 %in% c(2, 3) |
     (H4MI7 %in% c(7, NA) & H4MI6A %in% 0 &
      ((H4MI6B %in% 1 & H4MI6C %in% 0) |
       (H4MI6B %in% 0 & H4MI6C %in% 1))))))
  conflict <- with(w, (H4MI1 %in% 0 & (H4MI3 %in% 1 | H4MI7 %in% 1:3)) |
    (H4MI3 %in% c(0, 7) & H4MI7 %in% 1:3) |
    (H4MI7 %in% 1 & H4MI6A %in% 0) |
    (H4MI7 %in% 2 & H4MI6B %in% 0) |
    (H4MI7 %in% 3 & H4MI6C %in% 0)) | (active & inactive)
  active[conflict] <- FALSE
  inactive[conflict] <- FALSE
  reason <- ifelse(interviewed & inactive & w$PRISON4 %in% 0,
                   "eligible", "unresolved")
  reason[active | (!interviewed & p %in% 486)] <- "active_duty_military"
  reason[w$PRISON4 %in% 1 | (!interviewed & p %in% c(477, 613))] <- "incarcerated"
  reason[!interviewed & p %in% 478] <- "institutionalized"
  reason[!interviewed & p %in% 482] <- "nonresident"
  if (mortality_enabled_for_wave(cfg, 4L)) {
    mort <- resolve_mortality_spec(cfg, 4L)
    assert_required_columns(m, mort$death_before_outcome_var, "status mortality priority")
    dead <- m[[mort$death_before_outcome_var]]
    stopifnot(length(dead)==nrow(m), all(dead %in% 0:1))
    reason[dead==1L] <- "mortality_handled_separately"
  }
  out <- data.frame(id=m[[id]], wave=4L, family=cfg$outcome$family,
    status_zero=as.integer(reason %in% c("incarcerated","active_duty_military",
      "institutionalized","nonresident")),
    reference_verified=as.integer(reason!="unresolved"), reason=reason,
    reference_period=ifelse(interviewed, "Wave_IV_interview", "Wave_IV_final_field_disposition"),
    evidence_source=ifelse(interviewed, "PRISON4_and_H4MI1_3_6ABC_7", "DSP4"),
    military_response_conflict=conflict, stringsAsFactors=FALSE)
  names(out)[1L] <- id
  out
}

apply_verified_labor_status <- function(df, cfg, status = NULL) {
  mode <- resolve_status_mode(cfg)
  df$.status_excluded <- FALSE
  df$.labor_status_zero <- FALSE
  df$.labor_status_verified <- FALSE
  df$.labor_status_reason <- "unresolved"
  if (mode == "audit_only") return(list(data = df, audit = NULL))
  if (!identical(as.integer(cfg$outcome$current_wave), 4L) ||
      !cfg$outcome$family %in% c("HoursWorked", "LaborForceParticipation"))
    stop("Verified status recoding is restricted to Wave-IV hours/LFP.", call. = FALSE)
  id <- cfg$analysis$id_var; yv <- cfg$analysis$outcome_var
  if (is.null(status) && isTRUE(cfg$analysis$auto_military_prison_status))
    status <- build_documented_military_prison_status(df, cfg,
      read_xpt_df(cfg$paths$wave4_inhome), read_xpt_df(cfg$paths$wave4_disposition))
  if (is.null(status)) status <- utils::read.csv(cfg$paths$verified_labor_status,
                                                 colClasses = "character", check.names = FALSE, stringsAsFactors = FALSE)
  assert_required_columns(status, c(id, "wave", "family", "status_zero",
                                    "reference_verified", "reason", "reference_period", "evidence_source"), "verified status input")
  status <- status[which(as.character(status$wave) == "4" & status$family == cfg$outcome$family), , drop = FALSE]
  status <- coerce_join_key(status, id, "verified status input", require_complete = TRUE)
  assert_unique_key(status, id, "verified status input", require_complete = TRUE)
  idx <- match(as.character(df[[id]]), as.character(status[[id]]))
  if (anyNA(idx)) stop("Verified status input must cover every analytic respondent, including interviewees.", call. = FALSE)
  s <- status[idx, , drop = FALSE]
  flag <- suppressWarnings(as.integer(as.character(s$status_zero)))
  verified <- as.character(s$reference_verified)
  if (anyNA(flag) || any(!as.character(s$status_zero) %in% c("0", "1")) ||
      anyNA(verified) || any(!verified %in% c("0", "1")))
    stop("status_zero and reference_verified must both be 0/1.", call. = FALSE)
  for (nm in c("reason", "reference_period", "evidence_source"))
    if (anyNA(s[[nm]]) || any(!nzchar(trimws(as.character(s[[nm]])))))
      stop("Status input has missing adjudication field: ", nm, call. = FALSE)
  if (any(flag == 1L & verified != "1") ||
      any(verified == "0" & (flag != 0L | s$reason != "unresolved")) ||
      any(s$reason == "unresolved" & verified != "0"))
    stop("Unresolved status must be explicitly unverified and cannot create a zero or exclusion.",
         call. = FALSE)
  allowed <- c("incarcerated", "institutionalized", "active_duty_military", "nonresident")
  if (any(flag == 1L & !s$reason %in% allowed))
    stop("Nonzero status flags require a supported nondeath status reason.", call. = FALSE)
  mort <- if (mortality_enabled_for_wave(cfg, 4L)) resolve_mortality_spec(cfg, 4L) else NULL
  if (!is.null(mort) && mort$death_before_outcome_var %in% names(df) &&
      any(flag == 1L & df[[mort$death_before_outcome_var]] == 1L, na.rm = TRUE))
    stop("Death classifications cannot be overridden by the civilian-status input.", call. = FALSE)
  df$.labor_status_zero <- flag == 1L
  df$.labor_status_verified <- verified == "1"
  df$.labor_status_reason <- as.character(s$reason)
  before <- df[[yv]]
  if (mode == "composite") {
    df[[yv]][verified == "0" & is.finite(before) & before != 0] <- NA_real_
    df[[yv]][flag == 1L] <- 0
  }
  if (mode == "exclude_sensitivity") df$.status_excluded <- flag == 1L
  audit <- data.frame(mode = mode, family = cfg$outcome$family,
                      n_reviewed = nrow(df), n_verified = sum(verified == "1"),
    n_unresolved = sum(verified == "0"), n_flagged = sum(flag),
    n_unresolved_nonzero_masked = if (mode == "composite")
      sum(verified == "0" & is.finite(before) & before != 0) else 0L,
    n_missing_flagged = sum(flag == 1L & !is.finite(before)),
                      n_observed_nonzero_flagged = sum(flag == 1L & is.finite(before) & before != 0),
                      estimand_status = if (mode == "composite") "documented_status_zero_composite" else "post_exposure_selected_population",
                      stringsAsFactors = FALSE)
  # Data-integrity gate (same class as expected_final_n / expected_treated_n).
  # Composite recoding masks observed nonzero outcomes whose status is
  # unresolved, which item nonresponse on PRISON4/H4MI* can trigger. A small
  # masked fraction is genuine ambiguity; a large one means a merge or coding
  # failure. The floor exempts small fixtures, where a handful of rows is a
  # large fraction by construction. Fires in data build, before any fitting.
  if (mode == "composite") {
    n_nonzero <- sum(is.finite(before) & before != 0)
    audit$n_observed_nonzero_before <- n_nonzero
    audit$status_masked_fraction <-
      if (n_nonzero > 0L) audit$n_unresolved_nonzero_masked / n_nonzero else 0
    gate_min <- cfg$analysis$status_mask_gate_min_nonzero %||% 500L
    gate_max <- cfg$analysis$max_status_masked_fraction %||% 0.10
    if (n_nonzero >= gate_min && audit$status_masked_fraction > gate_max)
      stop(sprintf(paste0("Status recoding masked %d of %d observed nonzero outcomes ",
        "(%.1f%%; limit %.0f%%). This indicates a data or merge failure in ",
        "PRISON4/H4MI*, not genuine status ambiguity. Inspect ",
        "verified_labor_status_audit.csv before proceeding."),
        audit$n_unresolved_nonzero_masked, n_nonzero,
        100 * audit$status_masked_fraction, 100 * gate_max), call. = FALSE)
  }
  details <- s
  details$outcome_before <- before
  details$outcome_after <- df[[yv]]
  if (!"military_response_conflict" %in% names(details))
    details$military_response_conflict <- NA
  list(data = df, audit = audit, details = details)
}

build_disposition_audit <- function(df, cfg, dsp = NULL) {
  if (!isTRUE(cfg$analysis$enable_dsp4_audit) ||
      !identical(as.integer(cfg$outcome$current_wave), 4L)) return(NULL)
  path <- cfg$paths$wave4_disposition
  if (is.null(dsp)) {
    if (is.null(path) || length(path) != 1L || is.na(path) || !file.exists(path))
      return(data.frame(status = "disposition_source_unavailable", dsp4 = NA_integer_,
                        n = nrow(df), family = cfg$outcome$family, stringsAsFactors = FALSE))
    dsp <- read_xpt_df(path)
  }
  id <- cfg$analysis$id_var
  assert_required_columns(dsp, c(id, "DSP4"), "Wave-IV dispositions")
  dsp <- coerce_join_key(dsp, id, "Wave-IV dispositions", require_complete = TRUE)
  assert_unique_key(dsp, id, "Wave-IV dispositions", require_complete = TRUE)
  matched <- match(as.character(df[[id]]), as.character(dsp[[id]]))
  d <- to_numeric_codes(dsp$DSP4[matched])
  y <- df[[cfg$analysis$outcome_var]]
  mort <- if (mortality_enabled_for_wave(cfg, 4L)) resolve_mortality_spec(cfg, 4L) else NULL
  death <- if (!is.null(mort) && mort$death_before_outcome_var %in% names(df))
    df[[mort$death_before_outcome_var]] else rep(NA_integer_, nrow(df))
  group <- ifelse(is.na(d), "missing_or_unmatched", as.character(d))
  do.call(rbind, lapply(unique(group), function(code) {
    ii <- which(group == code)
    data.frame(status = paste0("disposition_audit_", resolve_status_mode(cfg)), dsp4 = code,
               n = length(ii), n_unmatched_id = sum(is.na(matched[ii])),
               n_outcome_observed = sum(is.finite(y[ii])),
               n_outcome_missing = sum(!is.finite(y[ii])),
               n_observed_nonzero = sum(is.finite(y[ii]) & y[ii] != 0),
               n_dated_preoutcome_death = sum(death[ii] == 1L, na.rm = TRUE),
               n_dated_nonpreoutcome = sum(death[ii] == 0L, na.rm = TRUE),
               n_mortality_unresolved = sum(is.na(death[ii]) | (code == "459" & death[ii] %in% 0L)),
      n_disposition_death_without_dated_confirmation =
        if (code == "459") sum(is.na(death[ii]) | death[ii] %in% 0L) else 0L,
               possible_non_death_status = code %in% as.character(cfg$analysis$dsp4_structural_zero_codes),
               family = cfg$outcome$family, analytic_scope = configured_target_population(cfg),
               note = if (code == "459") "Unconfirmed field-coded deaths remain unresolved; dated status 0 is not proof of survival. No automatic outcome recoding." else "",
               stringsAsFactors = FALSE)
  }))
}

build_wave1_variable_source_registry <- function(source_tables, cfg) {
  rows <- lapply(names(source_tables), function(src) {
    data.frame(
      source = src,
      raw_variable = names(source_tables[[src]]),
      canonical_variable = canonical_join_variable_name(names(source_tables[[src]])),
      derived_from = NA_character_,
      stringsAsFactors = FALSE)
  })
  out <- if (length(rows)) do.call(rbind, rows) else empty_variable_source_registry()
  rownames(out) <- NULL
  validate_variable_source_registry(out)
}

append_derived_variable_registry <- function(registry, derived_variable,
                                             derived_from, source) {
  registry <- validate_variable_source_registry(registry)
  source <- as.character(source)
  derived_variable <- as.character(derived_variable)
  derived_from <- as.character(derived_from)
  if (length(source) != 1L || is.na(source) || !nzchar(trimws(source)) ||
      length(derived_variable) != 1L || is.na(derived_variable) ||
      !nzchar(trimws(derived_variable)) || !length(derived_from) ||
      anyNA(derived_from) || any(!nzchar(trimws(derived_from))))
    stop("Derived-variable registry entries require one nonblank source/variable and valid parent(s).",
         call. = FALSE)
  
  src_rows <- registry[toupper(registry$source) == toupper(source), , drop = FALSE]
  if (!nrow(src_rows))
    stop("Cannot register derived variable '", derived_variable,
         "': source '", source, "' is absent from the descriptive registry.",
         call. = FALSE)
  if (!all(canonical_role_key(derived_from) %in% canonical_role_key(src_rows$raw_variable)))
    stop("Cannot register derived variable '", derived_variable,
         "': parent '", derived_from, "' is absent from source '", source,
         "' in the registry.", call. = FALSE)
  
  row <- data.frame(
    source = source,
    raw_variable = derived_variable,
    canonical_variable = canonical_join_variable_name(derived_variable),
    derived_from = paste(unique(derived_from), collapse = ";"),
    stringsAsFactors = FALSE)
  validate_variable_source_registry(rbind(registry, row))
}

collapse_registry_by_canonical <- function(registry) {
  registry <- validate_variable_source_registry(registry)
  if (!nrow(registry)) {
    return(data.frame(
      canonical_key = character(0), canonical_variable = character(0),
      source = character(0), derived_from = character(0),
      stringsAsFactors = FALSE))
  }
  split_rows <- split(registry, canonical_role_key(registry$canonical_variable))
  out <- lapply(split_rows, function(d) {
    derived <- unique(na.omit(as.character(d$derived_from)))
    data.frame(
      canonical_key = canonical_role_key(d$canonical_variable[1L]),
      canonical_variable = canonical_join_variable_name(d$canonical_variable[1L]),
      source = paste(sort(unique(as.character(d$source))), collapse = ";"),
      derived_from = paste(sort(derived), collapse = ";"),
      stringsAsFactors = FALSE)
  })
  out <- do.call(rbind, out)
  rownames(out) <- NULL
  out
}

restore_custom_data_frame_attributes <- function(df, saved_attributes) {
  core <- c("names", "row.names", "class")
  for (nm in setdiff(names(saved_attributes), core))
    attr(df, nm) <- saved_attributes[[nm]]
  df
}

canonicalize_mandatory_W_columns <- function(df, cfg) {
  if (!is.data.frame(df)) stop("Mandatory-W canonicalization requires a data frame.", call. = FALSE)
  saved_attributes <- attributes(df)
  audit_rows <- list()
  for (target in get_mandatory_W(cfg)) {
    key <- canonical_role_key(target)
    hits <- names(df)[canonical_role_key(names(df)) == key]
    if (!length(hits)) next
    exact <- hits[toupper(hits) == toupper(target)]
    preferred <- if (length(exact)) exact[1L] else hits[1L]
    if (length(hits) == 1L && identical(preferred, target)) next
    
    normalized <- lapply(hits, function(nm) normalize_design_field_values(df[[nm]]))
    names(normalized) <- hits
    canonical_chr <- rep(NA_character_, nrow(df))
    conflicts <- rep(FALSE, nrow(df))
    for (nm in c(preferred, setdiff(hits, preferred))) {
      z <- normalized[[nm]]
      z_chr <- trimws(as.character(z))
      z_chr[is.na(z)] <- NA_character_
      present <- !is.na(z_chr) & nzchar(z_chr)
      overlap <- present & !is.na(canonical_chr)
      conflicts <- conflicts | (overlap & canonical_chr != z_chr)
      canonical_chr[present & is.na(canonical_chr)] <- z_chr[present & is.na(canonical_chr)]
    }
    if (any(conflicts)) {
      ii <- head(which(conflicts), 5L)
      stop(sprintf(
        "Mandatory W '%s' has conflicting aliases in columns %s (example rows %s).",
        target, paste(hits, collapse = ", "), paste(ii, collapse = ", ")),
        call. = FALSE)
    }
    parsed <- suppressWarnings(as.numeric(canonical_chr))
    nonmissing <- !is.na(canonical_chr)
    canonical <- if (any(nonmissing) && all(is.finite(parsed[nonmissing]))) {
      if (all(abs(parsed[nonmissing] - round(parsed[nonmissing])) <= 1e-8))
        as.integer(round(parsed)) else parsed
    } else canonical_chr
    df <- df[, !names(df) %in% hits, drop = FALSE]
    df[[target]] <- canonical
    audit_rows[[length(audit_rows) + 1L]] <- data.frame(
      mandatory_variable = target,
      source_columns = paste(hits, collapse = ";"),
      n_sources = length(hits),
      n_conflicts = 0L,
      n_missing = sum(is.na(canonical) | trimws(as.character(canonical)) == ""),
      stringsAsFactors = FALSE)
  }
  df <- restore_custom_data_frame_attributes(df, saved_attributes)
  prior <- attr(df, "mandatory_W_canonicalization_audit")
  new <- if (length(audit_rows)) do.call(rbind, audit_rows) else data.frame()
  if (is.data.frame(prior) && nrow(prior)) new <- rbind(prior, new)
  if (nrow(new)) {
    new <- new[!duplicated(new[, c("mandatory_variable", "source_columns"), drop = FALSE]), , drop = FALSE]
    rownames(new) <- NULL
  }
  attr(df, "mandatory_W_canonicalization_audit") <- new
  df
}

get_mortality_role_vars <- function(cfg) {
  mort <- cfg$mortality_sensitivity %||% list()
  specs <- mort$wave_specs %||% list()
  wave_vars <- unlist(lapply(specs, function(z) c(
    z$interview_year_var %||% character(0),
    z$interview_month_var %||% character(0),
    z$derived_death_year_var %||% character(0),
    z$derived_death_month_var %||% character(0),
    z$death_in_window_var %||% character(0),
    z$death_before_outcome_var %||% character(0),
    z$timing_status_var %||% character(0))), use.names = FALSE)
  unique(c(mort$source_var %||% character(0),
           mort$source_month_var %||% character(0), wave_vars))
}


# Canonical raw ancestry for generated names already used by this pipeline.
# The raw source is denied before recipes run; these suffix rules additionally
# prevent cached/manual missing indicators and time transforms re-entering W.
source_candidate_key <- function(x) {
  z <- toupper(trimws(as.character(x)))
  repeat {
    old <- z
    z <- sub("(?:\\.[XY])+$", "", z, perl=TRUE)
    z <- sub("^BROADQ__", "", z)
    z <- sub("(?:_MISSA|_MISS97|__TSIN|__TCOS)$", "", z, perl=TRUE)
    if (identical(old,z)) break
  }
  z
}

excluded_candidate_source_mask <- function(df, cfg, variables=names(df), registry=NULL) {
  denied <- tolower(trimws(as.character(
    cfg$causal_governance$excluded_candidate_sources %||% "birth_records")))
  if (anyNA(denied) || any(!nzchar(denied)))
    stop("Invalid candidate source denylist.",call.=FALSE)
  if (is.null(registry)) registry <- get_variable_source_registry(df,cfg,required=FALSE)
  registry <- validate_variable_source_registry(registry)
  denied_rows <- tolower(trimws(registry$source)) %in% denied
  keys <- unique(source_candidate_key(registry$canonical_variable[denied_rows]))
  # Exact field names documented in the configured birth-record source. This
  # fail-safe prevents known source fields leaking through legacy partial registries.
  if ("birth_records" %in% denied) keys <- unique(c(keys,
    paste0("RIWA00",1:4),paste0("RIDA00",1:2),paste0("RPDA00",1:7),"RMMA001"))
  # Follow declared dependencies transitively, even if a derivative is recorded
  # under a different source label. Shared-name ambiguity is resolved conservatively.
  if (nrow(registry)) {
    parents <- lapply(registry$derived_from,function(z) {
      if (is.na(z) || !nzchar(trimws(z))) character(0) else
        source_candidate_key(trimws(strsplit(z,";",fixed=TRUE)[[1L]]))
    })
    repeat {
      affected <- vapply(parents,function(z) any(z %in% keys),logical(1))
      enlarged <- unique(c(keys,source_candidate_key(registry$canonical_variable[affected])))
      if (setequal(enlarged,keys)) break
      keys <- enlarged
    }
  }
  source_candidate_key(variables) %in% keys
}

assert_no_excluded_source_W <- function(df,cfg,variables,label="W design") {
  bad <- excluded_candidate_source_mask(df,cfg,variables)
  if (any(bad)) stop(label, " contains excluded-source predictor(s): ",
                     paste(variables[bad],collapse=", "),call.=FALSE)
  invisible(TRUE)
}

build_candidate_alias_audit <- function(df, cfg) {
  registry <- get_variable_source_registry(
    df, cfg, required = TRUE)
  reg <- collapse_registry_by_canonical(registry)
  reg_match <- match(canonical_role_key(names(df)), reg$canonical_key)
  exclusions <- get_common_exclusion_vars(cfg, include_analysis_outputs = TRUE)
  exclusion_keys <- canonical_role_key(exclusions)
  role_names <- unique(c(
    cfg$analysis$id_var, cfg$analysis$cluster_var, cfg$analysis$strata_var,
    cfg$analysis$weight_var, cfg$analysis$exposure_var,
    cfg$analysis$outcome_var, cfg$analysis$outcome_observed_var,
    get_mortality_role_vars(cfg),
    cfg$exposure$drop_from_candidates %||% character(0),
    get_outcome_drop_vars(cfg)
  ))
  role_keys <- canonical_role_key(role_names)
  actual <- names(df)
  canonical <- canonical_join_variable_name(actual)
  canonical_key <- canonical_role_key(actual)
  excluded <- canonical_key %in% exclusion_keys
  role_alias <- canonical_key %in% role_keys
  registered <- !is.na(reg_match)
  source <- rep(NA_character_, length(actual))
  if (any(registered)) source[registered] <- reg$source[reg_match[registered]]
  source_excluded <- excluded_candidate_source_mask(df,cfg,actual,registry)
  eligible <- !excluded & !role_alias & !source_excluded
  reason <- ifelse(role_alias, "analysis_role_or_source_alias",
                   ifelse(source_excluded, "excluded_source_or_derived_predictor",
                     ifelse(excluded, "configured_exclusion_or_alias", "eligible_by_role_exclusions")))
  data.frame(
    actual_variable = actual,
    canonical_variable = canonical,
    has_join_suffix = grepl("(?:\\.[xy])+$", actual, perl = TRUE),
    has_recursive_join_suffix = grepl("(?:\\.[xy]){2,}$", actual, perl = TRUE),
    source = source,
    registered_in_source_audit = registered,
    excluded_candidate_source = source_excluded,
    configured_exclusion = excluded,
    protected_analysis_role = role_alias,
    mandatory_W = canonical_key %in% canonical_role_key(get_mandatory_W(cfg)),
    eligible_candidate_W = eligible,
    eligibility_reason = reason,
    stringsAsFactors = FALSE)
}

validate_candidate_governance <- function(df, cfg, audit = NULL) {
  if (is.null(audit)) audit <- build_candidate_alias_audit(df, cfg)
  candidates <- audit$actual_variable[audit$eligible_candidate_W]
  assert_no_excluded_source_W(df,cfg,candidates,"Candidate governance")
  bad_role <- canonical_role_key(candidates) %in% canonical_role_key(c(
    cfg$analysis$id_var, cfg$analysis$cluster_var, cfg$analysis$strata_var,
    cfg$analysis$weight_var, cfg$analysis$exposure_var,
    cfg$analysis$outcome_var, cfg$analysis$outcome_observed_var,
    get_mortality_role_vars(cfg),
    cfg$exposure$drop_from_candidates %||% character(0),
    get_outcome_drop_vars(cfg)
  ))
  if (any(bad_role) && isTRUE(cfg$safety$fail_on_role_alias_leakage %||% TRUE))
    stop("Analysis-role alias(es) survived candidate governance: ",
         paste(candidates[bad_role], collapse = ", "), call. = FALSE)
  mandatory <- get_mandatory_W(cfg)
  mandatory_keys <- canonical_role_key(mandatory)
  candidate_keys <- canonical_role_key(candidates)
  missing_mandatory <- mandatory[!mandatory_keys %in% candidate_keys]
  if (length(missing_mandatory) && isTRUE(cfg$safety$fail_on_missing_mandatory_W %||% TRUE))
    stop("Mandatory pre-exposure W variable(s) are absent or ineligible: ",
         paste(missing_mandatory, collapse = ", "), call. = FALSE)
  invisible(list(candidates = candidates, audit = audit,
                 missing_mandatory = missing_mandatory))
}

get_outcome_drop_vars <- function(cfg) {
  fam_drop <- character(0)
  if (!is.null(cfg$outcome$family)) {
    fam_cfg <- cfg$outcome$families[[cfg$outcome$family]]
    if (!is.null(fam_cfg)) {
      cur_wave <- cfg$outcome$current_wave
      if (!is.null(cur_wave) && !is.null(fam_cfg$drop_from_candidates_by_wave)) {
        per_wave <- fam_cfg$drop_from_candidates_by_wave[[as.character(cur_wave)]]
        fam_drop <- if (!is.null(per_wave)) as.character(per_wave) else
          fam_cfg$drop_from_candidates %||% character(0)
      } else {
        fam_drop <- fam_cfg$drop_from_candidates %||% character(0)
      }
      if (!is.null(fam_cfg$source_var))
        fam_drop <- unique(c(fam_drop, as.character(fam_cfg$source_var)))
    }
  }
  unique(c(cfg$outcome$drop_from_candidates %||% character(0), fam_drop))
}

get_common_exclusion_vars <- function(cfg, include_analysis_outputs = TRUE) {
  death_vars <- get_mortality_role_vars(cfg)
  base <- unique(c(
    cfg$analysis$id_var, cfg$analysis$cluster_var, cfg$analysis$strata_var,
    cfg$analysis$weight_var,
    "H1GH50", cfg$analysis$extra_exclude_from_candidates %||% character(0),
    death_vars,
    ".status_excluded", ".DSP4_audit", ".hours_uncapped",
    cfg$exposure$drop_from_candidates %||% character(0),
    get_outcome_drop_vars(cfg)))
  if (isTRUE(include_analysis_outputs)) {
    base <- unique(c(base, cfg$analysis$exposure_var, cfg$analysis$outcome_var,
                     cfg$analysis$outcome_observed_var))
  }
  base
}

design_field_source_audit <- function(source_tables, field_name) {
  rows <- lapply(names(source_tables), function(src) {
    df <- source_tables[[src]]
    hits <- names(df)[tolower(names(df)) == tolower(field_name)]
    data.frame(
      source = src,
      field = field_name,
      matching_columns = paste(hits, collapse = ";"),
      n_matches = length(hits),
      n_rows = nrow(df),
      stringsAsFactors = FALSE)
  })
  do.call(rbind, rows)
}

normalize_design_field_values <- function(x) {
  missing <- is.na(x)
  chr <- trimws(as.character(x))
  chr[missing | is.na(chr) | chr == ""] <- NA_character_
  parsed <- suppressWarnings(as.numeric(chr))
  nonmissing <- !is.na(chr)
  if (any(nonmissing) && all(is.finite(parsed[nonmissing]))) {
    out <- parsed
    if (all(abs(out[nonmissing] - round(out[nonmissing])) <= 1e-8))
      out <- as.integer(round(out))
    return(out)
  }
  chr
}

# Canonicalize one required join key from an exact key name or documented aliases.
# Multiple matching source columns are accepted only when they agree row by row;
# otherwise the merge stops before any row multiplication can occur.
canonicalize_join_key_alias <- function(df, key, aliases = character(0),
                                        label = deparse(substitute(df)),
                                        require_complete = FALSE) {
  if (!is.data.frame(df)) stop(label, " is not a data frame.", call. = FALSE)
  accepted <- unique(tolower(c(key, aliases)))
  hits <- names(df)[tolower(names(df)) %in% accepted]
  if (!length(hits))
    stop(label, " is missing required join key ", key,
         " and aliases: ", paste(aliases, collapse = ", "), call. = FALSE)
  values <- lapply(hits, function(nm) normalize_design_field_values(df[[nm]]))
  names(values) <- hits
  combined <- values[[1L]]
  if (length(values) > 1L) {
    for (j in 2:length(values)) {
      z <- values[[j]]
      c_chr <- trimws(as.character(combined)); z_chr <- trimws(as.character(z))
      c_present <- !is.na(combined) & nzchar(c_chr)
      z_present <- !is.na(z) & nzchar(z_chr)
      conflict <- c_present & z_present & c_chr != z_chr
      if (any(conflict)) {
        ii <- which(conflict)[seq_len(min(5L, sum(conflict)))]
        stop(sprintf(
          "%s has conflicting aliases for join key %s in columns %s (examples at rows %s).",
          label, key, paste(hits, collapse = ", "), paste(ii, collapse = ", ")),
          call. = FALSE)
      }
      fill <- !c_present & z_present
      combined[fill] <- z[fill]
    }
  }
  df <- df[, !names(df) %in% hits, drop = FALSE]
  df[[key]] <- combined
  key_chr <- trimws(as.character(df[[key]]))
  incomplete <- is.na(df[[key]]) | is.na(key_chr) | !nzchar(key_chr)
  if (isTRUE(require_complete) && any(incomplete))
    stop(label, " contains missing or blank values in canonical join key ", key, ".", call. = FALSE)
  df
}

canonicalize_merged_design_field <- function(df, field_name, source_audit = NULL) {
  prior_audit <- attr(df, "canonical_design_field_audit")
  name_lower <- tolower(names(df))
  field_lower <- tolower(field_name)
  suffix_pattern <- paste0("^", field_lower, "(?:\\.[xy])+$")
  candidates <- names(df)[name_lower == field_lower |
                            grepl(suffix_pattern, name_lower, perl = TRUE)]
  if (!length(candidates)) {
    src_txt <- if (!is.null(source_audit) && nrow(source_audit)) {
      paste(sprintf("%s:[%s]", source_audit$source,
                    ifelse(source_audit$n_matches > 0L,
                           source_audit$matching_columns, "none")), collapse = "; ")
    } else "source audit unavailable"
    stop(sprintf(
      "Required design field '%s' was not found after the Wave-I merges. Raw-source audit: %s.",
      field_name, src_txt), call. = FALSE)
  }
  
  normalized <- lapply(candidates, function(nm) normalize_design_field_values(df[[nm]]))
  names(normalized) <- candidates
  canonical_chr <- rep(NA_character_, nrow(df))
  conflict <- rep(FALSE, nrow(df))
  conflict_examples <- character(0)
  for (nm in candidates) {
    z <- normalized[[nm]]
    z_chr <- trimws(as.character(z))
    z_chr[is.na(z)] <- NA_character_
    present <- !is.na(z_chr) & nzchar(z_chr)
    overlap <- present & !is.na(canonical_chr)
    bad <- overlap & canonical_chr != z_chr
    if (any(bad)) {
      conflict <- conflict | bad
      ii <- which(bad)[seq_len(min(3L, sum(bad)))]
      conflict_examples <- c(conflict_examples,
                             sprintf("row %d: existing=%s, %s=%s", ii, canonical_chr[ii], nm, z_chr[ii]))
    }
    fill <- present & is.na(canonical_chr)
    canonical_chr[fill] <- z_chr[fill]
  }
  if (any(conflict)) {
    stop(sprintf(
      "Conflicting values were found while canonicalizing design field '%s' from columns %s (%d conflicting rows; examples: %s).",
      field_name, paste(candidates, collapse = ", "), sum(conflict),
      paste(head(conflict_examples, 6L), collapse = " | ")), call. = FALSE)
  }
  
  parsed <- suppressWarnings(as.numeric(canonical_chr))
  nonmissing <- !is.na(canonical_chr)
  canonical <- if (any(nonmissing) && all(is.finite(parsed[nonmissing]))) {
    if (all(abs(parsed[nonmissing] - round(parsed[nonmissing])) <= 1e-8))
      as.integer(round(parsed)) else parsed
  } else canonical_chr
  
  df <- df[, !names(df) %in% candidates, drop = FALSE]
  df[[field_name]] <- canonical
  new_audit <- data.frame(
    field = field_name,
    source_columns = paste(candidates, collapse = ";"),
    n_rows = nrow(df),
    n_missing = sum(is.na(canonical) | trimws(as.character(canonical)) == ""),
    n_unique_nonmissing = length(unique(canonical[!is.na(canonical)])),
    stringsAsFactors = FALSE)
  if (is.data.frame(prior_audit) && nrow(prior_audit) > 0L) {
    missing_old <- setdiff(names(new_audit), names(prior_audit))
    for (nm in missing_old) prior_audit[[nm]] <- NA
    missing_new <- setdiff(names(prior_audit), names(new_audit))
    for (nm in missing_new) new_audit[[nm]] <- NA
    combined_audit <- rbind(prior_audit[, names(new_audit), drop = FALSE], new_audit)
  } else combined_audit <- new_audit
  combined_audit <- combined_audit[!duplicated(
    combined_audit[, c("field", "source_columns"), drop = FALSE]), , drop = FALSE]
  rownames(combined_audit) <- NULL
  attr(df, "canonical_design_field_audit") <- combined_audit
  df
}

build_full_survey_design_frame <- function(w1_all, cfg) {
  id_var <- cfg$analysis$id_var
  psu_var <- cfg$analysis$cluster_var
  strata_var <- cfg$analysis$strata_var
  weight_var <- cfg$analysis$weight_var
  assert_required_columns(w1_all, c(id_var, psu_var, strata_var, weight_var),
                          "Wave-I merged survey-design frame")
  ids <- w1_all[[id_var]]
  if (anyNA(ids) || anyDuplicated(as.character(ids)))
    stop("Wave-I survey-design frame requires complete unique respondent IDs.", call. = FALSE)
  w <- suppressWarnings(as.numeric(w1_all[[weight_var]]))
  keep <- is.finite(w) & w > 0
  if (!any(keep)) stop("Wave-I survey-design frame has no positive finite sampling weights.", call. = FALSE)
  out <- w1_all[keep, c(id_var, psu_var, strata_var, weight_var), drop = FALSE]
  out[[weight_var]] <- w[keep]
  psu <- trimws(as.character(out[[psu_var]]))
  stratum <- trimws(as.character(out[[strata_var]]))
  if (anyNA(out[[psu_var]]) || any(!nzchar(psu)))
    stop(sprintf("Valid-weight Wave-I records contain missing or blank %s.", psu_var), call. = FALSE)
  if (anyNA(out[[strata_var]]) || any(!nzchar(stratum)))
    stop(sprintf("Valid-weight Wave-I records contain missing or blank %s.", strata_var), call. = FALSE)
  psu_strata_n <- tapply(stratum, psu, function(z) length(unique(z)))
  if (any(psu_strata_n != 1L))
    stop(sprintf("At least one %s maps to multiple %s values in the valid-weight Wave-I frame.",
                 psu_var, strata_var), call. = FALSE)
  expected_h <- as.integer(cfg$analysis$expected_strata_n %||% 4L)
  observed_h <- length(unique(stratum))
  if (is.finite(expected_h) && expected_h > 0L && observed_h != expected_h)
    stop(sprintf("Expected %d nonmissing %s levels in the valid-weight Wave-I frame, found %d.",
                 expected_h, strata_var, observed_h), call. = FALSE)
  psu_per_stratum <- tapply(psu, stratum, function(z) length(unique(z)))
  if (any(psu_per_stratum < 2L))
    stop(sprintf("Every %s level must contain at least two sampled %s values.",
                 strata_var, psu_var), call. = FALSE)
  out$.analysis_domain <- FALSE
  rownames(out) <- NULL
  attr(out, "design_audit") <- list(
    n_valid_weight_records = nrow(out),
    n_psu = length(unique(psu)),
    n_strata = observed_h,
    psu_per_stratum = as.integer(psu_per_stratum),
    strata_labels = names(psu_per_stratum))
  out
}

read_wave1_merged <- function(cfg) {
  msg("Reading and merging Wave 1 source files...", cfg = cfg)
  inhome_w1  <- read_xpt_df(cfg$paths$wave1_inhome)
  birth      <- read_xpt_df(cfg$paths$birth_records)
  nhood      <- read_xpt_df(cfg$paths$neighborhood_w1)
  inschool   <- read_xpt_df(cfg$paths$inschool_w1)
  context_w1 <- read_xpt_df(cfg$paths$contextual_w1)
  health_w1  <- read_xpt_df(cfg$paths$health_w1)
  spatial_w1 <- read_xpt_df(cfg$paths$spatial_w1)
  stchr95_w1 <- read_xpt_df(cfg$paths$stchr95_w1)
  polcon_w1  <- read_xpt_df(cfg$paths$polcon_w1)
  weights_w1 <- read_xpt_df(cfg$paths$weights_w1)
  school_admin <- read_xpt_df(cfg$paths$school_admin_w1)
  school_admin <- canonicalize_join_key_alias(
    school_admin, cfg$analysis$cluster_var, aliases = "ASCHLCDE",
    label = "school_admin_w1", require_complete = FALSE)
  
  source_tables <- list(
    wave1_inhome = inhome_w1,
    birth_records = birth,
    neighborhood_w1 = nhood,
    inschool_w1 = inschool,
    contextual_w1 = context_w1,
    health_w1 = health_w1,
    spatial_w1 = spatial_w1,
    stchr95_w1 = stchr95_w1,
    polcon_w1 = polcon_w1,
    weights_w1 = weights_w1,
    school_admin_w1 = school_admin)
  variable_source_registry <- build_wave1_variable_source_registry(source_tables, cfg)
  strata_audit <- design_field_source_audit(source_tables, cfg$analysis$strata_var)
  if (any(strata_audit$n_matches > 1L)) {
    bad <- strata_audit$source[strata_audit$n_matches > 1L]
    stop(sprintf(
      "Multiple case-insensitive %s columns were found within source table(s): %s. Canonicalize the raw source before merging.",
      cfg$analysis$strata_var, paste(bad, collapse = ", ")), call. = FALSE)
  }
  if (!any(strata_audit$n_matches > 0L)) {
    stop(sprintf(
      paste0("Required Add Health design field '%s' was absent from every configured Wave-I source. ",
             "Verify the restricted-use file inventory and the column name in %s; no model fitting was attempted."),
      cfg$analysis$strata_var, cfg$paths$weights_w1), call. = FALSE)
  }
  msg(sprintf("  [design] %s found in raw source(s): %s.", cfg$analysis$strata_var,
              paste(strata_audit$source[strata_audit$n_matches > 0L], collapse = ", ")),
      cfg = cfg)
  
  id_var <- cfg$analysis$id_var
  cluster_var <- cfg$analysis$cluster_var
  w1_all <- merge_by_key(
    list(inhome_w1, birth, nhood, inschool, context_w1, health_w1,
         spatial_w1, stchr95_w1, polcon_w1, weights_w1), id_var,
    labels = c("wave1_inhome", "birth_records", "neighborhood_w1", "inschool_w1",
               "contextual_w1", "health_w1", "spatial_w1", "stchr95_w1",
               "polcon_w1", "weights_w1"))
  w1_all <- canonicalize_merged_design_field(w1_all, cluster_var)
  cluster_canonical_audit <- attr(w1_all, "canonical_design_field_audit")
  w1_all <- left_join_many_to_one(
    w1_all, school_admin, cluster_var,
    x_label = "wave1_person_merged", y_label = "school_admin_w1", row_id = id_var)
  
  collision_result <- resolve_join_suffix_collisions(w1_all)
  w1_all <- collision_result$data
  # REGION can appear in more than one source and the generic collision resolver
  # intentionally retains an .x name. Reconstruct one canonical field before
  # the dictionary is frozen or candidate variables are enumerated.
  w1_all <- canonicalize_merged_design_field(
    w1_all, cfg$analysis$strata_var, source_audit = strata_audit)
  region_canonical_audit <- attr(w1_all, "canonical_design_field_audit")
  canonical_audit <- rbind(cluster_canonical_audit, region_canonical_audit)
  canonical_audit <- canonical_audit[!duplicated(
    canonical_audit[, c("field", "source_columns"), drop = FALSE]), , drop = FALSE]
  rownames(canonical_audit) <- NULL
  w1_all <- canonicalize_mandatory_W_columns(w1_all, cfg)
  attr(w1_all, "join_suffix_collision_audit") <- collision_result$audit
  attr(w1_all, "design_strata_source_audit") <- strata_audit
  attr(w1_all, "canonical_design_field_audit") <- canonical_audit
  attr(w1_all, "variable_source_registry") <- variable_source_registry
  
  full_design_frame <- build_full_survey_design_frame(w1_all, cfg)
  attr(w1_all, "full_survey_design_frame") <- full_design_frame
  
  # Freeze semantic missing-code meanings using all Wave I rows, before Wave II
  # exposure measurement, outcome construction, fold creation, or screening.
  # REGION is a survey-design field, not a candidate confounder, and is excluded
  # by get_common_exclusion_vars along with AID, PSUSCID, and GSWGT1.
  dict_exclude <- get_common_exclusion_vars(cfg, include_analysis_outputs = FALSE)
  dict_exclude_keys <- canonical_role_key(dict_exclude)
  dict_vars <- names(w1_all)[!canonical_role_key(names(w1_all)) %in% dict_exclude_keys]
  if (cfg$analysis$strata_var %in% dict_vars)
    stop("Internal error: the survey stratum entered the missing-code dictionary.", call. = FALSE)
  dictionary <- build_global_missing_code_dictionary(
    w1_all, dict_vars, cfg$preprocessing)
  attr(w1_all, "global_missing_dictionary") <- dictionary
  msg(sprintf(
    "  [missing dictionary] Frozen exact-code rules for %d Wave I variables using all %d Wave I rows before exposure restriction.",
    length(dictionary), nrow(w1_all)), cfg = cfg)
  w1_all
}

# Column typing: a variable with few substantive unique values (after
# applying the conservative exact-code classifier) is treated as a factor.
# The factor declaration is frozen in the complete-Wave-I dictionary; fold-
# specific recipes only learn levels/pooling from training rows and apply them
# unchanged to validation rows.
classify_factors_by_uniques <- function(df, cfg_pre) {
  as_factor_preserve_values <- function(x) {
    if (is.factor(x)) droplevels(x) else factor(x)
  }
  factor_cols <- names(df)[vapply(names(df), function(nm) {
    rule <- get_missing_rule(df[[nm]], cfg_pre, variable_name = nm)
    isTRUE(rule$as_factor)
  }, logical(1))]
  if (length(factor_cols))
    df[factor_cols] <- lapply(df[factor_cols], as_factor_preserve_values)
  df
}

# Numeric covariates receive two indicators:
# *_missA = native/general missingness; *_miss97 = inferred structural skip.
# Factor missingness is represented once through explicit Missing/Skip levels.
# Exact special codes come from the frozen complete-Wave-I dictionary; no value
# is classified by numeric suffix.
add_dual_missingness_indicators <- function(data, factor_vars, numeric_vars, cfg_pre) {
  data <- as.data.frame(data)
  assert_no_missing_indicator_name_collisions(
    names(data), intersect(numeric_vars, names(data)),
    context = "add_dual_missingness_indicators")
  n_questionnaire <- 0L; n_continuous <- 0L; n_with_codes <- 0L
  n_factor_skip_retained <- 0L
  total_missA_numeric <- 0L; total_miss97_numeric <- 0L
  total_missA_factor  <- 0L; total_miss97_factor  <- 0L
  miss_label <- cfg_pre$factor_missing_label %||% "Missing"
  skip_label <- cfg_pre$factor_skip_label %||% "Skip"
  min_n_skip <- cfg_pre$factor_special_code_min_n %||% 30L
  min_pr_skip <- cfg_pre$factor_special_code_min_prop %||% 0.02
  
  # Numeric variables
  for (nm in intersect(numeric_vars, names(data))) {
    rule <- get_missing_rule(data[[nm]], cfg_pre, variable_name = nm)
    masks <- missing_masks_from_rule(data[[nm]], rule)
    x <- masks$numeric
    missA <- masks$general; miss97 <- masks$skip
    if (isTRUE(rule$questionnaire_like)) n_questionnaire <- n_questionnaire + 1L
    else n_continuous <- n_continuous + 1L
    if (length(rule$general_codes) || length(rule$skip_codes)) n_with_codes <- n_with_codes + 1L
    fill_value <- compute_simple_impute(x[!(missA | miss97)], cfg_pre$numeric_imputation)
    if (!isTRUE(identical(cfg_pre$numeric_missing_scheme, "dual_indicators"))) {
      missA <- missA | miss97
      miss97 <- rep(FALSE, length(x))
    }
    data[[paste0(nm, "_missA")]]  <- as.integer(missA)
    data[[paste0(nm, "_miss97")]] <- as.integer(miss97)
    total_missA_numeric  <- total_missA_numeric  + sum(missA)
    total_miss97_numeric <- total_miss97_numeric + sum(miss97)
    x[missA | miss97] <- fill_value
    data[[nm]] <- x
  }
  
  # Factor variables: use the same learned exact-code rule, then optionally
  # preserve an inferred skip as its own level when common enough.
  for (nm in intersect(factor_vars, names(data))) {
    rule <- get_missing_rule(data[[nm]], cfg_pre, variable_name = nm)
    masks <- missing_masks_from_rule(data[[nm]], rule)
    xc <- canonicalize_factor_text(data[[nm]])
    missA <- masks$general; miss97 <- masks$skip
    assert_reserved_factor_labels_safe(
      data[[nm]], missA, miss97,
      c(miss_label, skip_label, cfg_pre$factor_other_label %||% "_Other_"),
      nm, "add_dual_missingness_indicators")
    if (isTRUE(rule$questionnaire_like)) n_questionnaire <- n_questionnaire + 1L
    else n_continuous <- n_continuous + 1L
    if (length(rule$general_codes) || length(rule$skip_codes)) n_with_codes <- n_with_codes + 1L
    # Factor missingness is represented once through the explicit Missing/Skip
    # levels. Separate factor indicators would be deterministic duplicates.
    total_missA_factor  <- total_missA_factor  + sum(missA)
    total_miss97_factor <- total_miss97_factor + sum(miss97)
    
    n_skip <- sum(miss97); pr_skip <- n_skip / length(xc)
    retain_skip <- n_skip >= min_n_skip || pr_skip >= min_pr_skip
    if (retain_skip) {
      n_factor_skip_retained <- n_factor_skip_retained + 1L
      xc[missA] <- NA_character_
      xc[miss97] <- skip_label
    } else {
      xc[missA | miss97] <- NA_character_
    }
    f <- addNA(factor(xc))
    levels(f)[is.na(levels(f))] <- miss_label
    data[[nm]] <- f
  }
  
  message(sprintf(
    "  [add_dual_missingness_indicators] processed %d numeric and %d factor cols.",
    length(intersect(numeric_vars, names(data))),
    length(intersect(factor_vars, names(data)))))
  message(sprintf(
    "    Numeric: %d _missA flags, %d _miss97 flags (imputation = '%s').",
    total_missA_numeric, total_miss97_numeric, cfg_pre$numeric_imputation))
  message(sprintf(
    "    Factor: %d general-missing and %d structural-skip values represented through levels; skip retained for %d factors.",
    total_missA_factor, total_miss97_factor, n_factor_skip_retained))
  message(sprintf(
    "    Source-informed exact classifier: %d questionnaire-source/like, %d contextual/other; %d variables had an exact special-code family recognized.",
    n_questionnaire, n_continuous, n_with_codes))
  data
}

# =============================================================================
# OUTCOME FAMILY DISPATCHER (v6)
# =============================================================================
# Each family has a constructor that takes (main_df, wave, family_cfg, outcome_cfg)
# and returns a numeric or integer vector Y of length nrow(main_df), with NA
# for rows where the outcome is not observed at the requested wave.
# construct_outcome is the dispatcher called by build_main_dataset. It
# reads cfg$outcome$family and cfg$outcome$family_member to pick which
# constructor to call, writes the result to main_df[[cfg$analysis$outcome_var]],
# and sets the censoring indicator.

# ---- Placeholder helper: read the Wave-N in-home file when available --------
read_wave_inhome <- function(wave, cfg) {
  path_name <- paste0("wave", wave, "_inhome")
  if (!path_name %in% names(cfg$paths)) {
    stop(sprintf("cfg$paths$%s is not configured.", path_name), call. = FALSE)
  }
  p <- cfg$paths[[path_name]]
  if (is.null(p) || !file.exists(p)) {
    stop(sprintf("Wave %d in-home file not found at: %s", wave, p %||% "<NULL>"), call. = FALSE)
  }
  df <- read_xpt_df(p)
  df
}

# ---- Educational Attainment (nested binary) --------------------------------
# Wave III is attainment-to-date. H3ED5 establishes college graduation;
# H3ED1 values 13-17 or college graduation establish some college; and either
# H3ED2/H3ED3=1 or any higher threshold establishes high-school completion.
# Wave IV uses the verified nested thresholds of H4ED2.
construct_outcome_educational_attainment <- function(main_df, wave, family_cfg,
                                                     outcome_cfg, member, pipeline_cfg = NULL) {
  wave <- as.integer(wave)
  message(sprintf("    [outcome] Educational Attainment, wave %d, member = '%s'.", wave, member))
  src <- family_cfg$sources[[as.character(wave)]]
  if (is.null(src))
    stop(sprintf("EducationalAttainment is not configured for wave %d.", wave), call. = FALSE)
  allowed_members <- c("at_least_hs", "at_least_some_college",
                       "at_least_college_grad")
  if (!member %in% allowed_members)
    stop(sprintf("Unknown EducationalAttainment member: %s", member), call. = FALSE)
  main_df <- join_outcome_fields(
    main_df, wave, unname(src), pipeline_cfg,
    sprintf("Wave-%d education source", wave))
  
  if (identical(wave, 3L)) {
    required_roles <- c("highest_grade", "high_school_equivalency",
                        "high_school_diploma", "college_graduate")
    if (!is.character(src) || any(!required_roles %in% names(src)))
      stop("Wave-III education requires the four named H3ED1/H3ED2/H3ED3/H3ED5 sources.",
           call. = FALSE)
    h1_raw <- main_df[[unname(src["highest_grade"])]]
    h2_raw <- main_df[[unname(src["high_school_equivalency"])]]
    h3_raw <- main_df[[unname(src["high_school_diploma"])]]
    h5_raw <- main_df[[unname(src["college_graduate"])]]
    h1 <- to_numeric_codes(h1_raw); h2 <- to_numeric_codes(h2_raw)
    h3 <- to_numeric_codes(h3_raw); h5 <- to_numeric_codes(h5_raw)
    assert_only_known_codes(h1_raw, c(0:22, 96L, 98L, 99L), "H3ED1")
    assert_only_known_codes(h2_raw, c(0L, 1L, 6L, 8L, 9L), "H3ED2")
    assert_only_known_codes(h3_raw, c(0L, 1L, 6L, 8L, 9L), "H3ED3")
    assert_only_known_codes(h5_raw, c(0L, 1L, 6L, 8L, 9L), "H3ED5")
    
    h1_observed <- is.finite(h1) & !(h1 %in% c(96L, 98L, 99L))
    h2_observed <- is.finite(h2) & !(h2 %in% c(6L, 8L, 9L))
    h3_observed <- is.finite(h3) & !(h3 %in% c(6L, 8L, 9L))
    h5_observed <- is.finite(h5) & !(h5 %in% c(6L, 8L, 9L))
    grade_some_college <- h1_observed & h1 > 12 & h1 < 18
    grade_above_rule <- h1_observed & h1 >= 18
    education_conflict <- grade_above_rule & h5_observed & h5 == 0L
    
    college_grad <- rep(NA_integer_, nrow(main_df))
    college_grad[h5_observed & h5 == 1L] <- 1L
    college_grad[h5_observed & h5 == 0L & !education_conflict] <- 0L
    
    some_college <- rep(NA_integer_, nrow(main_df))
    some_college[grade_some_college | college_grad %in% 1L] <- 1L
    some_college[h5_observed & h5 == 0L & h1_observed & h1 <= 12L] <- 0L
    
    high_school <- rep(NA_integer_, nrow(main_df))
    high_school[(h2_observed & h2 == 1L) |
                  (h3_observed & h3 == 1L) |
                  some_college %in% 1L | college_grad %in% 1L] <- 1L
    high_school[h2_observed & h2 == 0L & h3_observed & h3 == 0L &
                  some_college %in% 0L] <- 0L
    
    # These assignments make nesting explicit even if a lower-threshold source
    # is missing: a verified higher attainment necessarily establishes lower
    # attainment. No lower-threshold value is allowed to overturn it.
    some_college[college_grad %in% 1L] <- 1L
    high_school[some_college %in% 1L | college_grad %in% 1L] <- 1L
    Y <- switch(member,
                at_least_hs = high_school,
                at_least_some_college = some_college,
                at_least_college_grad = college_grad)
    nested_violations <- sum(
      (college_grad == 1L & some_college != 1L) |
        (some_college == 1L & high_school != 1L), na.rm = TRUE)
    audit <- data.frame(
      metric = c("definition", "member", "primary", "n_observed", "n_one",
                 "n_zero", "n_missing", "n_h3ed1_13_to_17",
                 "n_college_grad_establishes_some_college",
                 "n_higher_attainment_establishes_hs",
                 "n_h3ed1_18_to_22_h3ed5_zero_conflict",
                 "n_nested_violations"),
      value = c("Wave III attainment-to-date nested binary", member, "TRUE",
                sum(!is.na(Y)), sum(Y == 1L, na.rm = TRUE),
                sum(Y == 0L, na.rm = TRUE), sum(is.na(Y)),
                sum(grade_some_college), sum(college_grad == 1L, na.rm = TRUE),
                sum(some_college == 1L | college_grad == 1L, na.rm = TRUE),
                sum(education_conflict), nested_violations),
      stringsAsFactors = FALSE)
  } else if (identical(wave, 4L)) {
    if (!is.character(src) || length(src) != 1L || !identical(unname(src), "H4ED2"))
      stop("Wave-IV education requires H4ED2 as its sole source.", call. = FALSE)
    raw_source <- main_df[[unname(src)]]
    raw <- to_numeric_codes(raw_source)
    assert_only_known_codes(raw_source, c(0:13, 96L, 98L), "H4ED2")
    observed <- is.finite(raw) & raw %in% 0:13
    threshold <- switch(member,
                        at_least_hs = 3L,
                        at_least_some_college = 6L,
                        at_least_college_grad = 7L)
    Y <- rep(NA_integer_, nrow(main_df))
    Y[observed] <- as.integer(raw[observed] >= threshold)
    audit <- data.frame(
      metric = c("definition", "member", "primary", "source", "threshold",
                 "n_observed", "n_one", "n_zero", "n_missing",
                 "n_nested_violations"),
      value = c("Wave IV H4ED2 nested binary", member, "TRUE", "H4ED2",
                threshold, sum(!is.na(Y)), sum(Y == 1L, na.rm = TRUE),
                sum(Y == 0L, na.rm = TRUE), sum(is.na(Y)), 0L),
      stringsAsFactors = FALSE)
  } else {
    stop("EducationalAttainment is production-configured only for waves III and IV.",
         call. = FALSE)
  }
  if (!any(!is.na(Y)))
    stop("EducationalAttainment constructor produced no observed outcomes.", call. = FALSE)
  message(sprintf("    [outcome] Constructed %d observed, %d missing. Prevalence: %.1f%%.",
                  sum(!is.na(Y)), sum(is.na(Y)), 100 * mean(Y, na.rm = TRUE)))
  list(Y = Y, audit = audit,
       support = list(natural_lower = 0, natural_upper = 1,
                      lower_rule = "fixed_binary", upper_rule = "fixed_binary"))
}

# ---- Labor Force Participation (binary) -----------------------------------
join_outcome_fields <- function(main_df, wave, vars, pipeline_cfg, label) {
  vars <- unique(as.character(vars))
  vars <- vars[!is.na(vars) & nzchar(vars)]
  need <- setdiff(vars, names(main_df))
  if (!length(need)) return(main_df)
  if (is.null(pipeline_cfg))
    stop(label, " requires the full pipeline configuration to read its source file.", call. = FALSE)
  inhome <- read_wave_inhome(wave, pipeline_cfg)
  id_var <- pipeline_cfg$analysis$id_var
  assert_required_columns(inhome, c(id_var, need), sprintf("wave%d inhome", wave))
  left_join_unique(
    main_df, inhome %>% dplyr::select(dplyr::all_of(c(id_var, need))), id_var,
    x_label = "main_df", y_label = label)
}

assert_only_known_codes <- function(x, known, variable, allow_native_missing = TRUE) {
  z <- to_numeric_codes(x)
  native <- character_native_missing_mask(x)
  bad <- is.finite(z) & !(z %in% known)
  if (any(bad))
    stop(sprintf("%s contains unmapped finite code(s): %s.", variable,
                 paste(head(sort(unique(z[bad])), 20L), collapse = ", ")), call. = FALSE)
  if (!isTRUE(allow_native_missing) && any(native))
    stop(variable, " contains native missing values but none are permitted.", call. = FALSE)
  invisible(z)
}

construct_outcome_labor_force_participation <- function(main_df, wave, family_cfg,
                                                        outcome_cfg, member, pipeline_cfg = NULL) {
  wave <- as.integer(wave)
  if (!identical(wave, 4L))
    stop("LaborForceParticipation is production-configured only for Wave IV.",
         call. = FALSE)
  message(sprintf("    [outcome] Labor Force Participation, wave %d.", wave))
  src <- family_cfg$sources[[as.character(wave)]]
  if (is.null(src)) stop(sprintf("LaborForceParticipation is not configured for wave %d.", wave), call. = FALSE)
  main_df <- join_outcome_fields(main_df, wave, unname(src), pipeline_cfg,
                                 sprintf("Wave-%d LFP source", wave))
  Y <- rep(NA_integer_, nrow(main_df))
  
  if (wave == 3L) {
    cc <- family_cfg$wave3_codes
    h7 <- to_numeric_codes(main_df[[unname(src["current_work"])]])
    known <- unique(c(cc$work_yes, cc$work_no, cc$missing))
    assert_only_known_codes(main_df[[unname(src["current_work"])]], known, "H3LM7")
    Y[h7 == cc$work_yes] <- 1L
    Y[h7 == cc$work_no] <- 0L
    audit <- data.frame(
      metric = c("definition", "n_observed", "n_one", "n_zero", "n_missing",
                 "note"),
      value = c("employment_10plus_proxy", sum(!is.na(Y)), sum(Y == 1L, na.rm = TRUE),
                sum(Y == 0L, na.rm = TRUE), sum(is.na(Y)),
                "Wave III cannot distinguish unemployed job-seekers from other nonworkers with this verified item"),
      stringsAsFactors = FALSE)
  } else if (wave == 4L) {
    cc <- family_cfg$wave4_codes
    h6 <- to_numeric_codes(main_df[[unname(src["first_job_current"])]])
    h11 <- to_numeric_codes(main_df[[unname(src["current_work"])]])
    h14 <- to_numeric_codes(main_df[[unname(src["current_status"])]])
    assert_only_known_codes(main_df[[unname(src["first_job_current"])]],
                            unique(c(0L, cc$first_job_yes, cc$lm6_missing)), "H4LM6")
    assert_only_known_codes(main_df[[unname(src["current_work"])]],
                            unique(c(cc$current_work_no, cc$current_work_yes, cc$lm11_missing)), "H4LM11")
    assert_only_known_codes(main_df[[unname(src["current_status"])]],
                            unique(c(1:10, cc$lm14_missing)), "H4LM14")
    # Current employment can be established upstream by H4LM6=1, which
    # legitimately skips H4LM11. Otherwise H4LM11=1 establishes employment.
    Y[h6 == cc$first_job_yes | h11 == cc$current_work_yes] <- 1L
    idx <- is.na(Y) & h11 == cc$current_work_no
    Y[idx & h14 %in% cc$in_labor_force_status] <- 1L
    Y[idx & h14 %in% cc$out_labor_force_status] <- 0L
    audit <- data.frame(
      metric = c("definition", "n_observed", "n_one", "n_zero", "n_missing",
                 "n_h4lm6_employed", "n_h4lm11_employed",
                 "n_status_in_lf", "n_status_out_lf", "n_status_other_unresolved"),
      value = c("route_aware_lfp", sum(!is.na(Y)), sum(Y == 1L, na.rm = TRUE),
                sum(Y == 0L, na.rm = TRUE), sum(is.na(Y)),
                sum(h6 == cc$first_job_yes, na.rm = TRUE),
                sum(h11 == cc$current_work_yes, na.rm = TRUE),
                sum(h11 == cc$current_work_no & h14 %in% cc$in_labor_force_status, na.rm = TRUE),
                sum(h11 == cc$current_work_no & h14 %in% cc$out_labor_force_status, na.rm = TRUE),
                sum(h11 == cc$current_work_no & h14 == cc$unresolved_status, na.rm = TRUE)),
      stringsAsFactors = FALSE)
  } else stop("LaborForceParticipation is production-configured only for Wave IV.", call. = FALSE)
  
  if (!any(!is.na(Y))) stop("LaborForceParticipation constructor produced no observed outcomes.", call. = FALSE)
  message(sprintf("    [outcome] LFP observed=%d, one=%d, zero=%d, missing=%d.",
                  sum(!is.na(Y)), sum(Y == 1L, na.rm = TRUE), sum(Y == 0L, na.rm = TRUE), sum(is.na(Y))))
  list(Y = Y, audit = audit,
       support = list(natural_lower = 0, natural_upper = 1,
                      lower_rule = "fixed_binary", upper_rule = "fixed_binary"))
}

# ---- Hours Worked (continuous) ---------------------------------------------
construct_outcome_hours_worked <- function(main_df, wave, family_cfg, outcome_cfg,
                                           member, pipeline_cfg = NULL) {
  wave <- as.integer(wave)
  if (!identical(wave, 4L))
    stop("HoursWorked is production-configured only for Wave IV.", call. = FALSE)
  message(sprintf("    [outcome] Hours Worked, wave %d.", wave))
  src <- family_cfg$sources[[as.character(wave)]]
  if (is.null(src)) stop(sprintf("HoursWorked is not configured for wave %d.", wave), call. = FALSE)
  main_df <- join_outcome_fields(main_df, wave, unname(src), pipeline_cfg,
                                 sprintf("Wave-%d hours source", wave))
  cap <- as.numeric(family_cfg$cap_hours %||% 120)
  if (!is.finite(cap) || cap <= 0) stop("HoursWorked cap_hours must be positive and finite.", call. = FALSE)
  Y_uncapped <- rep(NA_real_, nrow(main_df))
  
  if (wave == 3L) {
    cc <- family_cfg$wave3_codes
    h7 <- to_numeric_codes(main_df[[unname(src["current_work"])]])
    h16 <- to_numeric_codes(main_df[[unname(src["main_job_hours"])]])
    assert_only_known_codes(main_df[[unname(src["current_work"])]],
                            unique(c(cc$work_yes, cc$work_no, cc$work_missing)), "H3LM7")
    observed_min <- as.numeric(cc$hours_observed_min %||% cc$hours_valid_min)
    known_h <- c(seq(observed_min, cc$hours_valid_max), cc$hours_missing)
    assert_only_known_codes(main_df[[unname(src["main_job_hours"])]], known_h, "H3LM16")
    Y_uncapped[h7 == cc$work_no] <- 0
    worker <- h7 == cc$work_yes
    valid_hours <- is.finite(h16) & h16 >= cc$hours_valid_min & h16 <= cc$hours_valid_max
    inconsistent_low <- worker & is.finite(h16) &
      h16 >= observed_min & h16 < cc$hours_valid_min
    Y_uncapped[worker & valid_hours] <- h16[worker & valid_hours]
    route <- ifelse(h7 == cc$work_no, "not_working_zero",
                    ifelse(worker & valid_hours, "current_main_job_hours",
                           ifelse(inconsistent_low, "worker_hours_below_10_unresolved", "missing")))
    n_low <- sum(inconsistent_low, na.rm = TRUE)
  } else if (wave == 4L) {
    cc <- family_cfg$wave4_codes
    h6 <- to_numeric_codes(main_df[[unname(src["first_job_current"])]])
    h11 <- to_numeric_codes(main_df[[unname(src["current_work"])]])
    h12 <- to_numeric_codes(main_df[[unname(src["current_jobs"])]])
    h13 <- to_numeric_codes(main_df[[unname(src["total_hours"])]])
    h19 <- to_numeric_codes(main_df[[unname(src["primary_job_hours"])]])
    assert_only_known_codes(main_df[[unname(src["first_job_current"])]], c(0L,1L,6L,7L), "H4LM6")
    assert_only_known_codes(main_df[[unname(src["current_work"])]], c(0L,1L,5L,6L,7L), "H4LM11")
    assert_only_known_codes(main_df[[unname(src["current_jobs"])]],
                            unique(c(cc$current_jobs_valid, cc$current_jobs_missing)), "H4LM12")
    assert_only_known_codes(main_df[[unname(src["total_hours"])]],
                            unique(c(seq(cc$total_hours_valid_min, cc$total_hours_valid_max), cc$total_hours_missing)), "H4LM13")
    assert_only_known_codes(main_df[[unname(src["primary_job_hours"])]],
                            unique(c(seq(cc$primary_hours_valid_min, cc$primary_hours_valid_max), cc$primary_hours_missing)), "H4LM19")
    # Wave IV Section 11, pp. 3 and 6: these questions screen jobs >=10 h/week.
    # Zero means no qualifying current job, not necessarily no paid activity.
    # An unknown upstream answer must not erase an explicit current-work answer.
    # https://addhealth.cpc.unc.edu/wp-content/uploads/docs/data/codebooks/Wave-IV-In-Home-Interview-Data.zip
    working <- h6 %in% cc$first_job_yes | h11 %in% cc$current_work_yes
    nonworking <- !working & h11 %in% cc$current_work_no
    Y_uncapped[nonworking] <- 0
    total_route <- working & h12 %in% cc$current_jobs_total_hours_route
    one <- working & h12 %in% 1L
    valid_total <- is.finite(h13) & h13 >= cc$total_hours_valid_min & h13 <= cc$total_hours_valid_max
    valid_primary <- is.finite(h19) & h19 >= cc$primary_hours_valid_min & h19 <= cc$primary_hours_valid_max
    Y_uncapped[total_route & valid_total] <- h13[total_route & valid_total]
    # Deliberately no H4LM19 fallback for respondents routed to H4LM13 with a
    # missing total: primary-job hours would understate total current weekly hours.
    # H4LM12=98 (unknown number of current jobs) is explicitly routed to H4LM13
    # by the Wave-IV questionnaire and therefore uses a valid total if reported.
    Y_uncapped[one & valid_primary] <- h19[one & valid_primary]
    route <- ifelse(nonworking, "not_working_zero",
                    ifelse(total_route & valid_total, "multiple_or_unknown_jobs_total_h4lm13",
                           ifelse(one & valid_primary, "one_job_h4lm19", "missing")))
    n_low <- 0L
  } else stop("HoursWorked is production-configured only for Wave IV.", call. = FALSE)
  
  route[is.na(route)] <- "missing"
  if (length(route) != nrow(main_df) ||
      !identical(route == "missing", !is.finite(Y_uncapped)))
    stop("HoursWorked outcome and route missingness do not reconcile.", call. = FALSE)
  Y <- Y_uncapped
  Y[is.finite(Y)] <- pmin(Y[is.finite(Y)], cap)
  n_capped <- sum(is.finite(Y_uncapped) & Y_uncapped > cap)
  if (any(is.finite(Y) & (Y < 0 | Y > cap)))
    stop("HoursWorked escaped the configured [0, cap] support.", call. = FALSE)
  audit <- data.frame(
    metric = c("definition", "cap_hours", "n_observed", "n_missing", "n_zero",
               "n_capped", "n_wave3_worker_hours_below_10",
               "n_route_not_working_zero", "n_route_primary_or_main_job",
               "n_route_multiple_jobs_total", "n_route_worker_hours_below_10_unresolved",
               "n_route_missing"),
    value = c("unconditional_current_weekly_hours_in_10plus_jobs", cap, sum(is.finite(Y)), sum(!is.finite(Y)),
              sum(Y == 0, na.rm = TRUE), n_capped, n_low,
              sum(route == "not_working_zero", na.rm = TRUE),
              sum(route %in% c("current_main_job_hours", "one_job_h4lm19"), na.rm = TRUE),
              sum(route == "multiple_or_unknown_jobs_total_h4lm13", na.rm = TRUE),
              sum(route == "worker_hours_below_10_unresolved", na.rm = TRUE),
              sum(route == "missing", na.rm = TRUE)),
    stringsAsFactors = FALSE)
  message(sprintf("    [outcome] Hours observed=%d, zero=%d, missing=%d, capped=%d; range=[%s,%s].",
                  sum(is.finite(Y)), sum(Y == 0, na.rm = TRUE), sum(!is.finite(Y)), n_capped,
                  ifelse(any(is.finite(Y)), format(min(Y, na.rm=TRUE)), "NA"),
                  ifelse(any(is.finite(Y)), format(max(Y, na.rm=TRUE)), "NA")))
  list(Y = Y, audit = audit, uncapped = Y_uncapped,
       support = list(natural_lower = 0, natural_upper = cap,
                      lower_rule = "natural", upper_rule = "fixed"))
}

