# ---- Pass-through (negative-control / placebo) outcome --------------------
# Uses a PRE-EXISTING numeric column of the built dataset directly as Y, WITHOUT
# running any headline constructor. This is the correct mechanism for a
# negative-control outcome: it swaps the outcome FAMILY so the dispatcher does
# not build the headline outcome and relabel it (setting only analysis$outcome_var
# would do exactly that -- construct_outcome dispatches on cfg$outcome$family, and
# build_main_dataset writes the constructed Y into whatever analysis$outcome_var
# names). The named column must already be present in the built dataset; this
# constructor never fabricates, joins, or transforms it (no log_transform is
# applied here -- set cfg$outcome$log_transform = FALSE for a raw column). The
# downstream [0,1] bounding is computed from this column's own observed values,
# so it adapts automatically; set cfg$analysis$outcome_type ("continuous" or
# "binary") to match the column. Fails loud if the column is absent or non-numeric.
construct_outcome_pass_through <- function(main_df, wave, family_cfg, outcome_cfg, member, pipeline_cfg = NULL) {
  src <- family_cfg$source_var
  if (is.null(src) || !is.character(src) || length(src) != 1L || !nzchar(src))
    stop("PassThrough outcome: cfg$outcome$families$PassThrough$source_var must be a single existing column name.", call. = FALSE)
  if (!src %in% names(main_df))
    stop(sprintf("PassThrough outcome: source column '%s' is not present in the built dataset. Add it to the covariate read or pick a present column.", src), call. = FALSE)
  raw <- main_df[[src]]
  raw_chr <- trimws(as.character(raw))
  raw_observed <- !is.na(raw) & !is.na(raw_chr) & raw_chr != ""
  Y <- to_num(raw)
  bad_numeric <- raw_observed & !is.finite(Y)
  if (any(bad_numeric)) {
    examples <- unique(raw_chr[bad_numeric])
    examples <- examples[seq_len(min(length(examples), 5L))]
    stop(sprintf(
      "PassThrough outcome column '%s' contains %d observed nonnumeric value(s) (examples: %s).",
      src, sum(bad_numeric), paste(examples, collapse = ", ")), call. = FALSE)
  }
  if (all(!is.finite(Y)))
    stop(sprintf("PassThrough outcome column '%s' has no finite numeric values.", src), call. = FALSE)
  Y[!is.finite(Y)] <- NA_real_
  message(sprintf("    [outcome] PassThrough negative-control column '%s', wave %d: %d observed, %d missing.",
                  src, wave, sum(!is.na(Y)), sum(is.na(Y))))
  Y
}

construct_outcome <- function(main_df, cfg) {
  fam_name <- cfg$outcome$family
  wave     <- cfg$outcome$current_wave %||% cfg$outcome$waves
  if (length(wave) != 1L || !is.numeric(wave))
    stop("construct_outcome(): cfg$outcome$current_wave must be a single integer.", call. = FALSE)
  wave <- as.integer(wave)
  message(sprintf("  [outcome dispatcher] family = '%s', wave = %d.", fam_name, wave))
  fam_cfg <- cfg$outcome$families[[fam_name]]
  if (is.null(fam_cfg))
    stop(sprintf("Unknown outcome family '%s' (not in cfg$outcome$families).", fam_name), call. = FALSE)
  supported <- supported_outcome_waves(fam_name)
  if (!length(supported) || !wave %in% supported)
    stop(sprintf(
      "Outcome dispatcher hard-blocked family='%s', wave=%d; supported wave(s): %s.",
      fam_name, wave,
      if (length(supported)) paste(supported, collapse = ", ") else "none"),
      call. = FALSE)
  if (!is_verified_outcome_spec(cfg, fam_name, wave) &&
      !isTRUE(cfg$safety$allow_unverified_outcome_specs %||% FALSE)) {
    stop(sprintf(
      paste0("Outcome dispatcher blocked an unverified specification: family='%s', wave=%d. ",
             "Verify the constructor against the codebook or deliberately set ",
             "cfg$safety$allow_unverified_outcome_specs=TRUE."),
      fam_name, wave), call. = FALSE)
  }
  member <- cfg$outcome$family_member
  if (identical(fam_cfg$type, "binary_nested") && is.null(member)) {
    member <- names(fam_cfg$members)[length(fam_cfg$members)]
    message(sprintf("  [outcome dispatcher] No family_member set; defaulting to highest threshold '%s'.", member))
  }
  outcome_result <- switch(fam_name,
                           EducationalAttainment   = construct_outcome_educational_attainment(main_df, wave, fam_cfg, cfg$outcome, member, cfg),
                           LaborForceParticipation = construct_outcome_labor_force_participation(main_df, wave, fam_cfg, cfg$outcome, member, cfg),
                           HoursWorked             = construct_outcome_hours_worked(main_df, wave, fam_cfg, cfg$outcome, member, cfg),
                           UsualHours              = construct_outcome_usual_hours(main_df, wave, fam_cfg, cfg$outcome, member, cfg),
                           Compensation            = construct_outcome_compensation(main_df, wave, fam_cfg, cfg$outcome, member, cfg),
                           HealthStatus            = construct_outcome_health_status(main_df, wave, fam_cfg, cfg$outcome, member, cfg),
                           MentalHealth            = construct_outcome_mental_health(main_df, wave, fam_cfg, cfg$outcome, member, cfg),
                           SubstanceUse            = construct_outcome_substance_use(main_df, wave, fam_cfg, cfg$outcome, member, cfg),
                           PassThrough             = construct_outcome_pass_through(main_df, wave, fam_cfg, cfg$outcome, member, cfg),
                           stop(sprintf("Unknown outcome family '%s'.", fam_name), call. = FALSE))
  if (is.list(outcome_result) && !is.null(outcome_result$Y)) {
    Y <- outcome_result$Y
  } else {
    Y <- outcome_result
    outcome_result <- list(Y = Y)
  }
  if (isTRUE(cfg$outcome$stop_on_all_missing_outcome) && !isTRUE(cfg$safety$allow_placeholder_outcomes %||% FALSE) && all(is.na(Y))) {
    stop(sprintf(
      "Outcome constructor for family '%s' wave %d returned all missing values. This usually means the selected outcome family is still a placeholder or the configured source variables are unavailable.",
      fam_name, wave), call. = FALSE)
  }
  # The constructor may have left-joined source columns into main_df via a
  # local copy; re-attach them by re-reading here would duplicate work. We
  # assume the return vector Y is aligned row-for-row with main_df, which it
  # is because dplyr::left_join preserves row order for existing keys and the
  # constructors do not reorder.
  outcome_result$fam_name <- fam_name
  outcome_result$wave <- wave
  outcome_result$member <- member
  outcome_result
}

# hard-coded transform of H1GH50 (usual bedtime). H1GH50 is stored as
# a 12-hour clock STRING ("HH:MMA"/"HH:MMP", hours 00-12, minutes 00-59) with
# string sentinels "999996"/"999998"/"999999". It is parsed to minutes-since-
# midnight (AM 12->0, PM 12->12, PM h->h+12; hour 00 treated as 12 on the
# clock face) and REPLACED by H1GH50__tsin / H1GH50__tcos = sin/cos of the
# 24h angle, preserving the midnight wraparound. Sentinel and unparseable
# values become NA in both columns and are handled by the existing
# missingness machinery. The transform is gated by transform_time_variables.
transform_time_variables_in_df <- function(df, cfg) {
  if (!isTRUE(cfg$analysis$transform_time_variables %||% FALSE)) return(df)
  v <- "H1GH50"
  if (!(v %in% names(df))) {
    msg("  [time] H1GH50 not present; nothing to transform.", cfg = cfg)
    return(df)
  }
  raw <- trimws(as.character(df[[v]]))                  # column is character
  sentinels <- c("999996", "999998", "999999")          # refused / DK / N/A
  is_sent   <- raw %in% sentinels | is.na(raw) | raw == ""
  # Parse "HH:MM" + A/P. Hours 00-12 are all accepted (this encoding uses 00),
  # minutes 00-59, suffix A or P (case-insensitive). The suffix may be followed
  # by an optional "M"/"m" ("AM"/"PM") and preceded by optional whitespace, to
  # absorb extract-to-extract variation in how the meridiem is coded.
  m <- regmatches(raw, regexec("^([0-9]{1,2}):([0-5][0-9])\\s*([AaPp])[Mm]?$", raw))
  hour12 <- rep(NA_real_, length(raw))
  minute <- rep(NA_real_, length(raw))
  ampm   <- rep(NA_character_, length(raw))
  for (i in seq_along(m)) {
    g <- m[[i]]
    if (length(g) == 4L) {
      hour12[i] <- as.numeric(g[2]); minute[i] <- as.numeric(g[3])
      ampm[i]   <- toupper(g[4])
    }
  }
  # Treat hour 00 as 12 on the 12-hour face (same clock position) so the
  # AM/PM rule below applies uniformly.
  hour12[is.finite(hour12) & hour12 == 0] <- 12
  parsed_ok <- !is.na(hour12) & !is.na(minute) & !is.na(ampm) &
    hour12 >= 1 & hour12 <= 12 & !is_sent
  # 12h -> 24h: AM 12 -> 0, AM h -> h ; PM 12 -> 12, PM h -> h+12.
  hour24 <- ifelse(ampm == "A",
                   ifelse(hour12 == 12, 0, hour12),
                   ifelse(hour12 == 12, 12, hour12 + 12))
  minutes <- ifelse(parsed_ok, hour24 * 60 + minute, NA_real_)
  # Cyclical encoding preserves the midnight wraparound (bedtimes cluster on
  # both sides of midnight).
  ang <- 2 * pi * minutes / 1440
  df[[paste0(v, "__tsin")]] <- sin(ang)
  df[[paste0(v, "__tcos")]] <- cos(ang)
  df[[v]] <- NULL
  msg(sprintf("  [time] H1GH50 (12h A/P) -> sin/cos: %d parsed, %d sentinel, %d UNPARSEABLE of %d.",
              sum(parsed_ok), sum(is_sent), sum(!parsed_ok & !is_sent), length(raw)), cfg = cfg)
  df
}

validate_final_sample_design_fields <- function(df, cfg) {
  psu_var <- cfg$analysis$cluster_var
  strata_var <- cfg$analysis$strata_var
  assert_required_columns(df, c(psu_var, strata_var), "final analytic sample")
  psu <- as.character(df[[psu_var]])
  strata <- as.character(df[[strata_var]])
  if (anyNA(psu) || any(!nzchar(trimws(psu))))
    stop(sprintf("Final analytic sample has missing or blank %s values.", psu_var), call. = FALSE)
  if (anyNA(strata) || any(!nzchar(trimws(strata))))
    stop(sprintf(paste0("Final analytic sample has missing or blank %s values. ",
                        "No rows were dropped; repair the merge/design field before running."),
                 strata_var), call. = FALSE)
  psu_strata_n <- tapply(strata, psu, function(z) length(unique(z)))
  if (any(psu_strata_n != 1L))
    stop(sprintf("At least one %s maps to multiple %s values.", psu_var, strata_var), call. = FALSE)
  psu_per_stratum <- tapply(psu, strata, function(z) length(unique(z)))
  expected_h <- as.integer(cfg$analysis$expected_strata_n %||% 4L)
  if (is.finite(expected_h) && expected_h > 0L && length(psu_per_stratum) != expected_h)
    stop(sprintf("Expected %d observed %s levels, found %d.",
                 expected_h, strata_var, length(psu_per_stratum)), call. = FALSE)
  if (any(psu_per_stratum < 2L))
    stop(sprintf("Every observed %s must contain at least two sampled %s values.",
                 strata_var, psu_var), call. = FALSE)
  list(n_strata = length(psu_per_stratum),
       psu_per_stratum = as.integer(psu_per_stratum),
       strata_labels = names(psu_per_stratum))
}

validate_expected_final_sample_gates <- function(df, cfg) {
  if (!isTRUE(cfg$analysis$enforce_expected_sample_gates %||% FALSE))
    return(invisible(list(enforced = FALSE)))
  # Called on the unrestricted valid-weight completer cohort BEFORE optional
  # Wave-I/status restrictions; all upstream integrity gates remain applicable.
  
  expected_n <- as.integer(cfg$analysis$expected_final_n)
  expected_j <- as.integer(cfg$analysis$expected_cluster_n)
  found_t <- sum(df[[cfg$analysis$exposure_var]] == 1L)
  found_j <- length(unique(df[[cfg$analysis$cluster_var]]))
  
  cutpoint_gate <- isTRUE(cfg$analysis$enforce_expected_cutpoint_gate %||% TRUE)
  treated_gate <- isTRUE(cfg$analysis$enforce_expected_treated_gate %||% TRUE)
  expected_cutpoint <- as.numeric(cfg$analysis$expected_exposure_cutpoint)
  expected_t <- as.integer(cfg$analysis$expected_treated_n)
  found_cutpoint <- as.numeric(cfg$exposure$cutpoint)
  
  cutpoint_ok <- !cutpoint_gate || isTRUE(all.equal(found_cutpoint, expected_cutpoint))
  treated_ok <- !treated_gate || found_t == expected_t
  failed <- nrow(df) != expected_n || found_j != expected_j ||
    !cutpoint_ok || !treated_ok
  
  if (failed) {
    expected_parts <- c(sprintf("n=%d", expected_n), sprintf("PSUs=%d", expected_j))
    if (cutpoint_gate)
      expected_parts <- c(expected_parts, sprintf("cutpoint=%s", as.character(expected_cutpoint)))
    if (treated_gate)
      expected_parts <- c(expected_parts, sprintf("treated=%d", expected_t))
    stop(sprintf(paste0(
      "Final analytic-sample gate failed after design-field validation: ",
      "expected %s; found n=%d, PSUs=%d, treated=%d at cutpoint %s."),
      paste(expected_parts, collapse = ", "),
      nrow(df), found_j, found_t, as.character(found_cutpoint)),
      call. = FALSE)
  }
  
  invisible(list(
    enforced = TRUE,
    n = nrow(df),
    treated = found_t,
    psus = found_j,
    exposure_cutpoint = found_cutpoint,
    cutpoint_gate_applied = cutpoint_gate,
    treated_gate_applied = treated_gate
  ))
}

derive_mortality_indicator_from_data <- function(mortality, cfg) {
  mort <- resolve_mortality_spec(cfg, cfg$outcome$current_wave)
  id_var <- cfg$analysis$id_var
  source_var <- mort$source_var
  source_month_var <- mort$source_month_var
  death_year_var <- mort$derived_death_year_var
  death_month_var <- mort$derived_death_month_var
  raw_window_var <- mort$death_in_window_var
  assert_required_columns(
    mortality, c(id_var, source_var, source_month_var), "mortality linkage")
  mortality <- mortality[, c(id_var, source_var, source_month_var), drop = FALSE]
  mortality <- coerce_join_key(mortality, id_var, "mortality linkage",
                               require_complete = TRUE)
  assert_unique_key(mortality, id_var, "mortality linkage",
                    require_complete = TRUE)
  
  raw_year <- mortality[[source_var]]
  year_native_missing <- character_native_missing_mask(raw_year)
  year_num <- to_numeric_codes(raw_year)
  integer_year <- is.finite(year_num) & abs(year_num - round(year_num)) <= 1e-8
  year_int <- rep(NA_integer_, length(year_num))
  year_int[integer_year] <- as.integer(round(year_num[integer_year]))
  valid_year <- integer_year &
    year_int >= as.integer(mort$valid_year_min) &
    year_int <= as.integer(mort$valid_year_max)
  no_death_code <- is.finite(year_num) &
    year_num %in% as.numeric(mort$no_death_codes %||% numeric(0))
  usable_death_year <- valid_year & !no_death_code
  recognized_no_death <- no_death_code |
    (year_native_missing & isTRUE(mort$native_missing_means_no_death))
  recognized_year <- usable_death_year | recognized_no_death
  unrecognized_year <- !recognized_year
  if (any(unrecognized_year)) {
    examples <- unique(trimws(as.character(raw_year[unrecognized_year])))
    examples[is.na(examples) | examples == ""] <- "<native missing>"
    examples <- head(examples, 8L)
    message_text <- sprintf(
      "Mortality source %s contains %d unrecognized value(s); examples: %s.",
      source_var, sum(unrecognized_year), paste(examples, collapse = ", "))
    if (isTRUE(mort$fail_on_unrecognized_codes)) stop(message_text, call. = FALSE)
    warning(message_text,
            " Treating them as no recorded death because the gate is disabled.",
            call. = FALSE)
  }
  
  raw_month <- mortality[[source_month_var]]
  month_native_missing <- character_native_missing_mask(raw_month)
  month_num <- to_numeric_codes(raw_month)
  integer_month <- is.finite(month_num) & abs(month_num - round(month_num)) <= 1e-8
  month_int <- rep(NA_integer_, length(month_num))
  month_int[integer_month] <- as.integer(round(month_num[integer_month]))
  invalid_month_code <- is.finite(month_num) &
    month_num %in% as.numeric(mort$invalid_month_codes %||% integer(0))
  valid_month <- integer_month &
    month_int >= as.integer(mort$valid_month_min) &
    month_int <= as.integer(mort$valid_month_max)
  recognized_month <- month_native_missing | invalid_month_code | valid_month
  unrecognized_month <- !recognized_month
  if (any(unrecognized_month)) {
    examples <- unique(trimws(as.character(raw_month[unrecognized_month])))
    examples[is.na(examples) | examples == ""] <- "<native missing>"
    examples <- head(examples, 8L)
    stop(sprintf(
      paste0("Mortality month source %s contains %d nonmissing code(s) that are ",
             "neither valid months 1-12 nor configured invalid code(s); examples: %s."),
      source_month_var, sum(unrecognized_month), paste(examples, collapse = ", ")),
      call. = FALSE)
  }
  
  death_year <- rep(NA_integer_, length(year_int))
  death_year[usable_death_year] <- year_int[usable_death_year]
  death_month <- rep(NA_integer_, length(month_int))
  death_month[usable_death_year & valid_month] <-
    month_int[usable_death_year & valid_month]
  
  death_in_window <- as.integer(usable_death_year &
                                  year_int >= as.integer(mort$death_year_start) &
                                  year_int <= as.integer(mort$death_year_end))
  if (anyNA(death_in_window) || any(!death_in_window %in% c(0L, 1L)))
    stop("Internal mortality derivation error: incomplete/nonbinary raw-window indicator.",
         call. = FALSE)
  
  out <- mortality[, id_var, drop = FALSE]
  out[[death_year_var]] <- death_year
  out[[death_month_var]] <- death_month
  out[[raw_window_var]] <- death_in_window
  audit <- data.frame(
    source_variable = source_var,
    source_year_variable = source_var,
    source_month_variable = source_month_var,
    derived_death_year_variable = death_year_var,
    derived_death_month_variable = death_month_var,
    raw_window_variable = raw_window_var,
    death_year_start = as.integer(mort$death_year_start),
    death_year_end = as.integer(mort$death_year_end),
    n_mortality_records = nrow(mortality),
    n_valid_calendar_years = sum(valid_year),
    n_calendar_years_eligible_as_death = sum(usable_death_year),
    n_no_death_codes_overlapping_year_range = sum(no_death_code & valid_year),
    n_native_missing = sum(year_native_missing),
    n_native_missing_year = sum(year_native_missing),
    n_explicit_no_death_codes = sum(no_death_code),
    n_unrecognized_codes = sum(unrecognized_year),
    n_unrecognized_year_codes = sum(unrecognized_year),
    n_valid_death_months = sum(usable_death_year & is.finite(death_month)),
    n_unknown_death_months = sum(usable_death_year & !is.finite(death_month)),
    n_month_present_without_usable_death_year = sum(valid_month & !usable_death_year),
    n_native_missing_death_months = sum(usable_death_year & month_native_missing),
    n_997_death_months = sum(usable_death_year & invalid_month_code & month_num == 997),
    n_unrecognized_month_codes = sum(unrecognized_month),
    n_deaths_in_raw_window = sum(death_in_window),
    native_missing_means_no_death = isTRUE(mort$native_missing_means_no_death),
    stringsAsFactors = FALSE)
  list(data = out, audit = audit)
}

normalize_interview_timing <- function(interview_timing, mc, id_var,
                                       strict = TRUE) {
  iy <- mc$interview_year_var %||% NULL
  im <- mc$interview_month_var %||% NULL
  if (is.null(iy) || is.null(im))
    stop("Interview timing normalization requires configured year and month variables.",
         call. = FALSE)
  assert_required_columns(
    interview_timing, c(id_var, iy, im),
    sprintf("Wave-%d interview timing", mc$outcome_wave))
  timing <- interview_timing[, c(id_var, iy, im), drop = FALSE]
  timing <- coerce_join_key(
    timing, id_var, sprintf("Wave-%d interview timing", mc$outcome_wave),
    require_complete = TRUE)
  assert_unique_key(
    timing, id_var, sprintf("Wave-%d interview timing", mc$outcome_wave),
    require_complete = TRUE)
  
  raw_y <- timing[[iy]]
  raw_m <- timing[[im]]
  native_y <- character_native_missing_mask(raw_y)
  native_m <- character_native_missing_mask(raw_m)
  num_y <- to_numeric_codes(raw_y)
  num_m <- to_numeric_codes(raw_m)
  int_y <- is.finite(num_y) & abs(num_y - round(num_y)) <= 1e-8
  int_m <- is.finite(num_m) & abs(num_m - round(num_m)) <= 1e-8
  valid_y <- int_y & num_y >= as.integer(mc$interview_year_valid_min) &
    num_y <= as.integer(mc$interview_year_valid_max)
  valid_m <- int_m & num_m >= as.integer(mc$interview_month_valid_min) &
    num_m <= as.integer(mc$interview_month_valid_max)
  invalid_y <- !native_y & !valid_y
  invalid_m <- !native_m & !valid_m
  if (isTRUE(strict) && any(invalid_y))
    stop(sprintf(
      "Wave-%d interview year contains nonmissing values outside the configured valid range: %s",
      mc$outcome_wave,
      paste(head(sort(unique(as.character(raw_y[invalid_y]))), 10L), collapse = ", ")),
      call. = FALSE)
  if (isTRUE(strict) && any(invalid_m))
    stop(sprintf(
      "Wave-%d interview month contains nonmissing values outside 1-12: %s",
      mc$outcome_wave,
      paste(head(sort(unique(as.character(raw_m[invalid_m]))), 10L), collapse = ", ")),
      call. = FALSE)
  
  year <- rep(NA_integer_, nrow(timing))
  month <- rep(NA_integer_, nrow(timing))
  year[valid_y] <- as.integer(round(num_y[valid_y]))
  month[valid_m] <- as.integer(round(num_m[valid_m]))
  orphan_month <- is.finite(month) & !is.finite(year)
  if (isTRUE(strict) && any(orphan_month))
    stop(sprintf("Wave-%d interview timing has a valid month without a valid year.",
                 mc$outcome_wave), call. = FALSE)
  month[orphan_month] <- NA_integer_
  timing[[iy]] <- year
  timing[[im]] <- month
  
  complete <- is.finite(year) & is.finite(month)
  if (!any(complete))
    stop(sprintf(
      "Wave-%d interview timing contains no complete valid year-month values; cannot define the fieldwork fallback.",
      mc$outcome_wave), call. = FALSE)
  ym_key <- year[complete] * 12L + (month[complete] - 1L)
  first_key <- min(ym_key)
  first_year <- as.integer(first_key %/% 12L)
  first_month <- as.integer(first_key %% 12L + 1L)
  last_key <- max(ym_key)
  last_year <- as.integer(last_key %/% 12L)
  last_month <- as.integer(last_key %% 12L + 1L)
  
  audit <- data.frame(
    outcome_wave = as.integer(mc$outcome_wave),
    interview_year_variable = iy,
    interview_month_variable = im,
    n_wave_timing_rows = nrow(timing),
    n_complete_interview_dates = sum(complete),
    n_year_only_interview_dates = sum(is.finite(year) & !is.finite(month)),
    n_missing_interview_years = sum(!is.finite(year)),
    n_invalid_nonmissing_years = sum(invalid_y),
    n_invalid_nonmissing_months = sum(invalid_m),
    earliest_interview_year = first_year,
    earliest_interview_month = first_month,
    latest_interview_year = last_year,
    latest_interview_month = last_month,
    stringsAsFactors = FALSE)
  list(data = timing, fieldwork_start_year = first_year,
       fieldwork_start_month = first_month,
       fieldwork_end_year = last_year,
       fieldwork_end_month = last_month, audit = audit)
}

classify_mortality_timing <- function(raw_window, death_year, death_month,
                                      interview_year, interview_month,
                                      mc, fieldwork_start_year = NA_integer_,
                                      fieldwork_start_month = NA_integer_,
                                      fieldwork_end_year = NA_integer_,
                                      fieldwork_end_month = NA_integer_) {
  raw_window <- as.integer(raw_window)
  if (anyNA(raw_window) || any(!raw_window %in% c(0L, 1L)))
    stop("Mortality timing classification requires a complete 0/1 raw-window indicator.",
         call. = FALSE)
  n <- length(raw_window)
  if (length(death_year) != n || length(death_month) != n ||
      length(interview_year) != n || length(interview_month) != n)
    stop("Mortality timing classification vector lengths differ.", call. = FALSE)
  
  mode <- as.character(mc$timing_mode %||% "fixed_window")
  death <- integer(n)
  status <- rep("no_death_or_outside_horizon", n)
  candidate <- raw_window == 1L
  
  if (identical(mode, "fixed_window")) {
    death[candidate] <- 1L
    status[candidate] <- "fixed_window_death"
    return(list(death = death, status = status))
  }
  if (!identical(mode, "interview_month"))
    stop("Unknown mortality timing mode: ", mode, call. = FALSE)
  if (!is.finite(fieldwork_end_year) || !is.finite(fieldwork_end_month) ||
      fieldwork_end_month < 1L || fieldwork_end_month > 12L)
    stop("Interview-month mortality requires a finite fieldwork-end year/month.",
         call. = FALSE)
  
  iy_ok <- is.finite(interview_year)
  im_ok <- is.finite(interview_month)
  dm_ok <- is.finite(death_month)
  
  idx <- which(candidate & iy_ok & death_year < interview_year)
  death[idx] <- 1L; status[idx] <- "before_interview_year"
  idx <- which(candidate & iy_ok & death_year > interview_year)
  status[idx] <- "after_interview_year"
  
  same_year <- candidate & iy_ok & death_year == interview_year
  idx <- which(same_year & dm_ok & im_ok & death_month < interview_month)
  death[idx] <- 1L; status[idx] <- "before_interview_month"
  idx <- which(same_year & dm_ok & im_ok & death_month > interview_month)
  status[idx] <- "after_interview_month"
  idx <- which(same_year & dm_ok & im_ok & death_month == interview_month)
  status[idx] <- "same_interview_month_unordered"
  idx <- which(same_year & !(dm_ok & im_ok))
  status[idx] <- "same_interview_year_month_unknown"
  
  no_interview <- candidate & !iy_ok
  idx <- which(no_interview & death_year < fieldwork_end_year)
  death[idx] <- 1L; status[idx] <- "before_fieldwork_end_year_no_interview"
  idx <- which(no_interview & death_year > fieldwork_end_year)
  status[idx] <- "after_fieldwork_end_year_no_interview"
  same_end_year <- no_interview & death_year == fieldwork_end_year
  idx <- which(same_end_year & dm_ok & death_month <= fieldwork_end_month)
  death[idx] <- 1L
  status[idx] <- "on_or_before_fieldwork_end_month_no_interview"
  idx <- which(same_end_year & dm_ok & death_month > fieldwork_end_month)
  status[idx] <- "after_fieldwork_end_month_no_interview"
  idx <- which(same_end_year & !dm_ok)
  status[idx] <- "fieldwork_end_year_death_month_unknown_no_interview"
  
  if (anyNA(death) || any(!death %in% c(0L, 1L)))
    stop("Internal mortality timing classification produced a nonbinary indicator.",
         call. = FALSE)
  list(death = death, status = status)
}

merge_mortality_indicator_from_data <- function(main_sample, mortality, cfg,
                                                interview_timing = NULL) {
  mort <- derive_mortality_indicator_from_data(mortality, cfg)
  mc <- resolve_mortality_spec(cfg, cfg$outcome$current_wave)
  id_var <- cfg$analysis$id_var
  death_var <- mc$death_before_outcome_var
  death_year_var <- mc$derived_death_year_var
  death_month_var <- mc$derived_death_month_var
  raw_window_var <- mc$death_in_window_var
  timing_status_var <- mc$timing_status_var
  interview_year_var <- mc$interview_year_var %||% NULL
  interview_month_var <- mc$interview_month_var %||% NULL
  role_vars <- unique(c(
    death_var, death_year_var, death_month_var, raw_window_var,
    timing_status_var, interview_year_var %||% character(0),
    interview_month_var %||% character(0)))
  conflicts <- canonical_role_key(role_vars) %in% canonical_role_key(names(main_sample))
  if (any(conflicts))
    stop("Mortality-derived or interview-timing variable already exists before linkage: ",
         paste(role_vars[conflicts], collapse = ", "), call. = FALSE)
  
  joined <- left_join_unique(
    main_sample, mort$data, id_var,
    x_label = "main analytic sample", y_label = "mortality linkage",
    require_complete_x = TRUE, require_complete_y = TRUE)
  matched <- !is.na(joined[[raw_window_var]])
  if (isTRUE(cfg$preprocessing$drop_invalid_weights_at_build %||% TRUE) &&
      cfg$analysis$weight_var %in% names(joined)) {
    linkage_required <- suppressWarnings(as.numeric(joined[[cfg$analysis$weight_var]]))
    linkage_required <- is.finite(linkage_required) & linkage_required > 0
  } else linkage_required <- rep(TRUE, nrow(joined))
  unmatched <- !matched
  n_unmatched <- sum(unmatched)
  n_unmatched_required <- sum(unmatched & linkage_required)
  if (n_unmatched_required > 0L && isTRUE(mc$require_complete_linkage %||% TRUE))
    stop(sprintf("Mortality linkage did not cover %d valid-weight analytic respondent(s).",
                 n_unmatched_required), call. = FALSE)
  if (n_unmatched > 0L) {
    warning(sprintf(
      paste0("Mortality linkage omitted %d row(s), including %d valid-weight analytic row(s); ",
             "treating unmatched rows as no recorded death under the configured linkage rule."),
      n_unmatched, n_unmatched_required), call. = FALSE)
    joined[[raw_window_var]][unmatched] <- 0L
    joined[[death_year_var]][unmatched] <- NA_integer_
    joined[[death_month_var]][unmatched] <- NA_integer_
  }
  
  mode <- as.character(mc$timing_mode %||% "fixed_window")
  interview_year <- rep(NA_integer_, nrow(joined))
  interview_month <- rep(NA_integer_, nrow(joined))
  timing_audit <- data.frame()
  fieldwork_start_year <- NA_integer_
  fieldwork_start_month <- NA_integer_
  fieldwork_end_year <- NA_integer_
  fieldwork_end_month <- NA_integer_
  
  if (!is.null(interview_year_var) && !is.null(interview_month_var) &&
      !is.null(interview_timing)) {
    norm <- normalize_interview_timing(
      interview_timing, mc, id_var,
      strict = identical(mode, "interview_month"))
    timing <- norm$data
    fieldwork_start_year <- norm$fieldwork_start_year
    fieldwork_start_month <- norm$fieldwork_start_month
    fieldwork_end_year <- norm$fieldwork_end_year
    fieldwork_end_month <- norm$fieldwork_end_month
    joined <- left_join_unique(
      joined, timing, id_var,
      x_label = "mortality-linked analytic sample", y_label = "interview timing",
      require_complete_x = TRUE, require_complete_y = TRUE)
    interview_year <- as.integer(joined[[interview_year_var]])
    interview_month <- as.integer(joined[[interview_month_var]])
    timing_audit <- norm$audit
  } else {
    if (!is.null(interview_year_var)) joined[[interview_year_var]] <- interview_year
    if (!is.null(interview_month_var)) joined[[interview_month_var]] <- interview_month
  }
  
  if (identical(mode, "interview_month") && is.null(interview_timing))
    stop(sprintf(
      "Wave-%d interview-month mortality requires the full wave interview timing table.",
      mc$outcome_wave), call. = FALSE)
  
  classified <- classify_mortality_timing(
    raw_window = joined[[raw_window_var]],
    death_year = as.integer(joined[[death_year_var]]),
    death_month = as.integer(joined[[death_month_var]]),
    interview_year = interview_year,
    interview_month = interview_month,
    mc = mc,
    fieldwork_start_year = fieldwork_start_year,
    fieldwork_start_month = fieldwork_start_month,
    fieldwork_end_year = fieldwork_end_year,
    fieldwork_end_month = fieldwork_end_month)
  joined[[death_var]] <- as.integer(classified$death)
  joined[[timing_status_var]] <- as.character(classified$status)
  
  death <- joined[[death_var]] == 1L
  raw_candidate <- joined[[raw_window_var]] == 1L
  mort$audit$n_linkage_left_rows <- nrow(joined)
  mort$audit$n_valid_weight_rows_requiring_linkage <- sum(linkage_required)
  mort$audit$n_all_rows_matched <- sum(matched)
  mort$audit$n_all_rows_unmatched <- n_unmatched
  mort$audit$n_required_rows_unmatched <- n_unmatched_required
  mort$audit$n_nonrequired_rows_unmatched <- sum(unmatched & !linkage_required)
  mort$audit$n_linked_deaths_in_raw_window <- sum(raw_candidate)
  mort$audit$n_deaths_classified_before_outcome <- sum(death)
  mort$audit$mortality_timing_mode <- mode
  mort$audit$mortality_classification_rule <- mortality_timing_rule_text(mc)
  mort$audit$fieldwork_start_year <- fieldwork_start_year
  mort$audit$fieldwork_start_month <- fieldwork_start_month
  mort$audit$fieldwork_end_year <- fieldwork_end_year
  mort$audit$fieldwork_end_month <- fieldwork_end_month
  mort$audit$n_interview_year_observed <- sum(is.finite(interview_year))
  mort$audit$n_interview_month_observed <- sum(is.finite(interview_month))
  mort$audit$n_complete_interview_dates <-
    sum(is.finite(interview_year) & is.finite(interview_month))
  mort$audit$n_death_month_unknown_in_raw_window <-
    sum(raw_candidate & !is.finite(joined[[death_month_var]]))
  mort$audit$n_same_interview_month_unordered <-
    sum(joined[[timing_status_var]] == "same_interview_month_unordered")
  mort$audit$n_same_interview_year_month_unknown <-
    sum(joined[[timing_status_var]] == "same_interview_year_month_unknown")
  
  status_tab <- as.data.frame(table(joined[[timing_status_var]]),
                              stringsAsFactors = FALSE)
  names(status_tab) <- c("timing_status", "n")
  status_tab$outcome_wave <- as.integer(mc$outcome_wave)
  status_tab$timing_mode <- mode
  status_tab$fieldwork_start_year <- fieldwork_start_year
  status_tab$fieldwork_start_month <- fieldwork_start_month
  status_tab$fieldwork_end_year <- fieldwork_end_year
  status_tab$fieldwork_end_month <- fieldwork_end_month
  status_tab$interview_year_variable <- interview_year_var %||% NA_character_
  status_tab$interview_month_variable <- interview_month_var %||% NA_character_
  if (nrow(timing_audit)) {
    for (nm in setdiff(names(timing_audit), names(status_tab)))
      status_tab[[nm]] <- timing_audit[[nm]][1L]
  }
  
  list(data = joined, audit = mort$audit,
       interview_timing_audit = status_tab)
}

merge_mortality_indicator <- function(main_sample, cfg) {
  mc <- resolve_mortality_spec(cfg, cfg$outcome$current_wave)
  if (!isTRUE(mc$enabled)) return(main_sample)
  mortality <- read_xpt_df(cfg$paths$mortality)
  
  timing <- NULL
  iy <- mc$interview_year_var %||% NULL
  im <- mc$interview_month_var %||% NULL
  if (!is.null(iy) && !is.null(im)) {
    wave_df <- read_wave_inhome(cfg$outcome$current_wave, cfg)
    timing_vars <- c(cfg$analysis$id_var, iy, im)
    assert_required_columns(
      wave_df, timing_vars,
      sprintf("Wave-%d interview timing", cfg$outcome$current_wave))
    timing <- wave_df[, timing_vars, drop = FALSE]
  }
  
  linked <- merge_mortality_indicator_from_data(
    main_sample, mortality, cfg, interview_timing = timing)
  if (isTRUE(cfg$global$save_stage_csvs)) {
    write_run_csv(linked$audit, cfg, mc$linkage_audit_csv)
    if (!is.null(mc$interview_timing_audit_csv) &&
        !is.null(linked$interview_timing_audit) &&
        nrow(linked$interview_timing_audit))
      write_run_csv(
        linked$interview_timing_audit, cfg, mc$interview_timing_audit_csv)
  }
  linked$data
}

apply_mortality_composite <- function(main_sample, cfg) {
  mc <- resolve_mortality_spec(cfg, cfg$outcome$current_wave)
  death_var <- mc$death_before_outcome_var
  outcome_var <- cfg$analysis$outcome_var
  assert_required_columns(
    main_sample, c(death_var, outcome_var), "mortality-composite outcome")
  death <- to_numeric_codes(main_sample[[death_var]])
  if (anyNA(death) || any(!death %in% c(0, 1)))
    stop("Death-before-outcome indicator must be complete and exactly 0/1.",
         call. = FALSE)
  death <- as.integer(death)
  if (!is.numeric(main_sample[[outcome_var]]) &&
      !is.integer(main_sample[[outcome_var]]))
    stop("Mortality-composite outcome must be numeric before death recoding.",
         call. = FALSE)
  support <- attr(main_sample, "outcome_support")
  if (is.list(support)) {
    lower <- suppressWarnings(as.numeric(
      support$natural_lower %||% support$lower %||% NA_real_))
    upper <- suppressWarnings(as.numeric(
      support$natural_upper %||% support$upper %||% NA_real_))
    if ((is.finite(lower) && lower > 0) || (is.finite(upper) && upper < 0))
      stop("Mortality-composite zero lies outside the configured outcome support.",
           call. = FALSE)
  }
  
  original_y <- as.numeric(main_sample[[outcome_var]])
  observed_death <- death == 1L & is.finite(original_y)
  n_observed_death <- sum(observed_death)
  death_year_var <- mc$derived_death_year_var
  death_month_var <- mc$derived_death_month_var
  interview_year_var <- mc$interview_year_var %||% NULL
  interview_month_var <- mc$interview_month_var %||% NULL
  timing_status_var <- mc$timing_status_var %||% NULL
  audit <- data.frame(
    n_total = nrow(main_sample),
    n_deaths_before_outcome = sum(death == 1L),
    n_deaths_with_observed_original_outcome = n_observed_death,
    n_deaths_with_missing_original_outcome =
      sum(death == 1L & !is.finite(original_y)),
    n_deaths_recoded_to_observed_zero = sum(death == 1L),
    contradiction_gate_enabled = isTRUE(
      mc$fail_on_death_with_observed_original_outcome %||% TRUE),
    mortality_timing_mode = as.character(mc$timing_mode %||% "fixed_window"),
    composite_definition = paste0(
      "Configured outcome set to zero when pre-outcome death is classified by: ",
      mortality_timing_rule_text(mc)),
    stringsAsFactors = FALSE)
  
  if (n_observed_death > 0L) {
    contradiction <- data.frame(
      respondent_id = main_sample[[cfg$analysis$id_var]][observed_death],
      death_indicator = death[observed_death],
      original_outcome = original_y[observed_death],
      original_outcome_source = if ("EarningsSource" %in% names(main_sample))
        as.character(main_sample$EarningsSource[observed_death]) else NA_character_,
      death_year = if (death_year_var %in% names(main_sample))
        main_sample[[death_year_var]][observed_death] else NA_integer_,
      death_month = if (death_month_var %in% names(main_sample))
        main_sample[[death_month_var]][observed_death] else NA_integer_,
      interview_year = if (!is.null(interview_year_var) &&
                           interview_year_var %in% names(main_sample))
        main_sample[[interview_year_var]][observed_death] else NA_integer_,
      interview_month = if (!is.null(interview_month_var) &&
                            interview_month_var %in% names(main_sample))
        main_sample[[interview_month_var]][observed_death] else NA_integer_,
      timing_status = if (!is.null(timing_status_var) &&
                          timing_status_var %in% names(main_sample))
        as.character(main_sample[[timing_status_var]][observed_death]) else NA_character_,
      stringsAsFactors = FALSE)
    if (isTRUE(cfg$global$save_stage_csvs %||% TRUE))
      write_run_csv(contradiction, cfg, mc$contradiction_audit_csv)
    contradiction_message <- sprintf(
      paste0("Mortality linkage contradiction: %d respondent(s) were classified as ",
             "dead before the configured outcome but had a finite original outcome. ",
             "Review mortality/interview timing before permitting zero recoding."),
      n_observed_death)
    if (isTRUE(mc$fail_on_death_with_observed_original_outcome %||% TRUE))
      stop(contradiction_message, call. = FALSE)
    warning(contradiction_message,
            " The contradiction gate is disabled, so the values will be overwritten with zero.",
            call. = FALSE)
  }
  
  out <- main_sample
  out[[outcome_var]][death == 1L] <- 0
  if ("EarningsSource" %in% names(out)) {
    out$EarningsSource <- as.character(out$EarningsSource)
    out$EarningsSource[death == 1L] <- "mortality_zero"
  }
  list(data = out, audit = audit)
}


build_main_dataset <- function(w1_all, cfg) {
  msg("\n===== STAGE: Build main dataset =====", cfg = cfg)
  id_var <- cfg$analysis$id_var
  assert_required_columns(w1_all,
                          c(id_var, cfg$analysis$cluster_var, cfg$analysis$strata_var,
                            cfg$analysis$weight_var), "w1_all")
  main_sample <- w1_all
  sample_flow <- list(wave1_merged = nrow(main_sample))
  global_missing_dictionary <- attr(w1_all, "global_missing_dictionary")
  if (is.null(global_missing_dictionary) || !length(global_missing_dictionary))
    stop("Wave-I merge is missing the frozen global missing-code dictionary; rebuild the Wave-I cache.", call. = FALSE)
  # Use the same outcome-blind, all-Wave-I dictionary for the Wave-II
  # completion diagnostic and every later preprocessing step. Do not relearn
  # semantic reserve-code rules from the completer/noncompleter comparison.
  cfg$preprocessing$global_missing_dictionary <- global_missing_dictionary
  collision_audit <- attr(w1_all, "join_suffix_collision_audit")
  strata_source_audit <- attr(w1_all, "design_strata_source_audit")
  canonical_strata_audit <- attr(w1_all, "canonical_design_field_audit")
  variable_source_registry <- get_variable_source_registry(w1_all, cfg, required = TRUE)
  cfg$preprocessing$variable_source_registry <- variable_source_registry
  full_survey_design_frame <- attr(w1_all, "full_survey_design_frame")
  if (is.null(full_survey_design_frame) || !is.data.frame(full_survey_design_frame))
    stop("Wave I merge is missing the valid-weight full survey-design frame; rebuild the Wave I cache.", call. = FALSE)
  msg(sprintf("  Input W1 merged table: %d rows x %d cols.", nrow(main_sample), ncol(main_sample)), cfg = cfg)
  if (isTRUE(cfg$global$save_stage_csvs)) {
    dict_audit <- missing_dictionary_to_data_frame(global_missing_dictionary, w1_all)
    p_dict <- write_run_csv(
      dict_audit, cfg,
      cfg$diagnostics$global_missing_dictionary_csv %||% "global_missing_code_dictionary.csv")
    msg(sprintf("  [missing dictionary] Audit written: %s", basename(p_dict)), cfg = cfg)
    if (!is.null(strata_source_audit) && is.data.frame(strata_source_audit)) {
      p_strata_source <- write_run_csv(
        strata_source_audit, cfg,
        cfg$diagnostics$design_strata_source_audit_csv %||% "design_strata_source_audit.csv")
      msg(sprintf("  [design] Stratum source audit written: %s", basename(p_strata_source)), cfg = cfg)
    }
    if (!is.null(canonical_strata_audit) && is.data.frame(canonical_strata_audit)) {
      p_strata_canonical <- write_run_csv(
        canonical_strata_audit, cfg,
        cfg$diagnostics$canonical_design_field_audit_csv %||% "canonical_design_field_audit.csv")
      msg(sprintf("  [design] Canonical stratum audit written: %s", basename(p_strata_canonical)), cfg = cfg)
    }
  }
  
  # ---- Build exposure (CES-D -> Depressed): unchanged across outcomes/waves ---
  msg("  [exposure] Reading Wave 2 CES-D items to build 'Depressed'...", cfg = cfg)
  inhome_w2 <- read_xpt_df(cfg$paths$wave2_inhome)
  mh_cols   <- cfg$exposure$cesd_items
  assert_required_columns(inhome_w2, c(id_var, mh_cols), "inhome_w2")
  main_sample <- left_join_unique(
    main_sample, inhome_w2 %>% dplyr::select(dplyr::all_of(c(id_var, mh_cols))), id_var,
    x_label = "wave1 merged sample", y_label = "wave2 Feelings Scale")
  n_before <- nrow(main_sample)
  complete_cesd <- Reduce(`&`, lapply(mh_cols, function(nm) {
    z <- to_numeric_codes(main_sample[[nm]])
    is.finite(z) & !(z %in% cfg$exposure$nonresponse_codes) & z %in% 0:3
  }))
  wave2_completion_status <- data.frame(
    AID = as.character(main_sample[[id_var]]),
    wave2_cesd_complete = as.integer(complete_cesd),
    stringsAsFactors = FALSE)
  names(wave2_completion_status)[1L] <- id_var
  if (isTRUE(cfg$diagnostics$enable_wave2_completion_diagnostic %||% TRUE)) {
    completion_diag <- build_wave2_completion_diagnostic(main_sample, complete_cesd, cfg)
    if (isTRUE(cfg$global$save_stage_csvs)) {
      write_run_csv(completion_diag$balance, cfg,
                    cfg$diagnostics$wave2_completion_balance_csv %||%
                      "wave2_completion_balance.csv")
      write_run_csv(completion_diag$summary, cfg,
                    cfg$diagnostics$wave2_completion_summary_csv %||%
                      "wave2_completion_summary.csv")
    }
  }
  if (isTRUE(cfg$exposure$drop_missing_exposure)) {
    main_sample <- main_sample[complete_cesd, , drop = FALSE]
    msg(sprintf("  [exposure] Dropped %d of %d rows with missing/refused CES-D items; %d remain.",
                n_before - nrow(main_sample), n_before, nrow(main_sample)), cfg = cfg)
  }
  sample_flow$complete_wave2_cesd <- nrow(main_sample)
  if (isTRUE(cfg$analysis$enforce_expected_sample_gates %||% FALSE) &&
      nrow(main_sample) != as.integer(cfg$analysis$expected_complete_cesd_n))
    stop(sprintf("Complete-CES-D sample gate failed: expected %d rows, found %d.",
                 as.integer(cfg$analysis$expected_complete_cesd_n), nrow(main_sample)), call. = FALSE)
  # Preserve the original storage classes of Wave-I covariates. Only the
  # explicitly documented H2FS exposure items are converted here; blanket
  # numeric coercion can silently destroy character categories and identifiers.
  main_sample <- as.data.frame(main_sample, check.names = FALSE)
  if (!setequal(cfg$exposure$reverse_score_items, c("H2FS4", "H2FS8", "H2FS11", "H2FS15")))
    stop("Exposure reverse-score item set does not match the verified Wave-II Feelings Scale specification.", call. = FALSE)
  for (col in mh_cols) {
    z <- to_numeric_codes(main_sample[[col]])
    bad <- !is.finite(z) | !(z %in% 0:3)
    if (any(bad))
      stop(sprintf("Exposure item %s contains %d retained value(s) outside 0:3 after the missing-item restriction.", col, sum(bad)), call. = FALSE)
    main_sample[[col]] <- z
  }
  for (col in cfg$exposure$reverse_score_items)
    main_sample[[col]] <- 3 - main_sample[[col]]
  main_sample$MHSum <- rowSums(main_sample[, mh_cols, drop = FALSE], na.rm = FALSE)
  if (any(!is.finite(main_sample$MHSum)) ||
      any(main_sample$MHSum < 0 | main_sample$MHSum > 57))
    stop("Constructed Wave-II Feelings Scale total escaped its theoretical 0:57 range.", call. = FALSE)
  main_sample[[cfg$analysis$exposure_var]] <-
    as.integer(main_sample$MHSum >= cfg$exposure$cutpoint)
  msg(sprintf("  [exposure] MHSum in [%d, %d]; Depressed (cutpoint=%d): %d of %d = %.2f%%.",
              min(main_sample$MHSum, na.rm = TRUE), max(main_sample$MHSum, na.rm = TRUE),
              cfg$exposure$cutpoint,
              sum(main_sample[[cfg$analysis$exposure_var]] == 1L, na.rm = TRUE),
              nrow(main_sample),
              100 * mean(main_sample[[cfg$analysis$exposure_var]], na.rm = TRUE)), cfg = cfg)
  
  if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave)) {
    mc_now <- resolve_mortality_spec(cfg, cfg$outcome$current_wave)
    msg(sprintf("  [mortality] Wave %d: deriving %s via %s...",
                cfg$outcome$current_wave, mc_now$death_before_outcome_var,
                mortality_timing_rule_text(mc_now)), cfg = cfg)
    main_sample <- merge_mortality_indicator(main_sample, cfg)
  }
  
  # ---- Build outcome via the family dispatcher ---------------------------
  msg("  [outcome] Constructing outcome via family dispatcher...", cfg = cfg)
  oc <- construct_outcome(main_sample, cfg)
  main_sample[[cfg$analysis$outcome_var]] <- oc$Y
  if (identical(cfg$outcome$family,"HoursWorked") && !is.null(oc$uncapped)) {
    if (length(oc$uncapped)!=nrow(main_sample)) stop("Uncapped hours are misaligned.")
    main_sample$.hours_uncapped <- oc$uncapped
  }
  # Verified civilian/resident status is applied later, after cohort assembly.
  # Retained interview evidence takes precedence over final field dispositions.
  if (identical(cfg$outcome$family, "Compensation") &&
      !is.null(oc$source) && length(oc$source) == nrow(main_sample)) {
    main_sample$EarningsSource <- oc$source
    if (isTRUE(cfg$global$save_stage_csvs) && !is.null(oc$audit)) {
      audit_path <- write_run_csv(
        oc$audit, cfg,
        cfg$diagnostics$earnings_construction_audit_csv %||% "earnings_construction_audit.csv")
      msg(sprintf("  [outcome] Earnings construction audit written: %s", basename(audit_path)), cfg = cfg)
    }
    attr(main_sample, "earnings_construction_audit") <- oc$audit
    sample_flow$earnings_exact_before_weight_drop <- sum(main_sample$EarningsSource == "exact")
    sample_flow$earnings_bracket_before_weight_drop <- sum(main_sample$EarningsSource == "bracket_midpoint")
    sample_flow$earnings_missing_before_weight_drop <- sum(!is.finite(main_sample[[cfg$analysis$outcome_var]]))
    sample_flow$valid_zero_exact_before_weight_drop <- sum(
      main_sample$EarningsSource == "exact" & main_sample[[cfg$analysis$outcome_var]] == 0,
      na.rm = TRUE)
  }
  if (!identical(cfg$outcome$family, "Compensation") && !is.null(oc$audit)) {
    if (isTRUE(cfg$global$save_stage_csvs))
      write_run_csv(oc$audit, cfg, "outcome_construction_audit.csv")
    attr(main_sample, "outcome_construction_audit") <- oc$audit
  }
  attr(main_sample, "outcome_support") <- oc$support %||% NULL
  # Optional policy composite for truncation by death. Deaths in the configured
  # window are observed zeros, including respondents whose original outcome was
  # missing; ordinary nondeath outcome missingness continues through delta_Y/pi.
  if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave) &&
      isTRUE(resolve_mortality_spec(cfg, cfg$outcome$current_wave)$composite_zero_at_death %||% FALSE)) {
    mortality_composite <- apply_mortality_composite(main_sample, cfg)
    main_sample <- mortality_composite$data
    attr(main_sample, "mortality_composite_audit") <- mortality_composite$audit
    mort_now <- resolve_mortality_spec(cfg, cfg$outcome$current_wave)
    sample_flow$mortality_zero_before_weight_drop <-
      sum(main_sample[[mort_now$death_before_outcome_var]] == 1L, na.rm = TRUE)
    if (isTRUE(cfg$global$save_stage_csvs))
      write_run_csv(
        mortality_composite$audit, cfg,
        resolve_mortality_spec(cfg, cfg$outcome$current_wave)$output_csv)
  }
  # Censoring indicator
  main_sample[[cfg$analysis$outcome_observed_var]] <-
    as.integer(make_observed_mask(main_sample[[cfg$analysis$outcome_var]]))
  msg(sprintf("  [outcome] %d rows with observed Y (%.1f%%); %d censored.",
              sum(main_sample[[cfg$analysis$outcome_observed_var]] == 1L),
              100 * mean(main_sample[[cfg$analysis$outcome_observed_var]]),
              sum(main_sample[[cfg$analysis$outcome_observed_var]] == 0L)), cfg = cfg)
  sample_flow$outcome_observed_before_weight_drop <-
    sum(main_sample[[cfg$analysis$outcome_observed_var]] == 1L)
  
  if (!is.null(collision_audit) && nrow(collision_audit) > 0L) {
    action_counts <- table(collision_audit$action)
    msg(sprintf(
      "  [cleanup] Audited %d Wave I .y collision column(s): %s.",
      nrow(collision_audit),
      paste(sprintf("%s=%d", names(action_counts), as.integer(action_counts)), collapse = "; ")),
      cfg = cfg)
    if (isTRUE(cfg$global$save_stage_csvs)) {
      p_collision <- write_run_csv(
        collision_audit, cfg,
        cfg$diagnostics$join_suffix_collision_audit_csv %||% "join_suffix_collision_audit.csv")
      msg(sprintf("  [cleanup] Join-suffix collision audit written: %s", basename(p_collision)), cfg = cfg)
    }
  }
  
  # v6 Fix C: drop rows with invalid sampling weights at dataset-build time
  # so every downstream stage sees the same analytic sample.
  if (isTRUE(cfg$preprocessing$drop_invalid_weights_at_build)) {
    w <- suppressWarnings(as.numeric(main_sample[[cfg$analysis$weight_var]]))
    keep_w <- is.finite(w) & w > 0
    n_drop <- sum(!keep_w); n_total <- length(w)
    sample_flow$invalid_weight_dropped <- n_drop
    if (n_drop > 0L) {
      msg(sprintf("  [weights] Dropping %d of %d rows (%.2f%%) with non-positive or missing %s.",
                  n_drop, n_total, 100 * n_drop / n_total, cfg$analysis$weight_var), cfg = cfg)
      main_sample <- main_sample[keep_w, , drop = FALSE]
      msg(sprintf("  [weights] Analytic sample now has %d rows; weights range [%.4g, %.4g].",
                  nrow(main_sample),
                  min(main_sample[[cfg$analysis$weight_var]]),
                  max(main_sample[[cfg$analysis$weight_var]])), cfg = cfg)
    } else {
      msg(sprintf("  [weights] All %d rows have valid %s (no drops).",
                  n_total, cfg$analysis$weight_var), cfg = cfg)
    }
  }
  
  design_audit <- validate_final_sample_design_fields(main_sample, cfg)
  attr(main_sample, "design_field_audit") <- design_audit
  sample_flow$strata_final <- design_audit$n_strata
  
  sample_gate_audit <- validate_expected_final_sample_gates(main_sample, cfg)
  attr(main_sample, "expected_sample_gate_audit") <- sample_gate_audit
  
  # Score before defining any analysis domain. Native missingness is retained;
  # incomplete totals are never treated as zero or silently prorated.
  main_sample$MHSum_W1 <- score_wave1_cesd(main_sample)
  global_missing_dictionary[["MHSum_W1"]] <-
    make_native_only_missing_rule(main_sample$MHSum_W1, "MHSum_W1")
  variable_source_registry <- append_derived_variable_registry(
    variable_source_registry, "MHSum_W1", paste0("H1FS", 1:19), "wave1_inhome")
  sample_flow$unrestricted_valid_weight_n <- nrow(main_sample)
  sample_flow$wave1_total_missing <- sum(!is.finite(main_sample$MHSum_W1))
  if (isTRUE(cfg$analysis$restrict_wave1_depressed)) {
    keep <- is.finite(main_sample$MHSum_W1) &
      main_sample$MHSum_W1 >= (cfg$analysis$wave1_depression_cutpoint %||% 22)
    main_sample <- main_sample[keep, , drop = FALSE]
  }
  sample_flow$after_wave1_scope_n <- nrow(main_sample)
  # v8.44: optional Wave-III exposure scope. Applied AFTER every expected-count
  # gate, so the full-cohort integrity checks remain enforced in every mode.
  scope_result <- apply_exposure_mode_scope(main_sample, cfg)
  main_sample <- scope_result$data
  attr(main_sample, "exposure_mode_audit") <- scope_result$audit
  if (!is.null(scope_result$audit)) {
    sa <- scope_result$audit
    sample_flow$exposure_scope_wave3_complete_n <- sa$n_wave3_scale_complete
    sample_flow$exposure_scope_w2neg_w3pos_n <- sa$n_w2neg_w3pos
    sample_flow$exposure_scope_retained_n <- sa$n_retained
    sample_flow$exposure_scope_exposed_retained_n <- sa$exposed_retained
    msg(sprintf(paste0("  [exposure scope] %s: %d of %d retained (exposed %d of %d; comparison %d of %d); ",
                       "Wave-III-only positives among comparison completers: %d."),
                sa$exposure_mode, sa$n_retained, sa$n_before, sa$exposed_retained,
                sa$exposed_before, sa$comparison_retained, sa$comparison_before,
                sa$n_w2neg_w3pos), cfg = cfg)
    if (isTRUE(cfg$global$save_stage_csvs))
      write_run_csv(sa, cfg, "exposure_mode_audit.csv")
  }
  sample_flow$after_exposure_scope_n <- nrow(main_sample)
  status_result <- apply_verified_labor_status(main_sample, cfg)
  main_sample <- status_result$data
  attr(main_sample, "verified_labor_status_audit") <- status_result$audit
  attr(main_sample, "status_records") <- status_result$details
  sample_flow$verified_status_excluded_n <- sum(main_sample$.status_excluded)
  main_sample <- main_sample[!main_sample$.status_excluded, , drop = FALSE]
  if (!nrow(main_sample)) stop("Configured analysis scope retained no respondents.", call. = FALSE)
  # Recompute after any verified composite zeros; domain and flow below then
  # refer to exactly the rows/outcomes that enter nuisance estimation.
  main_sample[[cfg$analysis$outcome_observed_var]] <-
    as.integer(make_observed_mask(main_sample[[cfg$analysis$outcome_var]]))
  attr(main_sample, "design_field_audit") <- validate_final_sample_design_fields(main_sample, cfg)
  if (!is.null(status_result$audit))
    write_run_csv(status_result$audit, cfg, "verified_labor_status_audit.csv")
  
  weight_winsor_cap_used <- NULL
  weight_renorm_factor_used <- 1
  # winsorize sampling weights at the configured upper quantile, on the
  # FINALIZED analytic sample (clean positive weights only). This dampens the
  # influence of very-high-weight respondents. Runs after the invalid-weight
  # drop so the quantile is not distorted by zero/negative/missing weights.
  wq <- cfg$analysis$weight_winsor_quantile
  if (!is.null(wq) && is.finite(wq) && wq > 0 && wq < 1) {
    w_cur <- suppressWarnings(as.numeric(main_sample[[cfg$analysis$weight_var]]))
    cap <- unname(stats::quantile(w_cur, probs = wq, na.rm = TRUE, type = 8))
    n_wins <- sum(w_cur > cap, na.rm = TRUE)
    w_new <- pmin(w_cur, cap)
    weight_winsor_cap_used <- cap
    # Optional renormalization to preserve the original mean weight, so the
    # winsorized weights represent the same effective population total.
    if (isTRUE(cfg$analysis$weight_winsor_renormalize %||% FALSE)) {
      mean_old <- mean(w_cur, na.rm = TRUE)
      mean_new <- mean(w_new, na.rm = TRUE)
      if (is.finite(mean_new) && mean_new > 0) {
        weight_renorm_factor_used <- mean_old / mean_new
        w_new <- w_new * weight_renorm_factor_used
      }
    }
    main_sample[[cfg$analysis$weight_var]] <- w_new
    msg(sprintf("  [weights] Winsorized %d of %d weights at q%.2f (cap=%.4g); range now [%.4g, %.4g]%s.",
                n_wins, length(w_cur), wq, cap,
                min(w_new, na.rm = TRUE), max(w_new, na.rm = TRUE),
                if (isTRUE(cfg$analysis$weight_winsor_renormalize %||% FALSE)) ", renormalized to original mean" else ""),
        cfg = cfg)
  }
  
  # Preserve the complete valid-weight Wave-I survey design and mark the
  # complete-CES-D analytic sample as a domain. This lets survey::subset retain
  # PSUs outside the analytic domain when linearizing the ATT EIF, as recommended
  # for Add Health subpopulation analyses. No respondent outside the analytic
  # domain enters nuisance fitting or the point estimate.
  design_w <- suppressWarnings(as.numeric(full_survey_design_frame[[cfg$analysis$weight_var]]))
  if (!is.null(weight_winsor_cap_used))
    design_w <- pmin(design_w, weight_winsor_cap_used) * weight_renorm_factor_used
  full_survey_design_frame[[cfg$analysis$weight_var]] <- design_w
  design_ids <- as.character(full_survey_design_frame[[cfg$analysis$id_var]])
  analytic_ids <- as.character(main_sample[[cfg$analysis$id_var]])
  if (anyDuplicated(analytic_ids) || any(!analytic_ids %in% design_ids))
    stop("Final analytic respondents do not map uniquely into the full survey-design frame.", call. = FALSE)
  full_survey_design_frame$.analysis_domain <- design_ids %in% analytic_ids
  if (sum(full_survey_design_frame$.analysis_domain) != nrow(main_sample))
    stop("Survey-design domain membership does not equal the final analytic sample size.", call. = FALSE)
  match_domain <- match(analytic_ids, design_ids)
  if (!isTRUE(all.equal(
    as.numeric(full_survey_design_frame[[cfg$analysis$weight_var]][match_domain]),
    as.numeric(main_sample[[cfg$analysis$weight_var]]), tolerance = 1e-12)))
    stop("Survey-design domain weights do not match the analytic-sample weights.", call. = FALSE)
  
  sample_flow$valid_weight_final <- nrow(main_sample)
  sample_flow$treated_final <- sum(main_sample[[cfg$analysis$exposure_var]] == 1L)
  sample_flow$outcome_observed_final <- sum(main_sample[[cfg$analysis$outcome_observed_var]] == 1L)
  sample_flow$psu_final <- length(unique(main_sample[[cfg$analysis$cluster_var]]))
  sample_flow$strata_final <- length(unique(main_sample[[cfg$analysis$strata_var]]))
  sample_flow$control_final <- sum(main_sample[[cfg$analysis$exposure_var]] == 0L)
  sample_flow$outcome_missing_final <- sum(main_sample[[cfg$analysis$outcome_observed_var]] == 0L)
  sample_flow$earnings_exact_final <- if ("EarningsSource" %in% names(main_sample))
    sum(main_sample$EarningsSource == "exact") else NA_integer_
  sample_flow$earnings_bracket_final <- if ("EarningsSource" %in% names(main_sample))
    sum(main_sample$EarningsSource == "bracket_midpoint") else NA_integer_
  mort_now <- if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave)) resolve_mortality_spec(cfg, cfg$outcome$current_wave) else NULL
  sample_flow$mortality_zero_final <- if (!is.null(mort_now) && mort_now$death_before_outcome_var %in% names(main_sample))
    sum(main_sample[[mort_now$death_before_outcome_var]] == 1L) else 0L
  obs_info <- resolve_composite_observation(main_sample,cfg)
  sample_flow$contribution_verified_structural_zero <- sum(obs_info$structural_zero)
  sample_flow$contribution_mortality_zero <- sum(obs_info$source=="mortality_composite_zero")
  sample_flow$contribution_other_verified_zero <- sum(obs_info$structural_zero & obs_info$source!="mortality_composite_zero")
  sample_flow$contribution_interview_reported <- sum(obs_info$response)
  sample_flow$contribution_outcome_missing <- sum(obs_info$source=="outcome_missing")
  sample_flow$contribution_interview_observed_rate <- if (sum(obs_info$S)>0) sum(obs_info$response)/sum(obs_info$S) else NA_real_
  attr(main_sample,"composite_scope") <- obs_info$scope
  
  sample_flow$valid_zero_exact_final <- if ("EarningsSource" %in% names(main_sample))
    sum(main_sample$EarningsSource == "exact" &
          main_sample[[cfg$analysis$outcome_var]] == 0, na.rm = TRUE) else NA_integer_
  sample_flow$full_design_psu <- length(unique(full_survey_design_frame[[cfg$analysis$cluster_var]]))
  dsp_audit <- build_disposition_audit(main_sample, cfg)
  attr(main_sample, "dsp4_outcome_audit") <- dsp_audit
  if (!is.null(dsp_audit)) write_run_csv(dsp_audit, cfg,
                                         cfg$diagnostics$dsp4_outcome_audit_csv %||% "dsp4_outcome_audit.csv")
  
  # parse and cyclically encode the H1GH50 bedtime (12-hour clock
  # string) on the finalized analytic sample, before it is cached and before
  # screening.
  main_sample <- transform_time_variables_in_df(main_sample, cfg)
  # Derived bedtime sine/cosine columns use native missingness only; all raw
  # Wave I semantic rules remain the globally frozen dictionary.
  for (nm in intersect(c("H1GH50__tsin", "H1GH50__tcos"), names(main_sample))) {
    if (!nm %in% names(global_missing_dictionary))
      global_missing_dictionary[[nm]] <- make_native_only_missing_rule(main_sample[[nm]], nm)
    variable_source_registry <- append_derived_variable_registry(
      variable_source_registry, nm, "H1GH50", "wave1_inhome")
  }
  
  main_sample <- canonicalize_mandatory_W_columns(main_sample, cfg)
  attr(main_sample, "global_missing_dictionary") <- global_missing_dictionary
  attr(main_sample, "variable_source_registry") <- variable_source_registry
  cfg$preprocessing$variable_source_registry <- variable_source_registry
  candidate_alias_audit <- build_candidate_alias_audit(main_sample, cfg)
  validate_candidate_governance(main_sample, cfg, candidate_alias_audit)
  attr(main_sample, "candidate_alias_audit") <- candidate_alias_audit
  if (isTRUE(cfg$global$save_stage_csvs)) {
    p_registry <- write_run_csv(
      variable_source_registry, cfg,
      cfg$causal_governance$variable_source_registry_csv %||%
        "variable_source_registry.csv")
    p_alias <- write_run_csv(
      candidate_alias_audit, cfg,
      cfg$causal_governance$candidate_alias_audit_csv %||%
        "candidate_alias_audit.csv")
    mandatory_audit <- attr(main_sample, "mandatory_W_canonicalization_audit")
    if (is.data.frame(mandatory_audit) && nrow(mandatory_audit))
      write_run_csv(
        mandatory_audit, cfg,
        cfg$causal_governance$mandatory_W_canonicalization_audit_csv %||%
          "mandatory_W_canonicalization_audit.csv")
    msg(sprintf("  [governance] Source registry written: %s", basename(p_registry)), cfg = cfg)
    msg(sprintf("  [governance] Candidate-alias audit written: %s", basename(p_alias)), cfg = cfg)
  }
  attr(main_sample, "sample_flow") <- sample_flow
  attr(main_sample, "survey_design_frame") <- full_survey_design_frame
  attr(main_sample, "wave2_completion_status") <- wave2_completion_status
  
  msg(sprintf("===== Main dataset ready: %d rows x %d cols. =====",
              nrow(main_sample), ncol(main_sample)), cfg = cfg)
  main_sample
}

# Which columns are eligible to enter screening/estimation as W. Excludes
# the exposure, outcome, IDs, cluster, weights, outcome-observed indicator,
# and any helper columns the exposure/outcome constructors created.
get_candidate_vars <- function(df, cfg) {
  audit <- build_candidate_alias_audit(df, cfg)
  governed <- validate_candidate_governance(df, cfg, audit)
  governed$candidates
}

# =============================================================================
# 4) CLUSTER-AWARE FOLD CONSTRUCTION
# =============================================================================
# Plain-English role: build cross-validation folds at the CLUSTER level (not
# the row level). Entire clusters stay together in train or validation so
# dependence within a cluster cannot leak across the CV boundary. We also
# greedily balance the number of exposed units across folds, which is
# important when exposure prevalence is only ~9%.

make_cluster_folds_balanced <- function(cluster, A, k = 5L, seed = 1L,
                                        weights = NULL, delta = NULL,
                                        balance_on_weights = FALSE,
                                        max_attempts = 500L,
                                        projected_size_tolerance_prop = 0.02,
                                        max_size_ratio = 1.60,
                                        max_size_deviation_prop = 0.35,
                                        min_active_cell_n = 1L) {
  cluster <- trimws(as.character(cluster))
  if (!length(cluster) || anyNA(cluster) || any(!nzchar(cluster)))
    stop("Fold construction requires complete nonblank cluster identifiers.", call. = FALSE)
  A <- as.integer(A)
  if (length(A) != length(cluster) || anyNA(A) || any(!A %in% c(0L, 1L)))
    stop("Fold construction requires a complete binary treatment vector.", call. = FALSE)
  if (is.null(weights)) weights <- rep(1, length(A))
  weights <- as.numeric(weights)
  if (length(weights) != length(A) || any(!is.finite(weights)) || any(weights <= 0))
    stop("Fold construction requires positive finite weights.", call. = FALSE)
  if (is.null(delta)) delta <- rep(1L, length(A))
  delta <- as.integer(delta)
  if (length(delta) != length(A) || anyNA(delta) || any(!delta %in% c(0L, 1L)))
    stop("Fold construction requires a complete binary outcome-observation vector.", call. = FALSE)
  max_attempts <- as.integer(max_attempts)
  min_active_cell_n <- as.integer(min_active_cell_n)
  if (!is.finite(max_attempts) || max_attempts < 1L ||
      !is.finite(projected_size_tolerance_prop) ||
      projected_size_tolerance_prop < 0 || projected_size_tolerance_prop > 0.20 ||
      !is.finite(max_size_ratio) || max_size_ratio <= 1 ||
      !is.finite(max_size_deviation_prop) || max_size_deviation_prop <= 0 ||
      !is.finite(min_active_cell_n) || min_active_cell_n < 1L)
    stop("Fold construction controls are invalid.", call. = FALSE)
  
  dat <- data.frame(cluster = cluster, A = A, delta = delta, w = weights,
                    stringsAsFactors = FALSE)
  dat$a1d1 <- as.integer(A == 1L & delta == 1L)
  dat$a1d0 <- as.integer(A == 1L & delta == 0L)
  dat$a0d1 <- as.integer(A == 0L & delta == 1L)
  dat$a0d0 <- as.integer(A == 0L & delta == 0L)
  cell_names <- c("a1d1", "a1d0", "a0d1", "a0d0")
  cl_stats <- stats::aggregate(
    x = list(n = rep(1L, nrow(dat)),
             a_sum = dat$A,
             a_w = dat$w * dat$A,
             obs_a = dat$A * dat$delta,
             a1d1 = dat$a1d1, a1d0 = dat$a1d0,
             a0d1 = dat$a0d1, a0d0 = dat$a0d0),
    by = list(cluster = dat$cluster), FUN = sum)
  n_clusters <- nrow(cl_stats)
  k_requested <- as.integer(k)
  k <- min(k_requested, n_clusters)
  if (!is.finite(k) || k < 2L)
    stop("Need at least two unique clusters to make folds.", call. = FALSE)
  
  cell_totals <- colSums(cl_stats[cell_names])
  active <- cell_totals > 0
  if (any(active)) {
    clusters_with_cell <- vapply(cell_names, function(z) sum(cl_stats[[z]] > 0), integer(1))
    k_by_cluster_support <- min(clusters_with_cell[active])
    k_by_count_support <- min(floor(cell_totals[active] / min_active_cell_n))
    k <- min(k, k_by_cluster_support, k_by_count_support)
  }
  if (k < 2L)
    stop("Fewer than two folds can satisfy the active treatment-by-observation support requirement.", call. = FALSE)
  
  target_n <- nrow(dat) / k
  total_cell_counts <- cell_totals
  best_assignment <- NULL
  best_key <- c(Inf, Inf, Inf)
  
  assignment_diagnostics <- function(out) {
    fold_n <- tabulate(out, nbins = k)
    if (any(fold_n <= 0L)) return(NULL)
    fold_cells <- vapply(seq_len(k), function(f) {
      c(a1d1 = sum(A[out == f] == 1L & delta[out == f] == 1L),
        a1d0 = sum(A[out == f] == 1L & delta[out == f] == 0L),
        a0d1 = sum(A[out == f] == 0L & delta[out == f] == 1L),
        a0d0 = sum(A[out == f] == 0L & delta[out == f] == 0L))
    }, numeric(4L))
    support_validation <- fold_cells >= min_active_cell_n
    support_training <- sweep(fold_cells, 1L, total_cell_counts, function(x, tot) tot - x) >= min_active_cell_n
    support_ok <- all(support_validation[active, , drop = FALSE]) &&
      all(support_training[active, , drop = FALSE])
    size_ratio <- max(fold_n) / min(fold_n)
    size_deviation_prop <- max(abs(fold_n - target_n)) / target_n
    active_targets <- pmax(total_cell_counts[active] / k, 1)
    cell_balance <- if (any(active)) {
      mean((sweep(fold_cells[active, , drop = FALSE], 1L, active_targets, "/") - 1)^2)
    } else 0
    list(fold_n = fold_n, fold_cells = fold_cells,
         support_ok = support_ok, size_ratio = size_ratio,
         size_deviation_prop = size_deviation_prop,
         cell_balance = cell_balance)
  }
  
  target_a <- sum(A) / k
  target_obs_a <- sum(A * delta) / k
  target_aw <- sum(weights * A) / k
  target_cells <- pmax(total_cell_counts / k, 1)
  
  for (attempt in seq_len(max_attempts)) {
    cs <- cl_stats
    cs$.tie <- with_local_seed(seed + attempt - 1L, stats::runif(n_clusters))
    # Largest clusters are placed first, as in longest-processing-time bin
    # packing. This prevents treatment balance from creating tiny validation
    # folds when treatment is concentrated in a few large schools.
    cs <- cs[order(-cs$n, -cs$a_sum, -cs$obs_a, -cs$a_w, cs$.tie), , drop = FALSE]
    fold_a <- rep(0, k); fold_aw <- rep(0, k)
    fold_n <- rep(0, k); fold_obs_a <- rep(0, k)
    fold_cells_running <- matrix(0, nrow = length(cell_names), ncol = k,
                                 dimnames = list(cell_names, NULL))
    fold_assign_cluster <- integer(nrow(cs))
    
    for (i in seq_len(nrow(cs))) {
      projected_n <- fold_n + cs$n[i]
      best_projected_n <- min(projected_n)
      size_tolerance <- max(1, projected_size_tolerance_prop * target_n)
      eligible <- which(projected_n <= best_projected_n + size_tolerance + 1e-12)
      
      cell_add <- as.numeric(unlist(cs[i, cell_names, drop = FALSE],
                                    use.names = FALSE))
      cell_score <- vapply(eligible, function(f) {
        projected_cells <- fold_cells_running[, f] + cell_add
        mean(((projected_cells[active] - target_cells[active]) /
                target_cells[active])^2)
      }, numeric(1))
      treatment_score <- ((fold_a[eligible] + cs$a_sum[i] - target_a) / max(target_a, 1))^2 +
        ((fold_obs_a[eligible] + cs$obs_a[i] - target_obs_a) / max(target_obs_a, 1))^2
      if (isTRUE(balance_on_weights))
        treatment_score <- treatment_score +
        ((fold_aw[eligible] + cs$a_w[i] - target_aw) / max(target_aw, 1))^2
      score <- cell_score + treatment_score
      best <- eligible[score <= min(score) + 1e-12]
      chosen <- if (length(best) == 1L) best[[1L]] else
        with_local_seed(seed + attempt * 100000L + i, sample(best, 1L))
      
      fold_assign_cluster[i] <- chosen
      fold_a[chosen] <- fold_a[chosen] + cs$a_sum[i]
      fold_aw[chosen] <- fold_aw[chosen] + cs$a_w[i]
      fold_obs_a[chosen] <- fold_obs_a[chosen] + cs$obs_a[i]
      fold_n[chosen] <- fold_n[chosen] + cs$n[i]
      fold_cells_running[, chosen] <- fold_cells_running[, chosen] + cell_add
    }
    
    map <- stats::setNames(fold_assign_cluster, cs$cluster)
    out <- unname(as.integer(map[cluster]))
    if (anyNA(out) || length(unique(out)) != k) next
    diag <- assignment_diagnostics(out)
    if (is.null(diag) || !isTRUE(diag$support_ok)) next
    key <- c(diag$size_ratio, diag$size_deviation_prop, diag$cell_balance)
    # Lexicographic comparison prevents improved cell balance from
    # compensating for worse fold-size balance.
    better <- is.null(best_assignment) || key[1] < best_key[1] - 1e-12 ||
      (abs(key[1] - best_key[1]) <= 1e-12 && key[2] < best_key[2] - 1e-12) ||
      (abs(key[1] - best_key[1]) <= 1e-12 && abs(key[2] - best_key[2]) <= 1e-12 &&
         key[3] < best_key[3] - 1e-12)
    if (better) {
      best_assignment <- list(fold = out, diagnostics = diag, attempt = attempt)
      best_key <- key
    }
  }
  
  if (is.null(best_assignment))
    stop(sprintf(paste0("Could not construct %d whole-cluster folds with at least %d observation(s) ",
                        "in every active A-by-delta cell in validation and training complements after %d attempts."),
                 k, min_active_cell_n, max_attempts), call. = FALSE)
  if (best_assignment$diagnostics$size_ratio > max_size_ratio ||
      best_assignment$diagnostics$size_deviation_prop > max_size_deviation_prop) {
    stop(sprintf(paste0("Best whole-cluster assignment remains too imbalanced: fold sizes [%s], ",
                        "max/min=%.3f (limit %.3f), maximum target deviation=%.3f (limit %.3f)."),
                 paste(best_assignment$diagnostics$fold_n, collapse = ","),
                 best_assignment$diagnostics$size_ratio, max_size_ratio,
                 best_assignment$diagnostics$size_deviation_prop, max_size_deviation_prop),
         call. = FALSE)
  }
  attr(best_assignment$fold, "fold_diagnostics") <- c(best_assignment$diagnostics,
                                                      list(k_requested = k_requested, k_used = k, attempts_used = best_assignment$attempt,
                                                           assignment_method = "LPT_size_primary_with_hard_A_delta_support"))
  best_assignment$fold
}

fold_control_from_cfg <- function(cfg, level = c("outer", "internal")) {
  level <- match.arg(level)
  internal <- identical(level, "internal")
  list(
    max_attempts = as.integer(cfg$final_tmle$fold_max_attempts %||% 500L),
    projected_size_tolerance_prop = as.numeric(
      cfg$final_tmle$fold_projected_size_tolerance_prop %||% 0.02),
    max_size_ratio = as.numeric(if (internal)
      cfg$final_tmle$fold_internal_max_size_ratio %||% 1.75 else
        cfg$final_tmle$fold_max_size_ratio %||% 1.60),
    max_size_deviation_prop = as.numeric(if (internal)
      cfg$final_tmle$fold_internal_max_size_deviation_prop %||% 0.45 else
        cfg$final_tmle$fold_max_size_deviation_prop %||% 0.35),
    min_active_cell_n = as.integer(cfg$final_tmle$fold_min_active_cell_n %||% 1L))
}


# Build whole-cluster fold ids for the rough prescreen. Row-level folds are
# prohibited so school dependence cannot cross screening-validation boundaries.
make_rough_fold_ids <- function(n, K, seed, cluster_vec = NULL, A_vec = NULL,
                                delta_vec = NULL, weights = NULL,
                                cluster_aware = TRUE, fold_control = NULL) {
  if (!isTRUE(cluster_aware))
    stop("Row-level rough-screen folds are disabled; use whole-cluster folds.", call. = FALSE)
  if (is.null(cluster_vec) || is.null(A_vec) || length(cluster_vec) != n || length(A_vec) != n)
    stop("Cluster-aware rough-screen folds require aligned cluster and treatment vectors.", call. = FALSE)
  ctl <- fold_control %||% list()
  do.call(make_cluster_folds_balanced, c(list(
    cluster = cluster_vec, A = A_vec, k = K, seed = seed,
    weights = weights, delta = delta_vec), ctl))
}

# =============================================================================
# 5) STAGE 1: ROUGH PRE-SCREEN
# =============================================================================
# Plain-English role: a fast first-pass filter. For every candidate variable
# we fit a single-variable cross-validated model predicting (a) the exposure
# and (b) the outcome, compute a score (logloss- or MSE-based R^2), then keep
# the variables whose scores exceed a "knee" cutoff. The purpose is to drop
# obvious noise columns before final TMLE. In the default
# pipeline, the rough screen is nested inside final TMLE folds and always
# uses whole-school validation folds.

build_single_var_screen_df <- function(nm, X, impute_method = "median") {
  if (grepl("(_missA|_miss97)$", nm)) return(NULL)
  col <- X[[nm]]
  miss_names <- paste0(nm, c("_missA", "_miss97"))
  miss_names <- miss_names[miss_names %in% names(X)]
  if (is.numeric(col)) {
    x <- as.numeric(col)
    fill_value <- compute_simple_impute(x, impute_method)
    x[is.na(x)] <- fill_value
    out <- data.frame(value = x, check.names = FALSE)
  } else {
    f  <- addNA(as.factor(col))
    mm <- stats::model.matrix(~ f, data = data.frame(f = f), na.action = stats::na.pass)
    if (nrow(mm) != length(f)) stop(sprintf("build_single_var_screen_df(): variable '%s' produced %d rows but expected %d.", nm, nrow(mm), length(f)), call. = FALSE)
    mm <- mm[, colnames(mm) != "(Intercept)", drop = FALSE]
    if (ncol(mm) == 0L) return(NULL)
    out <- as.data.frame(mm, check.names = FALSE)
  }
  if (length(miss_names) > 0L)
    out <- cbind(out, as.data.frame(X[, miss_names, drop = FALSE], check.names = FALSE))
  out
}

screen_binom_linear <- function(y, X, K = 5L, seed = 1L, eps = 1e-15,
                                fold = NULL, weights = NULL, ridge_lambda = 1.0,
                                glmnet_maxit = 1000000L, glmnet_thresh = 1e-5) {
  keep <- !is.na(y)
  if (!is.null(weights)) keep <- keep & is.finite(weights) & weights > 0
  y <- y[keep]; X <- X[keep, , drop = FALSE]
  w <- normalize_positive_weights(if (is.null(weights)) NULL else weights[keep],
                                  length(y), "binary screen weights")
  stopifnot(all(y %in% 0:1))
  n <- length(y)
  if (n < max(10L, K)) return(setNames(rep(NA_real_, ncol(X)), names(X)))
  if (is.null(fold)) {
    fold <- with_local_seed(seed, sample(rep(seq_len(K), length.out = n)))
  } else fold <- fold[keep]
  if (length(fold) != n || anyNA(fold) || any(fold < 1L))
    stop("Binary screen received invalid fold assignments.", call. = FALSE)
  K <- max(as.integer(fold))
  clip <- function(p) pmin(pmax(p, eps), 1 - eps)
  wmean <- function(z, ww) sum(ww * z) / sum(ww)
  logloss <- function(yy, p, ww) {
    p <- clip(p)
    sum(ww * (-(yy * log(p) + (1 - yy) * log(1 - p)))) / sum(ww)
  }
  p0 <- numeric(n)
  for (k in seq_len(K)) {
    tr <- fold != k; te <- !tr
    p0[te] <- wmean(y[tr], w[tr])
  }
  ll0 <- logloss(y, p0, w)
  if (!is.finite(ll0) || ll0 <= 0) return(setNames(rep(NA_real_, ncol(X)), names(X)))
  
  fit_predict <- function(Xtr, ytr, Xte, wtr) {
    mu_y <- wmean(ytr, wtr)
    if (length(unique(ytr)) < 2L || nrow(Xtr) < 5L) return(rep(mu_y, nrow(Xte)))
    Xtr <- suppressWarnings(data.matrix(Xtr)); Xte <- suppressWarnings(data.matrix(Xte))
    Xtr[!is.finite(Xtr)] <- 0; Xte[!is.finite(Xte)] <- 0
    sds <- if (ncol(Xtr)) apply(Xtr, 2, stats::sd) else numeric(0)
    keep_cols <- is.finite(sds) & sds > 0
    nc0 <- sum(keep_cols)
    if (nc0 == 0L) return(rep(mu_y, nrow(Xte)))
    Xtr <- Xtr[, keep_cols, drop = FALSE]; Xte <- Xte[, keep_cols, drop = FALSE]
    wtr <- normalize_positive_weights(wtr, length(ytr), "binary screen training weights")
    if (nc0 == 1L) {
      xs_mu <- wmean(Xtr[, 1], wtr)
      xs_sd <- sqrt(sum(wtr * (Xtr[, 1] - xs_mu)^2) / sum(wtr))
      if (!is.finite(xs_sd) || xs_sd <= 0) return(rep(mu_y, nrow(Xte)))
      ztr <- (Xtr[, 1] - xs_mu) / xs_sd; zte <- (Xte[, 1] - xs_mu) / xs_sd
      Ztr <- cbind(value = ztr, .glmnet_pad = 0); Zte <- cbind(value = zte, .glmnet_pad = 0)
      fit1 <- tryCatch(glmnet::glmnet(
        x = Ztr, y = ytr, family = "binomial", weights = wtr,
        alpha = 0, lambda = ridge_lambda, standardize = FALSE,
        intercept = TRUE, thresh = glmnet_thresh, maxit = glmnet_maxit),
        error = function(e) NULL)
      if (is.null(fit1)) return(rep(NA_real_, nrow(Xte)))
      pr <- tryCatch(as.numeric(stats::predict(
        fit1, newx = Zte, type = "response", s = ridge_lambda)),
        error = function(e) NULL)
      if (is.null(pr) || !all(is.finite(pr))) return(rep(NA_real_, nrow(Xte)))
      return(pr)
    }
    fit <- tryCatch(glmnet::glmnet(
      x = Xtr, y = ytr, family = "binomial", weights = wtr,
      alpha = 0, lambda = ridge_lambda, standardize = TRUE,
      intercept = TRUE, thresh = glmnet_thresh, maxit = glmnet_maxit),
      error = function(e) NULL)
    if (is.null(fit)) return(rep(NA_real_, nrow(Xte)))
    pr <- tryCatch(as.numeric(stats::predict(
      fit, newx = Xte, type = "response", s = ridge_lambda)),
      error = function(e) NULL)
    if (is.null(pr) || !all(is.finite(pr))) rep(NA_real_, nrow(Xte)) else pr
  }
  
  vapply(names(X), function(nm) {
    if (grepl("(_missA|_miss97)$", nm)) return(NA_real_)
    Xnm <- tryCatch(build_single_var_screen_df(nm, X, impute_method = "median"),
                    error = function(e) NULL)
    if (is.null(Xnm) || ncol(Xnm) == 0L) return(NA_real_)
    p <- numeric(n)
    for (k in seq_len(K)) {
      tr <- fold != k; te <- !tr
      p[te] <- fit_predict(Xnm[tr, , drop = FALSE], y[tr],
                           Xnm[te, , drop = FALSE], w[tr])
    }
    ll <- logloss(y, p, w)
    1 - ll / ll0
  }, numeric(1))
}
screen_gauss_linear <- function(y, X, K = 5L, seed = 1L,
                                fold = NULL, weights = NULL) {
  keep <- is.finite(y)
  if (!is.null(weights)) keep <- keep & is.finite(weights) & weights > 0
  y <- y[keep]; X <- X[keep, , drop = FALSE]
  w <- normalize_positive_weights(if (is.null(weights)) NULL else weights[keep],
                                  length(y), "gaussian screen weights")
  n <- length(y)
  if (n < max(10L, K)) return(setNames(rep(NA_real_, ncol(X)), names(X)))
  if (is.null(fold)) {
    fold <- with_local_seed(seed, sample(rep(seq_len(K), length.out = n)))
  } else fold <- fold[keep]
  if (length(fold) != n || anyNA(fold) || any(fold < 1L))
    stop("Gaussian screen received invalid fold assignments.", call. = FALSE)
  K <- max(as.integer(fold))
  wmean <- function(z, ww) sum(ww * z) / sum(ww)
  mse <- function(yy, yhat, ww) sum(ww * (yy - yhat)^2) / sum(ww)
  y0 <- numeric(n)
  for (k in seq_len(K)) {
    tr <- fold != k; te <- !tr
    y0[te] <- wmean(y[tr], w[tr])
  }
  mse0 <- mse(y, y0, w)
  if (!is.finite(mse0) || mse0 <= 0) return(setNames(rep(NA_real_, ncol(X)), names(X)))
  
  vapply(names(X), function(nm) {
    col <- X[[nm]]
    if (is.matrix(col)) { if (ncol(col) == 1L) col <- col[, 1] else return(NA_real_) }
    if (grepl("(_missA|_miss97)$", nm)) return(NA_real_)
    yhat <- numeric(n)
    if (is.numeric(col)) {
      miss_names <- paste0(nm, c("_missA", "_miss97"))
      miss_names <- miss_names[miss_names %in% names(X)]
      for (k in seq_len(K)) {
        tr <- fold != k; te <- !tr
        xt <- col[tr]; yt <- y[tr]; wt <- w[tr]
        good <- is.finite(yt) & is.finite(wt) & wt > 0
        xt <- xt[good]; yt <- yt[good]; wt <- wt[good]
        if (length(yt) < 2L) { yhat[te] <- wmean(y[tr], w[tr]); next }
        mu <- wmean(xt, wt)
        if (!is.finite(mu)) { yhat[te] <- wmean(yt, wt); next }
        xtr <- xt - mu; xtr[is.na(xtr)] <- 0
        Xtr <- matrix(1, nrow = length(yt), ncol = 1)
        use_x <- !all(xtr == 0)
        if (use_x) Xtr <- cbind(Xtr, xtr)
        if (length(miss_names) > 0L) {
          Mtr <- as.matrix(X[tr, miss_names, drop = FALSE])[good, , drop = FALSE]
          Mtr[is.na(Mtr)] <- 0; Xtr <- cbind(Xtr, Mtr)
        }
        b <- tryCatch(stats::lm.wfit(Xtr, yt, w = wt)$coefficients,
                      error = function(e) rep(NA_real_, ncol(Xtr)))
        b[!is.finite(b)] <- 0
        xte <- col[te] - mu; xte[is.na(xte)] <- 0
        Xte <- matrix(1, nrow = sum(te), ncol = 1)
        if (use_x) Xte <- cbind(Xte, xte)
        if (length(miss_names) > 0L) {
          Mte <- data.matrix(X[te, miss_names, drop = FALSE])
          Mte[is.na(Mte)] <- 0; Xte <- cbind(Xte, Mte)
        }
        yhat[te] <- drop(Xte %*% b)
      }
    } else {
      f <- addNA(as.factor(col))
      for (k in seq_len(K)) {
        tr <- fold != k; te <- !tr
        yt <- y[tr]; ft <- f[tr]; wt <- w[tr]
        lev_num <- tapply(wt * yt, ft, sum)
        lev_den <- tapply(wt, ft, sum)
        levm <- lev_num / lev_den
        ybar <- wmean(yt, wt)
        mk <- levm[as.character(f[te])]
        yhat[te] <- ifelse(is.na(mk), ybar, mk)
      }
    }
    1 - mse(y, yhat, w) / mse0
  }, numeric(1))
}

# Orchestrator for the rough prescreen. Writes the shortlist to CSV and
# saves knee-curve PNGs so reviewers can see where the cutoff landed.
# =============================================================================
# 6) FINAL W PREPROCESSING HELPERS
# =============================================================================
# Plain-English role: these helpers learn preprocessing rules on each final
# TMLE training fold and apply the frozen rules to that fold's validation rows.
# They are used by the nested fold-specific rough screen and the optional
# augmented multivariable elastic-net union screening step inside final TMLE.

winsorize_vec <- function(x, probs) {
  if (anyNA(x)) stop("winsorize_vec: NAs should have been handled upstream.", call. = FALSE)
  q <- stats::quantile(x, probs = probs, na.rm = TRUE, names = FALSE, type = 8)
  pmin(pmax(x, q[1]), q[2])
}

nonconstant_cols <- function(M, tol) {
  if (ncol(M) == 0L) return(logical(0))
  vv <- apply(M, 2L, stats::var)
  is.finite(vv) & vv > tol
}

infer_var_types <- function(df, numeric_imputation) {
  types <- vapply(df, function(col) {
    if (is.factor(col))  return("factor")
    if (is.logical(col)) return("numeric")
    if (is.numeric(col)) return("numeric")
    if (is.character(col)) return("factor")
    "factor"
  }, character(1))
  types
}

prep_numeric_train <- function(x, cfg_gp, cfg_pre, support = NULL, variable_name = NULL) {
  n <- length(x)
  n_obs <- if (!is.null(support$n_obs)) as.integer(support$n_obs) else sum(is.finite(x))
  p_obs <- if (!is.null(support$p_obs)) as.numeric(support$p_obs) else n_obs / max(1, n)
  # A retained numeric variable must satisfy both absolute and proportional
  # original-support requirements. Support is measured before imputation and
  # excludes every frozen general-missing and structural-skip code.
  if (n_obs < cfg_gp$numeric_min_observed_n || p_obs < cfg_gp$numeric_min_observed_prop)
    return(NULL)
  x_ok <- as.numeric(x[is.finite(x)])
  if (!length(x_ok)) return(NULL)
  is_indicator <- !is.null(variable_name) && grepl("(_missA|_miss97)$", variable_name)
  ux <- sort(unique(x_ok))
  is_binary <- length(ux) <= 2L && all(ux %in% c(0, 1))
  is_low_cardinality <- length(ux) <= (cfg_pre$factor_unique_threshold %||% 10L)
  do_winsor <- !(is_indicator || is_binary || is_low_cardinality || identical(variable_name, "MHSum_W1"))
  if (is_indicator || is_binary) {
    return(list(mu = 0, s = 1, win_q = c(-Inf, Inf), fill = 0,
                identity = TRUE, n_obs_original = n_obs, p_obs_original = p_obs))
  }
  win_q <- if (do_winsor)
    stats::quantile(x_ok, probs = cfg_gp$winsor_probs, na.rm = TRUE, names = FALSE, type = 8)
  else c(-Inf, Inf)
  win <- pmin(pmax(x_ok, win_q[1]), win_q[2])
  mu <- mean(win, na.rm = TRUE); sdev <- stats::sd(win, na.rm = TRUE)
  if (!is.finite(mu)) mu <- 0
  if (!is.finite(sdev) || sdev < cfg_pre$scale_eps) sdev <- 1
  list(mu = mu, s = sdev, win_q = win_q, fill = stats::median(win, na.rm = TRUE),
       identity = FALSE, n_obs_original = n_obs, p_obs_original = p_obs)
}

apply_numeric_transform <- function(x, prep) {
  obs <- is.finite(x)
  val <- as.numeric(x); val[!obs] <- prep$fill
  val <- pmin(pmax(val, prep$win_q[1]), prep$win_q[2])
  if (isTRUE(prep$identity)) return(as.matrix(val))
  as.matrix((val - prep$mu) / prep$s)
}


deterministic_factor_levels <- function(values, special_levels = character(0)) {
  vals <- unique(as.character(values))
  vals <- vals[!is.na(vals) & nzchar(vals)]
  special_levels <- unique(as.character(special_levels))
  ordinary <- setdiff(vals, special_levels)
  num <- suppressWarnings(as.numeric(ordinary))
  if (length(ordinary) && all(is.finite(num))) {
    ordinary <- ordinary[order(num, ordinary)]
  } else {
    ordinary <- sort(ordinary, method = "radix")
  }
  unique(c(ordinary, special_levels))
}


prep_factor_train <- function(x, cfg_gp, cfg_pre, A = NULL,
                              preserve_substantive_levels = FALSE) {
  x_chr <- canonicalize_factor_text(x)
  is_na <- is.na(x_chr)
  
  other_label   <- cfg_pre$factor_other_label   %||% "_Other_"
  missing_label <- cfg_pre$factor_missing_label %||% "Missing"
  skip_label    <- cfg_pre$factor_skip_label    %||% "Skip"
  skip_present <- skip_label %in% x_chr
  special_levels <- unique(c(missing_label,
                             if (skip_present) skip_label else character(0),
                             other_label))
  x_chr[is_na] <- missing_label
  
  tab <- table(x_chr, useNA = "no")
  if (length(tab) == 0L) {
    return(list(
      levels = deterministic_factor_levels(c(missing_label, other_label),
                                           c(missing_label, other_label)),
      other_label = other_label,
      missing_label = missing_label,
      skip_label = skip_label,
      preserve_substantive_levels = isTRUE(preserve_substantive_levels),
      observed_substantive_levels = character(0)
    ))
  }
  
  observed_substantive <- setdiff(unique(x_chr), special_levels)
  if (!isTRUE(preserve_substantive_levels)) {
    rare_levels <- names(tab)[tab < cfg_gp$rare_level_min_n &
                                !(names(tab) %in% special_levels)]
    if (length(rare_levels)) x_chr[x_chr %in% rare_levels] <- other_label
    
    min_exp <- cfg_gp$factor_min_exposed_per_level %||% 0L
    if (!is.null(A) && min_exp > 0L && length(A) == length(x_chr)) {
      A01 <- suppressWarnings(as.integer(A))
      if (anyNA(A01) || any(!A01 %in% c(0L, 1L)))
        stop("prep_factor_train received an invalid treatment vector.", call. = FALSE)
      tab_all <- table(x_chr, useNA = "no")
      tab_exp <- table(x_chr[A01 == 1L], useNA = "no")
      exp_counts <- setNames(rep(0L, length(tab_all)), names(tab_all))
      exp_counts[names(tab_exp)] <- as.integer(tab_exp)
      low_exp_levels <- names(exp_counts)[
        exp_counts < min_exp & !(names(exp_counts) %in% special_levels)
      ]
      if (length(low_exp_levels)) x_chr[x_chr %in% low_exp_levels] <- other_label
    }
    
    current_levels <- unique(x_chr)
    if (length(current_levels) > cfg_gp$factor_max_levels_after_collapse) {
      ordinary_by_frequency <- setdiff(
        names(sort(table(x_chr), decreasing = TRUE)), special_levels)
      n_special <- length(intersect(special_levels, unique(c(x_chr, special_levels))))
      n_top <- max(0L, cfg_gp$factor_max_levels_after_collapse - n_special)
      top_levels <- head(ordinary_by_frequency, n_top)
      keep_levels <- unique(c(top_levels, special_levels))
      x_chr[!(x_chr %in% keep_levels)] <- other_label
    }
  }
  
  # Deterministic ordering prevents fold-dependent reference categories caused
  # solely by row order. Protected H1FS variables retain every substantive
  # category observed in the training fold; unseen validation categories map
  # to _Other_ through the frozen recipe.
  final_levels <- deterministic_factor_levels(x_chr, special_levels)
  if (length(final_levels) < 2L) final_levels <- unique(c(final_levels, other_label))
  
  list(
    levels = final_levels,
    other_label = other_label,
    missing_label = missing_label,
    skip_label = skip_label,
    preserve_substantive_levels = isTRUE(preserve_substantive_levels),
    observed_substantive_levels = deterministic_factor_levels(
      observed_substantive, character(0))
  )
}

apply_factor_transform <- function(x, prep) {
  x_chr <- canonicalize_factor_text(x)
  
  levels_safe <- unique(c(
    prep$levels,
    prep$missing_label,
    prep$other_label
  ))
  
  x_chr[is.na(x_chr)] <- prep$missing_label
  x_chr[!(x_chr %in% levels_safe)] <- prep$other_label
  
  f <- factor(x_chr, levels = levels_safe)
  mm_full <- stats::model.matrix(
    ~ f,
    data = data.frame(f = f),
    na.action = stats::na.pass
  )
  if (nrow(mm_full) != length(x_chr))
    stop(sprintf("apply_factor_transform(): factor produced %d rows but expected %d.",
                 nrow(mm_full), length(x_chr)), call. = FALSE)
  # Drop the intercept/reference column so factor levels are represented once
  # without the exact full-dummy-plus-intercept dependency in regression and
  # GAM learners. Missing and Skip remain available either as explicit dummies
  # or through the reference pattern.
  mm <- mm_full[, colnames(mm_full) != "(Intercept)", drop = FALSE]
  colnames(mm) <- gsub("^f", "", colnames(mm))
  as.matrix(mm)
}

# Build design matrix for a set of columns. Returns processed matrix and
# a "group" id per column (all dummies for one factor share a group id).
# v5: enforces a HARD stop at hard_max_processed_columns to prevent RAM
# blowouts on the small-memory workstations used for this project.

build_grouped_design_train <- function(df, cfg_gp, cfg_pre, hard_max_cols = NULL,
                                       A = NULL, protected_raw_vars = character(0)) {
  if (ncol(df) == 0L) return(list(X = matrix(0, nrow = nrow(df), ncol = 0),
                                  group = integer(0), recipes = list()))
  protected_raw_vars <- unique(as.character(protected_raw_vars %||% character(0)))
  recipes <- list(); mats <- list(); groups <- integer(0); grp <- 0L
  types <- infer_var_types(df, cfg_pre$numeric_imputation)
  support_map <- attr(df, "numeric_support") %||% list()
  for (nm in names(df)) {
    col <- df[[nm]]
    if (identical(types[[nm]], "numeric")) {
      prep <- prep_numeric_train(as.numeric(col), cfg_gp, cfg_pre,
                                 support = support_map[[nm]], variable_name = nm)
      if (is.null(prep)) next
      M <- apply_numeric_transform(as.numeric(col), prep)
      colnames(M) <- nm
      rec_obj <- list(type = "numeric", prep = prep)
    } else {
      preserve <- nm %in% protected_raw_vars
      prep <- prep_factor_train(
        col, cfg_gp, cfg_pre, A = A,
        preserve_substantive_levels = preserve)
      if (is.null(prep) || length(prep$levels) < 2L) next
      M <- apply_factor_transform(col, prep)
      if (ncol(M) == 0L) next
      colnames(M) <- paste0(nm, "_", colnames(M))
      rec_obj <- list(type = "factor", prep = prep)
    }
    keep <- nonconstant_cols(M, tol = cfg_pre$constant_variance_tol)
    M <- M[, keep, drop = FALSE]
    if (ncol(M) == 0L) next
    recipes[[nm]] <- rec_obj
    grp <- grp + 1L
    groups <- c(groups, rep(grp, ncol(M)))
    mats[[nm]] <- M
    if (!is.null(hard_max_cols) && length(groups) > hard_max_cols) {
      stop(sprintf(
        "Processed design matrix exceeded hard_max_processed_columns = %d columns. ",
        hard_max_cols),
        "Tighten nested rough-screen caps, collapse nonprotected long factors more aggressively, or ",
        "raise hard_max_processed_columns if RAM allows.",
        call. = FALSE)
    }
  }
  if (length(mats) == 0L)
    return(list(X = matrix(0, nrow = nrow(df), ncol = 0),
                group = integer(0), recipes = recipes))
  X <- do.call(cbind, mats)
  list(X = X, group = groups, recipes = recipes)
}


apply_preprocess_recipe <- function(df, recipes) {
  mats <- list()
  for (nm in names(recipes)) {
    if (!nm %in% names(df))
      stop("apply_preprocess_recipe is missing required variable '", nm, "'.", call. = FALSE)
    col <- df[[nm]]; rec <- recipes[[nm]]
    if (identical(rec$type, "numeric")) {
      M <- apply_numeric_transform(as.numeric(col), rec$prep); colnames(M) <- nm
    } else {
      M <- apply_factor_transform(col, rec$prep)
      if (ncol(M) > 0L) colnames(M) <- paste0(nm, "_", colnames(M))
    }
    if (nrow(M) != nrow(df)) {
      stop(sprintf(
        "apply_preprocess_recipe(): variable '%s' produced %d rows but expected %d. This usually means factor levels created NA rows during model.matrix().",
        nm, nrow(M), nrow(df)
      ), call. = FALSE)
    }
    if (ncol(M) > 0L) mats[[nm]] <- M
  }
  if (length(mats) == 0L) return(matrix(0, nrow = nrow(df), ncol = 0))
  do.call(cbind, mats)
}

# =============================================================================
# 7) LEARNER REGISTRY FOR FINAL TMLE
# =============================================================================
# Plain-English role: decide which machine-learning algorithms the final
# TMLE stage will stack together to form the outcome (Q), treatment (g), and
# outcome-missingness (pi) estimators. We keep the library intentionally
# lean: mean, GLM, ridge/lasso, random forest, gradient boosting, and
# (optionally for Q) multivariate adaptive regression splines. Every learner
# is forced to single-threaded operation so parallelism cannot exhaust RAM.
# The SuperLearner meta-learner picks the convex combination of these that
# minimizes held-out loss inside each training fold. Cross-fitting then
# prevents the resulting Q, g, pi from overfitting the target parameter.

.SL_RUNTIME_ENV <- new.env(parent = emptyenv())

set_sl_glmnet_context <- function(target, seed, nfolds = 5L, unpenalized = NULL) {
  target <- match.arg(target, c("Q", "g", "pi"))
  # Q/pi always condition on A. The actual g model has A as its outcome.
  # Auxiliary models retain g-style response-stratified tuning but explicitly
  # pass unpenalized="A" because A is a predictor in those models.
  if (is.null(unpenalized)) unpenalized <- if (target %in% c("Q","pi")) "A" else character(0)
  if (!is.character(unpenalized) || anyNA(unpenalized) ||
      any(!nzchar(unpenalized)) || anyDuplicated(unpenalized))
    stop("Unpenalized predictor names must be unique nonblank strings.",call.=FALSE)
  if (target %in% c("Q","pi") && !identical(unpenalized,"A"))
    stop("Q/pi elastic-net fits must leave exactly A unpenalized.",call.=FALSE)
  .SL_RUNTIME_ENV$glmnet_context <- list(
    target = target, seed = as.integer(seed), nfolds = as.integer(nfolds),
    unpenalized_columns = unpenalized,
    h1fs_processed_columns = .SL_RUNTIME_ENV$h1fs_processed_columns %||% character(0))
  invisible(NULL)
}

clear_sl_glmnet_context <- function() {
  if (exists("glmnet_context", envir = .SL_RUNTIME_ENV, inherits = FALSE))
    rm("glmnet_context", envir = .SL_RUNTIME_ENV)
  invisible(NULL)
}

with_sl_glmnet_context <- function(target, seed, nfolds, expr, unpenalized = NULL) {
  had_context <- exists("glmnet_context", envir = .SL_RUNTIME_ENV, inherits = FALSE)
  old_context <- if (had_context)
    get("glmnet_context", envir = .SL_RUNTIME_ENV, inherits = FALSE) else NULL
  set_sl_glmnet_context(target, seed, nfolds, unpenalized=unpenalized)
  on.exit({
    if (had_context) assign("glmnet_context", old_context, envir = .SL_RUNTIME_ENV)
    else clear_sl_glmnet_context()
  }, add = TRUE)
  force(expr)
}



# Named factor vector in the ACTUAL model-matrix order, including any padding.
# glmnet internally rescales positive factors; store this input vector, not a
# false claim that the other fitted coefficients/lambda path stay identical.
make_glmnet_penalty_factor <- function(columns, unpenalized=character(0)) {
  if (!is.character(columns) || !length(columns) || anyNA(columns) ||
      any(!nzchar(columns)) || anyDuplicated(columns) ||
      !is.character(unpenalized) || anyNA(unpenalized) ||
      any(!nzchar(unpenalized)) || anyDuplicated(unpenalized) ||
      !all(unpenalized %in% columns))
    stop("Cannot map unpenalized columns uniquely to the glmnet matrix.",call.=FALSE)
  pf <- stats::setNames(rep(1,length(columns)),columns)
  pf[unpenalized] <- 0
  if (!any(pf > 0)) stop("glmnet requires at least one penalized matrix column.",call.=FALSE)
  pf
}

validate_cv_glmnet_fit <- function(cvfit, selected_lambda = NULL,
                                   expected_ncol = NULL, label = "cv.glmnet") {
  if (is.null(cvfit) || !inherits(cvfit, "cv.glmnet"))
    stop(label, " did not return a cv.glmnet object.", call. = FALSE)
  lam_path <- as.numeric(cvfit$lambda)
  cvm <- as.numeric(cvfit$cvm)
  if (!length(lam_path) || length(cvm) != length(lam_path) ||
      any(!is.finite(lam_path)) || any(lam_path <= 0) ||
      sum(is.finite(cvm)) < 2L)
    stop(label, " returned an invalid lambda path or CV risk curve.", call. = FALSE)
  if (is.null(selected_lambda)) selected_lambda <- cvfit$lambda.min
  selected_lambda <- as.numeric(selected_lambda)[1L]
  if (!is.finite(selected_lambda) || selected_lambda <= 0 ||
      selected_lambda < min(lam_path) * (1 - 1e-8) ||
      selected_lambda > max(lam_path) * (1 + 1e-8))
    stop(label, " returned an invalid selected lambda.", call. = FALSE)
  if (!is.null(expected_ncol)) {
    b <- tryCatch(as.numeric(stats::coef(cvfit, s = selected_lambda)),
                  error = function(e) e)
    if (inherits(b, "error") || length(b) != as.integer(expected_ncol) + 1L ||
        any(!is.finite(b)))
      stop(label, " returned an invalid coefficient vector at the selected lambda.",
           call. = FALSE)
  }
  jerr <- suppressWarnings(as.integer(cvfit$glmnet.fit$jerr %||% 0L))[1L]
  if (is.finite(jerr) && jerr > 0L)
    stop(sprintf("%s encountered fatal glmnet error code %d.", label, jerr),
         call. = FALSE)
  if (is.finite(jerr) && jerr < 0L)
    warning(sprintf(paste0("%s returned nonfatal glmnet path code %d; the selected lambda and ",
                           "coefficient vector were verified within the returned path."),
                    label, jerr), call. = FALSE)
  invisible(list(lambda = selected_lambda, jerr = jerr,
                 n_lambda = length(lam_path), n_finite_cvm = sum(is.finite(cvm))))
}

summarize_prediction_clipping <- function(pred, lower, upper, fold,
                                          prediction_set) {
  pred <- as.numeric(pred)
  if (!length(pred) || any(!is.finite(pred)))
    stop("Q clipping summary requires nonempty finite predictions.", call. = FALSE)
  clipped <- pmin(pmax(pred, lower), upper)
  below <- pred < lower
  above <- pred > upper
  disp <- abs(clipped - pred)
  data.frame(
    fold = as.integer(fold),
    prediction_set = as.character(prediction_set),
    n_predictions = length(pred),
    raw_min = min(pred),
    raw_max = max(pred),
    n_below = sum(below),
    n_above = sum(above),
    n_clipped = sum(below | above),
    fraction_clipped = mean(below | above),
    mean_absolute_clipping_displacement = mean(disp),
    max_absolute_clipping_displacement = max(disp),
    lower_bound = lower,
    upper_bound = upper,
    stringsAsFactors = FALSE
  )
}

register_custom_learners <- function(cfg) {
  lcfg <- cfg$learners
  # Random forest with num.threads = 1L to avoid nested parallelism.
  if (isTRUE(lcfg$Q$use_ranger) || isTRUE(lcfg$g$use_ranger) || isTRUE(lcfg$pi$use_ranger) ||
      isTRUE(lcfg$Q$use_ranger_control_arm)) {
    assign("SL.ranger.fixed",
           function(Y, X, newX, family, obsWeights = NULL, ...) {
             X <- as.data.frame(X, check.names = FALSE)
             newX <- as.data.frame(newX, check.names = FALSE)
             newX <- newX[, names(X), drop = FALSE]
             family_name <- family$family
             y_fit <- if (identical(family_name, "binomial"))
               factor(as.integer(Y), levels = c(0L, 1L)) else as.numeric(Y)
             # A is offered at every node only where it is a predictor and
             # varies (the pooled Q fit). g has no A column; control-arm fits
             # remove it before calling this learner.
             force_A <- isTRUE(lcfg$ranger$always_split_A %||% FALSE) &&
               "A" %in% names(X) && ncol(X) > 1L && length(unique(X$A)) > 1L
             rf <- ranger::ranger(
               y = y_fit, x = X, num.trees = lcfg$ranger$num.trees,
               probability = identical(family_name, "binomial"),
               always.split.variables = if (force_A) "A" else NULL,
               case.weights = normalize_positive_weights(obsWeights, length(Y), "SL.ranger.fixed weights"),
               num.threads = 1L)
             pred_obj <- stats::predict(rf, data = newX, num.threads = 1L)$predictions
             pred <- if (identical(family_name, "binomial")) {
               if (!is.matrix(pred_obj) || !"1" %in% colnames(pred_obj))
                 stop("SL.ranger.fixed did not return a named event-probability column '1'.", call. = FALSE)
               pred_obj[, "1"]
             } else as.numeric(pred_obj)
             fit <- list(object = rf, family_name = family_name, train_names = names(X),
                         always_split_A = force_A)
             class(fit) <- "SL.ranger.fixed"
             list(pred = as.numeric(pred), fit = fit)
           }, envir = .GlobalEnv)
    assign("predict.SL.ranger.fixed", function(object, newdata, ...) {
      newdata <- as.data.frame(newdata, check.names = FALSE)
      newdata <- newdata[, object$train_names, drop = FALSE]
      pr <- stats::predict(object$object, data = newdata, num.threads = 1L)$predictions
      if (identical(object$family_name, "binomial")) {
        if (!is.matrix(pr) || !"1" %in% colnames(pr)) stop("Ranger event column '1' missing.", call. = FALSE)
        pr <- pr[, "1"]
      }
      as.numeric(pr)
    }, envir = .GlobalEnv)
  }
  # Gradient boosting with nthread = 1 for the same reason.
  if (isTRUE(lcfg$Q$use_xgboost) || isTRUE(lcfg$g$use_xgboost) || isTRUE(lcfg$pi$use_xgboost) ||
      isTRUE(lcfg$Q$use_xgboost_control_arm)) {
    assign("SL.xgboost.fixed",
           function(Y, X, newX, family, obsWeights = NULL, ...) {
             X <- as.data.frame(X, check.names = FALSE); newX <- as.data.frame(newX, check.names = FALSE)
             newX <- newX[, names(X), drop = FALSE]
             Xm <- data.matrix(X); newXm <- data.matrix(newX)
             storage.mode(Xm) <- "double"; storage.mode(newXm) <- "double"
             if (any(!is.finite(Xm)) || any(!is.finite(newXm)))
               stop("SL.xgboost.fixed received non-finite predictors.", call. = FALSE)
             xgb_w <- normalize_positive_weights(obsWeights, length(Y), "SL.xgboost.fixed weights")
             family_name <- family$family
             dtrain <- xgboost::xgb.DMatrix(Xm, label = Y, weight = xgb_w)
             fit_obj <- xgboost::xgb.train(
               params = list(
                 eta = lcfg$xgboost$shrinkage, max_depth = lcfg$xgboost$max_depth,
                 min_child_weight = lcfg$xgboost$min_child_weight %||% 20, nthread = 1L,
                 objective = if (family_name == "binomial") "binary:logistic" else "reg:squarederror",
                 eval_metric = if (family_name == "binomial") "logloss" else "rmse"),
               data = dtrain, nrounds = lcfg$xgboost$ntrees, verbose = 0)
             pred <- stats::predict(fit_obj, newdata = xgboost::xgb.DMatrix(newXm))
             fit <- list(object = fit_obj, train_names = names(X), family_name = family_name)
             class(fit) <- "SL.xgboost.fixed"
             list(pred = as.numeric(pred), fit = fit)
           }, envir = .GlobalEnv)
    assign("predict.SL.xgboost.fixed", function(object, newdata, ...) {
      newdata <- as.data.frame(newdata, check.names = FALSE)
      newdata <- newdata[, object$train_names, drop = FALSE]
      Xm <- data.matrix(newdata); storage.mode(Xm) <- "double"
      if (any(!is.finite(Xm))) stop("XGBoost prediction data are non-finite.", call. = FALSE)
      as.numeric(stats::predict(object$object, newdata = xgboost::xgb.DMatrix(Xm)))
    }, envir = .GlobalEnv)
  }
  # Separate Q-only richer booster for the designated sensitivity arm. It has
  # its own configuration and learner name, so g and pi remain unchanged.
  if (isTRUE(lcfg$Q$use_xgboost_rich %||% FALSE)) {
    assign("SL.xgboost.rich",
           function(Y, X, newX, family, obsWeights = NULL, ...) {
             X <- as.data.frame(X, check.names = FALSE)
             newX <- as.data.frame(newX, check.names = FALSE)
             missing_new <- setdiff(names(X), names(newX))
             if (length(missing_new))
               stop("SL.xgboost.rich prediction data are missing columns: ",
                    paste(missing_new, collapse = ", "), call. = FALSE)
             newX <- newX[, names(X), drop = FALSE]
             Xm <- data.matrix(X); newXm <- data.matrix(newX)
             storage.mode(Xm) <- "double"; storage.mode(newXm) <- "double"
             if (any(!is.finite(Xm)) || any(!is.finite(newXm)))
               stop("SL.xgboost.rich received non-finite predictors.", call. = FALSE)
             xgb_w <- normalize_positive_weights(
               obsWeights, length(Y), "SL.xgboost.rich weights")
             family_name <- family$family
             dtrain <- xgboost::xgb.DMatrix(Xm, label = Y, weight = xgb_w)
             fit_obj <- xgboost::xgb.train(
               params = list(
                 eta = lcfg$xgboost_rich$shrinkage,
                 max_depth = as.integer(lcfg$xgboost_rich$max_depth),
                 min_child_weight = lcfg$xgboost_rich$min_child_weight,
                 nthread = 1L,
                 objective = if (family_name == "binomial")
                   "binary:logistic" else "reg:squarederror",
                 eval_metric = if (family_name == "binomial") "logloss" else "rmse"),
               data = dtrain,
               nrounds = as.integer(lcfg$xgboost_rich$ntrees),
               verbose = 0)
             pred <- stats::predict(fit_obj, newdata = xgboost::xgb.DMatrix(newXm))
             if (length(pred) != nrow(newX) || any(!is.finite(pred)))
               stop("SL.xgboost.rich produced invalid predictions.", call. = FALSE)
             fit <- list(object = fit_obj, train_names = names(X),
                         family_name = family_name)
             class(fit) <- "SL.xgboost.rich"
             list(pred = as.numeric(pred), fit = fit)
           }, envir = .GlobalEnv)
    assign("predict.SL.xgboost.rich", function(object, newdata, ...) {
      newdata <- as.data.frame(newdata, check.names = FALSE)
      missing_new <- setdiff(object$train_names, names(newdata))
      if (length(missing_new))
        stop("predict.SL.xgboost.rich missing columns: ",
             paste(missing_new, collapse = ", "), call. = FALSE)
      newdata <- newdata[, object$train_names, drop = FALSE]
      Xm <- data.matrix(newdata); storage.mode(Xm) <- "double"
      if (any(!is.finite(Xm)))
        stop("SL.xgboost.rich prediction data are non-finite.", call. = FALSE)
      pred <- stats::predict(object$object, newdata = xgboost::xgb.DMatrix(Xm))
      if (length(pred) != nrow(newdata) || any(!is.finite(pred)))
        stop("predict.SL.xgboost.rich produced invalid predictions.", call. = FALSE)
      as.numeric(pred)
    }, envir = .GlobalEnv)
  }
  if (isTRUE(lcfg$Q$use_earth)) {
    assign("SL.earth.fixed",
           function(Y, X, newX, family, obsWeights = NULL, ...) {
             # v6 Fix A: earth rebuilds the call via a formula interface in some
             # versions, which calls model.frame and requires a data.frame input.
             # Force X and newX to data.frame and ensure all columns are numeric.
             if (!is.data.frame(X))    X    <- as.data.frame(X,    stringsAsFactors = FALSE)
             if (!is.data.frame(newX)) newX <- as.data.frame(newX, stringsAsFactors = FALSE)
             X[]    <- lapply(X,    function(c) if (is.numeric(c)) c else suppressWarnings(as.numeric(as.character(c))))
             newX[] <- lapply(newX, function(c) if (is.numeric(c)) c else suppressWarnings(as.numeric(as.character(c))))
             if (any(!is.finite(as.matrix(X))) || any(!is.finite(as.matrix(newX))) || any(!is.finite(Y)))
               stop("SL.earth.fixed received non-finite data.", call. = FALSE)
             earth_w <- normalize_positive_weights(obsWeights, length(Y), "SL.earth.fixed weights")
             earth_obj <- earth::earth(x = X, y = Y, weights = earth_w,
                                       glm = if (family$family == "binomial") list(family = stats::binomial()) else NULL,
                                       degree = lcfg$earth$degree %||% 2, nprune = lcfg$earth$nprune)
             pred <- stats::predict(earth_obj, newdata = newX,
                                    type = if (family$family == "binomial") "response" else "link")
             fit <- list(object = earth_obj, train_names = names(X),
                         family_name = family$family)
             class(fit) <- "SL.earth.fixed"
             list(pred = as.numeric(pred), fit = fit)
           }, envir = .GlobalEnv)
    assign("predict.SL.earth.fixed", function(object, newdata, ...) {
      newdata <- as.data.frame(newdata, check.names = FALSE)
      newdata <- newdata[, object$train_names, drop = FALSE]
      as.numeric(stats::predict(object$object, newdata = newdata,
                                type = if (object$family_name == "binomial") "response" else "link"))
    }, envir = .GlobalEnv)
  }
  # BUG FIX: stock SL.glmnet hardcodes alpha = 1 (pure LASSO) and ignores
  # whatever is in cfg$learners$glmnet$alpha. With ~70% of columns being
  # dummy-expanded factors, pure LASSO arbitrarily picks one dummy per
  # correlated cluster and zeros the rest, producing high cross-fold variance.
  # This wrapper passes alpha and nlambda from cfg through to cv.glmnet so
  # the elastic-net configuration in cfg$learners$glmnet actually takes effect.
  if ("SL.glmnet.fixed" %in% lcfg$auxiliary_binary_library || isTRUE(lcfg$Q$use_glmnet) || isTRUE(lcfg$g$use_glmnet) || isTRUE(lcfg$pi$use_glmnet)) {
    assign("SL.glmnet.fixed",
           function(Y, X, newX, family, obsWeights = NULL, id = NULL, ...) {
             if (!is.data.frame(X))    X    <- as.data.frame(X,    stringsAsFactors = FALSE)
             if (!is.data.frame(newX)) newX <- as.data.frame(newX, stringsAsFactors = FALSE)
             if (!exists("glmnet_context",envir=.SL_RUNTIME_ENV,inherits=FALSE))
               stop("SL.glmnet.fixed has no externally supplied tuning context.",call.=FALSE)
             ctx <- get("glmnet_context",envir=.SL_RUNTIME_ENV,inherits=FALSE)
             unpenalized <- ctx$unpenalized_columns %||% character(0)
             if (anyDuplicated(names(X)) || anyDuplicated(names(newX)) ||
                 !all(unpenalized %in% names(X)) || !all(unpenalized %in% names(newX)))
               stop("SL.glmnet.fixed unpenalized predictors are missing or duplicated.",call.=FALSE)
             # A must be one numeric 0/1 matrix column, not two factor dummies.
             if ("A" %in% unpenalized) {
               X$A <- normalize_binary_var(X$A,"glmnet training A",require_both=FALSE)
               newX$A <- normalize_binary_var(newX$A,"glmnet prediction A",require_both=FALSE)
             }
             # glmnet wants a numeric matrix; model.matrix expands any residual
             # factors to dummies. With Fix 2 the data has already been
             # numerically expanded upstream, so this is mostly a no-op, but
             # remains for safety in case factor columns slip through.
             # Defensive: coerce NAs to zero (numeric) or "Missing" (factor) so
             # model.matrix's default na.action doesn't silently drop rows.
             for (cn in names(X)) {
               col <- X[[cn]]
               if (is.numeric(col)) {
                 col[!is.finite(col)] <- 0
                 X[[cn]] <- col
               } else if (is.factor(col)) {
                 if (any(is.na(col))) {
                   col <- addNA(col)
                   levels(col)[is.na(levels(col))] <- "Missing"
                   X[[cn]] <- col
                 }
               }
             }
             for (cn in names(newX)) {
               col <- newX[[cn]]
               if (is.numeric(col)) {
                 col[!is.finite(col)] <- 0
                 newX[[cn]] <- col
               } else if (is.factor(col)) {
                 if (any(is.na(col))) {
                   col <- addNA(col)
                   levels(col)[is.na(levels(col))] <- "Missing"
                   newX[[cn]] <- col
                 }
               }
             }
             Xm    <- stats::model.matrix(~ . - 1, data = X,    na.action = stats::na.pass)
             newXm <- stats::model.matrix(~ . - 1, data = newX, na.action = stats::na.pass)
             if (nrow(Xm) != nrow(X) || nrow(newXm) != nrow(newX)) {
               stop(sprintf("SL.glmnet.fixed model.matrix row mismatch: train %d/%d, valid %d/%d.",
                            nrow(Xm), nrow(X), nrow(newXm), nrow(newX)), call. = FALSE)
             }
             # Align newXm columns to Xm columns. If validation is missing a
             # training column (factor level not seen in validation), fill it
             # with 0. If validation has an extra column not in training, drop
             # it (the model can't use it).
             miss_cols <- setdiff(colnames(Xm), colnames(newXm))
             if (length(miss_cols) > 0L) {
               fill <- matrix(0, nrow = nrow(newXm), ncol = length(miss_cols),
                              dimnames = list(NULL, miss_cols))
               newXm <- cbind(newXm, fill)
             }
             extra_cols <- setdiff(colnames(newXm), colnames(Xm))
             if (length(extra_cols) > 0L)
               newXm <- newXm[, !colnames(newXm) %in% extra_cols, drop = FALSE]
             newXm <- newXm[, colnames(Xm), drop = FALSE]
             if (ncol(Xm) == 1L) {
               Xm <- cbind(Xm, .glmnet_pad = 0)
               newXm <- cbind(newXm, .glmnet_pad = 0)
             }
             if (is.null(id) || length(id) != length(Y))
               stop("SL.glmnet.fixed requires the cluster id vector.", call. = FALSE)
             if (!exists("glmnet_context", envir = .SL_RUNTIME_ENV, inherits = FALSE))
               stop("SL.glmnet.fixed has no externally supplied tuning context.", call. = FALSE)
             ctx <- get("glmnet_context", envir = .SL_RUNTIME_ENV, inherits = FALSE)
             ids <- as.character(id)
             w_glmnet <- normalize_positive_weights(obsWeights, length(Y), "SL.glmnet.fixed weights")
             if (identical(ctx$target, "Q")) {
               if (!"A" %in% names(X)) stop("SL.glmnet.fixed Q tuning requires A in X.", call. = FALSE)
               A_tune <- normalize_binary_var(X$A, "SL.glmnet.fixed Q treatment")
               delta_tune <- rep(1L, length(Y))
             } else if (identical(ctx$target, "g")) {
               A_tune <- normalize_binary_var(Y, "SL.glmnet.fixed g outcome")
               delta_tune <- rep(1L, length(Y))
             } else {
               if (!"A" %in% names(X)) stop("SL.glmnet.fixed pi tuning requires A in X.", call. = FALSE)
               A_tune <- normalize_binary_var(X$A, "SL.glmnet.fixed pi treatment")
               delta_tune <- normalize_binary_var(Y, "SL.glmnet.fixed pi outcome")
             }
             foldid_glmnet <- do.call(make_cluster_folds_balanced, c(list(
               cluster = ids, A = A_tune, k = ctx$nfolds,
               seed = ctx$seed, weights = w_glmnet, delta = delta_tune,
               balance_on_weights = isTRUE(cfg$final_tmle$internal_fold_balance_on_weights)),
               fold_control_from_cfg(cfg, "internal")))
             if (length(unique(foldid_glmnet)) < 3L)
               stop("SL.glmnet.fixed requires at least three cluster-aware tuning folds in every SuperLearner training subset.", call. = FALSE)
             penalty_factor <- make_glmnet_penalty_factor(colnames(Xm),unpenalized)
             x_glmnet <- if (requireNamespace("Matrix", quietly = TRUE)) Matrix::Matrix(Xm, sparse = TRUE) else Xm
             fit <- glmnet::cv.glmnet(
               x = x_glmnet, y = Y, family = family$family,
               alpha = lcfg$glmnet$alpha %||% 1,
               nlambda = lcfg$glmnet$nlambda %||% 100L,
               weights = w_glmnet, foldid = foldid_glmnet,
               penalty.factor = penalty_factor,
               standardize = isTRUE(lcfg$glmnet$standardize %||% TRUE),
               maxit = lcfg$glmnet$maxit %||% 100000L)
             # lambda choice: "min" (default) or "1se"
             lam <- if (identical(lcfg$glmnet$lambda_choice %||% "min", "1se"))
               fit$lambda.1se else fit$lambda.min
             validate_cv_glmnet_fit(fit, lam, expected_ncol = ncol(Xm),
                                    label = paste0("SL.glmnet.fixed[", ctx$target, "]"))
             pred <- stats::predict(fit, newx = newXm, s = lam,
                                    type = if (family$family == "binomial") "response" else "link")
             pred <- as.numeric(pred)
             if (length(pred) != nrow(newXm) || any(!is.finite(pred)))
               stop("SL.glmnet.fixed produced invalid predictions.", call. = FALSE)
             if (family$family == "binomial" && any(pred < 0 | pred > 1))
               stop("SL.glmnet.fixed produced binomial predictions outside [0,1].", call. = FALSE)
             fit_out <- list(object = fit, lambda = lam, columns = colnames(Xm),
                             train_names = names(X), family_name = family$family,
                             penalty_factor = penalty_factor,
                             unpenalized_columns = unpenalized,
                             tuning_context = ctx$target)
             class(fit_out) <- "SL.glmnet.fixed"
             list(pred = pred, fit = fit_out)
           }, envir = .GlobalEnv)
    assign("predict.SL.glmnet.fixed", function(object, newdata, ...) {
      newdata <- as.data.frame(newdata, check.names = FALSE)
      if ("A" %in% (object$unpenalized_columns %||% character(0))) {
        if (!"A" %in% names(newdata)) stop("Prediction data lack unpenalized A.",call.=FALSE)
        newdata$A <- normalize_binary_var(newdata$A,"glmnet prediction A",require_both=FALSE)
      }
      missing_raw <- setdiff(object$train_names, names(newdata))
      if (length(missing_raw)) stop("predict.SL.glmnet.fixed missing raw columns: ", paste(missing_raw, collapse = ", "), call. = FALSE)
      newdata <- newdata[, object$train_names, drop = FALSE]
      for (cn in names(newdata)) {
        col <- newdata[[cn]]
        if (is.numeric(col)) {
          col[!is.finite(col)] <- 0
          newdata[[cn]] <- col
        } else if (is.factor(col) && anyNA(col)) {
          col <- addNA(col)
          levels(col)[is.na(levels(col))] <- "Missing"
          newdata[[cn]] <- col
        }
      }
      mm <- stats::model.matrix(~ . - 1, data = newdata, na.action = stats::na.pass)
      if (nrow(mm) != nrow(newdata) || any(!is.finite(mm)))
        stop("predict.SL.glmnet.fixed produced an invalid model matrix.", call. = FALSE)
      missing_cols <- setdiff(object$columns, colnames(mm))
      if (length(missing_cols)) {
        add <- matrix(0, nrow(mm), length(missing_cols), dimnames = list(NULL, missing_cols))
        mm <- cbind(mm, add)
      }
      mm <- mm[, object$columns, drop = FALSE]
      as.numeric(stats::predict(object$object, newx = mm, s = object$lambda,
                                type = if (object$family_name == "binomial") "response" else "link"))
    }, envir = .GlobalEnv)
  }

  # ---------------------------------------------------------------------------
  # v8.44 CONTROL-ARM Q LEARNERS.
  # For the ATT the counterfactual mean is E[ Q(0,W) | A=1 ]. A pooled fit that
  # barely uses A predicts roughly E[Y|W] = Q(0,W) + g(W)*effect, i.e. it is
  # pulled toward exposed outcomes exactly where exposed respondents live.
  # These candidates remove that channel: the base learner is trained on the
  # unexposed rows only, with A removed from the design. The exposed-arm
  # prediction is the control-arm prediction plus one survey-weighted shift
  # (identity scale for gaussian, logit scale for binomial) estimated on the
  # exposed training rows, which the control-arm fit never used.
  # Everything is learned inside the SuperLearner training subset it is given.
  control_arm_glmnet_base <- function(Y, X, newX, family, obsWeights, id) {
    ctx <- get("glmnet_context", envir = .SL_RUNTIME_ENV, inherits = FALSE)
    sanitize <- function(d) {
      for (cn in names(d)) {
        z <- d[[cn]]
        if (is.numeric(z)) { z[!is.finite(z)] <- 0; d[[cn]] <- z }
        else if (is.factor(z) && anyNA(z)) {
          z <- addNA(z); levels(z)[is.na(levels(z))] <- "Missing"; d[[cn]] <- z }
      }
      d
    }
    X <- sanitize(X); newX <- sanitize(newX)
    Xm <- stats::model.matrix(~ . - 1, X, na.action = stats::na.pass)
    newXm <- stats::model.matrix(~ . - 1, newX, na.action = stats::na.pass)
    if (nrow(Xm) != nrow(X) || nrow(newXm) != nrow(newX))
      stop("Control-arm glmnet model.matrix row mismatch.", call. = FALSE)
    miss <- setdiff(colnames(Xm), colnames(newXm))
    if (length(miss))
      newXm <- cbind(newXm, matrix(0, nrow(newXm), length(miss), dimnames = list(NULL, miss)))
    newXm <- newXm[, colnames(Xm), drop = FALSE]
    if (ncol(Xm) == 1L) { Xm <- cbind(Xm, .glmnet_pad = 0); newXm <- cbind(newXm, .glmnet_pad = 0) }
    if (is.null(id) || length(id) != length(Y))
      stop("Control-arm glmnet requires the cluster id vector.", call. = FALSE)
    w <- normalize_positive_weights(obsWeights, length(Y), "control-arm glmnet weights")
    # Whole-PSU tuning folds; only one exposure arm is present by construction.
    foldid <- do.call(make_cluster_folds_balanced, c(list(
      cluster = as.character(id), A = rep(0L, length(Y)), k = ctx$nfolds,
      seed = ctx$seed, weights = w, delta = rep(1L, length(Y)),
      balance_on_weights = isTRUE(cfg$final_tmle$internal_fold_balance_on_weights)),
      fold_control_from_cfg(cfg, "internal")))
    if (length(unique(foldid)) < 3L)
      stop("Control-arm glmnet requires at least three cluster-aware tuning folds.", call. = FALSE)
    xsp <- if (requireNamespace("Matrix", quietly = TRUE)) Matrix::Matrix(Xm, sparse = TRUE) else Xm
    fit <- glmnet::cv.glmnet(
      x = xsp, y = Y, family = family$family,
      alpha = lcfg$glmnet$alpha %||% 1, nlambda = lcfg$glmnet$nlambda %||% 100L,
      weights = w, foldid = foldid,
      standardize = isTRUE(lcfg$glmnet$standardize %||% TRUE),
      maxit = lcfg$glmnet$maxit %||% 100000L)
    lam <- if (identical(lcfg$glmnet$lambda_choice %||% "min", "1se")) fit$lambda.1se else fit$lambda.min
    validate_cv_glmnet_fit(fit, lam, expected_ncol = ncol(Xm), label = "SL.glmnet.control_arm[Q]")
    pred <- as.numeric(stats::predict(fit, newx = newXm, s = lam,
      type = if (family$family == "binomial") "response" else "link"))
    fo <- list(object = fit, lambda = lam, columns = colnames(Xm),
               train_names = names(X), family_name = family$family)
    class(fo) <- "control_arm_glmnet_base"
    list(pred = pred, fit = fo)
  }
  assign("predict.control_arm_glmnet_base", function(object, newdata, ...) {
    newdata <- as.data.frame(newdata, check.names = FALSE)
    missing_raw <- setdiff(object$train_names, names(newdata))
    if (length(missing_raw))
      stop("Control-arm glmnet prediction data lack columns: ",
           paste(missing_raw, collapse = ", "), call. = FALSE)
    newdata <- newdata[, object$train_names, drop = FALSE]
    for (cn in names(newdata)) {
      z <- newdata[[cn]]
      if (is.numeric(z)) { z[!is.finite(z)] <- 0; newdata[[cn]] <- z }
      else if (is.factor(z) && anyNA(z)) {
        z <- addNA(z); levels(z)[is.na(levels(z))] <- "Missing"; newdata[[cn]] <- z }
    }
    mm <- stats::model.matrix(~ . - 1, data = newdata, na.action = stats::na.pass)
    miss <- setdiff(object$columns, colnames(mm))
    if (length(miss)) mm <- cbind(mm, matrix(0, nrow(mm), length(miss), dimnames = list(NULL, miss)))
    mm <- mm[, object$columns, drop = FALSE]
    as.numeric(stats::predict(object$object, newx = mm, s = object$lambda,
      type = if (object$family_name == "binomial") "response" else "link"))
  }, envir = .GlobalEnv)

  control_arm_shift <- function(y1, f1, w1, family_name) {
    # One parameter, exposed training rows only.
    if (!length(y1)) stop("Control-arm Q learner found no exposed training rows.", call. = FALSE)
    if (identical(family_name, "binomial")) {
      p <- pmin(pmax(f1, 1e-6), 1 - 1e-6); off <- stats::qlogis(p)
      score <- function(t) sum(w1 * (y1 - stats::plogis(off + t)))
      if (all(y1 == 1)) return(8)
      if (all(y1 == 0)) return(-8)
      return(stats::uniroot(score, c(-12, 12), tol = 1e-10)$root)
    }
    sum(w1 * (y1 - f1)) / sum(w1)
  }
  control_arm_combine <- function(f0, a, shift, family_name) {
    if (identical(family_name, "binomial"))
      return(stats::plogis(stats::qlogis(pmin(pmax(f0, 1e-6), 1 - 1e-6)) + a * shift))
    f0 + a * shift
  }
  register_control_arm_Q_learner <- function(sl_name, base_kind) {
    assign(sl_name,
      function(Y, X, newX, family, obsWeights = NULL, id = NULL, ...) {
        X <- as.data.frame(X, check.names = FALSE)
        newX <- as.data.frame(newX, check.names = FALSE)
        if (!"A" %in% names(X) || !"A" %in% names(newX))
          stop(sl_name, " is a Q-only learner and requires A in X and newX.", call. = FALSE)
        if (exists("glmnet_context", envir = .SL_RUNTIME_ENV, inherits = FALSE) &&
            !identical(get("glmnet_context", envir = .SL_RUNTIME_ENV, inherits = FALSE)$target, "Q"))
          stop(sl_name, " may be used only in the Q library.", call. = FALSE)
        missing_new <- setdiff(names(X), names(newX))
        if (length(missing_new))
          stop(sl_name, " newX missing columns: ", paste(missing_new, collapse = ", "), call. = FALSE)
        a <- normalize_binary_var(X$A, paste0(sl_name, " training A"))
        a_new <- normalize_binary_var(newX$A, paste0(sl_name, " prediction A"), require_both = FALSE)
        keep <- setdiff(names(X), "A")
        if (!length(keep)) stop(sl_name, " requires at least one covariate besides A.", call. = FALSE)
        Y <- as.numeric(Y)
        w <- normalize_positive_weights(obsWeights, length(Y), paste0(sl_name, " weights"))
        i0 <- which(a == 0L); i1 <- which(a == 1L)
        family_name <- family$family
        if (identical(family_name, "binomial") && length(unique(Y[i0])) < 2L)
          stop(sl_name, " requires both outcome classes among unexposed training rows.", call. = FALSE)
        # One base call predicts the requested rows AND the exposed training
        # rows (never used in the fit), so no second prediction pass is needed.
        pred_X <- rbind(newX[, keep, drop = FALSE], X[i1, keep, drop = FALSE])
        base <- switch(base_kind,
          ranger = get("SL.ranger.fixed", envir = .GlobalEnv)(
            Y = Y[i0], X = X[i0, keep, drop = FALSE], newX = pred_X,
            family = family, obsWeights = w[i0]),
          xgboost = get("SL.xgboost.fixed", envir = .GlobalEnv)(
            Y = Y[i0], X = X[i0, keep, drop = FALSE], newX = pred_X,
            family = family, obsWeights = w[i0]),
          glmnet = control_arm_glmnet_base(
            Y = Y[i0], X = X[i0, keep, drop = FALSE], newX = pred_X,
            family = family, obsWeights = w[i0], id = id[i0]),
          stop("Unknown control-arm base learner.", call. = FALSE))
        f_all <- as.numeric(base$pred)
        if (length(f_all) != nrow(pred_X) || any(!is.finite(f_all)))
          stop(sl_name, " base learner returned invalid predictions.", call. = FALSE)
        f_new <- f_all[seq_len(nrow(newX))]
        f_trt <- f_all[nrow(newX) + seq_along(i1)]
        shift <- control_arm_shift(Y[i1], f_trt, w[i1], family_name)
        if (!is.finite(shift)) stop(sl_name, " produced a nonfinite exposed-arm shift.", call. = FALSE)
        pred <- control_arm_combine(f_new, a_new, shift, family_name)
        if (any(!is.finite(pred))) stop(sl_name, " produced invalid predictions.", call. = FALSE)
        fit <- list(base = base$fit, shift = shift, family_name = family_name,
                    covariates = keep, base_kind = base_kind,
                    n_control_train = length(i0), n_exposed_train = length(i1))
        class(fit) <- sl_name
        list(pred = as.numeric(pred), fit = fit)
      }, envir = .GlobalEnv)
    assign(paste0("predict.", sl_name), function(object, newdata, ...) {
      newdata <- as.data.frame(newdata, check.names = FALSE)
      if (!"A" %in% names(newdata)) stop("Control-arm Q prediction data lack A.", call. = FALSE)
      a_new <- normalize_binary_var(newdata$A, "control-arm prediction A", require_both = FALSE)
      f0 <- as.numeric(stats::predict(object$base,
        newdata = newdata[, object$covariates, drop = FALSE]))
      control_arm_combine(f0, a_new, object$shift, object$family_name)
    }, envir = .GlobalEnv)
  }
  if (isTRUE(lcfg$Q$use_glmnet_control_arm %||% FALSE))
    register_control_arm_Q_learner("SL.glmnet.control_arm", "glmnet")
  if (isTRUE(lcfg$Q$use_ranger_control_arm %||% FALSE))
    register_control_arm_Q_learner("SL.ranger.control_arm", "ranger")
  if (isTRUE(lcfg$Q$use_xgboost_control_arm %||% FALSE))
    register_control_arm_Q_learner("SL.xgboost.control_arm", "xgboost")

  # Dedicated elastic-net sensitivity learners. These are additional
  # SuperLearner candidates and do not alter the baseline SL.glmnet.fixed.
  register_penalized_glmnet_sensitivity <- function(sl_name, mode) {
    assign(sl_name,
           function(Y, X, newX, family, obsWeights = NULL, id = NULL, ...) {
             X <- as.data.frame(X, check.names = FALSE)
             newX <- as.data.frame(newX, check.names = FALSE)
             missing_raw <- setdiff(names(X), names(newX))
             if (length(missing_raw)) stop(sl_name, " newX missing columns: ", paste(missing_raw, collapse = ", "), call. = FALSE)
             newX <- newX[, names(X), drop = FALSE]
             sanitize <- function(d) {
               for (cn in names(d)) {
                 z <- d[[cn]]
                 if (is.numeric(z)) { z[!is.finite(z)] <- 0; d[[cn]] <- z }
                 else if (is.factor(z) && anyNA(z)) { z <- addNA(z); levels(z)[is.na(levels(z))] <- "Missing"; d[[cn]] <- z }
               }
               d
             }
             X <- sanitize(X); newX <- sanitize(newX)
             Xm <- stats::model.matrix(~ . - 1, X, na.action = stats::na.pass)
             newXm <- stats::model.matrix(~ . - 1, newX, na.action = stats::na.pass)
             miss <- setdiff(colnames(Xm), colnames(newXm))
             if (length(miss)) newXm <- cbind(newXm, matrix(0, nrow(newXm), length(miss), dimnames=list(NULL, miss)))
             newXm <- newXm[, colnames(Xm), drop = FALSE]
             if (ncol(Xm) == 1L) { Xm <- cbind(Xm, .glmnet_pad=0); newXm <- cbind(newXm, .glmnet_pad=0) }
             if (is.null(id) || length(id) != length(Y)) stop(sl_name, " requires cluster ids.", call. = FALSE)
             ctx <- get("glmnet_context", envir=.SL_RUNTIME_ENV, inherits=FALSE)
             if (mode == "h1fs" && !identical(ctx$target, "g")) stop(sl_name, " is g-only.", call. = FALSE)
             if (mode == "A" && !identical(ctx$target, "pi")) stop(sl_name, " is pi-only.", call. = FALSE)
             w <- normalize_positive_weights(obsWeights, length(Y), paste0(sl_name, " weights"))
             if (identical(ctx$target, "g")) { At <- normalize_binary_var(Y, paste0(sl_name, " g outcome")); dt <- rep(1L,length(Y)) }
             else { At <- normalize_binary_var(X$A, paste0(sl_name, " pi treatment")); dt <- normalize_binary_var(Y, paste0(sl_name, " pi outcome")) }
             foldid <- do.call(make_cluster_folds_balanced, c(list(cluster=as.character(id), A=At, k=ctx$nfolds,
                                                                   seed=ctx$seed, weights=w, delta=dt,
                                                                   balance_on_weights=isTRUE(cfg$final_tmle$internal_fold_balance_on_weights)), fold_control_from_cfg(cfg,"internal")))
             pf <- rep(1, ncol(Xm)); names(pf) <- colnames(Xm)
             if (mode == "A") {
               a_cols <- which(colnames(Xm) == "A")
               if (length(a_cols) != 1L) stop(sl_name, " could not identify exactly one A column.", call. = FALSE)
               pf[a_cols] <- as.numeric(lcfg$glmnet_pi_A$A_penalty_multiplier %||% 0)
             } else {
               hcols <- intersect(ctx$h1fs_processed_columns %||% character(0), colnames(Xm))
               if (!length(hcols)) stop(sl_name, " found no mapped H1FS processed columns.", call. = FALSE)
               pf[hcols] <- as.numeric(lcfg$glmnet_h1fs$h1fs_penalty_multiplier %||% 0.25)
             }
             xsp <- if (requireNamespace("Matrix", quietly=TRUE)) Matrix::Matrix(Xm, sparse=TRUE) else Xm
             fit <- glmnet::cv.glmnet(x=xsp, y=Y, family=family$family,
                                      alpha=lcfg$glmnet$alpha %||% 0.5, nlambda=lcfg$glmnet$nlambda %||% 100L,
                                      weights=w, foldid=foldid, standardize=isTRUE(lcfg$glmnet$standardize %||% TRUE),
                                      maxit=lcfg$glmnet$maxit %||% 100000L, penalty.factor=pf)
             lam <- if (identical(lcfg$glmnet$lambda_choice %||% "min", "1se")) fit$lambda.1se else fit$lambda.min
             validate_cv_glmnet_fit(fit, lam, expected_ncol=ncol(Xm), label=paste0(sl_name,"[",ctx$target,"]"))
             pred <- as.numeric(stats::predict(fit, newx=newXm, s=lam, type=if (family$family=="binomial") "response" else "link"))
             if (length(pred)!=nrow(newXm) || any(!is.finite(pred))) stop(sl_name, " produced invalid predictions.", call. = FALSE)
             fo <- list(
               object = fit, lambda = lam, columns = colnames(Xm),
               train_names = names(X), family_name = family$family,
               penalty_factor = pf, sensitivity_mode = mode)
             class(fo) <- sl_name
             list(pred=pred, fit=fo)
           }, envir=.GlobalEnv)
    pred_name <- paste0("predict.", sl_name)
    assign(pred_name, function(object, newdata, ...) {
      newdata <- as.data.frame(newdata, check.names = FALSE)
      missing_raw <- setdiff(object$train_names, names(newdata))
      if (length(missing_raw))
        stop(pred_name, " missing raw columns: ", paste(missing_raw, collapse = ", "), call. = FALSE)
      newdata <- newdata[, object$train_names, drop = FALSE]
      for (cn in names(newdata)) {
        z <- newdata[[cn]]
        if (is.numeric(z)) {
          z[!is.finite(z)] <- 0
          newdata[[cn]] <- z
        } else if (is.factor(z) && anyNA(z)) {
          z <- addNA(z)
          levels(z)[is.na(levels(z))] <- "Missing"
          newdata[[cn]] <- z
        }
      }
      mm <- stats::model.matrix(~ . - 1, data = newdata, na.action = stats::na.pass)
      if (nrow(mm) != nrow(newdata) || any(!is.finite(mm)))
        stop(pred_name, " produced an invalid model matrix.", call. = FALSE)
      miss <- setdiff(object$columns, colnames(mm))
      if (length(miss))
        mm <- cbind(mm, matrix(0, nrow(mm), length(miss), dimnames = list(NULL, miss)))
      extra <- setdiff(colnames(mm), object$columns)
      if (length(extra)) mm <- mm[, !colnames(mm) %in% extra, drop = FALSE]
      mm <- mm[, object$columns, drop = FALSE]
      pred <- as.numeric(stats::predict(object$object, newx = mm, s = object$lambda,
                                        type = if (object$family_name == "binomial") "response" else "link"))
      if (length(pred) != nrow(mm) || any(!is.finite(pred)))
        stop(pred_name, " produced invalid predictions.", call. = FALSE)
      pred
    }, envir = .GlobalEnv)
  }
  if (isTRUE(lcfg$g$use_glmnet_h1fs %||% FALSE)) register_penalized_glmnet_sensitivity("SL.glmnet.h1fs", "h1fs")
  # v8.37: the unpenalized-A pi learner is registered when it is either in the
  # PRIMARY pi library or used only by the per-fold alternate pi fit.
  if (isTRUE(lcfg$pi$use_glmnet_A_unpenalized %||% FALSE) ||
      isTRUE(lcfg$pi$dual_fit_A_unpenalized %||% FALSE))
    register_penalized_glmnet_sensitivity("SL.glmnet.pi_A_unpenalized", "A")
  
  # Safeguarded GAM learner used for the outcome-observation model pi.
  if (isTRUE(lcfg$Q$use_gam) || isTRUE(lcfg$g$use_gam) || isTRUE(lcfg$pi$use_gam)) {
    assign("SL.gam.fixed",
           function(Y, X, newX, family, obsWeights = NULL, id = NULL, ...) {
             if (!requireNamespace("mgcv", quietly = TRUE))
               stop("SL.gam.fixed requires the mgcv package.", call. = FALSE)
             X <- as.data.frame(X, check.names = FALSE)
             newX <- as.data.frame(newX, check.names = FALSE)
             if (nrow(X) != length(Y)) stop("SL.gam.fixed training-row mismatch.", call. = FALSE)
             if (".obsw" %in% names(X) || "Y" %in% names(X))
               stop("SL.gam.fixed received a predictor name reserved for its model data.", call. = FALSE)
             missing_new <- setdiff(names(X), names(newX))
             if (length(missing_new)) stop("SL.gam.fixed newX missing columns: ", paste(missing_new, collapse = ", "), call. = FALSE)
             newX <- newX[, names(X), drop = FALSE]
             X[] <- lapply(X, function(z) suppressWarnings(as.numeric(z)))
             newX[] <- lapply(newX, function(z) suppressWarnings(as.numeric(z)))
             if (any(!is.finite(as.matrix(X))) || any(!is.finite(as.matrix(newX))) || any(!is.finite(Y)))
               stop("SL.gam.fixed received non-finite data.", call. = FALSE)
             if (is.null(obsWeights)) obsWeights <- rep(1, length(Y))
             obsWeights <- as.numeric(obsWeights)
             if (length(obsWeights) != length(Y) || any(!is.finite(obsWeights)) || any(obsWeights <= 0))
               stop("SL.gam.fixed received invalid observation weights.", call. = FALSE)
             obsWeights <- obsWeights / mean(obsWeights)
             family_name <- family$family
             eps_gam <- lcfg$gam$eps %||% 1e-6
             sanitize_pred <- function(z, n_expected) {
               z <- as.numeric(z)
               if (length(z) != n_expected || any(!is.finite(z)))
                 stop("SL.gam.fixed produced invalid predictions.", call. = FALSE)
               if (identical(family_name, "binomial")) z <- pmin(pmax(z, eps_gam), 1 - eps_gam)
               z
             }
             make_fit <- function(object) {
               z <- list(object = object, fallback = FALSE, family_name = family_name,
                         eps = eps_gam, train_names = names(X))
               class(z) <- "SL.gam.fixed"
               z
             }
             if (length(unique(Y)) < 2L)
               stop("SL.gam.fixed requires outcome variation in every training subset.", call. = FALSE)
             unique_n <- vapply(X, function(z) length(unique(z)), integer(1))
             sm <- names(X)[unique_n > (lcfg$gam$smooth_unique_min %||% 10L)]
             lin <- setdiff(names(X), sm)
             quote_nm <- function(z) paste0("`", gsub("`", "", z, fixed = TRUE), "`")
             terms <- c(if (length(sm)) sprintf("s(%s, k=%d)", quote_nm(sm), as.integer(lcfg$gam$k %||% 4L)),
                        if (length(lin)) quote_nm(lin))
             form <- stats::as.formula(paste("Y ~", if (length(terms)) paste(terms, collapse = " + ") else "1"))
             environment(form) <- asNamespace("mgcv")
             # Keep observation weights inside the model data. mgcv evaluates the
             # weights expression through model.frame; a wrapper-local symbol such as
             # obsWeights is not reliably visible after SuperLearner evaluates the
             # learner call. Storing the normalized weights as .obsw and referring to
             # that data column prevents the verified "object 'obsWeights' not found"
             # hard failure without allowing .obsw to enter the explicitly constructed
             # predictor formula.
             train_dat <- data.frame(Y = Y, X, .obsw = obsWeights, check.names = FALSE)
             valid_dat <- data.frame(newX, check.names = FALSE)
             fit <- tryCatch(
               withCallingHandlers(
                 mgcv::gam(form, data = train_dat, family = family,
                           weights = .obsw, method = "REML", select = TRUE,
                           na.action = stats::na.fail,
                           control = mgcv::gam.control(maxit = lcfg$gam$maxit %||% 100L)),
                 warning = function(w) {
                   if (grepl("non-integer #successes", conditionMessage(w), fixed = TRUE))
                     invokeRestart("muffleWarning")
                 }),
               error = function(e) e)
             if (inherits(fit, "error") || (!is.null(fit$converged) && !isTRUE(fit$converged))) {
               reason <- if (inherits(fit, "error")) conditionMessage(fit) else "mgcv convergence failure"
               stop("SL.gam.fixed failed: ", reason, call. = FALSE)
             }
             pred <- tryCatch(as.numeric(mgcv::predict.gam(fit, newdata = valid_dat, type = "response")),
                              error = function(e) e)
             if (inherits(pred, "error") || length(pred) != nrow(newX) || any(!is.finite(pred))) {
               reason <- if (inherits(pred, "error")) conditionMessage(pred) else "invalid predictions"
               stop("SL.gam.fixed prediction failed: ", reason, call. = FALSE)
             }
             pred <- sanitize_pred(pred, nrow(newX))
             list(pred = pred, fit = make_fit(fit))
           }, envir = .GlobalEnv)
    assign("predict.SL.gam.fixed",
           function(object, newdata, ...) {
             newdata <- as.data.frame(newdata, check.names = FALSE)
             missing_new <- setdiff(object$train_names, names(newdata))
             if (length(missing_new)) stop("predict.SL.gam.fixed missing columns: ", paste(missing_new, collapse = ", "), call. = FALSE)
             newdata <- newdata[, object$train_names, drop = FALSE]
             newdata[] <- lapply(newdata, function(z) suppressWarnings(as.numeric(z)))
             pred <- tryCatch(
               as.numeric(mgcv::predict.gam(object$object, newdata = newdata, type = "response")),
               error = function(e) stop("predict.SL.gam.fixed failed: ", conditionMessage(e), call. = FALSE))
             if (length(pred) != nrow(newdata) || any(!is.finite(pred)))
               stop("predict.SL.gam.fixed produced invalid predictions.", call. = FALSE)
             if (identical(object$family_name, "binomial")) pred <- pmin(pmax(pred, object$eps), 1 - object$eps)
             as.numeric(pred)
           }, envir = .GlobalEnv)
  }
  invisible(TRUE)
}

build_sl_library <- function(cfg, target = c("Q","g","pi")) {
  target <- match.arg(target)
  tcfg <- cfg$learners[[target]]; lib <- character()
  if (isTRUE(tcfg$use_mean))   lib <- c(lib, "SL.mean")
  if (isTRUE(tcfg$use_glm))    lib <- c(lib, "SL.glm")
  if (isTRUE(tcfg$use_glmnet)) lib <- c(lib, "SL.glmnet.fixed")
  if (identical(target, "g") && isTRUE(tcfg$use_glmnet_h1fs %||% FALSE))
    lib <- c(lib, "SL.glmnet.h1fs")
  if (identical(target, "pi") && isTRUE(tcfg$use_glmnet_A_unpenalized %||% FALSE))
    lib <- c(lib, "SL.glmnet.pi_A_unpenalized")
  if (isTRUE(tcfg$use_ranger)) lib <- c(lib, "SL.ranger.fixed")
  if (isTRUE(tcfg$use_xgboost)) lib <- c(lib, "SL.xgboost.fixed")
  if (identical(target, "Q")) {
    if (isTRUE(tcfg$use_glmnet_control_arm %||% FALSE)) lib <- c(lib, "SL.glmnet.control_arm")
    if (isTRUE(tcfg$use_ranger_control_arm %||% FALSE)) lib <- c(lib, "SL.ranger.control_arm")
    if (isTRUE(tcfg$use_xgboost_control_arm %||% FALSE)) lib <- c(lib, "SL.xgboost.control_arm")
  }
  if (isTRUE(tcfg$use_xgboost_rich %||% FALSE) && target == "Q")
    lib <- c(lib, "SL.xgboost.rich")
  if (isTRUE(tcfg$use_earth) && target == "Q") lib <- c(lib, "SL.earth.fixed")
  if (isTRUE(tcfg$use_gam))    lib <- c(lib, "SL.gam.fixed")
  if (isTRUE(tcfg$use_svm))    lib <- c(lib, "SL.svm")
  if (isTRUE(tcfg$use_nnet))   lib <- c(lib, "SL.nnet")
  if (length(lib) == 0L)
    stop(sprintf("SuperLearner library for %s is empty.", target), call. = FALSE)
  lib
}

# v8.37: alternate pi library = the primary pi library plus the glmnet learner
# that leaves the treatment indicator A unpenalized. Used only by the per-fold
# dual pi fit; the primary library is never modified. Returns NULL when the
# dual fit is disabled or when the learner is already in the primary library
# (in which case a second fit would be redundant).
build_pi_alt_library <- function(cfg) {
  if (!isTRUE(cfg$learners$pi$dual_fit_A_unpenalized %||% FALSE)) return(NULL)
  if (isTRUE(cfg$learners$pi$use_glmnet)) {
    warning("Alternate pi refit skipped: primary SL.glmnet.fixed already leaves A unpenalized.",call.=FALSE)
    return(NULL)
  }
  base <- build_sl_library(cfg, "pi")
  if ("SL.glmnet.pi_A_unpenalized" %in% base) return(NULL)
  c(base, "SL.glmnet.pi_A_unpenalized")
}


assert_superlearner_fit <- function(fit, expected_library, target, outer_fold,
                                    expected_prediction_n) {
  if (is.null(fit))
    stop(sprintf("Fold %d %s SuperLearner fit is NULL.", outer_fold, target), call. = FALSE)
  if (!inherits(fit, "SuperLearner"))
    stop(sprintf("Fold %d %s did not return a SuperLearner object.", outer_fold, target), call. = FALSE)
  expected_library <- if (is.list(expected_library))
    vapply(expected_library,function(z) paste(z,collapse="_"),character(1)) else
      as.character(expected_library)
  if (!length(expected_library) || anyNA(expected_library) || any(!nzchar(expected_library)) ||
      anyDuplicated(expected_library))
    stop(sprintf("Fold %d %s configured SuperLearner library is empty, invalid, or duplicated.",
                 outer_fold, target), call. = FALSE)
  normalize_sl_name <- function(z) sub("_All$", "", as.character(z))
  library_names <- as.character(fit$libraryNames %||% names(fit$coef) %||% character(0))
  library_base <- normalize_sl_name(library_names)
  if (anyDuplicated(library_base))
    stop(sprintf("Fold %d %s SuperLearner returned duplicated learner names.",
                 outer_fold, target), call. = FALSE)
  if (length(library_base) != length(expected_library) ||
      !setequal(library_base, expected_library))
    stop(sprintf("Fold %d %s SuperLearner library does not match the configured library.",
                 outer_fold, target), call. = FALSE)
  
  align_flag <- function(flag, label) {
    if (is.null(flag))
      stop(sprintf("Fold %d %s SuperLearner lacks required %s diagnostics.",
                   outer_fold, target, label), call. = FALSE)
    flag <- as.logical(flag)
    if (length(flag) != length(library_names))
      stop(sprintf("Fold %d %s SuperLearner %s length mismatch.",
                   outer_fold, target, label), call. = FALSE)
    nm <- names(flag)
    if (!is.null(nm) && length(nm) == length(flag)) {
      idx <- match(expected_library, normalize_sl_name(nm))
    } else {
      idx <- match(expected_library, library_base)
    }
    if (anyNA(idx) || anyNA(flag[idx]))
      stop(sprintf("Fold %d %s SuperLearner could not align %s to configured learners.",
                   outer_fold, target, label), call. = FALSE)
    setNames(flag[idx], expected_library)
  }
  err_cv <- align_flag(fit$errorsInCVLibrary, "errorsInCVLibrary")
  err_full <- align_flag(fit$errorsInLibrary, "errorsInLibrary")
  failed <- names(err_cv)[err_cv | err_full]
  if (length(failed))
    stop(sprintf(paste0("Fold %d %s SuperLearner learner failure(s) detected by the package: %s. ",
                        "Strict production mode forbids silently zero-weighting failed learners."),
                 outer_fold, target, paste(failed, collapse = ", ")), call. = FALSE)
  
  pred_sl <- as.numeric(fit$SL.predict)
  if (length(pred_sl) != expected_prediction_n || any(!is.finite(pred_sl)))
    stop(sprintf("Fold %d %s SuperLearner returned invalid ensemble predictions.",
                 outer_fold, target), call. = FALSE)
  
  coef_names <- names(fit$coef) %||% library_names
  risk_names <- names(fit$cvRisk) %||% library_names
  coef_base <- normalize_sl_name(coef_names)
  risk_base <- normalize_sl_name(risk_names)
  coef_ix <- match(expected_library, coef_base)
  risk_ix <- match(expected_library, risk_base)
  if (anyNA(coef_ix) || anyNA(risk_ix))
    stop(sprintf("Fold %d %s SuperLearner omitted a configured coefficient or CV risk.",
                 outer_fold, target), call. = FALSE)
  coef_values <- as.numeric(fit$coef[coef_ix])
  risk_values <- as.numeric(fit$cvRisk[risk_ix])
  if (any(!is.finite(coef_values)) || any(coef_values < -1e-10) ||
      !isTRUE(all.equal(sum(coef_values), 1, tolerance = 1e-6)) ||
      any(!is.finite(risk_values)))
    stop(sprintf("Fold %d %s SuperLearner has invalid ensemble coefficients or CV risks.",
                 outer_fold, target), call. = FALSE)
  
  lp <- fit$library.predict
  if (is.null(lp) || !is.matrix(lp) || nrow(lp) != expected_prediction_n ||
      ncol(lp) != length(library_names) || any(!is.finite(lp)))
    stop(sprintf("Fold %d %s SuperLearner has invalid base-learner predictions on newX.",
                 outer_fold, target), call. = FALSE)
  if (!is.null(colnames(lp)) &&
      !identical(normalize_sl_name(colnames(lp)), library_base))
    stop(sprintf("Fold %d %s SuperLearner base-prediction columns are misaligned with its learner library.",
                 outer_fold, target), call. = FALSE)
  Z <- fit$Z
  if (is.null(Z) || !is.matrix(Z) || ncol(Z) != length(library_names) ||
      any(!is.finite(Z)))
    stop(sprintf("Fold %d %s SuperLearner has an invalid internal CV prediction matrix.",
                 outer_fold, target), call. = FALSE)
  
  if (is.null(fit$fitLibrary) || length(fit$fitLibrary) != length(library_names) ||
      any(vapply(fit$fitLibrary, is.null, logical(1))))
    stop(sprintf(paste0("Fold %d %s SuperLearner has an incomplete fitted learner library. ",
                        "Production calls require saveFitLibrary=TRUE."),
                 outer_fold, target), call. = FALSE)
  fitlib_names <- names(fit$fitLibrary)
  if (!is.null(fitlib_names) &&
      !identical(normalize_sl_name(fitlib_names), library_base))
    stop(sprintf("Fold %d %s SuperLearner fitted-library entries are misaligned.",
                 outer_fold, target), call. = FALSE)
  fallback <- vapply(fit$fitLibrary, function(z) {
    is.list(z) && isTRUE(z$fallback %||% FALSE)
  }, logical(1))
  if (any(fallback))
    stop(sprintf("Fold %d %s SuperLearner contains an internal learner fallback: %s.",
                 outer_fold, target,
                 paste(library_names[fallback], collapse = ", ")), call. = FALSE)
  invisible(TRUE)
}


extract_pi_counterfactual_blocks <- function(preds, n_expected) {
  preds <- as.numeric(preds)
  n_expected <- as.integer(n_expected)[1L]
  if (!is.finite(n_expected) || n_expected < 1L ||
      length(preds) != 3L * n_expected || any(!is.finite(preds)))
    stop(sprintf("pi counterfactual extraction expected %d finite predictions but received %d.",
                 3L * n_expected, length(preds)), call. = FALSE)
  list(
    pi_1W = preds[seq_len(n_expected)],
    pi_0W = preds[n_expected + seq_len(n_expected)],
    pi_AW = preds[2L * n_expected + seq_len(n_expected)])
}

# =============================================================================
# 8) FINAL CV-TMLE
# =============================================================================
# Plain-English role: the main estimator. Splits the data into outer folds
# (balanced on exposure at the cluster level), then for each fold:
# (a) Runs nested cluster-aware rough screening on training rows only
# to decide which raw covariates W to keep (no selection leakage).
# (b) Builds a fold-specific processed design matrix W using only the
# training rows' transformation recipes (levels, medians, winsor
# bounds), and sanitizes column names.
# (c) Fits three SuperLearner models on the training rows: Q (outcome),
# g (propensity), pi (outcome-observation). Each uses mandatory whole-school cluster-aware
# internal CV; row-level internal CV is not a supported production path.
# (d) Predicts Q1W, Q0W, QAW, gn, piAW, pi1W, pi0W on validation rows.
# (e) Runs the TMLE fluctuation step on held-out predictions to produce
# targeted Qbar1W*, Qbar0W*.
# (f) Assembles the ATE estimator and the efficient influence function
# on the bounded [0,1] outcome scale, back-transformed for variance.
# (g) Uses the GSWGT1-weighted, REGION-stratified, PSUSCID-clustered
# with-replacement survey design to build a 95% EIF interval.
# v5 ADDITIONS:
# * Cluster-aware SuperLearner internal CV via validRows in cvControl.
# * Per-fold checkpointing: fold results written to RDS so that if the
# process crashes, a rerun resumes from the last completed fold.
# * Per-fold SL summaries (coef, CV risk, fallback flags) written to CSV.
# * Both-sided clipping on pi predictions; overlap product diagnostics.
# * EIF residuals built on bounded [0,1] Y-scale, scaled back for
# reporting, so heavy-tailed outliers above the 99th percentile do
# not inflate the reported standard error.
# * Fold-level assertions: every nuisance estimate is checked to be
# finite and within admissible range as the fold completes.

compute_continuous_cap <- function(y, weights, probability, cfg) {
  keep <- is.finite(y) & is.finite(weights) & weights > 0
  if (!any(keep)) stop("Cannot compute outcome cap: no finite observed outcomes with positive weights.", call. = FALSE)
  yk <- as.numeric(y[keep]); wk <- as.numeric(weights[keep])
  if (!is.finite(probability) || probability <= 0 || probability > 1)
    stop("Outcome-cap probability must lie in (0, 1].", call. = FALSE)
  if (probability >= 1) return(max(yk))
  if (isTRUE(cfg$outcome$continuous_cap_weighted %||% TRUE)) {
    dat <- data.frame(y = yk, w = wk)
    des <- survey::svydesign(ids = ~1, weights = ~w, data = dat)
    q <- survey::svyquantile(~y, design = des, quantiles = probability,
                             qrule = cfg$outcome$continuous_cap_qrule %||% "hf8",
                             ci = FALSE, se = FALSE, na.rm = TRUE)
    q_value <- as.numeric(stats::coef(q))[1L]
    if (!is.finite(q_value)) stop("Weighted outcome quantile is not finite.", call. = FALSE)
    return(q_value)
  }
  as.numeric(stats::quantile(yk, probs = probability, na.rm = TRUE,
                             names = FALSE, type = 8))
}

get_outcome_support_spec <- function(cfg, outcome_type, constructor_support = NULL) {
  if (identical(outcome_type, "binary"))
    return(list(lower = 0, upper = 1, lower_rule = "fixed_binary", upper_rule = "fixed_binary"))
  fam_cfg <- cfg$outcome$families[[cfg$outcome$family]]
  if (!is.null(constructor_support)) {
    lower <- constructor_support$natural_lower %||% constructor_support$lower %||%
      fam_cfg$natural_lower_bound %||% NA_real_
    upper <- constructor_support$natural_upper %||% constructor_support$upper %||%
      fam_cfg$natural_upper_bound %||% Inf
    lower_rule <- constructor_support$lower_rule %||% fam_cfg$lower_bound_rule %||% "empirical"
    upper_rule <- constructor_support$upper_rule %||% fam_cfg$upper_bound_rule %||% "quantile"
  } else {
    lower <- fam_cfg$natural_lower_bound %||% NA_real_
    upper <- fam_cfg$natural_upper_bound %||% Inf
    lower_rule <- fam_cfg$lower_bound_rule %||% "empirical"
    upper_rule <- fam_cfg$upper_bound_rule %||% "quantile"
  }
  list(lower = as.numeric(lower), upper = as.numeric(upper),
       lower_rule = lower_rule, upper_rule = upper_rule)
}

prepare_final_analysis_data <- function(main_df, cfg) {
  constructor_support <- attr(main_df, "outcome_support")
  df <- main_df
  A <- normalize_binary_var(df[[cfg$analysis$exposure_var]], cfg$analysis$exposure_var)
  outcome_info <- prepare_modeled_outcome(
    df[[cfg$analysis$outcome_var]], cfg$analysis$outcome_type, cfg$analysis$outcome_var)
  Y_raw        <- outcome_info$values
  outcome_type <- outcome_info$type
  outcome_obs  <- outcome_info$observed
  delta_Y <- as.integer(outcome_obs)
  delta_name <- cfg$analysis$outcome_observed_var
  if (delta_name %in% names(df)) {
    delta_stored <- normalize_binary_var(df[[delta_name]], delta_name, require_both = FALSE)
    if (!identical(delta_stored, delta_Y))
      stop("Stored outcome-observation indicator is inconsistent with the modeled outcome.",
           call. = FALSE)
  }
  w_raw <- as.numeric(df[[cfg$analysis$weight_var]])
  # Invalid weights must have been removed during main-dataset construction.
  # Silently dropping rows here would desynchronize the analytic sample from
  # the frozen sample gates and the full survey-domain design frame.
  keep_w <- is.finite(w_raw) & w_raw > 0
  if (any(!keep_w))
    stop(sprintf(
      "Final TMLE received %d row(s) with non-positive or missing sampling weights. Rebuild the main dataset; rows may not be dropped after the survey-domain frame is frozen.",
      sum(!keep_w)), call. = FALSE)
  cluster <- df[[cfg$analysis$cluster_var]]
  if (anyNA(cluster))
    stop(sprintf("Final TMLE analytic sample contains %d row(s) with missing %s; folds cannot be defined without a PSU.",
                 sum(is.na(cluster)), cfg$analysis$cluster_var), call. = FALSE)
  if (!cfg$analysis$strata_var %in% names(df))
    stop(sprintf("Required Add Health design stratum '%s' is absent from the analytic data.",
                 cfg$analysis$strata_var), call. = FALSE)
  strata <- df[[cfg$analysis$strata_var]]
  if (anyNA(strata) || any(trimws(as.character(strata)) == ""))
    stop(sprintf("Final TMLE analytic sample contains missing or blank %s values; stratified PSU inference cannot be computed.",
                 cfg$analysis$strata_var), call. = FALSE)
  expected_h <- as.integer(cfg$analysis$expected_strata_n %||% 4L)
  observed_h <- length(unique(as.character(strata)))
  if (observed_h != expected_h)
    stop(sprintf("Final TMLE requires exactly %d observed %s levels; found %d.",
                 expected_h, cfg$analysis$strata_var, observed_h), call. = FALSE)
  # Bound Y to an outcome-specific finite range for TMLE. Verified natural
  # support is used when available; otherwise the empirical lower bound and
  # configured upper-cap rule define the range. The fluctuation runs on [0,1].
  y_obs_vals <- Y_raw[delta_Y == 1L & is.finite(Y_raw)]
  if (length(y_obs_vals) == 0L)
    stop("Final TMLE has no observed finite outcomes from which to define the bounded outcome.", call. = FALSE)
  support <- get_outcome_support_spec(cfg, outcome_type, constructor_support)
  if (outcome_type == "binary") {
    if (!isTRUE(all.equal(as.numeric(c(support$lower, support$upper)), c(0, 1),
                          tolerance = 0)))
      stop("Binary outcome support must be exactly 0/1.", call. = FALSE)
    if (!all(y_obs_vals %in% c(0, 1)))
      stop("Binary outcome contains values other than 0/1 after preparation.", call. = FALSE)
    # Binary outcomes must remain on their exact natural support regardless of
    # any continuous-outcome epsilon setting.
    y_lower <- 0
    y_upper <- 1
    cap_value <- 1
  } else {
    q_up <- if (identical(support$upper_rule, "fixed") && is.finite(support$upper)) {
      support$upper
    } else {
      compute_continuous_cap(
        Y_raw[delta_Y == 1L], w_raw[delta_Y == 1L],
        cfg$outcome$continuous_upper_quantile, cfg)
    }
    if (identical(support$lower_rule, "natural") && is.finite(support$lower)) {
      if (any(y_obs_vals < support$lower))
        stop("Observed outcome values fall below the verified natural lower bound.", call. = FALSE)
      y_lower <- support$lower - cfg$outcome$continuous_bound_eps
    } else {
      y_lower <- min(y_obs_vals, na.rm = TRUE) - cfg$outcome$continuous_bound_eps
    }
    if (is.finite(support$upper) && any(y_obs_vals > support$upper))
      stop("Observed outcome values exceed the verified natural upper bound.", call. = FALSE)
    applied_upper <- min(q_up, support$upper)
    y_upper <- applied_upper + cfg$outcome$continuous_bound_eps
    cap_value <- applied_upper
  }
  y_range <- y_upper - y_lower
  if (!is.finite(y_range) || y_range <= 0) stop("Invalid bounded-Y range.", call. = FALSE)
  obs_i <- which(delta_Y == 1L & is.finite(Y_raw))
  Y_bounded_orig <- rep(NA_real_, length(Y_raw))
  Y_bounded_orig[obs_i] <- pmin(pmax(Y_raw[obs_i], y_lower), y_upper)
  Y_star <- rep(NA_real_, length(Y_raw))
  Y_star[obs_i] <- (Y_bounded_orig[obs_i] - y_lower) / y_range
  if (any(Y_star[obs_i] < -1e-12 | Y_star[obs_i] > 1 + 1e-12))
    stop("Canonical bounded outcome escaped [0,1].", call. = FALSE)
  list(df = df, A = A, Y_raw = Y_raw, Y_bounded_orig = Y_bounded_orig,
       Y_star = Y_star, delta_Y = delta_Y,
       weights = w_raw, cluster = cluster,
       strata = strata,
       outcome_type = outcome_type, y_lower = y_lower, y_upper = y_upper,
       y_range = y_range,
       cap_value = if (identical(outcome_type, "continuous")) cap_value else NA_real_,
       cap_weighted = identical(outcome_type, "continuous") &&
         !identical(support$upper_rule, "fixed") &&
         isTRUE(cfg$outcome$continuous_cap_weighted %||% TRUE),
       cap_qrule = if (identical(outcome_type, "continuous"))
         if (identical(support$upper_rule, "fixed")) "fixed" else
           cfg$outcome$continuous_cap_qrule %||% "hf8" else NA_character_,
       cap_rule = if (identical(outcome_type, "continuous")) support$upper_rule else "fixed_binary")
}

make_final_cv_folds <- function(data_pack, cfg) {
  do.call(make_cluster_folds_balanced, c(list(
    cluster = data_pack$cluster, A = data_pack$A, k = cfg$final_tmle$vfolds,
    seed = seed_for(cfg, 7777L), weights = data_pack$weights,
    delta = data_pack$delta_Y,
    balance_on_weights = isTRUE(cfg$final_tmle$outer_fold_balance_on_weights)),
    fold_control_from_cfg(cfg, "outer")))
}

# Learn and apply final-W preprocessing recipes --------------------------------
# Semantic missing-code families and factor declarations come from the frozen,
# full-Wave-I outcome-blind dictionary. Only imputation, skip-level retention,
# factor levels, rare-level pooling, winsorization, scaling, dummy levels, and
# column retention are learned from the outer-fold training rows.

learn_final_missing_recipe <- function(df, cfg_pre) {
  df <- classify_factors_by_uniques(df, cfg_pre)
  if ("MHSum_W1" %in% names(df)) df$MHSum_W1 <- to_numeric_codes(df$MHSum_W1)
  numeric_names <- names(df)[vapply(df, function(z) is.numeric(z) || is.integer(z), logical(1))]
  assert_no_missing_indicator_name_collisions(
    names(df), numeric_names, context = "learn_final_missing_recipe")
  recipes <- list()
  miss_label  <- cfg_pre$factor_missing_label %||% "Missing"
  skip_label  <- cfg_pre$factor_skip_label %||% "Skip"
  other_label <- cfg_pre$factor_other_label %||% "_Other_"
  min_n_skip  <- cfg_pre$factor_special_code_min_n %||% 30L
  min_pr_skip <- cfg_pre$factor_special_code_min_prop %||% 0.02
  
  for (nm in names(df)) {
    col <- df[[nm]]
    rule <- get_missing_rule(col, cfg_pre, variable_name = nm)
    masks <- missing_masks_from_rule(col, rule)
    if (is.factor(col) || is.character(col)) {
      xc <- canonicalize_factor_text(col)
      missA <- masks$general; miss97 <- masks$skip
      assert_reserved_factor_labels_safe(
        col, missA, miss97, c(miss_label, skip_label, other_label),
        nm, "learn_final_missing_recipe")
      n_skip <- sum(miss97); pr_skip <- n_skip / length(xc)
      retain_skip <- n_skip >= min_n_skip || pr_skip >= min_pr_skip
      if (retain_skip) {
        xc[missA] <- NA_character_
        xc[miss97] <- skip_label
      } else {
        xc[missA | miss97] <- NA_character_
      }
      f <- addNA(factor(xc))
      levels(f)[is.na(levels(f))] <- miss_label
      levs <- unique(c(levels(f), other_label))
      recipes[[nm]] <- list(
        type = "factor", general_codes = rule$general_codes,
        skip_codes = rule$skip_codes, numeric_coded = rule$numeric_coded,
        classifier_rule = rule, retain_skip = retain_skip,
        levels = levs, missing_label = miss_label,
        skip_label = skip_label, other_label = other_label)
    } else {
      x <- masks$numeric
      fill <- compute_simple_impute(x[!(masks$general | masks$skip)],
                                    cfg_pre$numeric_imputation)
      recipes[[nm]] <- list(
        type = "numeric", fill = fill,
        general_codes = rule$general_codes, skip_codes = rule$skip_codes,
        numeric_coded = rule$numeric_coded, classifier_rule = rule)
    }
  }
  recipes
}

apply_final_missing_recipe <- function(df, recipes, cfg_pre) {
  n <- nrow(df)
  out <- data.frame(row_id_internal = seq_len(n))[0]
  numeric_support <- list()
  for (nm in names(recipes)) {
    rec <- recipes[[nm]]
    if (!nm %in% names(df))
      stop("apply_final_missing_recipe is missing required raw variable '", nm, "'.", call. = FALSE)
    col <- df[[nm]]
    rule <- rec$classifier_rule %||% list(
      numeric_coded = rec$numeric_coded %||% TRUE,
      general_codes = rec$general_codes %||% numeric(0),
      skip_codes = rec$skip_codes %||% numeric(0))
    masks <- missing_masks_from_rule(col, rule)
    missA <- masks$general; miss97 <- masks$skip
    if (identical(rec$type, "numeric")) {
      x <- masks$numeric
      originally_observed <- !(missA | miss97) & is.finite(x)
      numeric_support[[nm]] <- list(n_obs = sum(originally_observed),
                                    p_obs = mean(originally_observed))
      x[!originally_observed] <- rec$fill
      out[[nm]] <- x
      # Numeric missingness indicators remain exact 0/1 variables and are not
      # winsorized or standardized later. They include coded nonresponse and
      # structural skips, not only native NA values.
      out[[paste0(nm, "_missA")]]  <- as.integer(missA)
      out[[paste0(nm, "_miss97")]] <- as.integer(miss97)
      numeric_support[[paste0(nm, "_missA")]] <- list(n_obs = n, p_obs = 1)
      numeric_support[[paste0(nm, "_miss97")]] <- list(n_obs = n, p_obs = 1)
    } else {
      xc <- canonicalize_factor_text(col)
      if (isTRUE(rec$retain_skip)) {
        xc[missA] <- NA_character_
        xc[miss97] <- rec$skip_label
      } else {
        xc[missA | miss97] <- NA_character_
      }
      xc[is.na(xc)] <- rec$missing_label
      xc[!(xc %in% rec$levels)] <- rec$other_label
      out[[nm]] <- factor(xc, levels = rec$levels)
    }
  }
  attr(out, "numeric_support") <- numeric_support
  out
}


# Priority-aware ordering for final-W post-expansion caps. This avoids letting
# arbitrary union/traversal order decide which raw variables survive when factor
# expansion exceeds the processed-column cap. Variables with outcome,
# missingness, and joint A/Y evidence are protected ahead of A-only variables.
order_vars_for_final_cap <- function(vars, priority_table = NULL) {
  vars <- unique(vars)
  if (length(vars) == 0L || is.null(priority_table) || !"variable" %in% names(priority_table)) {
    return(vars)
  }
  pt <- priority_table[match(vars, priority_table$variable), , drop = FALSE]
  flag <- function(nm) if (nm %in% names(pt)) isTRUE_vec(pt[[nm]]) else rep(FALSE, nrow(pt))
  score <- function(nm) if (nm %in% names(pt)) suppressWarnings(as.numeric(pt[[nm]])) else rep(NA_real_, nrow(pt))
  lasso_y <- flag("selected_by_lasso_Y")
  joint   <- flag("selected_by_joint_AY")
  lasso_d <- flag("selected_by_lasso_delta")
  outc    <- flag("selected_by_outcome")
  delt    <- flag("selected_by_delta")
  lasso_a <- flag("selected_by_lasso_A")
  both_ay <- lasso_a & lasso_y
  aonly   <- flag("selected_by_exposure_only") | flag("selected_by_exposure_candidate_for_lasso")
  priority <- ifelse(both_ay, 1L,
                     ifelse(joint, 2L,
                            ifelse(lasso_y, 3L,
                                   ifelse(lasso_d, 4L,
                                          ifelse(outc, 5L,
                                                 ifelse(delt, 6L,
                                                        ifelse(lasso_a, 7L,
                                                               ifelse(aonly, 8L, 9L))))))))
  best_score <- pmax(score("outcome_score"), score("delta_score"), score("exposure_score"), na.rm = TRUE)
  best_score[!is.finite(best_score)] <- -Inf
  vars[order(priority, -best_score, vars)]
}

isTRUE_vec <- function(x) {
  if (is.null(x)) return(logical(0))
  out <- as.logical(x)
  out[is.na(out)] <- FALSE
  out
}

build_final_W_train_valid <- function(train_df, valid_df, selected_vars, cfg, priority_table = NULL, processed_cap_override = NULL) {
  cand_vars <- intersect(unique(selected_vars), names(train_df))
  cand_vars <- order_vars_for_final_cap(cand_vars, priority_table)
  protected_W <- intersect(resolve_protected_W(cfg), names(train_df))
  mandatory_W <- intersect(get_mandatory_W(cfg), names(train_df))
  cand_vars <- c(mandatory_W, setdiff(cand_vars, mandatory_W))
  # Guard fixed-W/sensitivity routes as well as the automatic screens.
  assert_no_excluded_source_W(train_df,cfg,cand_vars,"Final W construction")
  original_cand_vars <- cand_vars
  missing_selected <- setdiff(unique(selected_vars), names(train_df))
  if (!length(cand_vars))
    stop("Final W construction received no valid selected variables.", call. = FALSE)
  
  t0 <- proc.time()[3]
  nonprotected_budget <- as.integer(processed_cap_override %||%
                                      cfg$final_tmle$final_max_processed_columns %||% 260L)
  hard_total <- as.integer(cfg$final_tmle$hard_max_processed_columns %||% 450L)
  if (!is.finite(nonprotected_budget) || nonprotected_budget < 1L ||
      !is.finite(hard_total) || hard_total < 1L)
    stop("Invalid processed-column budgets.", call. = FALSE)
  
  raw_all_tr <- train_df[, cand_vars, drop = FALSE]
  miss_all <- learn_final_missing_recipe(raw_all_tr, cfg$preprocessing)
  proc_all <- apply_final_missing_recipe(raw_all_tr, miss_all, cfg$preprocessing)
  support_all <- attr(proc_all, "numeric_support") %||% list()
  A_factor <- normalize_binary_var(train_df[[cfg$analysis$exposure_var]], cfg$analysis$exposure_var)
  
  # Count each raw variable's processed representation before constructing the
  # combined matrix. This makes the engineering budget preventive rather than
  # attempting to trim only after an oversized design already exists.
  processed_counts <- setNames(integer(length(cand_vars)), cand_vars)
  for (v in cand_vars) {
    cols <- intersect(names(proc_all), c(v, paste0(v, "_missA"), paste0(v, "_miss97")))
    one <- proc_all[, cols, drop = FALSE]
    attr(one, "numeric_support") <- support_all[intersect(names(support_all), cols)]
    d <- build_grouped_design_train(one, cfg$final_preprocess, cfg$preprocessing,
                                    hard_max_cols = hard_total, A = A_factor,
                                    protected_raw_vars = protected_W)
    processed_counts[[v]] <- ncol(d$X)
  }
  if (any(processed_counts[protected_W] < 1L)) {
    bad <- protected_W[processed_counts[protected_W] < 1L]
    stop("Protected H1FS item(s) produced no usable processed columns: ",
         paste(bad, collapse = ", "), call. = FALSE)
  }
  
  keep_vars <- mandatory_W
  used_nonmandatory <- 0L
  for (v in setdiff(cand_vars, mandatory_W)) {
    add <- processed_counts[[v]]
    if (add < 1L) next
    if (used_nonmandatory + add <= nonprotected_budget) {
      keep_vars <- c(keep_vars, v)
      used_nonmandatory <- used_nonmandatory + add
    }
  }
  keep_vars <- unique(keep_vars)
  if (!length(keep_vars)) stop("Processed-column allocation retained no variables.", call. = FALSE)
  expected_total <- sum(processed_counts[keep_vars])
  if (expected_total > hard_total)
    stop(sprintf("Final design requires %d processed columns, exceeding hard total guard %d.",
                 expected_total, hard_total), call. = FALSE)
  
  raw_tr <- train_df[, keep_vars, drop = FALSE]
  raw_te <- valid_df[, keep_vars, drop = FALSE]
  miss_rec <- learn_final_missing_recipe(raw_tr, cfg$preprocessing)
  proc_tr <- apply_final_missing_recipe(raw_tr, miss_rec, cfg$preprocessing)
  proc_te <- apply_final_missing_recipe(raw_te, miss_rec, cfg$preprocessing)
  des_tr <- build_grouped_design_train(proc_tr, cfg$final_preprocess, cfg$preprocessing,
                                       hard_max_cols = hard_total, A = A_factor,
                                       protected_raw_vars = protected_W)
  if (!ncol(des_tr$X)) stop("Final W preprocessing produced an empty training design.", call. = FALSE)
  if (ncol(des_tr$X) > hard_total) stop("Final design exceeded the hard total column guard.", call. = FALSE)
  
  X_te <- apply_preprocess_recipe(proc_te, des_tr$recipes)
  tr_cols <- colnames(des_tr$X)
  missing_in_te <- setdiff(tr_cols, colnames(X_te))
  extra_in_te <- setdiff(colnames(X_te), tr_cols)
  if (length(missing_in_te)) {
    add <- matrix(0, nrow(X_te), length(missing_in_te), dimnames = list(NULL, missing_in_te))
    X_te <- cbind(X_te, add)
  }
  if (length(extra_in_te)) X_te <- X_te[, !colnames(X_te) %in% extra_in_te, drop = FALSE]
  X_te <- X_te[, tr_cols, drop = FALSE]
  
  W_tr <- as.data.frame(des_tr$X, check.names = FALSE)
  W_te <- as.data.frame(X_te, check.names = FALSE)
  raw_map <- strip_missing_suffix(names(des_tr$recipes)[des_tr$group])
  protected_map <- table(factor(raw_map[raw_map %in% protected_W], levels = protected_W))
  mandatory_map <- table(factor(raw_map[raw_map %in% mandatory_W], levels = mandatory_W))
  if (length(mandatory_W) && any(mandatory_map < 1L)) {
    bad <- mandatory_W[mandatory_map < 1L]
    stop("At least one mandatory W variable disappeared from the final processed design: ",
         paste(bad, collapse = ", "), call. = FALSE)
  }
  if (length(protected_W) && any(protected_map < 1L))
    stop("At least one protected H1FS item disappeared from the final processed design.", call. = FALSE)
  protected_level_audit <- do.call(rbind, lapply(protected_W, function(v) {
    rec <- des_tr$recipes[[v]]
    if (identical(v, "MHSum_W1") && !is.null(rec) && identical(rec$type, "numeric"))
      return(data.frame(variable = v, observed_substantive_levels = "continuous_total_0_57",
                        retained_recipe_levels = "continuous_total_no_tail_winsorization",
                        all_observed_levels_retained = TRUE, stringsAsFactors = FALSE))
    if (is.null(rec) || !identical(rec$type, "factor")) {
      return(data.frame(variable = v, observed_substantive_levels = NA_character_,
                        retained_recipe_levels = NA_character_,
                        all_observed_levels_retained = FALSE,
                        stringsAsFactors = FALSE))
    }
    observed <- rec$prep$observed_substantive_levels %||% character(0)
    retained <- rec$prep$levels %||% character(0)
    missing_levels <- setdiff(observed, retained)
    data.frame(variable = v,
               observed_substantive_levels = paste(observed, collapse = ";"),
               retained_recipe_levels = paste(retained, collapse = ";"),
               all_observed_levels_retained = length(missing_levels) == 0L,
               stringsAsFactors = FALSE)
  }))
  if (length(protected_W) &&
      (!is.data.frame(protected_level_audit) ||
       any(!protected_level_audit$all_observed_levels_retained))) {
    bad <- protected_level_audit$variable[!protected_level_audit$all_observed_levels_retained]
    stop("Protected H1FS substantive level(s) were lost during final preprocessing: ",
         paste(bad, collapse = ", "), call. = FALSE)
  }
  if (isTRUE(cfg$preprocessing$sanitize_column_names_for_model_matrix)) {
    clean_names <- make.unique(gsub("[^A-Za-z0-9_]", "_", names(W_tr)))
    names(W_tr) <- clean_names; names(W_te) <- clean_names
  }
  n_protected <- sum(raw_map %in% protected_W)
  n_mandatory <- sum(raw_map %in% mandatory_W)
  n_nonprotected <- ncol(W_tr) - n_protected
  n_budgeted <- ncol(W_tr) - n_mandatory
  if (n_budgeted > nonprotected_budget)
    stop("Final optional design exceeded its declared processed-column budget.", call. = FALSE)
  message(sprintf("  [final W] retained %d mandatory (%d protected H1FS) and %d budgeted processed columns (budget=%d; total=%d; hard total=%d).",
                  n_mandatory, n_protected, n_budgeted, nonprotected_budget, ncol(W_tr), hard_total))
  
  list(train = W_tr, valid = W_te, n_raw = length(keep_vars),
       n_original_raw = length(original_cand_vars), kept_raw_vars = keep_vars,
       dropped_by_column_cap = setdiff(original_cand_vars, keep_vars),
       n_missing_selected = length(missing_selected), n_processed = ncol(W_tr),
       n_processed_nonprotected = n_nonprotected,
       n_processed_optional_budgeted = n_budgeted,
       n_protected_cols = n_protected,
       n_mandatory_cols = n_mandatory,
       mandatory_raw_to_processed = as.integer(mandatory_map),
       mandatory_raw_names = mandatory_W,
       protected_raw_to_processed = as.integer(protected_map),
       protected_raw_names = protected_W,
       processed_raw_map = stats::setNames(raw_map, names(W_tr)),
       protected_level_audit = protected_level_audit,
       nonprotected_budget = nonprotected_budget,
       hard_total_budget = hard_total, missing_in_validation = length(missing_in_te),
       extra_in_validation = length(extra_in_te), seconds = proc.time()[3] - t0)
}


# high-dimensional safety helpers ---------------------------------------
truthy_or_false <- function(x) isTRUE(x)

compact_var_signature_for_duplicate <- function(x, rule = NULL) {
  if (!is.null(rule)) {
    masks <- missing_masks_from_rule(x, rule)
    token <- rep("<NA>", length(x))
    token[masks$general] <- "<GENERAL_MISSING>"
    token[masks$skip] <- "<STRUCTURAL_SKIP>"
    if (isTRUE(rule$numeric_coded)) {
      z <- masks$numeric
      substantive <- !(masks$general | masks$skip) & is.finite(z)
      token[substantive] <- format(round(z[substantive], 8), scientific = FALSE)
    } else {
      xc <- as.character(x)
      substantive <- !(masks$general | masks$skip) & !is.na(xc)
      token[substantive] <- xc[substantive]
    }
    return(paste(token, collapse = "\r"))
  }
  if (is.numeric(x) || is.integer(x) || is.logical(x)) {
    z <- suppressWarnings(as.numeric(x))
    z[!is.finite(z)] <- NA_real_
    paste(ifelse(is.na(z), "<NA>", format(round(z, 8), scientific = FALSE)), collapse = "\r")
  } else {
    z <- as.character(x)
    paste(ifelse(is.na(z), "<NA>", z), collapse = "\r")
  }
}

prefilter_candidate_vars_for_screen <- function(df, vars, cfg, fold_id = NA_integer_) {
  vars <- unique(vars[vars %in% names(df)])
  if (!isTRUE(cfg$final_tmle$rough_prefilter_enable %||% TRUE) || length(vars) == 0L) {
    return(list(vars = vars, log = data.frame(variable = vars, prefilter_kept = TRUE,
                                              prefilter_reason = "not_run", stringsAsFactors = FALSE)))
  }
  max_miss <- cfg$final_tmle$rough_prefilter_max_missing_prop %||% 0.95
  min_obs  <- cfg$final_tmle$rough_prefilter_min_observed_n %||% 30L
  min_uniq <- cfg$final_tmle$rough_prefilter_min_unique %||% 2L
  min_nonmodal <- cfg$final_tmle$rough_prefilter_min_nonmodal_n %||% 3L
  # two-arm estimability rule parameters and exposure vector.
  two_arm_min_n <- cfg$final_tmle$rough_prefilter_two_arm_min_n %||% 0L
  two_arm_max_levels <- cfg$final_tmle$rough_prefilter_two_arm_max_levels %||% 3L
  A_vec <- NULL
  if (two_arm_min_n > 0L) {
    ev <- cfg$analysis$exposure_var
    if (!is.null(ev) && ev %in% names(df)) {
      A_vec <- suppressWarnings(as.integer(as.character(df[[ev]])))
      if (length(unique(A_vec[is.finite(A_vec)])) < 2L) A_vec <- NULL
    }
  }
  log_rows <- vector("list", length(vars))
  keep <- rep(TRUE, length(vars))
  for (i in seq_along(vars)) {
    v <- vars[[i]]; x <- df[[v]]
    rule <- get_missing_rule(x, cfg$preprocessing, variable_name = v)
    masks <- missing_masks_from_rule(x, rule)
    obs <- !(masks$general | masks$skip)
    if (is.numeric(x) || is.integer(x)) vals <- masks$numeric[obs]
    else vals <- as.character(x)[obs]
    n_obs <- sum(obs); miss_prop <- 1 - n_obs / length(x)
    n_uniq <- length(unique(vals))
    nonmodal <- 0L
    if (n_obs > 0L && n_uniq > 0L) {
      tab <- table(vals, useNA = "no")
      nonmodal <- n_obs - max(tab)
    }
    reason <- "kept"
    if (miss_prop > max_miss) reason <- "too_missing"
    else if (n_obs < min_obs) reason <- "too_few_observed"
    else if (n_uniq < min_uniq) reason <- "too_few_unique"
    else if (nonmodal < min_nonmodal) reason <- "near_constant"
    # two-arm minimum-cell rule for (near-)binary indicators. Applied
    # only after the variable passed the basic checks above, only when an
    # exposure vector is available, and only to low-cardinality indicators.
    # capture two-arm audit fields so the exclusion reason is fully
    # transparent (which minority level, how many exposed/unexposed, threshold).
    ta_minority_level <- NA_character_
    ta_n_exp_present  <- NA_integer_
    ta_n_unexp_present <- NA_integer_
    ta_threshold      <- NA_integer_
    if (identical(reason, "kept") && !is.null(A_vec) &&
        n_uniq >= 2L && n_uniq <= two_arm_max_levels) {
      # Minority (rarest) SUBSTANTIVE observed level is the cell that drives
      # rare-cell positivity failures. `vals` already excludes only the exact
      # codes recognized by the frozen complete-Wave-I classifier, so no
      # additional blanket removal of 6-9 or 96-99 is performed here.
      vals_ta <- as.character(vals)
      tab_obs <- table(vals_ta, useNA = "no")
      if (length(tab_obs) >= 2L) {
        minority_level <- names(tab_obs)[which.min(as.integer(tab_obs))]
        present <- obs
        present[obs] <- as.character(vals) == minority_level
        a_known <- is.finite(A_vec)
        n_exp_present   <- sum(present & a_known & A_vec == 1L, na.rm = TRUE)
        n_unexp_present <- sum(present & a_known & A_vec == 0L, na.rm = TRUE)
        ta_minority_level  <- as.character(minority_level)
        ta_n_exp_present   <- as.integer(n_exp_present)
        ta_n_unexp_present <- as.integer(n_unexp_present)
        ta_threshold       <- as.integer(two_arm_min_n)
        if (n_exp_present < two_arm_min_n || n_unexp_present < two_arm_min_n)
          reason <- "rare_cell_two_arm"
      }
    }
    keep[[i]] <- identical(reason, "kept")
    log_rows[[i]] <- data.frame(
      fold = fold_id, variable = v, prefilter_kept = keep[[i]],
      prefilter_reason = reason, missing_prop = miss_prop,
      n_observed = n_obs, n_unique = n_uniq, n_nonmodal = nonmodal,
      missing_classifier_support = rule$support_type,
      questionnaire_source = isTRUE(rule$questionnaire_source),
      categorical_questionnaire = isTRUE(rule$categorical_questionnaire),
      forced_factor = isTRUE(rule$forced_factor),
      known_codebook_overlap = v %in% (cfg$preprocessing$known_codebook_overlap_vars %||% character(0)),
      percentage_like = isTRUE(rule$percentage_like),
      dense_small_count = isTRUE(rule$dense_small_count),
      missing_scheme_decision = rule$scheme_decision,
      missing_classifier_families = paste(rule$recognized_families, collapse = ";"),
      exact_general_codes = paste(rule$general_codes, collapse = ";"),
      exact_skip_codes = paste(rule$skip_codes, collapse = ";"),
      minority_level = ta_minority_level,
      n_exp_present = ta_n_exp_present,
      n_unexp_present = ta_n_unexp_present,
      two_arm_threshold = ta_threshold,
      stringsAsFactors = FALSE)
  }
  log_df <- do.call(rbind, log_rows)
  
  # Optional exact-duplicate removal after basic missingness/variation filters.
  if (isTRUE(cfg$final_tmle$rough_prefilter_drop_exact_duplicates %||% TRUE) && any(keep)) {
    kept_vars <- vars[keep]
    sig <- vapply(kept_vars, function(v) {
      rule <- get_missing_rule(df[[v]], cfg$preprocessing, variable_name = v)
      compact_var_signature_for_duplicate(df[[v]], rule = rule)
    }, character(1))
    dup <- duplicated(sig)
    if (any(dup)) {
      dup_vars <- kept_vars[dup]
      log_df$prefilter_kept[match(dup_vars, log_df$variable)] <- FALSE
      log_df$prefilter_reason[match(dup_vars, log_df$variable)] <- "exact_duplicate"
      keep[match(dup_vars, vars)] <- FALSE
    }
  }
  out_vars <- vars[keep]
  n_rare_cell <- sum(log_df$prefilter_reason == "rare_cell_two_arm")
  message(sprintf("    [fold %s prefilter] %d -> %d raw candidates; dropped %d (incl. %d rare-cell two-arm).",
                  as.character(fold_id), length(vars), length(out_vars),
                  length(vars) - length(out_vars), n_rare_cell))
  if (length(out_vars) == 0L) stop("Candidate prefilter removed every candidate variable.", call. = FALSE)
  list(vars = out_vars, log = log_df)
}

kish_ess_safe <- function(w) {
  w <- as.numeric(w); w <- w[is.finite(w) & w > 0]
  if (!length(w)) return(NA_real_)
  (sum(w)^2) / sum(w^2)
}

internal_fold_cell_counts <- function(ix, A_vec, delta_vec, weights) {
  tr <- setdiff(seq_along(A_vec), ix)
  one <- function(rows, a, d) {
    hit <- rows[A_vec[rows] == a & delta_vec[rows] == d]
    c(n = length(hit), ess = kish_ess_safe(weights[hit]))
  }
  cells <- expand.grid(a = 0:1, d = 0:1)
  out <- list()
  for (j in seq_len(nrow(cells))) {
    a <- cells$a[j]; d <- cells$d[j]; nm <- paste0("a", a, "d", d)
    vv <- one(ix, a, d); tt <- one(tr, a, d)
    out[[paste0("valid_n_", nm)]] <- vv[["n"]]
    out[[paste0("valid_ess_", nm)]] <- vv[["ess"]]
    out[[paste0("train_n_", nm)]] <- tt[["n"]]
    out[[paste0("train_ess_", nm)]] <- tt[["ess"]]
  }
  out
}

warn_internal_valid_rows <- function(validRows, A_vec, label, cfg, fold_id, delta_vec = NULL, weights = NULL) {
  if (!length(validRows)) stop("Internal CV produced no validation folds.", call. = FALSE)
  if (is.null(delta_vec)) delta_vec <- rep(1L, length(A_vec))
  if (is.null(weights)) weights <- rep(1, length(A_vec))
  A_vec <- as.integer(A_vec); delta_vec <- as.integer(delta_vec); weights <- as.numeric(weights)
  global_cells <- table(factor(A_vec, levels = 0:1), factor(delta_vec, levels = 0:1))
  required <- which(global_cells > 0, arr.ind = TRUE)
  rows <- list()
  for (j in seq_along(validRows)) {
    ix <- validRows[[j]]
    cc <- internal_fold_cell_counts(ix, A_vec, delta_vec, weights)
    for (r in seq_len(nrow(required))) {
      a <- required[r, 1] - 1L; d <- required[r, 2] - 1L; nm <- paste0("a", a, "d", d)
      if (cc[[paste0("valid_n_", nm)]] < 1L || cc[[paste0("train_n_", nm)]] < 1L)
        stop(sprintf("Fold %d internal %s CV lacks support for A=%d, delta=%d in validation or its training complement.",
                     fold_id, label, a, d), call. = FALSE)
    }
    rows[[j]] <- cc
  }
  treated <- vapply(validRows, function(ix) sum(A_vec[ix] == 1L), integer(1))
  observed_treated <- vapply(validRows, function(ix) sum(A_vec[ix] == 1L & delta_vec[ix] == 1L), integer(1))
  ess_t <- vapply(validRows, function(ix) kish_ess_safe(weights[ix][A_vec[ix] == 1L]), numeric(1))
  message(sprintf("    [fold %d] Internal %s support: treated=[%s], observed-treated=[%s], treated ESS=[%s].",
                  fold_id, label, paste(treated, collapse = ","),
                  paste(observed_treated, collapse = ","),
                  paste(sprintf("%.1f", ess_t), collapse = ",")))
  min_t <- cfg$final_tmle$internal_fold_min_treated_warning_n %||% 8L
  min_ot <- cfg$final_tmle$internal_fold_min_observed_treated_warning_n %||% 6L
  if (any(treated < min_t))
    warning(sprintf("Fold %d internal %s CV has validation treated count below %d.", fold_id, label, min_t), call. = FALSE)
  if (any(observed_treated < min_ot))
    warning(sprintf("Fold %d internal %s CV has validation observed-treated count below %d.", fold_id, label, min_ot), call. = FALSE)
  invisible(rows)
}


make_wave1_cache_fingerprint <- function(cfg) {
  list(version = cfg$global$version %||% "v8.33_restored_no_mortality_composite_sensitivity",
       script = pipeline_script_fingerprint(
         cfg, strict = isTRUE(cfg$global$require_script_md5 %||% FALSE)),
       paths = lapply(cfg$paths[c("wave1_inhome", "birth_records", "neighborhood_w1", "inschool_w1",
                                  "contextual_w1", "health_w1", "spatial_w1", "stchr95_w1",
                                  "polcon_w1", "weights_w1", "school_admin_w1")], file_fingerprint),
       dictionary_exclusions = sort(get_common_exclusion_vars(cfg, include_analysis_outputs = FALSE)),
       analysis_roles = cfg$analysis[c("id_var", "cluster_var", "strata_var", "weight_var",
                                       "extra_exclude_from_candidates", "transform_time_variables")],
       exposure_definition = cfg$exposure,
       outcome_drop_vars = sort(get_outcome_drop_vars(cfg)),
       causal_governance = cfg$causal_governance,
       mortality_sensitivity = cfg$mortality_sensitivity,
       preprocessing_core = cfg$preprocessing[setdiff(names(cfg$preprocessing),
                                                      c("global_missing_dictionary",
                                                        "variable_source_registry"))])
}

load_wave1_cache <- function(path, cfg) {
  obj <- readRDS(path)
  current_fp <- make_wave1_cache_fingerprint(cfg)
  if (is.list(obj) && !is.null(obj$data) && !is.null(obj$fingerprint)) {
    if (identical(obj$fingerprint, current_fp)) {
      if (isTRUE(cfg$preprocessing$global_missing_dictionary_required %||% TRUE) &&
          (is.null(attr(obj$data, "global_missing_dictionary")) ||
           !length(attr(obj$data, "global_missing_dictionary")))) {
        message("  [cache] Cached Wave 1 merge lacks the frozen missing-code dictionary; rebuilding.")
        return(NULL)
      }
      if (is.null(attr(obj$data, "full_survey_design_frame")) ||
          !is.data.frame(attr(obj$data, "full_survey_design_frame"))) {
        message("  [cache] Cached Wave 1 merge lacks the full survey-design frame; rebuilding.")
        return(NULL)
      }
      registry <- attr(obj$data, "variable_source_registry")
      if (is.null(registry)) {
        message("  [cache] Cached Wave 1 merge lacks the descriptive source registry; rebuilding.")
        return(NULL)
      }
      validate_variable_source_registry(registry, "cached Wave-I source registry")
      return(obj$data)
    }
    msg <- "  [cache] Cached Wave 1 merge fingerprint is stale."
    if (isTRUE(cfg$safety$stop_on_stale_wave1_cache %||% FALSE)) stop(msg, call. = FALSE)
    message(msg, " Rebuilding Wave 1 merge.")
    return(NULL)
  }
  if (isTRUE(cfg$cache$use_wave1_fingerprint %||% TRUE)) {
    message("  [cache] Cached Wave 1 merge lacks fingerprint; rebuilding Wave 1 merge.")
    return(NULL)
  }
  obj
}

save_wave1_cache <- function(w1_all, path, cfg) {
  if (isTRUE(cfg$cache$use_wave1_fingerprint %||% TRUE)) {
    atomic_save_rds(list(data = w1_all, fingerprint = make_wave1_cache_fingerprint(cfg)), path, overwrite = TRUE)
  } else {
    atomic_save_rds(w1_all, path, overwrite = TRUE)
  }
}

make_main_dataset_cache_fingerprint <- function(cfg, w1_all = NULL) {
  list(
    version = cfg$global$version %||% "v8.33_restored_no_mortality_composite_sensitivity",
    script = pipeline_script_fingerprint(
      cfg, strict = isTRUE(cfg$global$require_script_md5 %||% FALSE)),
    outcome_family = cfg$outcome$family,
    # include the ACTIVE family's full config so two runs of the same
    # family with different settings (e.g. a PassThrough negative control with a
    # different source_var) do not silently reuse each other's cached outcome Y.
    outcome_family_config = cfg$outcome$families[[cfg$outcome$family]],
    outcome_wave = cfg$outcome$current_wave %||% cfg$outcome$waves,
    family_member = cfg$outcome$family_member %||% NA_character_,
    exposure_definition = cfg$exposure,
    analysis_scope = cfg$analysis[c("restrict_wave1_depressed", "wave1_depression_cutpoint",
                                    "protected_W_mode", "dsp4_mode", "dsp4_structural_zero_families",
                                    "dsp4_structural_zero_codes", "enable_dsp4_audit")],
    weight_var = cfg$analysis$weight_var,
    cluster_var = cfg$analysis$cluster_var,
    strata_var = cfg$analysis$strata_var,
    exposure_var = cfg$analysis$exposure_var,
    outcome_var = cfg$analysis$outcome_var,
    sample_gates = cfg$analysis[c("enforce_expected_sample_gates",
                                  "enforce_expected_cutpoint_gate",
                                  "enforce_expected_treated_gate",
                                  "expected_complete_cesd_n", "expected_final_n",
                                  "expected_exposure_cutpoint", "expected_treated_n",
                                  "expected_cluster_n", "expected_strata_n")],
    # winsorization changes the stored weight column, so it must be
    # part of the cache identity or a changed quantile would silently reuse
    # a stale dataset.
    weight_winsor_quantile = cfg$analysis$weight_winsor_quantile %||% NA_real_,
    transform_time_variables = isTRUE(cfg$analysis$transform_time_variables),
    auto_military_prison_status = isTRUE(cfg$analysis$auto_military_prison_status),
    weight_winsor_renormalize = isTRUE(cfg$analysis$weight_winsor_renormalize),
    paths = lapply(cfg$paths, file_fingerprint),
    log_transform = cfg$outcome$log_transform,
    compensation_transform = cfg$outcome$compensation_transform,
    compensation_asinh_scale = cfg$outcome$compensation_asinh_scale,
    compensation_exact_only = cfg$outcome$compensation_exact_only,
    continuous_upper_quantile = cfg$outcome$continuous_upper_quantile,
    continuous_cap_weighted = cfg$outcome$continuous_cap_weighted,
    continuous_cap_censoring_adjusted = cfg$outcome$continuous_cap_censoring_adjusted,
    continuous_cap_qrule = cfg$outcome$continuous_cap_qrule,
    mortality_sensitivity = cfg$mortality_sensitivity,
    diagnostic_construction = cfg$diagnostics[c(
      "enable_wave2_completion_diagnostic"
    )],
    causal_governance = cfg$causal_governance,
    common_exclusions = sort(get_common_exclusion_vars(cfg)),
    preprocessing_core = cfg$preprocessing[setdiff(names(cfg$preprocessing),
                                                   c("global_missing_dictionary",
                                                     "variable_source_registry"))],
    global_missing_dictionary_md5 = if (is.null(w1_all)) NA_character_ else
      object_md5(attr(w1_all, "global_missing_dictionary")),
    variable_source_registry_md5 = if (is.null(w1_all)) NA_character_ else
      object_md5(attr(w1_all, "variable_source_registry")),
    n_w1 = if (is.null(w1_all)) NA_integer_ else nrow(w1_all),
    names_w1 = if (is.null(w1_all)) character(0) else names(w1_all)
  )
}

load_main_dataset_cache <- function(path, cfg, w1_all) {
  obj <- readRDS(path)
  current_fp <- make_main_dataset_cache_fingerprint(cfg, w1_all)
  if (is.list(obj) && !is.null(obj$data) && !is.null(obj$fingerprint)) {
    if (identical(obj$fingerprint, current_fp)) {
      if (isTRUE(cfg$preprocessing$global_missing_dictionary_required %||% TRUE) &&
          (is.null(attr(obj$data, "global_missing_dictionary")) ||
           !length(attr(obj$data, "global_missing_dictionary")))) {
        message("  [cache] Cached main dataset lacks the frozen missing-code dictionary; rebuilding.")
        return(NULL)
      }
      if (is.null(attr(obj$data, "survey_design_frame")) ||
          !is.data.frame(attr(obj$data, "survey_design_frame"))) {
        message("  [cache] Cached main dataset lacks the survey-domain design frame; rebuilding.")
        return(NULL)
      }
      registry <- attr(obj$data, "variable_source_registry")
      if (is.null(registry)) {
        message("  [cache] Cached main dataset lacks the descriptive source registry; rebuilding.")
        return(NULL)
      }
      validate_variable_source_registry(registry, "cached main-data source registry")
      if (isTRUE(cfg$diagnostics$enable_wave2_completion_diagnostic %||% TRUE)) {
        completion_status <- attr(obj$data, "wave2_completion_status", exact = TRUE)
        if (is.null(completion_status) || !is.data.frame(completion_status)) {
          message("  [cache] Cached main dataset lacks the Wave-II completion-status frame; rebuilding.")
          return(NULL)
        }
      }
      attr(obj$data, "main_dataset_cache_fingerprint") <- obj$fingerprint
      return(obj$data)
    }
    message("  [cache] Cached main dataset fingerprint is stale; rebuilding main dataset.")
    return(NULL)
  }
  if (isTRUE(cfg$cache$use_main_dataset_fingerprint %||% TRUE)) {
    message("  [cache] Cached main dataset lacks fingerprint; rebuilding main dataset.")
    return(NULL)
  }
  obj
}

save_main_dataset_cache <- function(main_df, path, cfg, w1_all) {
  if (isTRUE(cfg$cache$use_main_dataset_fingerprint %||% TRUE)) {
    fp <- make_main_dataset_cache_fingerprint(cfg, w1_all)
    attr(main_df, "main_dataset_cache_fingerprint") <- fp
    atomic_save_rds(list(data = main_df, fingerprint = fp), path, overwrite = TRUE)
  } else {
    atomic_save_rds(main_df, path, overwrite = TRUE)
  }
}

# Nested data-driven screen run on a final TMLE fold's training rows only.
# This is the reviewer-responsive selection step. It uses marginal rough
# screens only as a broad first pass, applies data-driven redundancy control,
# and optionally runs a nested multivariable elastic-net screen on the rough
# candidate pool. It does NOT force inclusion of exposure-only predictors.

top_score_names <- function(scores, n) {
  s <- scores[is.finite(scores)]
  if (length(s) == 0L || n <= 0L) return(character(0))
  names(sort(s, decreasing = TRUE))[seq_len(min(length(s), n))]
}

top_joint_score_names <- function(exposure_scores, outcome_scores, n) {
  if (n <= 0L) return(character(0))
  common <- intersect(names(exposure_scores), names(outcome_scores))
  common <- common[is.finite(exposure_scores[common]) & is.finite(outcome_scores[common])]
  if (length(common) == 0L) return(character(0))
  rA <- rank(-exposure_scores[common], ties.method = "average")
  rY <- rank(-outcome_scores[common], ties.method = "average")
  joint_rank <- rA + rY
  names(sort(joint_rank, decreasing = FALSE))[seq_len(min(length(joint_rank), n))]
}

strip_missing_suffix <- function(x) sub("(_missA|_miss97)$", "", x)

score_summary_msg <- function(scores) {
  s <- scores[is.finite(scores)]
  if (length(s) == 0L) return("no finite scores")
  sprintf("n=%d, min=%.4f, median=%.4f, max=%.4f",
          length(s), min(s), stats::median(s), max(s))
}

# Build one empirical signature per raw variable for data-driven redundancy
# control. Numeric variables use their imputed standardized value; factor
# variables use the first singular vector of their one-variable dummy matrix.
# This avoids manual grouping while still preventing a single correlated block
# from consuming the rough-screen shortlist.
make_screen_signature_matrix <- function(vars, X_base, impute_method = "median") {
  vars <- unique(vars[vars %in% names(X_base)])
  if (length(vars) == 0L) return(matrix(0, nrow = nrow(X_base), ncol = 0))
  sigs <- list()
  for (nm in vars) {
    Xnm <- tryCatch(build_single_var_screen_df(nm, X_base, impute_method = impute_method),
                    error = function(e) NULL)
    if (is.null(Xnm) || ncol(Xnm) == 0L) next
    M <- suppressWarnings(data.matrix(Xnm))
    M[!is.finite(M)] <- 0
    if (ncol(M) == 1L) {
      v <- M[, 1]
    } else {
      M <- scale(M)
      M[!is.finite(M)] <- 0
      v <- tryCatch({
        sv <- svd(M, nu = 1L, nv = 0L)
        as.numeric(sv$u[, 1L] * sv$d[1L])
      }, error = function(e) rowMeans(M))
    }
    if (!any(is.finite(v)) || stats::sd(v, na.rm = TRUE) <= 1e-12) next
    v <- as.numeric(scale(v))
    v[!is.finite(v)] <- 0
    sigs[[nm]] <- v
  }
  if (length(sigs) == 0L) return(matrix(0, nrow = nrow(X_base), ncol = 0))
  out <- do.call(cbind, sigs)
  colnames(out) <- names(sigs)
  out
}

greedy_redundancy_filter <- function(ranked_vars, X_base, max_vars,
                                     cor_threshold = 0.90,
                                     impute_method = "median",
                                     enable = TRUE) {
  ranked_vars <- unique(ranked_vars[ranked_vars %in% names(X_base)])
  if (length(ranked_vars) == 0L || max_vars <= 0L)
    return(list(selected = character(0), dropped = character(0)))
  if (!isTRUE(enable))
    return(list(selected = ranked_vars[seq_len(min(length(ranked_vars), max_vars))],
                dropped = character(0)))
  sig <- make_screen_signature_matrix(ranked_vars, X_base, impute_method = impute_method)
  selected <- character(0); dropped <- character(0)
  for (v in ranked_vars) {
    if (length(selected) >= max_vars) break
    if (!v %in% colnames(sig)) {
      selected <- c(selected, v)
      next
    }
    sig_selected <- intersect(selected, colnames(sig))
    if (length(sig_selected) == 0L) {
      selected <- c(selected, v)
      next
    }
    cors <- suppressWarnings(abs(stats::cor(sig[, v], sig[, sig_selected, drop = FALSE])))
    cors <- as.numeric(cors)
    if (any(is.finite(cors) & cors >= cor_threshold)) dropped <- c(dropped, v)
    else selected <- c(selected, v)
  }
  list(selected = selected, dropped = dropped)
}

# deterministic correlation-clustering redundancy filter.
# Replaces the greedy keep-first filter. Variables are grouped into clusters by
# their signature correlation structure using hierarchical clustering, which is
# order-independent and seed-independent (the same correlation matrix always
# yields the same clusters). Each cluster is represented by a single
# deterministically-chosen member: the variable whose signature is closest (in
# absolute correlation) to the cluster's SIGN-ALIGNED, standardized mean
# signature. Sign-alignment flips members that are negatively correlated with a
# reference before averaging, so the mean reinforces the shared signal instead
# of cancelling it. This eliminates the seed-dependent "which member survives"
# churn while keeping real variables (no synthetic columns injected downstream).
cluster_redundancy_filter <- function(ranked_vars, X_base, max_vars,
                                      cor_threshold = 0.90,
                                      linkage = "complete",
                                      impute_method = "median",
                                      enable = TRUE) {
  ranked_vars <- unique(ranked_vars[ranked_vars %in% names(X_base)])
  if (length(ranked_vars) == 0L || max_vars <= 0L)
    return(list(selected = character(0), dropped = character(0),
                n_clusters = 0L, n_singletons = 0L))
  if (!isTRUE(enable))
    return(list(selected = ranked_vars[seq_len(min(length(ranked_vars), max_vars))],
                dropped = character(0), n_clusters = NA_integer_, n_singletons = NA_integer_))
  
  sig <- make_screen_signature_matrix(ranked_vars, X_base, impute_method = impute_method)
  has_sig <- colnames(sig)
  # Variables without a usable signature cannot be clustered; pass them through
  # in their original (ranked) order as their own singletons.
  no_sig <- setdiff(ranked_vars, has_sig)
  
  reps <- character(0); dropped <- character(0); n_clusters <- 0L; n_singletons <- 0L
  
  if (length(has_sig) >= 2L) {
    # Correlation distance on |cor| so negatively-correlated (redundant)
    # variables are treated as close. Guard non-finite correlations to distance
    # 1 (treated as unrelated) so clustering never fails on degenerate columns.
    cmat <- suppressWarnings(stats::cor(sig[, has_sig, drop = FALSE]))
    cmat[!is.finite(cmat)] <- 0
    dmat <- 1 - abs(cmat)
    dmat[!is.finite(dmat)] <- 1
    diag(dmat) <- 0
    hc <- stats::hclust(stats::as.dist(dmat), method = linkage)
    # Cut so that members of a cluster are correlated >= cor_threshold. Under
    # complete linkage, cutting at height (1 - cor_threshold) guarantees every
    # pair within a cluster has |cor| >= cor_threshold.
    cut_h <- 1 - cor_threshold
    grp <- stats::cutree(hc, h = cut_h)
    # Process clusters in the order their first (highest-ranked) member appears,
    # so representative selection and the max_vars cap remain deterministic and
    # ranking-respecting at the cluster level.
    first_rank <- tapply(seq_along(has_sig), grp, min)
    cluster_order <- as.integer(names(sort(first_rank)))
    for (g in cluster_order) {
      members <- has_sig[grp == g]
      if (length(members) == 1L) {
        reps <- c(reps, members); n_singletons <- n_singletons + 1L
        next
      }
      n_clusters <- n_clusters + 1L
      S <- sig[, members, drop = FALSE]
      # Sign-align to the first member, then standardized mean.
      ref <- S[, 1L]
      aligned <- S
      for (j in seq_len(ncol(S))) {
        rj <- suppressWarnings(stats::cor(S[, j], ref))
        if (is.finite(rj) && rj < 0) aligned[, j] <- -S[, j]
      }
      mean_sig <- rowMeans(aligned)
      if (stats::sd(mean_sig) <= 1e-12) {
        # Degenerate mean: fall back to the highest-ranked member.
        rep_var <- members[1L]
      } else {
        cors_to_mean <- suppressWarnings(abs(stats::cor(S, mean_sig)))
        cors_to_mean[!is.finite(cors_to_mean)] <- -Inf
        rep_var <- members[which.max(cors_to_mean)]
      }
      reps <- c(reps, rep_var)
      dropped <- c(dropped, setdiff(members, rep_var))
    }
  } else {
    # 0 or 1 signature variable: nothing to cluster among the signatured set.
    reps <- c(reps, has_sig); n_singletons <- n_singletons + length(has_sig)
  }
  
  # Reassemble in the original ranked order (representatives + passthroughs),
  # then apply the max_vars cap deterministically.
  kept_set <- unique(c(reps, no_sig))
  selected <- ranked_vars[ranked_vars %in% kept_set]
  if (length(selected) > max_vars) {
    over <- selected[(max_vars + 1L):length(selected)]
    dropped <- unique(c(dropped, over))
    selected <- selected[seq_len(max_vars)]
  }
  list(selected = selected, dropped = unique(dropped),
       n_clusters = n_clusters, n_singletons = n_singletons)
}

# (Option A): de-duplicate the FULL candidate set by correlation
# clustering BEFORE marginal scoring. This prevents large blocks of mutually
# redundant variables (e.g. ~85 contextual CST/BST codes measuring one spatial
# construct) from consuming most of the top-N ranking slots and crowding out
# structurally distinct weak confounders. Because scoring has not happened yet,
# there is no ranking; clustering uses only the correlation structure
# (deterministic, seed-independent) and the stable column order of X_base for
# tie-breaking. Each cluster collapses to one deterministic representative (the
# member closest to the sign-aligned, standardized cluster mean). Returns the
# representative variable names plus all unclustered singletons. Guarded by a
# size cap: above max_cluster_vars the full O(n^2) correlation/hclust is skipped
# (returns all vars unchanged) to protect runtime/memory.
cluster_dedupe_candidates <- function(vars, X_base,
                                      cor_threshold = 0.90,
                                      linkage = "complete",
                                      impute_method = "median",
                                      max_cluster_vars = 4000L,
                                      enable = TRUE) {
  vars <- unique(vars[vars %in% names(X_base)])
  empty_assign <- data.frame(cluster_id = integer(0), cluster_size = integer(0),
                             representative_variable = character(0), member_variable = character(0),
                             correlation_to_representative = numeric(0), stringsAsFactors = FALSE)
  empty <- list(kept = vars, dropped = character(0),
                n_clusters = 0L, n_singletons = length(vars), skipped = FALSE,
                assignments = empty_assign)
  if (!isTRUE(enable) || length(vars) < 2L) return(empty)
  if (length(vars) > max_cluster_vars) {
    empty$skipped <- TRUE
    return(empty)
  }
  sig <- make_screen_signature_matrix(vars, X_base, impute_method = impute_method)
  has_sig <- colnames(sig)
  no_sig <- setdiff(vars, has_sig)
  if (length(has_sig) < 2L)
    return(list(kept = vars, dropped = character(0),
                n_clusters = 0L, n_singletons = length(vars), skipped = FALSE,
                assignments = empty_assign))
  
  cmat <- suppressWarnings(stats::cor(sig[, has_sig, drop = FALSE]))
  cmat[!is.finite(cmat)] <- 0
  dmat <- 1 - abs(cmat)
  dmat[!is.finite(dmat)] <- 1
  diag(dmat) <- 0
  hc  <- stats::hclust(stats::as.dist(dmat), method = linkage)
  grp <- stats::cutree(hc, h = 1 - cor_threshold)
  
  reps <- character(0); dropped <- character(0); n_clusters <- 0L; n_singletons <- 0L
  assign_rows <- list()   # per-member cluster-assignment diagnostic
  # Deterministic cluster order: by the first (lowest column-index) member, so
  # the result does not depend on anything seed-related.
  first_idx <- tapply(seq_along(has_sig), grp, min)
  for (g in as.integer(names(sort(first_idx)))) {
    members <- has_sig[grp == g]
    if (length(members) == 1L) {
      reps <- c(reps, members); n_singletons <- n_singletons + 1L
      assign_rows[[length(assign_rows) + 1L]] <- data.frame(
        cluster_id = g, cluster_size = 1L, representative_variable = members,
        member_variable = members, correlation_to_representative = 1,
        stringsAsFactors = FALSE)
      next
    }
    n_clusters <- n_clusters + 1L
    S <- sig[, members, drop = FALSE]
    ref <- S[, 1L]
    aligned <- S
    for (j in seq_len(ncol(S))) {
      rj <- suppressWarnings(stats::cor(S[, j], ref))
      if (is.finite(rj) && rj < 0) aligned[, j] <- -S[, j]
    }
    mean_sig <- rowMeans(aligned)
    if (stats::sd(mean_sig) <= 1e-12) {
      rep_var <- members[1L]
    } else {
      cors_to_mean <- suppressWarnings(abs(stats::cor(S, mean_sig)))
      cors_to_mean[!is.finite(cors_to_mean)] <- -Inf
      rep_var <- members[which.max(cors_to_mean)]
    }
    reps <- c(reps, rep_var)
    dropped <- c(dropped, setdiff(members, rep_var))
    # Record each member's correlation to the chosen representative.
    rep_sig <- sig[, rep_var]
    cor_to_rep <- vapply(members, function(mm) {
      cc <- suppressWarnings(stats::cor(sig[, mm], rep_sig))
      if (is.finite(cc)) abs(cc) else NA_real_
    }, numeric(1))
    assign_rows[[length(assign_rows) + 1L]] <- data.frame(
      cluster_id = g, cluster_size = length(members),
      representative_variable = rep_var, member_variable = members,
      correlation_to_representative = as.numeric(cor_to_rep),
      stringsAsFactors = FALSE)
  }
  # Preserve original column order in the kept set for downstream stability.
  kept_set <- unique(c(reps, no_sig))
  kept <- vars[vars %in% kept_set]
  assignments <- if (length(assign_rows)) do.call(rbind, assign_rows) else
    data.frame(cluster_id = integer(0), cluster_size = integer(0),
               representative_variable = character(0), member_variable = character(0),
               correlation_to_representative = numeric(0), stringsAsFactors = FALSE)
  list(kept = kept, dropped = unique(dropped),
       n_clusters = n_clusters, n_singletons = n_singletons, skipped = FALSE,
       assignments = assignments)
}


fit_nested_glmnet_screen <- function(X, y, family, foldid, weights, raw_map, cfg) {
  if (ncol(X) == 0L) return(character(0))
  if (length(y) != nrow(X))
    stop(sprintf("Nested elastic-net outcome length (%d) does not match design rows (%d).",
                 length(y), nrow(X)), call. = FALSE)
  if (length(raw_map) != ncol(X)) {
    stop(sprintf("Elastic-net raw-variable map length (%d) does not match processed columns (%d).",
                 length(raw_map), ncol(X)), call. = FALSE)
  }
  names(raw_map) <- colnames(X)
  y <- as.numeric(y)
  if (any(!is.finite(y)))
    stop("Nested elastic-net screen received a nonfinite outcome.", call. = FALSE)
  if (family == "binomial" && (!all(y %in% c(0, 1)) || length(unique(y)) < 2L))
    return(character(0))
  foldid <- as.integer(foldid)
  if (length(foldid) != nrow(X) || anyNA(foldid) || length(unique(foldid)) < 3L)
    stop("Nested elastic-net tuning requires aligned whole-cluster folds with at least three levels.",
         call. = FALSE)
  if (any(!is.finite(X)))
    stop("Nested elastic-net screen received nonfinite predictors.", call. = FALSE)
  w <- normalize_positive_weights(weights, length(y), "nested elastic-net screen weights")
  X_fit <- X
  pad_added <- FALSE
  if (ncol(X_fit) == 1L) {
    X_fit <- cbind(X_fit, .glmnet_pad = 0)
    pad_added <- TRUE
  }
  cvfit <- tryCatch(
    glmnet::cv.glmnet(
      x = if (requireNamespace("Matrix", quietly = TRUE)) Matrix::Matrix(X_fit, sparse = TRUE) else X_fit,
      y = y, family = family,
      alpha = cfg$final_tmle$lasso_screen_alpha %||% 0.25,
      nlambda = cfg$final_tmle$lasso_screen_nlambda %||% 50L,
      weights = w, foldid = foldid,
      standardize = isTRUE(cfg$learners$glmnet$standardize %||% TRUE),
      maxit = cfg$final_tmle$lasso_screen_glmnet_maxit %||% 100000L),
    error = function(e) e)
  if (inherits(cvfit, "error"))
    stop("Nested elastic-net screen failed: ", conditionMessage(cvfit), call. = FALSE)
  lam <- switch(cfg$final_tmle$lasso_screen_lambda_choice %||% "lambda.min",
                "lambda.1se" = cvfit$lambda.1se,
                "lambda.min" = cvfit$lambda.min,
                cvfit$lambda.min)
  validate_cv_glmnet_fit(cvfit, lam, expected_ncol = ncol(X_fit),
                         label = paste0("nested elastic-net ", family, " screen"))
  beta_all <- as.numeric(stats::coef(cvfit, s = lam))
  if (length(beta_all) != ncol(X_fit) + 1L || any(!is.finite(beta_all)))
    stop("Nested elastic-net screen produced an invalid coefficient vector.", call. = FALSE)
  # The zero-valued pad exists only to satisfy glmnet's one-predictor edge
  # case. It is never eligible for selection and is discarded here.
  beta_fit <- beta_all[-1L]
  beta <- beta_fit[seq_len(ncol(X))]
  if (isTRUE(pad_added) && length(beta_fit) != 2L)
    stop("Nested elastic-net one-predictor padding produced an unexpected coefficient vector.",
         call. = FALSE)
  nz <- which(abs(beta) > 0)
  if (!length(nz)) return(character(0))
  unique(strip_missing_suffix(raw_map[nz]))
}


run_nested_multivar_lasso_after_rough <- function(tr_df, rough_vars, cfg, fold_id,
                                                  A_tr, y_out, outcome_type,
                                                  outcome_obs, delta, cl_tr) {
  # Multivariable union screen fit only on the final fold's
  # training rows. It fits A~W, Y~W, and delta_Y~W, then takes the union.
  # This keeps the procedure data-driven while avoiding a half-blind screen
  # that can drop variables predictive of exposure and weakly/moderately
  # predictive of outcome. The rough screen supplies a diversified candidate
  # pool; A-only variables are not forced directly into final W.
  t0 <- proc.time()[3]
  empty <- list(selected = character(0), selected_a = character(0),
                selected_y = character(0), selected_delta = character(0),
                seconds = 0, n_processed = 0, n_raw_screened = 0)
  rough_vars <- unique(rough_vars[rough_vars %in% names(tr_df)])
  if (length(rough_vars) == 0L) return(empty)
  
  raw_dat <- tr_df[, rough_vars, drop = FALSE]
  miss_rec <- learn_final_missing_recipe(raw_dat, cfg$preprocessing)
  proc <- apply_final_missing_recipe(raw_dat, miss_rec, cfg$preprocessing)
  
  # Allocate the elastic-net screening design before materializing the full
  # matrix. The configured cap is a nonprotected-column budget; H1FS remains
  # mandatory but the total must stay below the genuine hard matrix guard.
  processed_cap <- as.integer(cfg$final_tmle$lasso_screen_max_processed_cols %||% 240L)
  hard_total <- as.integer(cfg$final_tmle$hard_max_processed_columns %||% 450L)
  protected_lasso <- intersect(resolve_protected_W(cfg), rough_vars)
  mandatory_lasso <- intersect(get_mandatory_W(cfg), rough_vars)
  ordered_vars <- c(mandatory_lasso, setdiff(rough_vars, mandatory_lasso))
  support_map <- attr(proc, "numeric_support") %||% list()
  counts <- setNames(integer(length(ordered_vars)), ordered_vars)
  for (v in ordered_vars) {
    cols <- intersect(names(proc), c(v, paste0(v, "_missA"), paste0(v, "_miss97")))
    one <- proc[, cols, drop = FALSE]
    attr(one, "numeric_support") <- support_map[intersect(names(support_map), cols)]
    d1 <- build_grouped_design_train(one, cfg$final_preprocess, cfg$preprocessing,
                                     hard_max_cols = hard_total, A = A_tr,
                                     protected_raw_vars = protected_lasso)
    counts[[v]] <- ncol(d1$X)
  }
  current_vars <- mandatory_lasso
  used_np <- 0L
  for (v in setdiff(ordered_vars, mandatory_lasso)) {
    add <- counts[[v]]
    if (add > 0L && used_np + add <= processed_cap) {
      current_vars <- c(current_vars, v); used_np <- used_np + add
    }
  }
  current_vars <- unique(current_vars)
  if (!length(current_vars)) {
    out <- empty; out$seconds <- proc.time()[3] - t0; return(out)
  }
  expected_total <- sum(counts[current_vars])
  if (expected_total > hard_total)
    stop(sprintf("Elastic-net screening design requires %d columns, above hard total %d.",
                 expected_total, hard_total), call. = FALSE)
  proc_cols <- intersect(names(proc), c(current_vars, paste0(current_vars, "_missA"), paste0(current_vars, "_miss97")))
  proc_cur <- proc[, proc_cols, drop = FALSE]
  attr(proc_cur, "numeric_support") <- support_map[intersect(names(support_map), proc_cols)]
  des <- build_grouped_design_train(proc_cur, cfg$final_preprocess, cfg$preprocessing,
                                    hard_max_cols = hard_total, A = A_tr,
                                    protected_raw_vars = protected_lasso)
  if (ncol(des$X) == 0L) {
    out <- empty; out$seconds <- proc.time()[3] - t0; return(out)
  }
  message(sprintf("    [fold %s elastic-net] design uses %d mandatory (%d protected H1FS) + %d budgeted processed columns (total %d).",
                  as.character(fold_id), sum(counts[mandatory_lasso]),
                  sum(counts[protected_lasso]), used_np, ncol(des$X)))
  
  
  raw_map <- strip_missing_suffix(names(des$recipes)[des$group])
  X <- des$X
  storage.mode(X) <- "double"
  X[!is.finite(X)] <- 0
  K <- cfg$final_tmle$lasso_screen_folds %||% 3L
  wt <- as.numeric(tr_df[[cfg$analysis$weight_var]])
  
  # Exposure screen: included for union screening. It is multivariable and
  # penalized, not a forced marginal A-only inclusion rule.
  selected_a <- character(0)
  if (length(unique(A_tr)) == 2L) {
    fold_a <- do.call(make_cluster_folds_balanced, c(list(
      cluster = cl_tr, A = A_tr, k = K,
      seed = seed_for(cfg, 14000L + ifelse(is.na(fold_id), 0L, fold_id)),
      weights = wt, delta = rep(1L, length(A_tr)),
      balance_on_weights = isTRUE(cfg$final_tmle$internal_fold_balance_on_weights)),
      fold_control_from_cfg(cfg, "internal")))
    selected_a <- fit_nested_glmnet_screen(
      X, A_tr, "binomial", fold_a, wt, raw_map, cfg)
  }
  
  # Outcome screen, fit only among rows with observed outcome.
  selected_y <- character(0)
  keep_y <- outcome_obs & is.finite(y_out)
  if (sum(keep_y) >= max(25L, K + 2L)) {
    yy <- y_out[keep_y]
    fam_y <- if (identical(outcome_type, "binary")) "binomial" else "gaussian"
    if (fam_y != "binomial" || length(unique(yy)) == 2L) {
      fold_y <- do.call(make_cluster_folds_balanced, c(list(
        cluster = cl_tr[keep_y], A = A_tr[keep_y], k = K,
        seed = seed_for(cfg, 15000L + ifelse(is.na(fold_id), 0L, fold_id)),
        weights = wt[keep_y], delta = delta[keep_y],
        balance_on_weights = isTRUE(cfg$final_tmle$internal_fold_balance_on_weights)),
        fold_control_from_cfg(cfg, "internal")))
      selected_y <- fit_nested_glmnet_screen(
        X[keep_y, , drop = FALSE], yy, fam_y, fold_y,
        wt[keep_y], raw_map, cfg)
    }
  }
  
  # Outcome-observation screen. This is included because missing Y is part of
  # the observed-data problem.
  selected_delta <- character(0)
  if (isTRUE(cfg$final_tmle$lasso_screen_include_delta) && length(unique(delta)) == 2L) {
    fold_d <- do.call(make_cluster_folds_balanced, c(list(
      cluster = cl_tr, A = A_tr, k = K,
      seed = seed_for(cfg, 16000L + ifelse(is.na(fold_id), 0L, fold_id)),
      weights = wt, delta = delta,
      balance_on_weights = isTRUE(cfg$final_tmle$internal_fold_balance_on_weights)),
      fold_control_from_cfg(cfg, "internal")))
    selected_delta <- fit_nested_glmnet_screen(
      X, delta, "binomial", fold_d, wt, raw_map, cfg)
  }
  selected <- unique(c(selected_a, selected_y, selected_delta))
  selected <- selected[selected %in% current_vars]
  list(selected = selected, selected_a = selected_a,
       selected_y = selected_y, selected_delta = selected_delta,
       seconds = proc.time()[3] - t0, n_processed = ncol(X),
       n_raw_screened = length(current_vars))
}
run_nested_rough_prescreen_for_final <- function(main_df, train_idx, cfg, fold_id = NA_integer_) {
  t_all <- proc.time()[3]
  tr_df <- main_df[train_idx, , drop = FALSE]
  protected_screen <- intersect(resolve_protected_W(cfg), names(tr_df))
  mandatory_screen <- intersect(get_mandatory_W(cfg), names(tr_df))
  cand <- get_candidate_vars(tr_df, cfg)
  if (length(cand) == 0L)
    stop("Nested rough screen has zero candidate variables.", call. = FALSE)
  prefilter_info <- prefilter_candidate_vars_for_screen(tr_df, cand, cfg, fold_id = fold_id)
  if (isTRUE(cfg$final_tmle$mandatory_W_bypass_screening %||% TRUE) && length(mandatory_screen)) {
    cand <- unique(c(mandatory_screen, prefilter_info$vars))
    hit <- match(mandatory_screen, prefilter_info$log$variable)
    hit <- hit[is.finite(hit)]
    if (length(hit)) {
      prefilter_info$log$prefilter_kept[hit] <- TRUE
      prefilter_info$log$prefilter_reason[hit] <- "mandatory_override"
    }
  } else {
    cand <- prefilter_info$vars
  }
  
  message(sprintf("    [fold %s screen] candidates=%d after prefilter; preprocessing for rough scores...",
                  as.character(fold_id), length(cand)))
  t_prep <- proc.time()[3]
  X_base <- tr_df[, cand, drop = FALSE]
  X_base <- classify_factors_by_uniques(X_base, cfg$preprocessing)
  fac <- names(X_base)[vapply(X_base, is.factor, logical(1))]
  num <- names(X_base)[vapply(X_base, is.numeric, logical(1))]
  X_base <- add_dual_missingness_indicators(X_base, fac, num, cfg$preprocessing)
  X_base <- remove_constant_columns(
    X_base, tol = cfg$preprocessing$constant_variance_tol,
    verbose = isTRUE(cfg$global$verbose))
  message(sprintf("    [fold %s screen] preprocessing done in %.1fs: %d columns after indicators/constants.",
                  as.character(fold_id), proc.time()[3] - t_prep, ncol(X_base)))
  
  # (Option A): cluster the FULL candidate set BEFORE marginal scoring, so
  # large redundant blocks collapse to single representatives before the top-N
  # ranking caps are applied. This stops a block of ~85 mutually-correlated
  # contextual variables from consuming most of the ranking slots and crowding
  # out distinct weak confounders. Deterministic and seed-independent. Only the
  # surviving representatives are scored and ranked below.
  # IMPORTANT: cluster only the SUBSTANTIVE (non-missingness-indicator) columns.
  # add_dual_missingness_indicators can roughly double the column count, which
  # would push the candidate count past cluster_dedupe_max_vars and silently
  # skip clustering. Missingness indicators are derived columns and are not the
  # source of the contextual-block redundancy, so we exclude them from the
  # clustering input (and hence from the size-guard count). When a substantive
  # variable is collapsed into a representative, its own missingness indicators
  # are dropped alongside it; representatives keep their indicators.
  cluster_assignments <- NULL   # returned for the cluster-assignment diagnostic
  if (identical(cfg$final_tmle$redundancy_method %||% "cluster", "cluster") &&
      isTRUE(cfg$final_tmle$rough_redundancy_control)) {
    t_clu <- proc.time()[3]
    all_cols   <- names(X_base)
    is_indic   <- grepl("(_missA|_miss97)$", all_cols)
    subst_cols <- all_cols[!is_indic]
    indic_cols <- all_cols[is_indic]
    clusterable_subst <- setdiff(subst_cols, mandatory_screen)
    dedupe <- cluster_dedupe_candidates(
      clusterable_subst, X_base,
      cor_threshold = cfg$final_tmle$rough_redundancy_cor_threshold %||% 0.90,
      linkage = cfg$final_tmle$redundancy_linkage %||% "complete",
      impute_method = cfg$preprocessing$numeric_imputation,
      max_cluster_vars = cfg$final_tmle$cluster_dedupe_max_vars %||% 6000L,
      enable = TRUE)
    if (isTRUE(dedupe$skipped)) {
      message(sprintf("    [fold %s screen] pre-score clustering SKIPPED: %d substantive candidates exceed cap %d; scoring full set.",
                      as.character(fold_id), length(clusterable_subst),
                      cfg$final_tmle$cluster_dedupe_max_vars %||% 6000L))
    } else {
      # Keep representatives + singletons, plus indicators whose base variable
      # survived. An indicator survives iff its stripped base name is kept.
      kept_base   <- unique(c(mandatory_screen, dedupe$kept))
      keep_indic  <- indic_cols[strip_missing_suffix(indic_cols) %in% kept_base]
      keep_cols   <- all_cols[all_cols %in% c(kept_base, keep_indic)]
      X_base <- X_base[, keep_cols, drop = FALSE]
      if (!is.null(dedupe$assignments) && nrow(dedupe$assignments) > 0L) {
        cluster_assignments <- cbind(
          data.frame(fold = fold_id, stringsAsFactors = FALSE),
          dedupe$assignments)
      }
      message(sprintf("    [fold %s screen] pre-score clustering in %.1fs: %d substantive kept (%d collapsed across %d clusters); %d -> %d total columns.",
                      as.character(fold_id), proc.time()[3] - t_clu,
                      length(kept_base), length(dedupe$dropped), dedupe$n_clusters,
                      length(all_cols), ncol(X_base)))
    }
  }
  
  A_tr <- normalize_binary_var(tr_df[[cfg$analysis$exposure_var]], cfg$analysis$exposure_var)
  outcome_info <- prepare_modeled_outcome(
    tr_df[[cfg$analysis$outcome_var]], cfg$analysis$outcome_type, cfg$analysis$outcome_var)
  y_out <- outcome_info$values
  outcome_type <- outcome_info$type
  if (identical(outcome_type, "continuous")) {
    lo_screen <- cfg$final_tmle$screen_y_lower
    hi_screen <- cfg$final_tmle$screen_y_upper
    if (!is.finite(lo_screen) || !is.finite(hi_screen) || hi_screen <= lo_screen)
      stop("Nested screen is missing valid bounded-outcome limits.", call. = FALSE)
    obs_screen <- is.finite(y_out)
    y_out[obs_screen] <- pmin(pmax(y_out[obs_screen], lo_screen), hi_screen)
  }
  outcome_obs <- outcome_info$observed
  delta <- as.integer(outcome_obs)
  cl_tr <- tr_df[[cfg$analysis$cluster_var]]
  wt_tr <- normalize_positive_weights(
    tr_df[[cfg$analysis$weight_var]], nrow(tr_df), "rough-screen survey weights")
  
  K <- cfg$final_tmle$rough_folds %||% cfg$rough_prescreen$folds %||% 3L
  base_seed <- seed_for(cfg, 12000L + ifelse(is.na(fold_id), 0L, fold_id * 10L))
  fold_A <- make_rough_fold_ids(nrow(tr_df), K, base_seed,
                                cluster_vec = cl_tr, A_vec = A_tr, weights = wt_tr,
                                cluster_aware = TRUE, fold_control = fold_control_from_cfg(cfg, "internal"))
  fold_Y <- make_rough_fold_ids(nrow(tr_df), K, base_seed + 1L,
                                cluster_vec = cl_tr, A_vec = A_tr, delta_vec = delta,
                                weights = wt_tr, cluster_aware = TRUE,
                                fold_control = fold_control_from_cfg(cfg, "internal"))
  fold_D <- make_rough_fold_ids(nrow(tr_df), K, base_seed + 2L,
                                cluster_vec = cl_tr, A_vec = A_tr, delta_vec = delta,
                                weights = wt_tr, cluster_aware = TRUE,
                                fold_control = fold_control_from_cfg(cfg, "internal"))
  K_A <- max(fold_A); K_Y <- max(fold_Y); K_D <- max(fold_D)
  
  # A is scored only to build a joint A/Y ranking. A-only predictors are not
  # force-selected by default.
  t_A <- proc.time()[3]
  exposure_scores <- screen_binom_linear(
    A_tr, X_base, K = K_A, seed = base_seed,
    eps = cfg$rough_prescreen$binomial_eps, fold = fold_A, weights = wt_tr,
    glmnet_maxit = cfg$rough_prescreen$glmnet_maxit %||% 1000000L,
    glmnet_thresh = cfg$rough_prescreen$glmnet_thresh %||% 1e-5,
    ridge_lambda = cfg$rough_prescreen$ridge_lambda %||% 1.0)
  message(sprintf("    [fold %s screen] exposure score pass in %.1fs (%s).",
                  as.character(fold_id), proc.time()[3] - t_A,
                  score_summary_msg(exposure_scores)))
  
  t_Y <- proc.time()[3]
  if (outcome_type == "binary") {
    outcome_scores <- screen_binom_linear(
      y_out[outcome_obs], X_base[outcome_obs, , drop = FALSE],
      K = K_Y, seed = base_seed + 1L,
      eps = cfg$rough_prescreen$binomial_eps,
      fold = fold_Y[outcome_obs], weights = wt_tr[outcome_obs],
      glmnet_maxit = cfg$rough_prescreen$glmnet_maxit %||% 1000000L,
      glmnet_thresh = cfg$rough_prescreen$glmnet_thresh %||% 1e-5,
      ridge_lambda = cfg$rough_prescreen$ridge_lambda %||% 1.0)
  } else {
    outcome_scores <- screen_gauss_linear(
      y_out, X_base, K = K_Y, seed = base_seed + 1L, fold = fold_Y, weights = wt_tr)
  }
  message(sprintf("    [fold %s screen] outcome score pass in %.1fs (%s).",
                  as.character(fold_id), proc.time()[3] - t_Y,
                  score_summary_msg(outcome_scores)))
  
  missing_scores <- setNames(rep(NA_real_, length(exposure_scores)), names(exposure_scores))
  t_D <- proc.time()[3]
  if (length(unique(delta)) == 2L) {
    missing_scores <- screen_binom_linear(
      delta, X_base, K = K_D, seed = base_seed + 2L,
      eps = cfg$rough_prescreen$binomial_eps, fold = fold_D, weights = wt_tr,
      glmnet_maxit = cfg$rough_prescreen$glmnet_maxit %||% 1000000L,
      glmnet_thresh = cfg$rough_prescreen$glmnet_thresh %||% 1e-5,
      ridge_lambda = cfg$rough_prescreen$ridge_lambda %||% 1.0)
    message(sprintf("    [fold %s screen] delta_Y score pass in %.1fs (%s).",
                    as.character(fold_id), proc.time()[3] - t_D,
                    score_summary_msg(missing_scores)))
  } else {
    message(sprintf("    [fold %s screen] delta_Y score pass skipped: no variation in outcome observation.",
                    as.character(fold_id)))
  }
  
  nY  <- cfg$final_tmle$rough_top_n_outcome %||% 100L
  nD  <- cfg$final_tmle$rough_top_n_missingness %||% 40L
  nAY <- cfg$final_tmle$rough_top_n_joint_AY %||% 50L
  nA0 <- cfg$final_tmle$rough_top_n_exposure_only %||% 0L
  nA_lasso <- if (isTRUE(cfg$final_tmle$nested_lasso_after_rough))
    cfg$final_tmle$rough_top_n_exposure_for_lasso %||% 60L else nA0
  vars_Y  <- top_score_names(outcome_scores, nY)
  vars_D  <- top_score_names(missing_scores, nD)
  vars_AY <- top_joint_score_names(exposure_scores, outcome_scores, nAY)
  vars_A_for_lasso <- top_score_names(exposure_scores, nA_lasso)
  vars_A_only <- character(0)
  if (nA0 > 0L) {
    a_ranked <- top_score_names(exposure_scores, nA0 + length(vars_Y) + length(vars_D) + length(vars_AY))
    vars_A_only <- setdiff(a_ranked, unique(c(vars_Y, vars_D, vars_AY)))
    vars_A_only <- vars_A_only[seq_len(min(length(vars_A_only), nA0))]
  }
  
  # Final-eligible rough variables exclude exposure-only LASSO candidates.
  # Those candidates are available to the nested A~W elastic-net, but can enter
  # final W only if selected by that multivariable model or by another permitted
  # outcome/joint/missingness pathway.
  final_ranked_pool <- unique(c(mandatory_screen, vars_AY, vars_Y, vars_D, vars_A_only))
  final_ranked_pool <- final_ranked_pool[final_ranked_pool %in% names(X_base)]
  lasso_candidate_pool <- unique(c(final_ranked_pool, vars_A_for_lasso))
  lasso_candidate_pool <- lasso_candidate_pool[lasso_candidate_pool %in% names(X_base)]
  ranked_pool <- final_ranked_pool
  pool_cap <- cfg$final_tmle$rough_candidate_pool_max %||% 175L
  if (identical(cfg$final_tmle$redundancy_method %||% "cluster", "cluster")) {
    # Redundancy was already removed by pre-score clustering of the full
    # candidate set, so X_base (and hence ranked_pool) contains only cluster
    # representatives. Here we only apply the size cap; no second clustering.
    # Define `red`/`red_frac` from the pre-score dedupe result so the downstream
    # selection-audit table (which references red$dropped and red_frac) is
    # populated correctly. Guard for the case where clustering was skipped or
    # disabled, in which case nothing was dropped as redundant.
    pre_dropped <- if (exists("dedupe") && is.list(dedupe))
      dedupe$dropped %||% character(0) else character(0)
    pre_kept <- if (exists("dedupe") && is.list(dedupe))
      dedupe$kept %||% character(0) else character(0)
    pre_assignments <- if (exists("dedupe") && is.list(dedupe))
      dedupe$assignments %||% data.frame() else data.frame()
    red <- list(dropped = pre_dropped, assignments = pre_assignments)
    red_denom <- length(unique(c(pre_kept, pre_dropped)))
    red_frac <- if (red_denom > 0L) length(unique(pre_dropped)) / red_denom else NA_real_
    n_pre_cap <- length(ranked_pool)
    nonprotected_ranked <- setdiff(ranked_pool, mandatory_screen)
    rough_pool <- unique(c(mandatory_screen,
                           nonprotected_ranked[seq_len(min(length(nonprotected_ranked), pool_cap))]))
    message(sprintf("    [fold %s screen] ranked pool (already de-duplicated pre-score): %d -> %d after size cap %d; %d collapsed pre-score.",
                    as.character(fold_id), n_pre_cap, length(rough_pool), pool_cap, length(red$dropped)))
  } else {
    red <- greedy_redundancy_filter(
      setdiff(ranked_pool, mandatory_screen), X_base,
      max_vars = pool_cap,
      cor_threshold = cfg$final_tmle$rough_redundancy_cor_threshold %||% 0.80,
      impute_method = cfg$preprocessing$numeric_imputation,
      enable = isTRUE(cfg$final_tmle$rough_redundancy_control))
    red$assignments <- data.frame()
    rough_pool <- unique(c(mandatory_screen, red$selected))
    red_denom <- length(rough_pool) + length(red$dropped)
    red_frac <- if (red_denom > 0L) length(red$dropped) / red_denom else NA_real_
    message(sprintf("    [fold %s screen] rough pool after redundancy: %d kept, %d dropped as redundant (%.1f%%).",
                    as.character(fold_id), length(rough_pool), length(red$dropped), 100 * red_frac))
    if (is.finite(red_frac) && red_frac < 0.10 && isTRUE(cfg$final_tmle$rough_redundancy_control))
      warning(sprintf("Fold %s redundancy filter dropped only %.1f%% of pool variables; threshold may be too loose.",
                      as.character(fold_id), 100 * red_frac))
    if (is.finite(red_frac) && red_frac > 0.70 && isTRUE(cfg$final_tmle$rough_redundancy_control))
      warning(sprintf("Fold %s redundancy filter dropped %.1f%% of pool variables; threshold may be too tight.",
                      as.character(fold_id), 100 * red_frac))
  }
  
  lasso_info <- list(selected = character(0), selected_a = character(0),
                     selected_y = character(0), selected_delta = character(0),
                     seconds = 0, n_processed = 0, n_raw_screened = 0)
  if (isTRUE(cfg$final_tmle$nested_lasso_after_rough)) {
    lasso_info <- run_nested_multivar_lasso_after_rough(
      tr_df = tr_df, rough_vars = unique(c(rough_pool, lasso_candidate_pool)), cfg = cfg, fold_id = fold_id,
      A_tr = A_tr, y_out = y_out, outcome_type = outcome_type,
      outcome_obs = outcome_obs, delta = delta, cl_tr = cl_tr)
    message(sprintf("    [fold %s screen] nested multivariable elastic-net union in %.1fs: raw=%d, processed=%d, selected A=%d, Y=%d, delta=%d, union=%d.",
                    as.character(fold_id), lasso_info$seconds,
                    lasso_info$n_raw_screened, lasso_info$n_processed,
                    length(lasso_info$selected_a), length(lasso_info$selected_y),
                    length(lasso_info$selected_delta), length(lasso_info$selected)))
  }
  
  # Final selected variables: nested LASSO augments the diversified
  # rough pool; it never acts as a brittle hard bottleneck. This avoids
  # pathological runs where glmnet convergence/separation leaves only a few
  # variables and the final TMLE becomes underadjusted.
  # Nested LASSO is an augmenting multivariable union screen, not a
  # replacement gate. The diversified rough pool stays eligible so that
  # convergence issues or rare-event folds cannot collapse the final W set
  # to a handful of variables.
  selected <- unique(c(mandatory_screen, lasso_info$selected, rough_pool))
  
  min_total <- cfg$final_tmle$rough_min_total_vars %||% 1L
  min_lasso_augmented <- if (isTRUE(cfg$final_tmle$nested_lasso_after_rough))
    cfg$final_tmle$lasso_screen_min_vars %||% 30L else min_total
  target_min <- max(min_total, min_lasso_augmented)
  
  if (length(selected) < target_min) {
    add_pool <- setdiff(final_ranked_pool, selected)
    add_needed <- target_min - length(selected)
    selected <- unique(c(selected, add_pool[seq_len(min(add_needed, length(add_pool)))]))
  }
  
  max_lasso <- if (isTRUE(cfg$final_tmle$nested_lasso_after_rough))
    cfg$final_tmle$lasso_screen_max_vars %||% cfg$final_tmle$rough_max_total_vars else
      cfg$final_tmle$rough_max_total_vars
  max_total <- min(cfg$final_tmle$rough_max_total_vars %||% 90L, max_lasso %||% 90L)
  nonprotected_selected <- setdiff(selected, mandatory_screen)
  if (length(nonprotected_selected) > max_total) {
    # Protected H1FS items are cap-exempt. Among all other variables, preserve
    # joint A-and-Y evidence before outcome-only precision variables.
    both_ay_sel <- nonprotected_selected %in% intersect(lasso_info$selected_a, lasso_info$selected_y)
    priority <- ifelse(both_ay_sel, 1L,
                       ifelse(nonprotected_selected %in% vars_AY, 2L,
                              ifelse(nonprotected_selected %in% lasso_info$selected_y, 3L,
                                     ifelse(nonprotected_selected %in% lasso_info$selected_delta, 4L,
                                            ifelse(nonprotected_selected %in% vars_Y, 5L,
                                                   ifelse(nonprotected_selected %in% vars_D, 6L,
                                                          ifelse(nonprotected_selected %in% lasso_info$selected_a, 7L, 8L)))))))
    best_score <- pmax(outcome_scores[nonprotected_selected], missing_scores[nonprotected_selected],
                       exposure_scores[nonprotected_selected], na.rm = TRUE)
    best_score[!is.finite(best_score)] <- -Inf
    nonprotected_selected <- nonprotected_selected[order(priority, -best_score)]
    nonprotected_selected <- nonprotected_selected[seq_len(max_total)]
  }
  selected <- unique(c(mandatory_screen, nonprotected_selected))
  
  a_candidate_only <- setdiff(
    vars_A_for_lasso,
    unique(c(mandatory_screen, vars_AY, vars_Y, vars_D, vars_A_only)))
  illegal_a_only <- setdiff(intersect(selected, a_candidate_only), lasso_info$selected)
  if (length(illegal_a_only))
    stop("Exposure-only LASSO candidate(s) entered final W without an allowed selection pathway: ",
         paste(illegal_a_only, collapse = ", "), call. = FALSE)
  
  selected <- unique(selected[selected %in% names(tr_df)])
  if (length(lasso_info$selected) < min_lasso_augmented && isTRUE(cfg$final_tmle$nested_lasso_after_rough)) {
    warning(sprintf("Fold %s nested elastic-net selected only %d variables (< %d); using augmented rough-pool fallback.",
                    as.character(fold_id), length(lasso_info$selected), min_lasso_augmented))
  }
  if (length(selected) < min_total) {
    warning(sprintf("Fold %s final nested screen selected only %d variables (< %d).",
                    as.character(fold_id), length(selected), min_total))
  }
  if (length(selected) == 0L)
    stop("Nested screen selected zero variables.", call. = FALSE)
  
  audit_vars <- unique(c(mandatory_screen, names(exposure_scores),
                         names(outcome_scores), names(missing_scores), red$dropped))
  redundancy_map <- if (is.data.frame(red$assignments) && nrow(red$assignments) > 0L) {
    red$assignments[!duplicated(red$assignments$member_variable), , drop = FALSE]
  } else data.frame()
  red_match <- if (nrow(redundancy_map))
    match(audit_vars, redundancy_map$member_variable) else rep(NA_integer_, length(audit_vars))
  sel_tab <- data.frame(
    fold = fold_id,
    variable = audit_vars,
    exposure_score = as.numeric(exposure_scores[audit_vars]),
    outcome_score = as.numeric(outcome_scores[audit_vars]),
    delta_score = as.numeric(missing_scores[audit_vars]),
    in_rough_pool = audit_vars %in% rough_pool,
    in_lasso_candidate_pool = audit_vars %in% lasso_candidate_pool,
    dropped_redundant = audit_vars %in% red$dropped,
    redundancy_drop_fraction = red_frac,
    redundancy_cluster_id = if (nrow(redundancy_map))
      as.integer(redundancy_map$cluster_id[red_match]) else NA_integer_,
    redundancy_cluster_size = if (nrow(redundancy_map))
      as.integer(redundancy_map$cluster_size[red_match]) else NA_integer_,
    redundancy_representative = if (nrow(redundancy_map))
      as.character(redundancy_map$representative_variable[red_match]) else NA_character_,
    redundancy_correlation_to_representative = if (nrow(redundancy_map))
      as.numeric(redundancy_map$correlation_to_representative[red_match]) else NA_real_,
    selected = audit_vars %in% selected,
    selected_by_joint_AY = audit_vars %in% vars_AY,
    selected_by_outcome = audit_vars %in% vars_Y,
    selected_by_delta = audit_vars %in% vars_D,
    selected_by_exposure_candidate_for_lasso = audit_vars %in% vars_A_for_lasso,
    selected_by_exposure_only = audit_vars %in% vars_A_only,
    selected_by_lasso_A = audit_vars %in% lasso_info$selected_a,
    selected_by_lasso_Y = audit_vars %in% lasso_info$selected_y,
    selected_by_lasso_delta = audit_vars %in% lasso_info$selected_delta,
    protected_fixed = audit_vars %in% protected_screen,
    mandatory_fixed = audit_vars %in% mandatory_screen,
    stringsAsFactors = FALSE)
  if (exists("prefilter_info") && !is.null(prefilter_info$log)) {
    sel_tab <- merge(sel_tab, prefilter_info$log, by = c("fold", "variable"),
                     all.x = TRUE, sort = FALSE)
    dropped_pf <- prefilter_info$log[!prefilter_info$log$prefilter_kept, , drop = FALSE]
    if (nrow(dropped_pf) > 0L) {
      dropped_rows <- data.frame(
        fold = dropped_pf$fold, variable = dropped_pf$variable,
        exposure_score = NA_real_, outcome_score = NA_real_, delta_score = NA_real_,
        in_rough_pool = FALSE, in_lasso_candidate_pool = FALSE, dropped_redundant = FALSE, redundancy_drop_fraction = red_frac,
        selected = FALSE, selected_by_joint_AY = FALSE, selected_by_outcome = FALSE,
        selected_by_delta = FALSE, selected_by_exposure_candidate_for_lasso = FALSE,
        selected_by_exposure_only = FALSE, selected_by_lasso_A = FALSE,
        selected_by_lasso_Y = FALSE, selected_by_lasso_delta = FALSE,
        protected_fixed = dropped_pf$variable %in% protected_screen,
        mandatory_fixed = dropped_pf$variable %in% mandatory_screen,
        stringsAsFactors = FALSE)
      dropped_rows <- merge(dropped_rows, dropped_pf, by = c("fold", "variable"),
                            all.x = TRUE, sort = FALSE)
      missing_cols <- setdiff(names(sel_tab), names(dropped_rows))
      for (cc in missing_cols) dropped_rows[[cc]] <- NA
      missing_cols2 <- setdiff(names(dropped_rows), names(sel_tab))
      for (cc in missing_cols2) sel_tab[[cc]] <- NA
      sel_tab <- rbind(sel_tab, dropped_rows[, names(sel_tab), drop = FALSE])
    }
  }
  sel_tab <- sel_tab[order(!sel_tab$selected,
                           !sel_tab$in_rough_pool,
                           -pmax(sel_tab$outcome_score, sel_tab$delta_score,
                                 sel_tab$exposure_score, na.rm = TRUE)), , drop = FALSE]
  
  message(sprintf(paste0(
    "    [fold %s screen] final selected=%d (rough_pool=%d, ",
    "jointAY=%d, Y=%d, delta=%d, A_candidates=%d, A_only=%d, lasso=%s) in %.1fs."),
    as.character(fold_id), length(selected), length(rough_pool),
    length(vars_AY), length(vars_Y), length(vars_D), length(vars_A_for_lasso), length(vars_A_only),
    ifelse(isTRUE(cfg$final_tmle$nested_lasso_after_rough), "on", "off"),
    proc.time()[3] - t_all))
  # annotate cluster assignments with final-selection status so the
  # diagnostic shows whether each cluster's representative (and thus the cluster)
  # survived into the final selected confounder set.
  if (!is.null(cluster_assignments) && nrow(cluster_assignments) > 0L) {
    cluster_assignments$selected_member <- cluster_assignments$member_variable %in% selected
    cluster_assignments$selected_representative <-
      cluster_assignments$representative_variable %in% selected
  }
  list(selected_vars = selected, selection_table = sel_tab,
       cluster_assignments = cluster_assignments)
}

# Checkpoint fingerprinting ----------------------------------------------------
compact_fingerprint <- function(x) {
  paste(utils::capture.output(str(x, max.level = 3, give.attr = FALSE)), collapse = "\n")
}

object_md5 <- function(x) {
  tf <- tempfile("fingerprint_", fileext = ".rds")
  on.exit(unlink(tf), add = TRUE)
  saveRDS(x, tf, version = 2)
  unname(tools::md5sum(tf))
}

make_fold_checkpoint_fingerprint <- function(cfg, main_df, data_pack, outer_fold, fold_id) {
  cfg_pre <- cfg$preprocessing
  dict <- cfg_pre$global_missing_dictionary
  cfg_pre$global_missing_dictionary <- NULL
  list(
    pipeline_version = cfg$global$version,
    script = pipeline_script_fingerprint(
      cfg, strict = isTRUE(cfg$global$require_script_md5 %||% FALSE)),
    run_tag = build_run_tag(cfg), fold_id = fold_id,
    ids = as.character(main_df[[cfg$analysis$id_var]]),
    clusters = as.character(data_pack$cluster),
    outer_fold = as.integer(outer_fold), exposure = as.integer(data_pack$A),
    delta_Y = as.integer(data_pack$delta_Y),
    weights = round(as.numeric(data_pack$weights), 8),
    Y_raw_md5 = object_md5(round(as.numeric(data_pack$Y_raw), 8)),
    Y_bounded_md5 = object_md5(round(as.numeric(data_pack$Y_bounded_orig), 8)),
    candidate_data_md5 = object_md5(main_df[, get_candidate_vars(main_df, cfg), drop = FALSE]),
    global_missing_dictionary_md5 = object_md5(dict),
    source_files = lapply(cfg$paths, file_fingerprint),
    y_lower = data_pack$y_lower, y_upper = data_pack$y_upper,
    final_tmle = cfg$final_tmle, final_preprocess = cfg$final_preprocess,
    learners = cfg$learners, preprocessing = cfg_pre,
    causal_governance = cfg$causal_governance,
    mortality_sensitivity = cfg$mortality_sensitivity,
    policy = cfg$policy,
    analysis = cfg$analysis,
    outcome = cfg$outcome,
    eligibility_md5 = object_md5(resolve_composite_observation(main_df,cfg)),
    persist_diagnostic_W_design = isTRUE(cfg$diagnostics$persist_diagnostic_W_design),
    software_runtime = cfg$provenance$runtime %||% runtime_provenance(),
    safety = strip_runtime_config_state(cfg,analysis_only=TRUE)$safety)
}

# Cluster-aware validRows for SuperLearner's internal CV. For each internal
# fold, the validation rows are whole clusters. This lets SuperLearner choose
# its meta-weights using held-out clusters, matching the outer-fold scheme.
build_cluster_valid_rows <- function(cluster_vec, A_vec, V, seed, weights = NULL,
                                     delta = NULL, balance_on_weights = FALSE,
                                     fold_control = NULL) {
  ctl <- fold_control %||% list()
  fold_ids <- do.call(make_cluster_folds_balanced, c(list(
    cluster = cluster_vec, A = A_vec, k = V, seed = seed,
    weights = weights, delta = delta,
    balance_on_weights = balance_on_weights), ctl))
  lapply(seq_len(max(fold_ids)), function(v) which(fold_ids == v))
}

make_internal_fold_support <- function(validRows, A_vec, delta_vec = NULL, weights = NULL,
                                       label = "", outer_fold = NA_integer_) {
  if (is.null(delta_vec)) delta_vec <- rep(1L, length(A_vec))
  if (is.null(weights)) weights <- rep(1, length(A_vec))
  do.call(rbind, lapply(seq_along(validRows), function(j) {
    ix <- validRows[[j]]
    cc <- internal_fold_cell_counts(ix, as.integer(A_vec), as.integer(delta_vec), as.numeric(weights))
    data.frame(
      outer_fold = outer_fold, nuisance = label, internal_fold = j,
      n = length(ix), treated = sum(A_vec[ix] == 1L),
      observed = sum(delta_vec[ix] == 1L),
      observed_treated = sum(A_vec[ix] == 1L & delta_vec[ix] == 1L),
      ess = kish_ess_safe(weights[ix]),
      ess_treated = kish_ess_safe(weights[ix][A_vec[ix] == 1L]),
      as.data.frame(cc, check.names = FALSE), stringsAsFactors = FALSE)
  }))
}


solve_target_score <- function(offset, H, Y, w, score_tol = 1e-10,
                               max_expand = 60L, label = "targeting") {
  offset <- as.numeric(offset); H <- as.numeric(H); Y <- as.numeric(Y); w <- as.numeric(w)
  ok <- is.finite(offset) & is.finite(H) & is.finite(Y) & is.finite(w) & w > 0
  if (!all(ok))
    stop(sprintf("%s: %d invalid targeting row(s); nuisance predictions or weights are not admissible.",
                 label, sum(!ok)), call. = FALSE)
  if (length(Y) < 2L || !any(abs(H) > 0))
    stop(label, ": insufficient nonzero clever-covariate support.", call. = FALSE)
  score <- function(eps) sum(w * H * (Y - stats::plogis(offset + eps * H)))
  denom <- max(1, sum(w * abs(H)))
  normalized <- function(eps) abs(score(eps)) / denom
  if (normalized(0) <= score_tol)
    return(list(epsilon = 0, normalized_score = normalized(0), iterations = 0L))
  lo <- -1; hi <- 1; s_lo <- score(lo); s_hi <- score(hi)
  j <- 0L
  while ((!is.finite(s_lo) || !is.finite(s_hi) || s_lo * s_hi > 0) && j < max_expand) {
    lo <- lo * 2; hi <- hi * 2
    s_lo <- score(lo); s_hi <- score(hi); j <- j + 1L
  }
  if (!is.finite(s_lo) || !is.finite(s_hi) || s_lo * s_hi > 0)
    stop(label, ": could not bracket the targeting-score root; inspect positivity and clever-covariate extremes.", call. = FALSE)
  ans <- stats::uniroot(score, interval = c(lo, hi), tol = 1e-12, maxiter = 1000L)
  nscore <- normalized(ans$root)
  if (!is.finite(nscore) || nscore > score_tol)
    stop(sprintf("%s: normalized targeting score %.3e exceeds tolerance %.3e.",
                 label, nscore, score_tol), call. = FALSE)
  list(epsilon = ans$root, normalized_score = nscore,
       iterations = ans$iter %||% NA_integer_)
}

cluster_inference_from_eif <- function(
    D, weights, cluster, estimate, strata = NULL,
    design_frame = NULL, domain_ids = NULL,
    id_var = NULL, cluster_var = NULL, strata_var = NULL, weight_var = NULL) {
  D <- as.numeric(D); weights <- as.numeric(weights); cluster <- as.character(cluster)
  if (length(D) != length(weights) || length(D) != length(cluster) ||
      any(!is.finite(D)) || any(!is.finite(weights)) || any(weights <= 0) || anyNA(cluster))
    stop("cluster_inference_from_eif received invalid analytic-sample vectors.", call. = FALSE)
  w_norm <- weights / mean(weights)
  cl <- tapply(w_norm * D, cluster, sum)
  J <- length(cl); n <- length(D)
  if (J < 2L) stop("Cluster inference requires at least two PSUs.", call. = FALSE)
  fsc <- J / (J - 1L)
  se_cluster <- sqrt(fsc * sum(cl^2) / n^2)
  df_cluster <- J - 1L
  crit_cluster <- stats::qt(0.975, df_cluster)
  stat_cluster <- if (se_cluster > 0) estimate / se_cluster else NA_real_
  p_cluster <- if (is.finite(stat_cluster)) 2 * stats::pt(-abs(stat_cluster), df_cluster) else NA_real_
  
  s2 <- sum(cl^2); s4 <- sum(cl^4)
  Gstar <- if (is.finite(s4) && s4 > 0) (s2^2) / s4 else NA_real_
  
  use_full_domain_design <- !is.null(design_frame)
  if (use_full_domain_design) {
    required_names <- c(id_var, cluster_var, strata_var, weight_var, ".analysis_domain")
    if (any(vapply(required_names, function(z) is.null(z) || length(z) != 1L || is.na(z) || !nzchar(z), logical(1))))
      stop("Full-domain survey inference requires nonempty design-field names.", call. = FALSE)
    assert_required_columns(design_frame, required_names, "full survey-design frame")
    if (is.null(domain_ids) || length(domain_ids) != length(D))
      stop("Full-domain survey inference requires one domain respondent ID per EIF value.", call. = FALSE)
    design_ids <- as.character(design_frame[[id_var]])
    domain_ids <- as.character(domain_ids)
    if (anyNA(design_ids) || anyDuplicated(design_ids) || anyNA(domain_ids) || anyDuplicated(domain_ids))
      stop("Full-domain survey inference requires complete unique respondent IDs.", call. = FALSE)
    idx <- match(domain_ids, design_ids)
    if (anyNA(idx))
      stop("At least one analytic respondent is absent from the full survey-design frame.", call. = FALSE)
    domain_flag <- as.logical(design_frame$.analysis_domain)
    if (anyNA(domain_flag) || sum(domain_flag) != length(D) || any(!domain_flag[idx]))
      stop("Full survey-design domain indicator is inconsistent with the analytic EIF rows.", call. = FALSE)
    design_weights <- suppressWarnings(as.numeric(design_frame[[weight_var]]))
    if (any(!is.finite(design_weights)) || any(design_weights <= 0))
      stop("Full survey-design frame contains invalid sampling weights.", call. = FALSE)
    if (!isTRUE(all.equal(design_weights[idx], weights, tolerance = 1e-10)))
      stop("Analytic EIF weights differ from their full survey-design-frame weights.", call. = FALSE)
    design_psu <- trimws(as.character(design_frame[[cluster_var]]))
    design_strata <- trimws(as.character(design_frame[[strata_var]]))
    analytic_psu <- trimws(as.character(cluster))
    if (is.null(strata) || length(strata) != length(D))
      stop("Full-domain survey inference requires an analytic strata vector aligned with the EIF.", call. = FALSE)
    analytic_strata <- trimws(as.character(strata))
    if (anyNA(design_frame[[cluster_var]]) || any(!nzchar(design_psu)) ||
        anyNA(design_frame[[strata_var]]) || any(!nzchar(design_strata)))
      stop("Full survey-design frame contains missing PSU or stratum values.", call. = FALSE)
    if (anyNA(cluster) || any(!nzchar(analytic_psu)) ||
        anyNA(strata) || any(!nzchar(analytic_strata)))
      stop("Analytic EIF rows contain missing PSU or stratum values.", call. = FALSE)
    if (length(analytic_psu) != length(idx) || any(design_psu[idx] != analytic_psu))
      stop("Analytic PSU values differ from their full survey-design-frame values.", call. = FALSE)
    if (length(analytic_strata) != length(idx) || any(design_strata[idx] != analytic_strata))
      stop("Analytic stratum values differ from their full survey-design-frame values.", call. = FALSE)
    psu_strata_n <- tapply(design_strata, design_psu, function(z) length(unique(z)))
    if (any(psu_strata_n != 1L))
      stop("A PSU maps to multiple strata in the full survey-design frame.", call. = FALSE)
    psu_per_stratum <- tapply(design_psu, design_strata, function(z) length(unique(z)))
    if (any(psu_per_stratum < 2L))
      stop("A full-design stratum contains fewer than two sampled PSUs.", call. = FALSE)
    
    dat <- data.frame(
      eif = 0,
      w = design_weights,
      psu = factor(design_psu),
      stratum = factor(design_strata),
      domain = domain_flag,
      stringsAsFactors = FALSE)
    dat$eif[idx] <- D
    des_full <- survey::svydesign(
      ids = ~psu, strata = ~stratum, weights = ~w,
      data = dat, nest = TRUE)
    des_domain <- subset(des_full, domain)
    est0 <- survey::svymean(~eif, design = des_domain, na.rm = FALSE)
    se <- sqrt(as.numeric(stats::vcov(est0)[1L, 1L]))
    df <- survey::degf(des_domain)
    if (!is.finite(df) || df < 1L)
      stop("Survey-domain design degrees of freedom are invalid.", call. = FALSE)
    crit <- stats::qt(0.975, df)
    statistic <- if (is.finite(se) && se > 0) estimate / se else NA_real_
    p <- if (is.finite(statistic)) 2 * stats::pt(-abs(statistic), df) else NA_real_
    method <- sprintf(
      "%s-weighted %s-stratified %s-clustered with-replacement EIF variance using the complete valid-weight Wave-I design and analytic-domain subpopulation",
      weight_var, strata_var, cluster_var)
    n_design <- nrow(design_frame)
    n_domain <- sum(domain_flag)
    J_design <- length(unique(design_psu))
    H_design <- length(unique(design_strata))
  } else if (!is.null(strata)) {
    strata <- as.character(strata)
    if (length(strata) != length(D) || anyNA(strata))
      stop("Design-stratified inference requires a complete strata vector aligned with the EIF.", call. = FALSE)
    psu_per_stratum <- tapply(cluster, strata, function(z) length(unique(z)))
    if (any(psu_per_stratum < 2L))
      stop("Design-stratified inference found a stratum with fewer than two sampled PSUs.", call. = FALSE)
    dat <- data.frame(eif = D, w = weights, psu = factor(cluster), stratum = factor(strata))
    des <- survey::svydesign(ids = ~psu, strata = ~stratum, weights = ~w,
                             data = dat, nest = TRUE)
    est0 <- survey::svymean(~eif, design = des, na.rm = FALSE)
    se <- sqrt(as.numeric(stats::vcov(est0)[1L, 1L]))
    df <- survey::degf(des)
    if (!is.finite(df) || df < 1L) stop("Survey design degrees of freedom are invalid.", call. = FALSE)
    crit <- stats::qt(0.975, df)
    statistic <- if (is.finite(se) && se > 0) estimate / se else NA_real_
    p <- if (is.finite(statistic)) 2 * stats::pt(-abs(statistic), df) else NA_real_
    method <- sprintf("%s-weighted %s-stratified %s-clustered with-replacement EIF variance on the analytic subset",
                      weight_var %||% "sampling-weight", strata_var %||% "stratum",
                      cluster_var %||% "PSU")
    n_design <- n; n_domain <- n; J_design <- J; H_design <- length(unique(strata))
  } else {
    se <- se_cluster; df <- df_cluster; crit <- crit_cluster
    statistic <- stat_cluster; p <- p_cluster
    method <- sprintf("%s-weighted %s-cluster EIF variance (%s unavailable)",
                      weight_var %||% "sampling-weight", cluster_var %||% "PSU",
                      strata_var %||% "strata")
    n_design <- n; n_domain <- n; J_design <- J; H_design <- NA_integer_
  }
  list(se = se, ci = estimate + c(-1, 1) * crit * se, statistic = statistic,
       reference_distribution = "t", p = p, cluster_eic = cl, J = J, fsc = fsc,
       Gstar = Gstar, df = df, method = method,
       design_n = n_design, domain_n = n_domain,
       design_psu_n = J_design, design_strata_n = H_design,
       se_cluster_only = se_cluster,
       ci_cluster_only = estimate + c(-1, 1) * crit_cluster * se_cluster,
       p_cluster_only = p_cluster, df_cluster_only = df_cluster)
}


# Sequential observation model for a fixed-cohort composite Z = S*H.
# S=0 denotes a documented structural zero. S=1 is the remaining cohort,
# including unknown status; response ignorability is assumed within S=1. Adult S is
# never a baseline propensity-score covariate or a restriction of the ATT.
resolve_composite_observation <- function(df, cfg) {
  cfg$analysis$dsp4_mode <- resolve_status_mode(cfg)
  n <- nrow(df); S <- rep(1L, n); source <- rep("interview_reported", n)
  y <- as.numeric(df[[cfg$analysis$outcome_var]])
  source[!is.finite(y)] <- "outcome_missing"
  mc <- if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
    resolve_mortality_spec(cfg, cfg$outcome$current_wave) else NULL
  if (!is.null(mc) && isTRUE(mc$enabled) && isTRUE(mc$composite_zero_at_death)) {
    dv <- mc$death_before_outcome_var
    assert_required_columns(df, dv, "sequential mortality observation model")
    death <- as.integer(df[[dv]])
    if (anyNA(death) || any(!death %in% 0:1))
      stop("Sequential mortality adjustment requires known dated mortality status for every analytic row.", call.=FALSE)
    S[death == 1L] <- 0L; source[death == 1L] <- "mortality_composite_zero"
  }
  if (identical(cfg$analysis$dsp4_mode, "composite")) {
    assert_required_columns(df, c(".labor_status_zero", ".labor_status_verified", ".labor_status_reason"),
                            "sequential civilian composite")
    # S distinguishes documented structural zeros from the remaining cohort.
    # It does not assert civilian eligibility for participants with unknown status.
    # Unresolved nonzero outcomes remain missing and enter the response model.
    if (any(df$.labor_status_zero & !df$.labor_status_verified) ||
        any(S == 1L & !df$.labor_status_verified & is.finite(y) & y != 0))
      stop("Unverified status cannot create a zero or an observed nonzero outcome.", call.=FALSE)
    zero <- df$.labor_status_zero & S == 1L
    S[zero] <- 0L; source[zero] <- paste0("verified_", df$.labor_status_reason[zero], "_zero")
  }
  if (any(S == 0L & (!is.finite(y) | y != 0)))
    stop("A verified composite-zero flag does not agree with its constructed outcome.", call.=FALSE)
  list(S=S, source=source, structural_zero=S == 0L,
       response=as.integer(S == 1L & is.finite(y)),
       scope=if (identical(cfg$analysis$dsp4_mode,"composite")) "documented_status_zero_composite" else
         if (!is.null(mc) && isTRUE(mc$composite_zero_at_death)) "mortality_inclusive_composite" else "ordinary_outcome")
}

# Cross-fitted binary nuisance for eligibility or an earnings-tail indicator.
# All training, inner validation and prediction rows are explicitly supplied.
fit_binary_auxiliary <- function(y, X, newX, weights, cluster, A, cfg, seed, label, fold) {
  if (length(y) != nrow(X) || anyNA(y) || any(!y %in% 0:1) || !length(y))
    stop(label, ": invalid binary training outcome.", call.=FALSE)
  if (length(unique(y)) == 1L)
    return(list(prediction=rep(as.numeric(y[1L]), nrow(newX)), status="constant_training_outcome"))
  # A prespecified training-only rule avoids impossible nested binomial fits
  # when an auxiliary class is extremely rare (especially a 0.5% earnings tail).
  # The main Q/g/pi libraries are unaffected; this decision is recorded by fold.
  class_psus <- vapply(0:1,function(k) length(unique(cluster[y==k])),integer(1))
  if (min(table(factor(y,levels=0:1))) < 10L || min(class_psus)<5L)
    return(list(prediction=rep(stats::weighted.mean(y,weights),nrow(newX)),
                status="training_minority_below_10_rows_or_5_PSUs_weighted_intercept"))
  # Binary-response stratification at both internal levels protects rare
  # classes without requiring every A-by-auxiliary-response cell in each fold.
  # The g context selects that tuning rule; X still contains A and all W.
  vr <- build_cluster_valid_rows(cluster, y, cfg$final_tmle$internal_superlearner_folds,
                                 seed, weights=weights, delta=rep(1L,length(y)),
                                 balance_on_weights=isTRUE(cfg$final_tmle$internal_fold_balance_on_weights),
                                 fold_control=fold_control_from_cfg(cfg,"internal"))
  lib <- as.character(cfg$learners$auxiliary_binary_library %||% c("SL.mean", "SL.glmnet.fixed"))
  fit <- with_sl_glmnet_context("g", seed + 1L,
                                as.integer(cfg$learners$glmnet$internal_folds %||% 5L),
                                with_local_seed(seed, SuperLearner::SuperLearner(
                                  Y=y, X=X, newX=newX, family=stats::binomial(), SL.library=lib,
                                  obsWeights=weights, id=as.character(cluster),
                                  cvControl=list(V=length(vr), validRows=vr, stratifyCV=FALSE, shuffle=FALSE),
                                  control=list(saveFitLibrary=TRUE,saveCVFitLibrary=FALSE), verbose=FALSE)),
                                unpenalized="A")
  assert_superlearner_fit(fit, lib, label, fold, nrow(newX))
  p <- as.numeric(fit$SL.predict)
  if (any(!is.finite(p) | p < 0 | p > 1)) stop(label, ": invalid predictions.",call.=FALSE)
  list(prediction=p, status="fitted")
}

# Influence of the OBSERVED-outcome, sampling-weighted percentile defining the
# earnings cap. This is not a population-earnings quantile corrected for response.
# The smooth case assumes a positive continuous density locally at the cap.
# At a strict interior point of an atom, the quantile is locally constant.
compute_cap_influence <- function(Y, delta, weights, cap, cfg, cap_rule) {
  n <- length(Y); zero <- rep(0, n)
  p <- as.numeric(cfg$outcome$continuous_upper_quantile)
  if (identical(cap_rule,"fixed") || !identical(cfg$outcome$family,"Compensation") || p >= 1)
    return(list(D=zero, method="fixed_or_uncapped", density=NA_real_, bandwidth=NA_real_, cap=cap))
  if (!isTRUE(cfg$outcome$continuous_cap_weighted) ||
      isTRUE(cfg$outcome$continuous_cap_censoring_adjusted))
    stop("Estimated-cap inference requires the declared sampling-weighted observed-outcome quantile.",call.=FALSE)
  ok <- delta == 1L & is.finite(Y)
  z <- Y[ok]; w <- weights[ok]; total <- sum(w)
  if (length(z) < 30L || !is.finite(cap) || cap <= 0)
    stop("Insufficient finite positive-cap information for percentile inference.",call.=FALSE)
  if (!identical(as.numeric(cfg$outcome$continuous_bound_eps),0))
    stop("Estimated-cap inference requires continuous_bound_eps=0.",call.=FALSE)
  # Only prespecified bracket midpoints define known atoms. A singleton jump
  # in the empirical CDF must not erase uncertainty for continuous earnings.
  atoms <- as.numeric(cfg$outcome$families$Compensation$bracket_map %||% numeric(0))
  if (!length(atoms)) atoms <- as.numeric(cfg$outcome$families$Compensation$bracket_midpoints %||% numeric(0))
  transform <- cfg$outcome$compensation_transform %||% "identity"
  if (transform=="log1p") atoms <- log1p(atoms)
  if (transform=="asinh") atoms <- asinh(atoms/(cfg$outcome$compensation_asinh_scale %||% 1))
  declared_atom <- cap %in% atoms && sum(z==cap)>=2L
  Fleft <- sum(w[z < cap])/total; Fright <- sum(w[z <= cap])/total
  if (declared_atom && Fleft < p - 1e-10 && Fright > p + 1e-10)
    return(list(D=zero, method="quantile_strictly_inside_atom", density=NA_real_,
                bandwidth=NA_real_, cap=cap, Fleft=Fleft, Fright=Fright))
  # A probability exactly on an atom boundary is a nonregular quantile target.
  if (declared_atom && Fright-Fleft > 1e-8 && min(abs(c(Fleft,Fright)-p)) < 1e-10)
    stop("Percentile lies on an atom boundary; a regular quantile influence function is not justified. Use an independently fixed cap.",call.=FALSE)
  pos <- z > 0; lz <- log(z[pos]); wp <- w[pos]
  ne <- sum(wp)^2/sum(wp^2)
  m <- sum(wp*lz)/sum(wp); sdlog <- sqrt(sum(wp*(lz-m)^2)/sum(wp))
  h <- 1.06*sdlog*ne^(-1/5)
  if (!is.finite(h) || h <= 0) stop("Cannot estimate a positive density bandwidth for the earnings cap.",call.=FALSE)
  density <- sum(wp*stats::dnorm((log(cap)-lz)/h))/(total*h*cap)
  if (!is.finite(density) || density <= 0) stop("Nonpositive estimated density at the earnings cap.",call.=FALSE)
  d <- zero
  observed_mass <- total/sum(weights)
  d[ok] <- (p-as.numeric(z <= cap))/(observed_mass*density)
  # Finite-sample centering removes the interpolation/rank discrepancy of hf8;
  # it does not remove the covariance of this term with the outcome EIF.
  d <- d-sum(weights*d)/sum(weights)
  list(D=d, method="smooth_observed_quantile_log_kernel", density=density,
       bandwidth=h, cap=cap, Fleft=Fleft, Fright=Fright,
       assumption="positive_smooth_density_at_population_observed_outcome_quantile")
}

# Shared targeting engine for primary estimation and every retargeted comparison.
# Residual R_a = S*Q_a + (1-S)*0 - M_a + S*R/pi_a*(H-Q_a).
# Stage one targets eligible-person Q; stage two targets the marginal composite
# M. This preserves effects through S rather than conditioning the final target on S.
target_composite_means <- function(A, S, delta, Y, weights, g, pi1, pi0,
                                   q1, q0, s1, s0, y_lower, y_range, cfg, estimand=c("att","ate","natural"),
                                   domain=rep(TRUE,length(A)), cap_if=rep(0,length(A)), tail_q1=NULL, tail_q0=NULL) {
  estimand <- match.arg(estimand); n <- length(A)
  v <- list(A,S,delta,Y,weights,g,pi1,pi0,q1,q0,s1,s0,domain,cap_if)
  if (any(lengths(v)!=n) || !n || anyNA(c(A,S,delta,domain)) ||
      any(!A %in% 0:1) || any(!S %in% 0:1) || any(!delta %in% 0:1) ||
      any(!is.finite(c(weights,g,pi1,pi0,q1,q0,s1,s0,cap_if))) ||
      any(weights<=0) || any(g<=0|g>=1) || any(pi1<=0|pi1>1|pi0<=0|pi0>1) ||
      any(s1<0|s1>1|s0<0|s0>1) || !is.finite(y_range) || y_range<=0)
    stop("Invalid sequential-targeting inputs.",call.=FALSE)
  if (any(S==0L & (delta!=1L | !is.finite(Y) | abs(Y)>1e-10)))
    stop("Known structural zeros must have observed zero outcomes.",call.=FALSE)
  bound <- function(x) pmin(pmax(x,1e-10),1-1e-10)
  q1 <- bound(q1); q0 <- bound(q0)
  z0 <- (0-y_lower)/y_range
  if (any(S==0L) && (z0<0 || z0>1)) stop("Composite zero is outside outcome support.",call.=FALSE)
  w <- weights; wn <- w/mean(w); d <- as.numeric(domain)
  pdom <- sum(wn*d)/n; pA <- sum(wn*d*A)/n
  if (pdom<=0 || (estimand=="att" && pA<=0)) stop("Empty target population.",call.=FALSE)
  pAuse <- if (estimand=="att") pA else pdom
  pa <- ifelse(A==1L,pi1,pi0); qa <- ifelse(A==1L,q1,q0)
  obs <- which(S==1L & delta==1L & d==1L)
  if (!length(obs) || any(!is.finite(Y[obs]))) stop("No observed eligible outcomes in target domain.",call.=FALSE)
  ys <- (Y[obs]-y_lower)/y_range
  if (any(ys< -1e-9|ys>1+1e-9)) stop("Outcome outside declared targeting bounds.",call.=FALSE)
  solve <- function(offset,H,y,w,label) solve_target_score(offset,H,y,w,
                                                           score_tol=cfg$final_tmle$target_score_tol %||% 1e-10,
                                                           max_expand=cfg$final_tmle$target_root_max_expand %||% 60L,label=label)
  marginal <- function(s,q) s*q+(1-s)*z0
  m1_initial <- marginal(s1,q1)*y_range+y_lower
  m0_initial <- marginal(s0,q0)*y_range+y_lower
  ma_initial <- ifelse(A==1L,m1_initial,m0_initial)
  qa_orig_initial <- qa*y_range+y_lower
  init_resid <- S*qa_orig_initial-ma_initial
  obs_all <- which(S==1L & delta==1L)
  init_resid[obs_all] <- init_resid[obs_all]+(Y[obs_all]-qa_orig_initial[obs_all])/pa[obs_all]
  if (estimand=="natural") {
    t <- solve(stats::qlogis(qa[obs]),1/pa[obs],ys,w[obs],"eligible natural mean")
    qn <- stats::plogis(stats::qlogis(qa)+t$epsilon/pa)
    mn <- bound(marginal(ifelse(A==1L,s1,s0),qn))
    pseudo <- S*qn+(1-S)*z0
    ii <- which(d==1L)
    u <- solve(stats::qlogis(mn[ii]),rep(1,length(ii)),pseudo[ii],w[ii],"marginal natural mean")
    mn <- stats::plogis(stats::qlogis(mn)+u$epsilon)*y_range+y_lower
    qno <- qn*y_range+y_lower
    resid <- S*qno-mn
    resid[obs_all] <- resid[obs_all]+(Y[obs_all]-qno[obs_all])/pa[obs_all]
    mu <- sum(wn*d*mn)/(n*pdom)
    D <- d/pdom*(mn-mu+resid)
    tail <- 0
    if (any(cap_if!=0)) {
      if (is.null(tail_q1)||is.null(tail_q0)) stop("Missing cross-fitted tail regressions for cap inference.",call.=FALSE)
      ty <- ifelse(delta==1L,as.numeric(Y>attr(cap_if,"cap")),NA_real_)
      # The caller supplies the uncapped exceedance indicator as an attribute.
      ty <- attr(cap_if,"tail_outcome") %||% ty
      tt <- target_composite_means(A,S,delta,ty,w,g,pi1,pi0,tail_q1,tail_q0,s1,s0,0,1,cfg,"natural",domain)
      tail <- tt$mean; D <- D+tail*cap_if
    }
    score <- max(t$normalized_score,u$normalized_score)
    if (abs(sum(wn*D)/n)/y_range > (cfg$final_tmle$att_eif_center_tol_scaled %||% 1e-8))
      stop("Sequential natural-mean influence function failed centering.",call.=FALSE)
    return(list(mean=mu,D=D,M=mn,Q=qn,score=score,epsilon=c(t$epsilon,u$epsilon),tail=tail))
  }
  h1 <- if (estimand=="att") rep(1,n) else 1/g
  h0 <- if (estimand=="att") g/(1-g) else 1/(1-g)
  t1 <- solve(stats::qlogis(qa[obs]),A[obs]*h1[obs]/pa[obs],ys,w[obs],"eligible mu1")
  t0 <- solve(stats::qlogis(qa[obs]),(1-A[obs])*h0[obs]/pa[obs],ys,w[obs],"eligible mu0")
  q1s <- stats::plogis(stats::qlogis(q1)+t1$epsilon*h1/pi1)
  q0s <- stats::plogis(stats::qlogis(q0)+t0$epsilon*h0/pi0)
  m1 <- bound(marginal(s1,q1s)); m0 <- bound(marginal(s0,q0s))
  ma <- ifelse(A==1L,m1,m0); qas <- ifelse(A==1L,q1s,q0s)
  pseudo <- S*qas+(1-S)*z0; ii <- which(d==1L)
  u1 <- solve(stats::qlogis(ma[ii]),A[ii]*h1[ii],pseudo[ii],w[ii],"marginal mu1")
  u0 <- solve(stats::qlogis(ma[ii]),(1-A[ii])*h0[ii],pseudo[ii],w[ii],"marginal mu0")
  m1 <- stats::plogis(stats::qlogis(m1)+u1$epsilon*h1)*y_range+y_lower
  m0 <- stats::plogis(stats::qlogis(m0)+u0$epsilon*h0)*y_range+y_lower
  mao <- ifelse(A==1L,m1,m0); qao <- qas*y_range+y_lower
  resid <- S*qao-mao
  resid[obs_all] <- resid[obs_all]+(Y[obs_all]-qao[obs_all])/pa[obs_all]
  target_w <- d*if (estimand=="att") A else 1
  den <- sum(wn*target_w)
  mu1 <- sum(wn*target_w*m1)/den; mu0 <- sum(wn*target_w*m0)/den
  est <- mu1-mu0
  D1 <- (target_w*(m1-mu1)+d*A*h1*resid)/pAuse
  D0 <- (target_w*(m0-mu0)+d*(1-A)*h0*resid)/pAuse
  direct <- (target_w*(m1-m0-est)+d*(A*h1-(1-A)*h0)*resid)/pAuse
  tails <- c(0,0)
  if (any(cap_if!=0)) {
    if (is.null(tail_q1)||is.null(tail_q0)||is.null(attr(cap_if,"tail_outcome")))
      stop("Estimated-cap inference requires cross-fitted tail predictions and uncapped indicators.",call.=FALSE)
    tt <- target_composite_means(A,S,delta,attr(cap_if,"tail_outcome"),w,g,pi1,pi0,
                                 tail_q1,tail_q0,s1,s0,0,1,cfg,estimand,domain)
    tails <- c(tt$mu1,tt$mu0)
    D1 <- D1+tails[1]*cap_if; D0 <- D0+tails[2]*cap_if
    direct <- direct+(tails[1]-tails[2])*cap_if
  }
  D <- D1-D0
  identity_error <- max(abs(direct-D))
  if (!is.finite(identity_error) || identity_error>1e-8)
    stop("Independent sequential ATT/ATE influence identity failed.",call.=FALSE)
  score1 <- max(t1$normalized_score,u1$normalized_score)
  score0 <- max(t0$normalized_score,u0$normalized_score)
  cent <- max(abs(c(sum(wn*D1),sum(wn*D0),sum(wn*D)))/n)/y_range
  if (!is.finite(cent)||cent>(cfg$final_tmle$att_eif_center_tol_scaled %||% 1e-8))
    stop("Sequential component influence functions failed centering.",call.=FALSE)
  plugin <- sum(wn*target_w*(m1_initial-m0_initial))/den
  residual_weight <- d*(A*h1-(1-A)*h0)
  onestep <- plugin+sum(wn*residual_weight*init_resid)/den
  Donestep <- (target_w*(m1_initial-m0_initial-onestep)+residual_weight*init_resid)/pAuse+
    (tails[1]-tails[2])*cap_if
  list(estimate=est,mu1=mu1,mu0=mu0,D=D,D1=D1,D0=D0,D_direct=direct,
       M1=m1,M0=m0,MA=mao,Q1=q1s,Q0=q0s,QA=qas,residual=resid,
       M1_initial=m1_initial,M0_initial=m0_initial,residual_initial=init_resid,
       plugin=plugin,onestep=onestep,D_onestep=Donestep,tail_means=tails,
       score1=score1,score0=score0,epsilon1=c(t1$epsilon,u1$epsilon),
       epsilon0=c(t0$epsilon,u0$epsilon),identity_error=identity_error)
}

retarget_stored_composite <- function(fit,cfg,g_lower,g_upper,pi_lower,pi_upper,
                                      estimand="att",domain=NULL) {
  ac <- fit$att_components; n <- length(ac$A)
  clip <- function(x,lo,hi) pmin(pmax(as.numeric(x),lo),hi)
  seq_model <- identical(fit$observation_model,"sequential_composite")
  cap <- fit$cap_inference$D %||% rep(0,n)
  if (any(cap!=0)) {
    attr(cap,"cap") <- fit$cap_inference$cap
    attr(cap,"tail_outcome") <- ifelse(ac$delta_Y==1L,as.numeric(ac$Y_raw>fit$cap_inference$cap),NA_real_)
  }
  target_composite_means(ac$A,if (seq_model) fit$eligibility else rep(1L,n),
                         ac$delta_Y,ac$Y_bounded_orig,ac$weights,clip(fit$gn_raw,g_lower,g_upper),
                         clip(fit$pi_1W_raw,pi_lower,pi_upper),clip(fit$pi_0W_raw,pi_lower,pi_upper),
                         if (seq_model) fit$Qeligible1W else fit$Qbar1W,
                         if (seq_model) fit$Qeligible0W else fit$Qbar0W,
                         if (seq_model) fit$S1W else rep(1,n),if (seq_model) fit$S0W else rep(1,n),
                         fit$y_lower,fit$y_range,cfg,estimand,domain %||% rep(TRUE,n),cap,
                         fit$tail_Q1W,fit$tail_Q0W)
}

composite_observed_weights <- function(ac) {
  S <- ac$eligibility %||% rep(1L,length(ac$weights))
  ac$weights*ifelse(S==0L,1,ac$delta_Y/ac$pi_AW)
}

mnar_composite_components <- function(ac) {
  if (!is.null(ac$eligibility)) {
    ac$Qbar1W_orig <- ac$Qeligible1W_targeted_orig
    ac$Qbar0W_orig <- ac$Qeligible0W_targeted_orig
    ac$pi_1W <- 1-ac$S1W*(1-ac$pi_1W)
    ac$pi_0W <- 1-ac$S0W*(1-ac$pi_0W)
  }
  ac
}

# A complete versioned fit is saved before optional work; consumers use an
# explicit adapter rather than guessing which legacy bundle fields correspond.
save_completed_fit <- function(cfg,main_df,tmle_fit) {
  cfg <- adopt_fit_g_bound(cfg,tmle_fit)
  path <- build_unique_path(cfg,"completed_fit.rds")
  payload <- list(schema="addhealth_completed_fit_v1",cfg=cfg,tmle_fit=tmle_fit,
                  source=get_frozen_source_fingerprint(cfg),
                  restricted_use_notice="Respondent-linked Add Health derived data; retain inside the restricted-use environment.")
  atomic_save_rds(payload,path,overwrite=isTRUE(cfg$global$resume_mode))
  restored <- readRDS(path)
  if (!identical(restored$tmle_fit$calibration_training_by_fold,
                 tmle_fit$calibration_training_by_fold) ||
      !identical(restored$tmle_fit$review_data,tmle_fit$review_data) ||
      !identical(restored$tmle_fit$status_records,tmle_fit$status_records))
    stop("Saved fit failed review-input reconstruction.",call.=FALSE)
  for (nm in c("Q_without_residual_predictions","Q_residual_candidate_predictions",
               "residual_Q_audit_by_fold","residual_Q_training_by_fold"))
    if (!identical(restored$tmle_fit[[nm]],tmle_fit[[nm]]))
      stop("Saved fit failed residual-Q archive reconstruction: ",nm)
  rr <- estimate_joint_att_under_clips(restored$tmle_fit,restored$cfg,
                                       cfg$final_tmle$g_lower,cfg$final_tmle$g_upper,cfg$final_tmle$pi_lower,cfg$final_tmle$pi_upper,"checkpoint_validation")
  ref <- tmle_fit$att_components
  if (abs(rr$att_estimate-ref$att_tmle_estimate)>1e-7 || abs(rr$att_se-ref$att_tmle_se)>1e-7)
    stop("Saved fit failed primary ATT/SE reconstruction.",call.=FALSE)
  invisible(path)
}

restore_completed_fit <- function(path) {
  z <- readRDS(path)
  if (!identical(z$schema,"addhealth_completed_fit_v1") || is.null(z$cfg) || is.null(z$tmle_fit))
    stop("Unsupported or incomplete completed-fit checkpoint.",call.=FALSE)
  for (ar in z$tmle_fit$residual_Q_training_by_fold %||% list())
    if (!is.null(ar) && identical(ar$schema,"residual_Q_training_v2"))
      validate_residual_Q_archive(ar)
  z
}

# Resolve automatic status handling consistently in both direct and top-level
# calls. A status file for current civilian hours never recodes annual earnings.
resolve_status_mode <- function(cfg) {
  mode <- cfg$analysis$dsp4_mode %||% 'audit_only'
  if (!identical(mode,'auto_verified')) return(mode)
  wave <- cfg$outcome$current_wave %||% cfg$outcome$waves
  if (isTRUE(cfg$analysis$auto_military_prison_status) &&
      cfg$outcome$family %in% c('HoursWorked','LaborForceParticipation') &&
      identical(as.character(wave), '4')) return('composite')
  p <- cfg$paths$verified_labor_status
  has_path <- is.character(p) && length(p)==1L && !is.na(p) && nzchar(trimws(p))
  current_endpoint <- cfg$outcome$family %in% c('HoursWorked','LaborForceParticipation')
  if (has_path && current_endpoint) 'composite' else 'audit_only'
}

# Compare any number of saved specifications against ONE held-out reference
# prognostic score. No nuisance models are refitted and no production run is
# needed. ID and outcome checks are enforced by the same diagnostic helper.
compare_saved_prognostic_balance <- function(checkpoint_paths,reference_checkpoint) {
  if (!is.character(checkpoint_paths)||!length(checkpoint_paths)||anyNA(checkpoint_paths))
    stop('Supply completed-fit checkpoint paths.',call.=FALSE)
  ref <- restore_completed_fit(reference_checkpoint)
  scores <- build_prognostic_score_export(ref$tmle_fit,ref$cfg)
  if (!nrow(scores)) stop('Reference fit has no prognostic scores.',call.=FALSE)
  temp <- tempfile(fileext='.csv');on.exit(unlink(temp),add=TRUE)
  utils::write.csv(scores,temp,row.names=FALSE)
  rows <- lapply(checkpoint_paths,function(p) {
    z <- restore_completed_fit(p);cc <- z$cfg
    cc$diagnostics$prognostic_reference_score_path <- temp
    ans <- build_prognostic_score_balance(z$tmle_fit,cc)
    ans <- ans[ans$score_source=='fixed_reference',,drop=FALSE]
    if (!nrow(ans)) stop('Reference score has no variation or comparison has inadequate support.',call.=FALSE)
    ans$checkpoint <- p;ans$reference_checkpoint <- reference_checkpoint;ans
  })
  do.call(rbind,rows)
}

run_sequential_composite_self_test <- function(cfg) {
  d <- expand.grid(j=seq_len(150L),U=0:1,A=0:1);n <- nrow(d)
  S <- as.integer(d$j<=ifelse(d$A==1L & d$U==0L,60L,120L))
  response <- as.integer(d$j%%5L!=0L)
  delta <- as.integer(S==0L | response==1L)
  y <- ifelse(S==0L,0,ifelse(response==1L,20+20*d$U,NA_real_))
  args <- list(A=d$A,S=S,delta=delta,Y=y,weights=rep(1,n),g=rep(.5,n),
               pi1=rep(.8,n),pi0=rep(.8,n),q1=rep((100/3)/120,n),q0=rep(30/120,n),
               s1=rep(.6,n),s0=rep(.8,n),y_lower=0,y_range=120,cfg=cfg)
  a <- do.call(target_composite_means,args)
  if (max(abs(c(a$estimate+4,a$mu1-20,a$mu0-24,mean(a$D))))>1e-7 ||
      max(abs(a$D_direct-(a$D1-a$D0)))>1e-8)
    stop('600-row sequential-composite known-answer test failed.',call.=FALSE)
  args$weights <- rep(37,n);b <- do.call(target_composite_means,args)
  if (max(abs(a$D-b$D))>1e-8 || abs(a$estimate-b$estimate)>1e-8)
    stop('Sequential-composite weight scaling test failed.',call.=FALSE)
  args$S[1L] <- NA_integer_
  if (!inherits(try(do.call(target_composite_means,args),silent=TRUE),'try-error'))
    stop('Unknown eligibility was not rejected.',call.=FALSE)
  invisible(TRUE)
}


# The main driver runs one outer fold at a time. Source/config/data-matched
# checkpoints are saved by default; reuse requires explicit resume mode.
run_final_cv_tmle <- function(cfg, main_df, timers = NULL) {
  cfg$analysis$dsp4_mode <- resolve_status_mode(cfg)
  if (is.null(main_df) || !is.data.frame(main_df))
    stop("run_final_cv_tmle requires a non-null main data frame.", call. = FALSE)
  if (is.null(cfg$preprocessing$global_missing_dictionary))
    cfg$preprocessing$global_missing_dictionary <- attr(main_df, "global_missing_dictionary")
  if (is.null(cfg$preprocessing$global_missing_dictionary) ||
      !length(cfg$preprocessing$global_missing_dictionary))
    stop("run_final_cv_tmle requires the frozen global Wave I missing-code dictionary.", call. = FALSE)
  cfg$preprocessing$variable_source_registry <- get_variable_source_registry(
    main_df, cfg, required = TRUE)
  main_df <- canonicalize_mandatory_W_columns(main_df, cfg)
  attr(main_df, "variable_source_registry") <- cfg$preprocessing$variable_source_registry
  validate_candidate_governance(main_df, cfg)
  if (!is.null(timers)) timers$start("final_cv_tmle")
  msg("\n===== STAGE: Final CV-TMLE =====", cfg = cfg)
  msg(sprintf("  V outer folds: %d  |  Internal SL folds: %d  |  Cluster-aware internal CV: %s",
              cfg$final_tmle$vfolds, cfg$final_tmle$internal_superlearner_folds,
              isTRUE(cfg$final_tmle$cluster_aware_internal_cv)), cfg = cfg)
  msg(sprintf("  g bounds: [%g, %g]  |  pi bounds: [%g, %g]",
              cfg$final_tmle$g_lower, cfg$final_tmle$g_upper,
              cfg$final_tmle$pi_lower, cfg$final_tmle$pi_upper), cfg = cfg)
  msg(sprintf("  Nested rough screen in-fold: %s  |  Fold checkpoints: %s",
              isTRUE(cfg$final_tmle$nested_rough_prescreen_in_final_cv),
              isTRUE(cfg$final_tmle$use_fold_checkpoints)), cfg = cfg)
  msg(sprintf("  Nested screen caps: Y top %d, delta top %d, joint A/Y top %d, final cap %d.",
              cfg$final_tmle$rough_top_n_outcome, cfg$final_tmle$rough_top_n_missingness,
              cfg$final_tmle$rough_top_n_joint_AY, cfg$final_tmle$rough_max_total_vars), cfg = cfg)
  ensure_output_dir(cfg$global$output_dir)
  if (requireNamespace("RhpcBLASctl", quietly = TRUE)) {
    try(RhpcBLASctl::blas_set_num_threads(1L), silent = TRUE)
    msg("  [TMLE] BLAS restricted to 1 thread (prevents nested OOM).", cfg = cfg)
  }
  msg("  [TMLE] Registering custom SuperLearner wrappers (ranger/xgboost/earth/glmnet/gam)...", cfg = cfg)
  register_custom_learners(cfg)
  checkpoint_dir <- file.path(cfg$global$output_dir, cfg$global$checkpoint_subdir)
  ensure_output_dir(checkpoint_dir)
  msg(sprintf("  [TMLE] Checkpoint directory: %s", checkpoint_dir), cfg = cfg)
  
  full_survey_design_frame <- attr(main_df, "survey_design_frame")
  if (is.null(full_survey_design_frame) || !is.data.frame(full_survey_design_frame))
    stop("Final CV-TMLE requires the complete valid-weight Wave-I survey-design frame for domain variance estimation; rebuild the main dataset cache.", call. = FALSE)
  msg("  [TMLE] Preparing final analysis data (bounding Y, building delta)...", cfg = cfg)
  data_pack <- prepare_final_analysis_data(main_df, cfg)
  cfg <- resolve_primary_g_bound(cfg,sum(data_pack$delta_Y==1L))
  msg(sprintf("  Resolved primary g lower bound: %.8f (%s; observed n=%d).",
    cfg$final_tmle$g_lower,cfg$final_tmle$g_lower_rule %||% "fixed",
    sum(data_pack$delta_Y==1L)),cfg=cfg)
  main_df   <- data_pack$df
  missing_mandatory <- setdiff(get_mandatory_W(cfg), names(main_df))
  if (length(missing_mandatory) > 0L) {
    stop("Missing mandatory Wave-I confounder(s): ",
         paste(missing_mandatory, collapse = ", "), call. = FALSE)
  }
  A         <- data_pack$A
  Y_raw     <- data_pack$Y_raw
  Y_bounded_orig <- data_pack$Y_bounded_orig
  Y_star    <- data_pack$Y_star
  delta_Y   <- data_pack$delta_Y
  weights   <- data_pack$weights
  cluster   <- data_pack$cluster
  strata    <- data_pack$strata
  respondent_ids <- as.character(main_df[[cfg$analysis$id_var]])
  if (length(respondent_ids) != length(weights) || anyNA(respondent_ids) || anyDuplicated(respondent_ids))
    stop("Final CV-TMLE requires complete unique respondent IDs aligned with the EIF rows.", call. = FALSE)
  observation <- resolve_composite_observation(main_df,cfg)
  eligibility <- observation$S
  delta_response <- observation$response
  structural_zero <- observation$structural_zero
  structural_zero_source <- observation$source
  cap_inference <- compute_cap_influence(Y_raw,delta_Y,weights,data_pack$cap_value,cfg,data_pack$cap_rule)
  tail_needed <- any(cap_inference$D != 0)
  tail_outcome <- ifelse(delta_Y==1L,as.numeric(Y_raw>data_pack$cap_value),NA_real_)
  msg(sprintf("  [TMLE] Sequential observation model: %d verified zeros, %d eligible responses; scope=%s.",
              sum(structural_zero),sum(delta_response),observation$scope),cfg=cfg)
  infer_primary_eif <- function(D_eif, estimate_eif) {
    cluster_inference_from_eif(
      D = D_eif, weights = weights, cluster = cluster, estimate = estimate_eif,
      strata = strata, design_frame = full_survey_design_frame,
      domain_ids = respondent_ids, id_var = cfg$analysis$id_var,
      cluster_var = cfg$analysis$cluster_var, strata_var = cfg$analysis$strata_var,
      weight_var = cfg$analysis$weight_var)
  }
  if (is.null(strata))
    stop(sprintf("Required Add Health design stratum '%s' is absent from the analytic data.",
                 cfg$analysis$strata_var), call. = FALSE)
  outcome_type <- data_pack$outcome_type
  compensation_transform <- tolower(cfg$outcome$compensation_transform %||% "identity")
  is_raw_dollar_outcome <- identical(cfg$outcome$family, "Compensation") &&
    identical(compensation_transform, "identity")
  policy_outcome_transform <- if (identical(cfg$outcome$family, "Compensation"))
    compensation_transform else "identity"
  family_cfg_current <- cfg$outcome$families[[cfg$outcome$family]]
  report_ratio_translations <- compensation_ratio_translation_enabled(cfg)
  y_lower <- data_pack$y_lower; y_upper <- data_pack$y_upper
  y_range <- data_pack$y_range
  cfg$final_tmle$screen_y_lower <- y_lower
  cfg$final_tmle$screen_y_upper <- y_upper
  n <- nrow(main_df); V <- cfg$final_tmle$vfolds
  msg(sprintf("  [TMLE] Analytic sample: n=%d, clusters=%d, exposed=%d (%.1f%%), outcome-observed=%d (%.1f%%).",
              n, length(unique(cluster)), sum(A == 1L), 100 * mean(A),
              sum(delta_Y == 1L), 100 * mean(delta_Y)), cfg = cfg)
  msg(sprintf("  [TMLE] Y bounded to [%.3f, %.3f] (range=%.3f) for fluctuation step.",
              y_lower, y_upper, y_range), cfg = cfg)
  
  msg("  [TMLE] Constructing cluster-balanced outer folds...", cfg = cfg)
  outer_fold <- make_final_cv_folds(data_pack, cfg)
  V_requested <- V
  V <- max(outer_fold)
  if (V != V_requested)
    msg(sprintf("    Requested %d outer folds; support constraints permit %d.", V_requested, V), cfg = cfg)
  msg(sprintf("    Outer fold sizes:      %s", paste(as.vector(table(outer_fold)), collapse = ", ")), cfg = cfg)
  msg(sprintf("    Treated per fold:      %s",
              paste(tapply(A, outer_fold, sum), collapse = ", ")), cfg = cfg)
  
  S1W <- S0W <- rep(NA_real_,n)
  tail_Q1W <- tail_Q0W <- rep(NA_real_,n)
  diagnostic_W_by_fold <- vector("list",V)
  Qbar1W <- Qbar0W <- QbarAW <- rep(NA_real_, n)
  Q_core_predictions <- matrix(NA_real_,n,3L,dimnames=list(NULL,c("Q1","Q0","QA")))
  broad_Q_audit_by_fold <- vector("list",V)
  residual_Q_on <- isTRUE(cfg$final_tmle$residual_Q_candidate) && is.null(cfg$final_tmle$prespecified_W)
  Q_without_residual_predictions <- Q_residual_candidate_predictions <-
    if (residual_Q_on) matrix(NA_real_,n,3L,dimnames=list(NULL,c("Q1","Q0","QA"))) else NULL
  residual_Q_audit_by_fold <- residual_Q_training_by_fold <-
    if (residual_Q_on) vector("list",V) else NULL
  gn     <- rep(NA_real_, n); pi_AW <- pi_1W <- pi_0W <- rep(NA_real_, n)
  gn_raw <- rep(NA_real_, n); pi_AW_raw <- pi_1W_raw <- pi_0W_raw <- rep(NA_real_, n)
  gn_uncalibrated <- pi_AW_uncalibrated <- rep(NA_real_, n)
  # v8.37: held-out predictions from the ALTERNATE pi fit (treatment indicator
  # left unpenalized in glmnet). These never enter the primary estimate; they
  # exist so the ATT can be retargeted from them as an isolated sensitivity.
  # NA for every fold when the dual fit is disabled or a fold's alternate fit
  # failed, which downstream diagnostics detect and report rather than impute.
  pi_AW_alt_raw <- pi_1W_alt_raw <- pi_0W_alt_raw <- rep(NA_real_, n)
  pi_alt_status <- rep(NA_character_, V)
  calibration_log <- vector("list", V)
  calibration_training_by_fold <- vector("list", V)
  pi_1W_uncalibrated <- pi_0W_uncalibrated <- rep(NA_real_,n)
  Y_star_obs <- Y_star
  
  per_fold_log <- list()
  fold_support_log <- list()
  internal_fold_support_log <- list()
  fold_times   <- numeric(V)
  selected_by_fold <- list()
  protected_mapping_by_fold <- list()
  nested_selection_log <- list()
  cluster_assignment_log <- list()   # per-fold cluster assignments
  run_manifest_rows <- list()
  q_clip_log <- list()
  
  lib_Q  <- build_sl_library(cfg, "Q")
  lib_g  <- build_sl_library(cfg, "g")
  lib_pi <- build_sl_library(cfg, "pi")
  lib_pi_alt <- build_pi_alt_library(cfg)
  msg(sprintf("  [TMLE] SL libraries:  Q=[%s]", paste(lib_Q, collapse = ", ")), cfg = cfg)
  msg(sprintf("                        g=[%s]", paste(lib_g, collapse = ", ")), cfg = cfg)
  msg(sprintf("                       pi=[%s]", paste(lib_pi, collapse = ", ")), cfg = cfg)
  if (!is.null(lib_pi_alt))
    msg(sprintf("                   pi_alt=[%s] (sensitivity only; not in the primary estimate)",
                paste(lib_pi_alt, collapse = ", ")), cfg = cfg)
  base_seed <- seed_for(cfg, 9000L)
  
  for (v in seq_len(V)) {
    fold_ck <- file.path(checkpoint_dir, sprintf("fold_%02d.rds", v))
    tr <- which(outer_fold != v); te <- which(outer_fold == v)
    current_fp <- if (isTRUE(cfg$final_tmle$use_fold_checkpoints)) {
      make_fold_checkpoint_fingerprint(cfg, main_df, data_pack, outer_fold, v)
    } else {
      list(pipeline_version = cfg$global$version, fold_id = v,
           checkpoints_disabled = TRUE)
    }
    
    if (isTRUE(cfg$final_tmle$use_fold_checkpoints) && file.exists(fold_ck)) {
      msg(sprintf("\n  [fold %d/%d] Found checkpoint %s; validating fingerprint...", v, V, fold_ck), cfg = cfg)
      cached <- readRDS(fold_ck)
      if (!is.null(cached$fingerprint) && identical(cached$fingerprint, current_fp)) {
        te <- cached$valid_idx
        Qbar1W[te] <- cached$Qbar1W; Qbar0W[te] <- cached$Qbar0W
        QbarAW[te] <- cached$QbarAW
        S1W[te] <- cached$S1W; S0W[te] <- cached$S0W
        tail_Q1W[te] <- cached$tail_Q1W; tail_Q0W[te] <- cached$tail_Q0W
        diagnostic_W_by_fold[[v]] <- cached$diagnostic_W_design
        gn[te]    <- cached$gn
        pi_AW[te] <- cached$pi_AW; pi_1W[te] <- cached$pi_1W; pi_0W[te] <- cached$pi_0W
        gn_raw[te] <- cached$gn_raw %||% cached$gn
        gn_uncalibrated[te] <- cached$gn_uncalibrated %||% cached$gn_raw
        pi_AW_uncalibrated[te] <- cached$pi_AW_uncalibrated %||% cached$pi_AW_raw
        if (!is.null(cached$calibration_audit)) calibration_log[[v]] <- cached$calibration_audit
        calibration_training_by_fold[[v]] <- cached$calibration_training
        if (isTRUE(cfg$final_tmle$broad_Q_candidate)) {
          if (is.null(cached$Q_core_predictions)) stop("Checkpoint lacks core Q comparator.")
          Q_core_predictions[te,] <- cached$Q_core_predictions
          broad_Q_audit_by_fold[v] <- list(cached$broad_Q_audit)
        }
        if (residual_Q_on) {
          if (is.null(cached$Q_without_residual_predictions) || is.null(cached$residual_Q_training) ||
              is.null(cached$residual_Q_audit) || is.null(cached$Q_residual_candidate_predictions))
            stop("Checkpoint lacks residual-Q predictions or audit archive.")
          Q_without_residual_predictions[te,] <- cached$Q_without_residual_predictions
          Q_residual_candidate_predictions[te,] <- cached$Q_residual_candidate_predictions
          residual_Q_audit_by_fold[[v]] <- cached$residual_Q_audit
          residual_Q_training_by_fold[[v]] <- cached$residual_Q_training
        }
        pi_1W_uncalibrated[te] <- cached$pi_1W_uncalibrated
        pi_0W_uncalibrated[te] <- cached$pi_0W_uncalibrated
        pi_AW_raw[te] <- cached$pi_AW_raw %||% cached$pi_AW
        pi_1W_raw[te] <- cached$pi_1W_raw %||% cached$pi_1W
        pi_0W_raw[te] <- cached$pi_0W_raw %||% cached$pi_0W
        # v8.37: alternate pi. A checkpoint written before this field existed
        # restores NA, which the downstream sensitivity detects and reports as
        # unavailable rather than silently substituting the primary fit.
        pi_AW_alt_raw[te] <- cached$pi_AW_alt_raw %||% rep(NA_real_, length(te))
        pi_1W_alt_raw[te] <- cached$pi_1W_alt_raw %||% rep(NA_real_, length(te))
        pi_0W_alt_raw[te] <- cached$pi_0W_alt_raw %||% rep(NA_real_, length(te))
        pi_alt_status[v] <- cached$pi_alt_status %||% NA_character_
        per_fold_log[[v]] <- cached$sl_log
        fold_times[v]     <- cached$fold_time
        selected_by_fold[[v]] <- cached$selected_vars
        if (!is.null(cached$protected_raw_to_processed))
          protected_mapping_by_fold[[v]] <- cached$protected_raw_to_processed
        if (!is.null(cached$selection_table)) nested_selection_log[[v]] <- cached$selection_table
        if (!is.null(cached$outer_support)) fold_support_log[[v]] <- cached$outer_support
        if (!is.null(cached$run_manifest_row)) run_manifest_rows[[v]] <- cached$run_manifest_row
        if (!is.null(cached$q_clip_log)) q_clip_log[[v]] <- cached$q_clip_log
        if (!is.null(cached$internal_support)) internal_fold_support_log[[paste0(v, "_cached")]] <- cached$internal_support
        # (point 2): also restore cached cluster assignments, so a fold
        # reused from checkpoint is not silently dropped from cluster_assignments.csv
        # (needed to audit H1FS/H1GH over-collapse across ALL folds).
        if (!is.null(cached$cluster_assignments) && nrow(cached$cluster_assignments) > 0L)
          cluster_assignment_log[[length(cluster_assignment_log) + 1L]] <- cached$cluster_assignments
        msg(sprintf("    Fingerprint OK; reused %d cached nuisance estimates (fold originally took %.1fs).",
                    length(te), cached$fold_time), cfg = cfg)
        next
      } else {
        msg("    Checkpoint fingerprint missing or stale; recomputing this fold.", cfg = cfg)
      }
    }
    
    t0 <- proc.time()[3]
    msg(sprintf("\n  [fold %d/%d] NEW fold: training rows=%d, validation rows=%d.",
                v, V, length(tr), length(te)), cfg = cfg)
    msg(sprintf("    Training: %d exposed (%.1f%%), %d outcome-observed (%.1f%%).",
                sum(A[tr] == 1L), 100 * mean(A[tr]),
                sum(delta_Y[tr] == 1L), 100 * mean(delta_Y[tr])), cfg = cfg)
    obs_treated_train <- sum(A[tr] == 1L & delta_Y[tr] == 1L)
    obs_treated_valid <- sum(A[te] == 1L & delta_Y[te] == 1L)
    # (point 3): per-fold binary event counts among OBSERVED rows
    # (delta==1), so a fold with treated rows but very few treated events or
    # non-events is visible for a binary outcome (e.g. LFP). NA for continuous.
    .isbin_fs <- identical(outcome_type, "binary")
    .evc <- function(idx, a, yv) if (.isbin_fs)
      sum(delta_Y[idx] == 1L & A[idx] == a & Y_raw[idx] == yv, na.rm = TRUE) else NA_integer_
    fold_support_log[[v]] <- data.frame(
      fold = v, n_train = length(tr), n_valid = length(te),
      clusters_train = length(unique(cluster[tr])), clusters_valid = length(unique(cluster[te])),
      treated_train = sum(A[tr] == 1L), treated_valid = sum(A[te] == 1L),
      observed_train = sum(delta_Y[tr] == 1L), observed_valid = sum(delta_Y[te] == 1L),
      observed_treated_train = obs_treated_train, observed_treated_valid = obs_treated_valid,
      ess_train = kish_ess_safe(weights[tr]), ess_valid = kish_ess_safe(weights[te]),
      ess_treated_train = kish_ess_safe(weights[tr][A[tr] == 1L]),
      ess_treated_valid = kish_ess_safe(weights[te][A[te] == 1L]),
      Y1_treated_train = .evc(tr, 1L, 1), Y0_treated_train = .evc(tr, 1L, 0),
      Y1_control_train = .evc(tr, 0L, 1), Y0_control_train = .evc(tr, 0L, 0),
      Y1_treated_valid = .evc(te, 1L, 1), Y0_treated_valid = .evc(te, 1L, 0),
      Y1_control_valid = .evc(te, 0L, 1), Y0_control_valid = .evc(te, 0L, 0),
      stringsAsFactors = FALSE)
    if (sum(A[tr] == 1L) < cfg$final_tmle$min_treated_warning_n)
      warning(sprintf("Fold %d has only %d treated training rows.",
                      v, sum(A[tr] == 1L)))
    if (obs_treated_train < (cfg$final_tmle$min_observed_treated_warning_n %||% 20L))
      warning(sprintf("Fold %d has only %d outcome-observed treated training rows.",
                      v, obs_treated_train))
    if (is.finite(fold_support_log[[v]]$ess_treated_train) &&
        fold_support_log[[v]]$ess_treated_train < (cfg$final_tmle$min_ess_treated_train_warning %||% 20))
      warning(sprintf("Fold %d has treated effective sample size %.1f below warning threshold %.1f.",
                      v, fold_support_log[[v]]$ess_treated_train,
                      cfg$final_tmle$min_ess_treated_train_warning %||% 20))
    # --- Nested data-driven screen on training rows only ----------------
    # Reset fold-local selection objects so optional checkpoint metadata can
    # never inherit an object created in a previous outer fold.
    rough_sel <- NULL
    # if a pre-specified W is supplied, bypass the nested screen and
    # use the fixed, theoretically-motivated variable list (intersected with
    # available columns). This supports the pre-specified-W sensitivity
    # scenario that addresses the "data-driven selection introduced bias"
    # objection. The list is the same in every fold by construction.
    prespec_W <- cfg$final_tmle$prespecified_W
    if (!is.null(prespec_W) && length(prespec_W) > 0L) {
      sel_vars <- intersect(prespec_W, names(main_df))
      if (length(sel_vars) == 0L)
        stop("prespecified_W contains no variables present in the dataset.", call. = FALSE)
      nested_selection_log[[v]] <- data.frame(
        fold = v, variable = sel_vars, source = "prespecified",
        stringsAsFactors = FALSE)
      msg(sprintf("    [fold %d] Using pre-specified W: %d of %d variables present.",
                  v, length(sel_vars), length(prespec_W)), cfg = cfg)
    } else if (isTRUE(cfg$final_tmle$nested_rough_prescreen_in_final_cv)) {
      t_sel <- proc.time()[3]
      rough_sel <- run_nested_rough_prescreen_for_final(main_df, tr, cfg, fold_id = v)
      sel_vars <- rough_sel$selected_vars
      nested_selection_log[[v]] <- rough_sel$selection_table
      if (!is.null(rough_sel$cluster_assignments) && nrow(rough_sel$cluster_assignments) > 0L)
        cluster_assignment_log[[length(cluster_assignment_log) + 1L]] <- rough_sel$cluster_assignments
      msg(sprintf("    [fold %d] Nested data-driven screen selected %d variables in %.1fs.",
                  v, length(sel_vars), proc.time()[3] - t_sel), cfg = cfg)
    } else {
      stop("No final screening path is active. Enable nested_rough_prescreen_in_final_cv=TRUE. Silent fallback to all candidates is disabled.",
           call. = FALSE)
    }
    if (length(sel_vars) == 0L)
      stop(sprintf("Fold %d selected zero variables.", v), call. = FALSE)
    selected_by_fold[[v]] <- sel_vars
    # Fold-pure W preprocessing: learn every preprocessing rule on training
    # rows, apply the frozen recipe to validation rows, then sanitize names.
    t_W <- proc.time()[3]
    # Fixed nonprotected processed-column engineering budget. Statistical
    # adequacy is assessed through cluster-held-out nuisance performance,
    # positivity, convergence, ESS diagnostics, and full-refit budget
    # sensitivities rather than an events-per-column formula.
    column_budget_applied <- as.integer(cfg$final_tmle$final_max_processed_columns %||% 260L)
    W_pack <- build_final_W_train_valid(
      train_df = main_df[tr, , drop = FALSE],
      valid_df = main_df[te, , drop = FALSE],
      selected_vars = sel_vars,
      cfg = cfg,
      priority_table = nested_selection_log[[v]],
      processed_cap_override = column_budget_applied)
    W_tr <- W_pack$train
    W_te <- W_pack$valid
    Q_broad_pack <- NULL
    lib_Q_fit <- lib_Q
    if (isTRUE(cfg$final_tmle$broad_Q_candidate) && is.null(prespec_W)) {
      Q_broad_pack <- build_broad_Q_pack(main_df,tr,te,rough_sel,sel_vars,cfg)
      lib_Q_fit <- c(lapply(lib_Q,function(z) c(z,"screen.Q_core")),
        list(c("SL.glmnet.fixed","screen.Q_broad")))
      broad_Q_audit_by_fold[[v]] <- list(
        raw_variables=Q_broad_pack$kept_raw_vars,
        processed_columns=names(Q_broad_pack$train),
        dropped_by_column_cap=Q_broad_pack$dropped_by_column_cap)
    }
    protected_mapping_by_fold[[v]] <- stats::setNames(
      as.integer(W_pack$protected_raw_to_processed), W_pack$protected_raw_names)
    # v8.37 SAFEGUARD: every protected baseline variable must actually reach the
    # fitted design in THIS fold. build_grouped_design_train bypasses the
    # support threshold only in its FACTOR branch, so a protected NUMERIC whose
    # prep returns NULL is skipped silently. Under protected_W_mode="summary"
    # the entire baseline-severity block is a single numeric column
    # (MHSum_W1), so a silent drop would remove baseline adjustment altogether
    # rather than degrade it. Fail loudly instead.
    {
      prot_raw <- resolve_protected_W(cfg)
      mapped <- stats::setNames(as.integer(W_pack$protected_raw_to_processed),
                                W_pack$protected_raw_names)
      absent <- setdiff(prot_raw, names(mapped)[is.finite(mapped) & mapped > 0L])
      if (length(absent))
        stop(sprintf(paste0("Fold %d lost protected baseline variable(s) from the final design: %s. ",
                            "Protected covariates must survive screening and design construction ",
                            "in every fold."),
                     v, paste(absent, collapse = ", ")), call. = FALSE)
      for (pr in prot_raw) {
        cols_pr <- names(W_pack$processed_raw_map)[W_pack$processed_raw_map == pr]
        if (!length(intersect(cols_pr, names(W_tr))) ||
            !length(intersect(cols_pr, names(W_te))))
          stop(sprintf(paste0("Fold %d mapped protected variable '%s' but it is absent from the ",
                              "training or validation design matrix."), v, pr), call. = FALSE)
      }
      msg(sprintf("    [fold %d] Protected baseline check OK: %s -> %d processed column(s).",
                  v, paste(prot_raw, collapse = ", "),
                  sum(mapped[prot_raw], na.rm = TRUE)), cfg = cfg)
    }
    msg(sprintf(
      "    [fold %d] W recipe built in %.1fs: %d raw vars -> %d processed cols; missing selected=%d; validation missing cols filled=%d; validation extras dropped=%d.",
      v, W_pack$seconds, W_pack$n_raw, W_pack$n_processed,
      W_pack$n_missing_selected, W_pack$missing_in_validation,
      W_pack$extra_in_validation), cfg = cfg)
    if (!is.null(nested_selection_log[[v]]) && "variable" %in% names(nested_selection_log[[v]])) {
      nested_selection_log[[v]]$kept_in_final_W <- nested_selection_log[[v]]$variable %in% W_pack$kept_raw_vars
      nested_selection_log[[v]]$dropped_by_column_cap <- nested_selection_log[[v]]$variable %in% W_pack$dropped_by_column_cap
    }
    # per-fold run manifest -- the design-verification numbers for this
    # fold (cap applied, columns produced, whether the cap bound, support).
    run_manifest_rows[[v]] <- data.frame(
      pipeline_version = cfg$global$version,
      run_id = cfg$global$run_id %||% NA_character_,
      script_md5 = get_frozen_source_fingerprint(cfg)$md5,
      analysis_spec_md5 = get_frozen_config_hash(cfg, "analysis"),
      resolved_run_config_md5 = get_frozen_config_hash(cfg, "resolved"),
      R_version = cfg$provenance$runtime$R_version,
      runtime_platform = cfg$provenance$runtime$platform,
      package_versions = cfg$provenance$runtime$packages,
      pipeline_seed = cfg$global$pipeline_seed,
      checkpoint_subdir = cfg$global$checkpoint_subdir,
      main_dataset_cache_fingerprint_md5 = object_md5(
        attr(main_df, "main_dataset_cache_fingerprint") %||%
          list(status = "unavailable_for_direct_main_df_input")),
      fold_checkpoint_fingerprint_md5 = object_md5(current_fp),
      target_population = configured_target_population(cfg),
      weight_variable = cfg$analysis$weight_var,
      outcome_family = cfg$outcome$family,
      outcome_wave = cfg$outcome$current_wave %||% cfg$outcome$waves,
      outcome_scale = configured_outcome_scale(cfg, outcome_type),
      outcome_cap_probability = if (identical(cfg$outcome$family, "Compensation")) cfg$outcome$continuous_upper_quantile else NA_real_,
      outcome_cap_value = data_pack$cap_value,
      outcome_bound_lower = y_lower,
      outcome_bound_upper = y_upper,
      outcome_cap_weighted = data_pack$cap_weighted,
      outcome_cap_quantile_rule = data_pack$cap_qrule,
      earnings_exact_valid_min = if (identical(cfg$outcome$family, "Compensation")) cfg$outcome$families$Compensation$exact_valid_min %||% NA_real_ else NA_real_,
      earnings_exact_valid_max = if (identical(cfg$outcome$family, "Compensation")) cfg$outcome$families$Compensation$exact_valid_max %||% NA_real_ else NA_real_,
      primary_estimand = cfg$final_tmle$primary_estimand,
      policy_primary_percentage = cfg$final_tmle$percentage_primary,
      policy_components_enabled = isTRUE(cfg$policy$enable_policy_components %||% TRUE),
      policy_translation_enabled = isTRUE(cfg$policy$enable_att_prevalence_translation %||% TRUE),
      mortality_sensitivity_enabled = mortality_enabled_for_wave(cfg, cfg$outcome$current_wave),
      mortality_composite_zero_at_death = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
        isTRUE(resolve_mortality_spec(cfg, cfg$outcome$current_wave)$composite_zero_at_death %||% FALSE) else FALSE,
      mortality_fail_on_observed_outcome_contradiction = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
        isTRUE(resolve_mortality_spec(cfg, cfg$outcome$current_wave)$fail_on_death_with_observed_original_outcome %||% TRUE) else NA,
      mortality_source_variable = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
        resolve_mortality_spec(cfg, cfg$outcome$current_wave)$source_var %||% NA_character_ else NA_character_,
      mortality_source_month_variable = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
        resolve_mortality_spec(cfg, cfg$outcome$current_wave)$source_month_var %||% NA_character_ else NA_character_,
      mortality_timing_mode = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
        resolve_mortality_spec(cfg, cfg$outcome$current_wave)$timing_mode %||% NA_character_ else NA_character_,
      mortality_timing_rule = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
        mortality_timing_rule_text(resolve_mortality_spec(cfg, cfg$outcome$current_wave)) else NA_character_,
      mortality_death_year_start = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
        resolve_mortality_spec(cfg, cfg$outcome$current_wave)$death_year_start %||% NA_integer_ else NA_integer_,
      mortality_death_year_end = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
        resolve_mortality_spec(cfg, cfg$outcome$current_wave)$death_year_end %||% NA_integer_ else NA_integer_,
      wave2_completion_diagnostic_enabled =
        isTRUE(cfg$diagnostics$enable_wave2_completion_diagnostic %||% TRUE),
      mnar_pattern_mixture_enabled =
        isTRUE(cfg$diagnostics$enable_mnar_pattern_mixture %||% TRUE),
      evalue_enabled = isTRUE(cfg$diagnostics$enable_evalue %||% FALSE),
      global_missing_dictionary_md5 = object_md5(cfg$preprocessing$global_missing_dictionary),
      protected_W = paste(resolve_protected_W(cfg), collapse = ";"),
      mandatory_W = paste(get_mandatory_W(cfg), collapse = ";"),
      excluded_candidate_sources = paste(cfg$causal_governance$excluded_candidate_sources,collapse=";"),
      glmnet_unpenalized_Q_pi_auxiliary = "A",
      glmnet_unpenalized_actual_g = "none",
      cap_priority_version = "protected;A_and_Y_lasso;joint_AY;Y_lasso;delta_lasso;marginal_Y;marginal_delta;A_lasso;A_only",
      q_library = paste(vapply(as.list(lib_Q_fit),paste,character(1),collapse="_"),collapse=";"),
      broad_Q_processed_columns = if (is.null(Q_broad_pack)) 0L else ncol(Q_broad_pack$train),
      residual_Q_enabled = residual_Q_on,
      residual_Q_pilot_max_raw = cfg$final_tmle$residual_Q_pilot_max_raw %||% NA_integer_,
      residual_Q_add_max_raw = cfg$final_tmle$residual_Q_add_max_raw %||% NA_integer_,
      residual_Q_max_processed = cfg$final_tmle$residual_Q_max_processed %||% NA_integer_,
      residual_Q_validation = "outer_screen_fixed_design_inner_PSU_CV",
      residual_Q_pilot_source = "existing_Q_inner_base_predictions_outer_training_mixture",
      residual_Q_separate_pilot_fitted = FALSE,
      g_library = paste(lib_g, collapse = ";"),
      pi_library = paste(lib_pi, collapse = ";"),
      fixed_xgboost_settings = paste(names(unlist(cfg$learners$xgboost)), unlist(cfg$learners$xgboost), sep = "=", collapse = ";"),
      q_xgboost_rich_settings = paste(names(unlist(cfg$learners$xgboost_rich)), unlist(cfg$learners$xgboost_rich), sep = "=", collapse = ";"),
      glmnet_settings = paste(names(unlist(cfg$learners$glmnet)), unlist(cfg$learners$glmnet), sep = "=", collapse = ";"),
      g_h1fs_penalty_multiplier = cfg$learners$glmnet_h1fs$h1fs_penalty_multiplier %||% NA_real_,
      pi_A_penalty_multiplier = cfg$learners$glmnet_pi_A$A_penalty_multiplier %||% NA_real_,
      # v8.37 provenance for the sensitivities added in this version.
      pi_alt_library = if (is.null(lib_pi_alt)) NA_character_ else paste(lib_pi_alt, collapse = ";"),
      pi_dual_fit_A_unpenalized = isTRUE(cfg$learners$pi$dual_fit_A_unpenalized %||% FALSE),
      g_lower_configured = cfg$final_tmle$g_lower_configured,
      g_lower_used = cfg$final_tmle$g_lower,
      g_lower_rule = cfg$final_tmle$g_lower_rule %||% "fixed",
      g_upper_configured = cfg$final_tmle$g_upper,
      # Gruber, Phillips, Lee & van der Laan (Am J Epidemiol 2022;191:1640-1651)
      # sample-size-based lower bound, computed on OBSERVED outcomes as that
      # paper directs. The sample_size rule uses this as the primary lower bound.
      g_lower_sample_size_bound = (as.numeric(
        cfg$diagnostics$att_g_clip_sample_size_constant %||% 5)) /
        (sqrt(sum(delta_Y == 1L)) * log(sum(delta_Y == 1L))),
      g_lower_sample_size_bound_n_observed_outcomes = sum(delta_Y == 1L),
      g_lower_sample_size_bound_reference =
        "Gruber Phillips Lee van der Laan 2022 AJE 191:1640-1651; c/(sqrt(n)*log(n)), c=5, n=observed outcomes",
      structural_zero_n = sum(structural_zero),
      structural_zero_source = paste(sort(unique(structural_zero_source[structural_zero])),collapse=";"),
      observation_model = "sequential_composite",
      composite_scope = observation$scope,
      cap_inference_method = cap_inference$method,
      run_label = cfg$global$run_label %||% NA_character_,
      outcome_definition = cfg$provenance$outcome_definition %||% configured_outcome_definition(cfg),
      outer_fold_balance = if (isTRUE(cfg$final_tmle$outer_fold_balance_on_weights))
        "size_first_weighted_treatment_with_hard_A_delta_support" else "size_first_raw_treatment_with_hard_A_delta_support",
      internal_fold_balance = if (isTRUE(cfg$final_tmle$internal_fold_balance_on_weights))
        "size_first_weighted_treatment_with_hard_A_delta_support" else "size_first_raw_treatment_with_hard_A_delta_support",
      fold = v,
      treated_train = sum(A[tr] == 1L),
      treated_valid = sum(A[te] == 1L),
      observed_treated_train = sum(A[tr] == 1L & delta_Y[tr] == 1L),
      observed_treated_valid = sum(A[te] == 1L & delta_Y[te] == 1L),
      clusters_valid = length(unique(cluster[te])),
      rows_valid = length(te),
      rows_train = length(tr),
      outer_fold_size_ratio = attr(outer_fold, "fold_diagnostics")$size_ratio %||% NA_real_,
      outer_fold_max_size_deviation_prop = attr(outer_fold, "fold_diagnostics")$size_deviation_prop %||% NA_real_,
      nonprotected_column_budget = column_budget_applied,
      n_selected_vars = length(sel_vars),
      n_raw_into_W = W_pack$n_raw,
      n_processed_cols = W_pack$n_processed,
      n_processed_cols_nonprotected = W_pack$n_processed_nonprotected,
      n_processed_cols_optional_budgeted = W_pack$n_processed_optional_budgeted,
      n_protected_cols = W_pack$n_protected_cols,
      n_mandatory_cols = W_pack$n_mandatory_cols,
      raw_treated_per_nonprotected_column = if (W_pack$n_processed_nonprotected > 0)
        sum(A[tr] == 1L) / W_pack$n_processed_nonprotected else NA_real_,
      raw_treated_per_optional_budgeted_column =
        if (W_pack$n_processed_optional_budgeted > 0)
          sum(A[tr] == 1L) / W_pack$n_processed_optional_budgeted else NA_real_,
      treated_ess_per_total_column_diagnostic = if (W_pack$n_processed > 0)
        kish_ess_safe(weights[tr][A[tr] == 1L]) / W_pack$n_processed else NA_real_,
      cap_binding = length(W_pack$dropped_by_column_cap) > 0L,
      ess_treated_train = kish_ess_safe(weights[tr][A[tr] == 1L]),
      stringsAsFactors = FALSE)
    
    A_tr <- A[tr]; A_te <- A[te]
    Y_star_tr <- Y_star[tr]; delta_tr <- delta_response[tr]
    pi_idx <- which(eligibility[tr]==1L)
    delta_pi <- delta_Y[tr][pi_idx]; A_pi <- A_tr[pi_idx]
    w_pi <- weights[tr][pi_idx]; cl_pi <- cluster[tr][pi_idx]
    w_tr <- weights[tr]; cl_tr <- cluster[tr]
    
    # Internal CV folds are always whole-PSU. Q and g require treatment support;
    # pi additionally balances treatment-by-outcome-observation cells. No fold uses continuous outcome values.
    V_int <- cfg$final_tmle$internal_superlearner_folds
    lcfg_nfolds <- as.integer(cfg$learners$glmnet$internal_folds %||% 5L)
    if (lcfg_nfolds < 3L) stop("learners$glmnet$internal_folds must be at least 3.", call. = FALSE)
    validRows_Q  <- build_cluster_valid_rows(cl_tr[delta_tr == 1L],
                                             A_tr[delta_tr == 1L],
                                             V_int, base_seed + v,
                                             weights = w_tr[delta_tr == 1L],
                                             delta = rep(1L, sum(delta_tr == 1L)),
                                             balance_on_weights = isTRUE(cfg$final_tmle$internal_fold_balance_on_weights),
                                             fold_control = fold_control_from_cfg(cfg, "internal"))
    validRows_g  <- build_cluster_valid_rows(cl_tr, A_tr, V_int, base_seed + v + 100L,
                                             weights = w_tr, delta = rep(1L, length(A_tr)),
                                             balance_on_weights = isTRUE(cfg$final_tmle$internal_fold_balance_on_weights),
                                             fold_control = fold_control_from_cfg(cfg, "internal"))
    validRows_pi <- build_cluster_valid_rows(cl_pi, A_pi, V_int, base_seed + v + 200L,
                                             weights = w_pi, delta = delta_pi,
                                             balance_on_weights = isTRUE(cfg$final_tmle$internal_fold_balance_on_weights),
                                             fold_control = fold_control_from_cfg(cfg, "internal"))
    cvQ  <- list(V = length(validRows_Q),  validRows = validRows_Q,  stratifyCV = FALSE, shuffle = FALSE)
    cvg  <- list(V = length(validRows_g),  validRows = validRows_g,  stratifyCV = FALSE, shuffle = FALSE)
    cvpi <- list(V = length(validRows_pi), validRows = validRows_pi, stratifyCV = FALSE, shuffle = FALSE)
    msg(sprintf("    [fold %d] Internal SL folds: Q=%d, g=%d, pi=%d.",
                v, length(validRows_Q), length(validRows_g), length(validRows_pi)), cfg = cfg)
    warn_internal_valid_rows(validRows_Q, A_tr[delta_tr == 1L], "Q", cfg, v,
                             delta_vec = rep(1L, sum(delta_tr == 1L)), weights = w_tr[delta_tr == 1L])
    warn_internal_valid_rows(validRows_g, A_tr, "g", cfg, v, delta_vec = rep(1L, length(A_tr)), weights = w_tr)
    warn_internal_valid_rows(validRows_pi, A_pi, "pi", cfg, v, delta_vec = delta_pi, weights = w_pi)
    internal_fold_support_log[[paste0(v, "_Q")]] <- make_internal_fold_support(
      validRows_Q, A_tr[delta_tr == 1L], rep(1L, sum(delta_tr == 1L)),
      w_tr[delta_tr == 1L], "Q", v)
    internal_fold_support_log[[paste0(v, "_g")]] <- make_internal_fold_support(
      validRows_g, A_tr, rep(1L, length(A_tr)), w_tr, "g", v)
    internal_fold_support_log[[paste0(v, "_pi")]] <- make_internal_fold_support(
      validRows_pi, A_pi, delta_pi, w_pi, "pi", v)
    
    .SL_RUNTIME_ENV$h1fs_processed_columns <- names(W_tr)[
      W_pack$processed_raw_map[names(W_tr)] %in% (resolve_protected_W(cfg))]
    if (isTRUE(cfg$learners$g$use_glmnet_h1fs %||% FALSE) &&
        length(.SL_RUNTIME_ENV$h1fs_processed_columns) != W_pack$n_protected_cols)
      stop(sprintf("Fold %d H1FS penalty mapping mismatch: mapped %d columns, expected %d.",
                   v, length(.SL_RUNTIME_ENV$h1fs_processed_columns), W_pack$n_protected_cols), call. = FALSE)
    
    # --- Fit Q on rows with observed outcome --------------------------------
    idx_obs <- which(delta_tr == 1L)
    msg(sprintf("    [fold %d] Fitting Q on %d outcome-observed training rows...", v, length(idx_obs)), cfg = cfg)
    t_Q <- proc.time()[3]
    # v6 Fix B: data.frame (not cbind) guarantees a data.frame result.
    # cbind(vector, data.frame) can return a matrix under R's method dispatch,
    # which breaks earth's formula path and other learners that call model.frame.
    X_Q_tr  <- data.frame(A = A_tr, W_tr, check.names = FALSE)[idx_obs, , drop = FALSE]
    X_Q_te_A1 <- data.frame(A = rep(1L, length(te)), W_te, check.names = FALSE)
    X_Q_te_A0 <- data.frame(A = rep(0L, length(te)), W_te, check.names = FALSE)
    X_Q_te_AA <- data.frame(A = A_te,                W_te, check.names = FALSE)
    if (!is.null(Q_broad_pack)) {
      X_Q_tr <- cbind(X_Q_tr,Q_broad_pack$train[idx_obs,,drop=FALSE])
      X_Q_te_A1 <- cbind(X_Q_te_A1,Q_broad_pack$valid)
      X_Q_te_A0 <- cbind(X_Q_te_A0,Q_broad_pack$valid)
      X_Q_te_AA <- cbind(X_Q_te_AA,Q_broad_pack$valid)
    }
    Q_fit <- tryCatch(with_sl_glmnet_context(
      "Q", base_seed + v + 10000L, lcfg_nfolds,
      with_local_seed(base_seed + v + 30000L,
                      SuperLearner::SuperLearner(
                        Y = Y_star_tr[idx_obs], X = X_Q_tr,
                        newX = rbind(X_Q_te_A1, X_Q_te_A0, X_Q_te_AA),
                        family = if (identical(data_pack$outcome_type, "binary")) stats::binomial() else stats::gaussian(),
                        SL.library = lib_Q_fit,
                        obsWeights = w_tr[idx_obs], id = as.character(cl_tr[idx_obs]),
                        cvControl = cvQ,
                        control = list(saveFitLibrary = TRUE, saveCVFitLibrary = FALSE),
                        verbose = FALSE))),
      error = function(e) { warning("Q SuperLearner failed: ", conditionMessage(e)); NULL })
    n_te <- length(te)
    q_lo <- cfg$final_tmle$Q_pred_lower %||% 0.005
    q_hi <- cfg$final_tmle$Q_pred_upper %||% 0.995
    if (is.null(Q_fit)) {
      if (residual_Q_on) stop("Residual-Q augmentation requires a successful baseline Q ensemble.")
      if (isTRUE(cfg$final_tmle$fail_on_nuisance_fallback %||% FALSE))
        stop(sprintf("Fold %d Q SuperLearner failed; strict production mode forbids fallback.", v), call. = FALSE)
      ybar <- stats::weighted.mean(Y_star_tr[idx_obs], w_tr[idx_obs], na.rm = TRUE)
      raw_mean <- rep(ybar, n_te)
      Qbar1W_v <- pmin(pmax(raw_mean, q_lo), q_hi)
      Qbar0W_v <- Qbar1W_v
      QbarAW_v <- Qbar1W_v
      q_fallback <- TRUE
      q_clip_log[[v]] <- rbind(
        summarize_prediction_clipping(raw_mean, q_lo, q_hi, v, "Q1W_fallback"),
        summarize_prediction_clipping(raw_mean, q_lo, q_hi, v, "Q0W_fallback"),
        summarize_prediction_clipping(raw_mean, q_lo, q_hi, v, "QAW_fallback"))
      Q_core_predictions[te,] <- cbind(Qbar1W_v,Qbar0W_v,QbarAW_v)
      q_coef <- numeric(0); q_risk <- numeric(0)
      msg(sprintf("      [fold %d] Q FALLBACK to grand mean %.4f (SL failed).", v, ybar), cfg = cfg)
    } else {
      assert_superlearner_fit(Q_fit, lib_Q_fit, "Q", v, 3L * n_te)
      # Bound the held-out ensemble predictions before they enter the
      # logit-fluctuation step. Gaussian-loss learners can predict outside
      # [0,1]; this post-fit bound stabilizes qlogis. SuperLearner CV risks are
      # computed before this bound, so the clipping fraction is logged as a
      # separate diagnostic rather than treated as part of meta-learning.
      preds <- as.numeric(Q_fit$SL.predict)
      if (length(preds) != 3L * n_te || any(!is.finite(preds)))
        stop(sprintf("Fold %d Q returned %d predictions; expected %d finite values.", v, length(preds), 3L * n_te), call. = FALSE)
      core_preds <- if (!is.null(Q_broad_pack))
        core_Q_predictions(Q_fit,Y_star_tr[idx_obs],w_tr[idx_obs])$pred else preds
      Q_core_predictions[te,] <- matrix(pmin(pmax(core_preds,q_lo),q_hi),ncol=3L)
      Q_aug <- NULL
      if (residual_Q_on) {
        Q_without_residual_predictions[te,] <- matrix(pmin(pmax(preds,q_lo),q_hi),ncol=3L)
        Q_aug <- with_local_seed(base_seed+v+610000L,
          augment_Q_with_residual_candidate(Q_fit,main_df,tr,te,idx_obs,
            Y_star_tr[idx_obs],validRows_Q,cfg,base_seed+v+620000L,v,
            family=if (identical(data_pack$outcome_type,"binary")) stats::binomial() else stats::gaussian(),
            Q_broad_pack=Q_broad_pack))
        preds <- Q_aug$pred
        Q_residual_candidate_predictions[te,] <- matrix(pmin(pmax(Q_aug$candidate_pred,q_lo),q_hi),ncol=3L)
        residual_Q_audit_by_fold[[v]] <- list(selection=Q_aug$selection,info=Q_aug$info)
        residual_Q_training_by_fold[[v]] <- Q_aug$training
        run_manifest_rows[[v]]$residual_Q_weight <- unname(tail(Q_aug$coef,1L))
        run_manifest_rows[[v]]$residual_Q_seconds <- sum(Q_aug$info$seconds)
        run_manifest_rows[[v]]$q_library <- paste(c(Q_fit$libraryNames,"SL.glmnet.residual_Q_All"),collapse=";")
      }
      pred_q1 <- preds[1:n_te]
      pred_q0 <- preds[(n_te+1):(2*n_te)]
      pred_qa <- preds[(2*n_te+1):(3*n_te)]
      q_clip_log[[v]] <- rbind(
        summarize_prediction_clipping(pred_q1, q_lo, q_hi, v, "Q1W"),
        summarize_prediction_clipping(pred_q0, q_lo, q_hi, v, "Q0W"),
        summarize_prediction_clipping(pred_qa, q_lo, q_hi, v, "QAW"),
        summarize_prediction_clipping(preds, q_lo, q_hi, v, "pooled"))
      n_clip_q <- q_clip_log[[v]]$n_clipped[q_clip_log[[v]]$prediction_set == "pooled"]
      Qbar1W_v <- pmin(pmax(pred_q1, q_lo), q_hi)
      Qbar0W_v <- pmin(pmax(pred_q0, q_lo), q_hi)
      QbarAW_v <- pmin(pmax(pred_qa, q_lo), q_hi)
      q_fallback <- FALSE
      q_coef <- if (is.null(Q_aug)) Q_fit$coef else Q_aug$coef
      q_risk <- if (is.null(Q_aug)) Q_fit$cvRisk else Q_aug$cvRisk
      top_q <- names(q_coef)[which.max(q_coef)]
      msg(sprintf("      [fold %d] Q fit in %.1fs. Top learner: %s (weight=%.3f). Qbar1W in [%.3f, %.3f].",
                  v, proc.time()[3] - t_Q, top_q, max(q_coef),
                  min(Qbar1W_v), max(Qbar1W_v)), cfg = cfg)
      msg(sprintf("      [fold %d] Q predictions: %d of %d (%.1f%%) hit a bound and were clipped to [%.3f, %.3f].",
                  v, n_clip_q, length(preds), 100 * n_clip_q / length(preds),
                  q_lo, q_hi), cfg = cfg)
    }
    
    # --- Fit g (propensity) -----------------------------------------------
    msg(sprintf("    [fold %d] Fitting g (propensity) on %d training rows...", v, length(tr)), cfg = cfg)
    t_g <- proc.time()[3]
    g_fit <- tryCatch(with_sl_glmnet_context(
      "g", base_seed + v + 11000L, lcfg_nfolds,
      with_local_seed(base_seed + v + 31000L,
                      SuperLearner::SuperLearner(
                        Y = A_tr, X = W_tr, newX = W_te, family = stats::binomial(),
                        SL.library = lib_g, obsWeights = w_tr, id = as.character(cl_tr),
                        cvControl = cvg,
                        control = list(saveFitLibrary = TRUE, saveCVFitLibrary = FALSE),
                        verbose = FALSE))),
      error = function(e) { warning("g SuperLearner failed: ", conditionMessage(e)); NULL })
    if (is.null(g_fit)) {
      if (isTRUE(cfg$final_tmle$fail_on_nuisance_fallback %||% FALSE))
        stop(sprintf("Fold %d g SuperLearner failed; strict production mode forbids fallback.", v), call. = FALSE)
      g_mean <- stats::weighted.mean(A_tr, w_tr)
      g_te <- rep(g_mean, n_te); g_fallback <- TRUE
      g_coef <- numeric(0); g_risk <- numeric(0)
      msg(sprintf("      [fold %d] g FALLBACK to weighted mean(A)=%.3f (SL failed).", v, g_mean), cfg = cfg)
    } else {
      assert_superlearner_fit(g_fit, lib_g, "g", v, n_te)
      g_te <- as.numeric(g_fit$SL.predict)
      if (length(g_te) != n_te || any(!is.finite(g_te)))
        stop(sprintf("Fold %d g returned invalid held-out predictions.", v), call. = FALSE)
      g_fallback <- FALSE
      g_coef <- g_fit$coef; g_risk <- g_fit$cvRisk
      top_g <- names(g_coef)[which.max(g_coef)]
      msg(sprintf("      [fold %d] g fit in %.1fs. Top learner: %s (weight=%.3f).",
                  v, proc.time()[3] - t_g, top_g, max(g_coef)), cfg = cfg)
    }
    gn_uncalibrated[te] <- g_te
    calibration_training_by_fold[[v]] <- list(g=capture_calibration_training(
      g_fit,A_tr,w_tr,respondent_ids[tr],cl_tr,v))
    fold_calibration <- list()
    if (isTRUE(cfg$analysis$calibrate_g)) {
      if (is.null(g_fit)) stop("Cannot calibrate a failed g fit.", call. = FALSE)
      cal <- calibrate_outer_predictions(g_fit, A_tr, w_tr, g_te,
                                         cfg$analysis$g_calibration_method %||% "platt", v, "g",
                                         bounds = c(cfg$final_tmle$g_lower, cfg$final_tmle$g_upper),
                                         candidates = cfg$analysis$g_calibration_candidates %||% c("identity", "platt"))
      g_te <- cal$prediction; fold_calibration$g <- cal$audit
      calibration_training_by_fold[[v]]$g$calibrator <- cal$object
    }
    g_te_preclip <- g_te
    gn_raw[te] <- g_te_preclip
    g_te <- pmin(pmax(g_te, cfg$final_tmle$g_lower), cfg$final_tmle$g_upper)
    n_clip <- sum(g_te != g_te_preclip)
    msg(sprintf("      [fold %d] g predictions: range=[%.3f, %.3f], %d of %d clipped to [%g, %g].",
                v, min(g_te), max(g_te), n_clip, n_te, cfg$final_tmle$g_lower, cfg$final_tmle$g_upper), cfg = cfg)
    
    # --- Fit pi (response | A, W, eligibility=1) ---------------------------------
    msg(sprintf("    [fold %d] Fitting pi (response | A,W,S=1)...", v), cfg = cfg)
    t_pi <- proc.time()[3]
    # v6 Fix B: data.frame guarantees a data.frame; see Q block above.
    X_pi_tr    <- data.frame(A = A_tr, W_tr, check.names = FALSE)[pi_idx,,drop=FALSE]
    X_pi_te_A1 <- data.frame(A = rep(1L, n_te),     W_te, check.names = FALSE)
    X_pi_te_A0 <- data.frame(A = rep(0L, n_te),     W_te, check.names = FALSE)
    X_pi_te_AA <- data.frame(A = A_te,              W_te, check.names = FALSE)
    pi_deterministic <- FALSE
    pi_fit <- NULL
    if (all(delta_pi == 1L)) {
      pi_1W_v <- rep(1, n_te); pi_0W_v <- rep(1, n_te); pi_AW_v <- rep(1, n_te)
      pi_fallback <- FALSE; pi_deterministic <- TRUE
      pi_coef <- c(deterministic_all_observed = 1)
      pi_risk <- c(deterministic_all_observed = 0)
      msg(sprintf("      [fold %d] pi is deterministically one because all training outcomes are observed.", v), cfg = cfg)
    } else if (all(delta_pi == 0L)) {
      stop(sprintf("Fold %d has no observed training outcomes; Q and pi are unidentified.", v),
           call. = FALSE)
    } else {
      pi_fit <- tryCatch(with_sl_glmnet_context(
        "pi", base_seed + v + 12000L, lcfg_nfolds,
        with_local_seed(base_seed + v + 32000L,
                        SuperLearner::SuperLearner(
                          Y = delta_pi, X = X_pi_tr,
                          newX = rbind(X_pi_te_A1, X_pi_te_A0, X_pi_te_AA),
                          family = stats::binomial(), SL.library = lib_pi,
                          obsWeights = w_pi, id = as.character(cl_pi),
                          cvControl = cvpi,
                          control = list(saveFitLibrary = TRUE, saveCVFitLibrary = FALSE),
                          verbose = FALSE))),
        error = function(e) { warning("pi SuperLearner failed: ", conditionMessage(e)); NULL })
      if (is.null(pi_fit)) {
        if (isTRUE(cfg$final_tmle$fail_on_nuisance_fallback %||% FALSE))
          stop(sprintf("Fold %d pi SuperLearner failed; strict production mode forbids fallback.", v), call. = FALSE)
        p <- stats::weighted.mean(delta_pi, w_pi)
        pi_1W_v <- rep(p, n_te); pi_0W_v <- rep(p, n_te); pi_AW_v <- rep(p, n_te)
        pi_fallback <- TRUE
        pi_coef <- numeric(0); pi_risk <- numeric(0)
        msg(sprintf("      [fold %d] pi FALLBACK to mean(delta_Y)=%.3f (SL failed).", v, p), cfg = cfg)
      } else {
        assert_superlearner_fit(pi_fit, lib_pi, "pi", v, 3L * n_te)
        preds <- as.numeric(pi_fit$SL.predict)
        if (length(preds) != 3L * n_te || any(!is.finite(preds)))
          stop(sprintf("Fold %d pi returned %d predictions; expected %d finite values.", v, length(preds), 3L * n_te), call. = FALSE)
        pi_blocks <- extract_pi_counterfactual_blocks(preds, n_te)
        pi_1W_v <- pi_blocks$pi_1W
        pi_0W_v <- pi_blocks$pi_0W
        pi_AW_v <- pi_blocks$pi_AW
        pi_fallback <- FALSE
        pi_coef <- pi_fit$coef; pi_risk <- pi_fit$cvRisk
        top_pi <- names(pi_coef)[which.max(pi_coef)]
        msg(sprintf("      [fold %d] pi fit in %.1fs. Top learner: %s (weight=%.3f).",
                    v, proc.time()[3] - t_pi, top_pi, max(pi_coef)), cfg = cfg)
      }
    }
    pi_AW_uncalibrated[te] <- pi_AW_v
    pi_1W_uncalibrated[te] <- pi_1W_v
    pi_0W_uncalibrated[te] <- pi_0W_v
    calibration_training_by_fold[[v]]$pi <- capture_calibration_training(
      pi_fit,delta_pi,w_pi,respondent_ids[tr][pi_idx],cl_pi,v,
      constant=if (pi_deterministic) 1 else NULL)
    if (isTRUE(cfg$analysis$calibrate_pi) && !pi_deterministic) {
      if (is.null(pi_fit)) stop("Cannot calibrate a failed pi fit.", call. = FALSE)
      cal <- calibrate_outer_predictions(pi_fit, delta_pi, w_pi,
                                         c(pi_1W_v, pi_0W_v, pi_AW_v),
                                         cfg$analysis$pi_calibration_method %||% "platt", v, "pi",
                                         bounds = c(cfg$final_tmle$pi_lower, cfg$final_tmle$pi_upper),
                                         candidates = cfg$analysis$pi_calibration_candidates %||% c("identity", "platt"))
      blocks <- extract_pi_counterfactual_blocks(cal$prediction, n_te)
      pi_1W_v <- blocks$pi_1W; pi_0W_v <- blocks$pi_0W; pi_AW_v <- blocks$pi_AW
      fold_calibration$pi <- cal$audit
      calibration_training_by_fold[[v]]$pi$calibrator <- cal$object
    }
    if (length(fold_calibration)) calibration_log[[v]] <- do.call(rbind, fold_calibration)
    # Preserve active calibrated, pre-clipping held-out probabilities for the
    # post-fit g/pi clipping sensitivity. Uncalibrated scores are kept separately.
    # sensitivity sweep, then apply the primary configured bounds.
    pi_1W_raw[te] <- pi_1W_v
    pi_0W_raw[te] <- pi_0W_v
    pi_AW_raw[te] <- pi_AW_v
    
    # --- v8.37: ALTERNATE pi fit (A unpenalized in glmnet) -------------------
    # Same training rows, same internal CV folds, same seeds, same calibration
    # rule; the ONLY difference is the library. Its predictions are stored for a
    # retargeted sensitivity row and never touch the primary estimate. A failure
    # here degrades the sensitivity, not the run, so it warns instead of
    # stopping and leaves NA that downstream diagnostics detect.
    if (!is.null(lib_pi_alt)) {
      tryCatch({
        if (pi_deterministic) {
          pi_1W_alt_raw[te] <- 1; pi_0W_alt_raw[te] <- 1; pi_AW_alt_raw[te] <- 1
          pi_alt_status[v] <- "deterministic_all_observed"
        } else {
          t_pi_alt <- proc.time()[3]
          pi_alt_fit <- tryCatch(with_sl_glmnet_context(
            "pi", base_seed + v + 12000L, lcfg_nfolds,
            with_local_seed(base_seed + v + 32000L,
                            SuperLearner::SuperLearner(
                              Y = delta_pi, X = X_pi_tr,
                              newX = rbind(X_pi_te_A1, X_pi_te_A0, X_pi_te_AA),
                              family = stats::binomial(), SL.library = lib_pi_alt,
                              obsWeights = w_pi, id = as.character(cl_pi),
                              cvControl = cvpi,
                              control = list(saveFitLibrary = TRUE, saveCVFitLibrary = FALSE),
                              verbose = FALSE))),
            error = function(e) {
              warning("Alternate pi SuperLearner failed: ", conditionMessage(e)); NULL })
          if (is.null(pi_alt_fit)) {
            pi_alt_status[v] <- "fit_failed"
            msg(sprintf("      [fold %d] ALTERNATE pi fit FAILED; sensitivity row will be skipped.", v), cfg = cfg)
          } else {
            assert_superlearner_fit(pi_alt_fit, lib_pi_alt, "pi_alt", v, 3L * n_te)
            preds_alt <- as.numeric(pi_alt_fit$SL.predict)
            if (length(preds_alt) != 3L * n_te || any(!is.finite(preds_alt)))
              stop(sprintf("Fold %d alternate pi returned %d predictions; expected %d finite values.",
                           v, length(preds_alt), 3L * n_te), call. = FALSE)
            blocks_alt <- extract_pi_counterfactual_blocks(preds_alt, n_te)
            pi_1W_alt_v <- blocks_alt$pi_1W
            pi_0W_alt_v <- blocks_alt$pi_0W
            pi_AW_alt_v <- blocks_alt$pi_AW
            if (isTRUE(cfg$analysis$calibrate_pi)) {
              cal_alt <- calibrate_outer_predictions(pi_alt_fit, delta_pi, w_pi,
                                                     c(pi_1W_alt_v, pi_0W_alt_v, pi_AW_alt_v),
                                                     cfg$analysis$pi_calibration_method %||% "platt", v, "pi_alt",
                                                     bounds = c(cfg$final_tmle$pi_lower, cfg$final_tmle$pi_upper),
                                                     candidates = cfg$analysis$pi_calibration_candidates %||% c("identity", "platt"))
              b <- extract_pi_counterfactual_blocks(cal_alt$prediction, n_te)
              pi_1W_alt_v <- b$pi_1W; pi_0W_alt_v <- b$pi_0W; pi_AW_alt_v <- b$pi_AW
            }
            pi_1W_alt_raw[te] <- pi_1W_alt_v
            pi_0W_alt_raw[te] <- pi_0W_alt_v
            pi_AW_alt_raw[te] <- pi_AW_alt_v
            pi_alt_status[v] <- "fitted"
            alt_coef <- pi_alt_fit$coef
            names(alt_coef) <- sub("_All$","",names(alt_coef))
            alt_w <- if ("SL.glmnet.pi_A_unpenalized" %in% names(alt_coef))
              unname(alt_coef[["SL.glmnet.pi_A_unpenalized"]]) else NA_real_
            msg(sprintf(paste0("      [fold %d] alternate pi fit in %.1fs. Unpenalized-A learner weight=%.3f. ",
                               "max|pi1-pi0| primary=%.3e, alternate=%.3e."),
                        v, proc.time()[3] - t_pi_alt, alt_w,
                        max(abs(pi_1W_v - pi_0W_v)), max(abs(pi_1W_alt_v - pi_0W_alt_v))), cfg = cfg)
          }
        }
      },error=function(e) {
        pi_AW_alt_raw[te] <<- NA_real_; pi_1W_alt_raw[te] <<- NA_real_; pi_0W_alt_raw[te] <<- NA_real_
        pi_alt_status[v] <<- paste0("failed: ",conditionMessage(e))
        warning("Optional alternate pi skipped in fold ",v,": ",conditionMessage(e),call.=FALSE)
      })
    } else {
      pi_alt_status[v] <- "disabled"
    }
    # Both-sided clipping (v5)
    pi_1W_v <- pmin(pmax(pi_1W_v, cfg$final_tmle$pi_lower), cfg$final_tmle$pi_upper)
    pi_0W_v <- pmin(pmax(pi_0W_v, cfg$final_tmle$pi_lower), cfg$final_tmle$pi_upper)
    pi_AW_v <- pmin(pmax(pi_AW_v, cfg$final_tmle$pi_lower), cfg$final_tmle$pi_upper)
    
    # Overlap-product diagnostics: the real positivity quantity for TMLE+censoring.
    op_1 <- g_te * pi_1W_v
    op_0 <- (1 - g_te) * pi_0W_v
    pos_thr <- cfg$final_tmle$positivity_warning_threshold
    frac_low_1 <- mean(op_1 < pos_thr)
    frac_low_0 <- mean(op_0 < pos_thr)
    msg(sprintf("      [fold %d] Overlap products: g*pi1 in [%.3f, %.3f] (%.1f%% < %g); (1-g)*pi0 in [%.3f, %.3f] (%.1f%% < %g).",
                v, min(op_1), max(op_1), 100 * frac_low_1, pos_thr,
                min(op_0), max(op_0), 100 * frac_low_0, pos_thr), cfg = cfg)
    if (frac_low_1 > cfg$final_tmle$positivity_warning_fraction ||
        frac_low_0 > cfg$final_tmle$positivity_warning_fraction) {
      warning(sprintf(
        paste0("Fold %d ATE overlap-product screen: %.1f%% (g*pi1) or %.1f%% ((1-g)*pi0) below %g. ",
               "For the ATT, evaluate control support for the treated population and censoring weights; ",
               "a small g*pi1 alone is not an ATT support failure."),
        v, 100 * frac_low_1, 100 * frac_low_0, pos_thr))
    }
    
    # Eligibility is integrated under each exposure, not added to baseline W.
    new_aux <- rbind(X_Q_te_A1,X_Q_te_A0,X_Q_te_AA)[,c("A",names(W_te)),drop=FALSE]
    es <- fit_binary_auxiliary(eligibility[tr],data.frame(A=A_tr,W_tr,check.names=FALSE),
                               new_aux,w_tr,cl_tr,A_tr,cfg,base_seed+v+41000L,"eligibility",v)
    eb <- extract_pi_counterfactual_blocks(es$prediction,n_te)
    S1W[te] <- eb$pi_1W; S0W[te] <- eb$pi_0W
    run_manifest_rows[[v]]$eligibility_fit_status <- es$status
    run_manifest_rows[[v]]$cap_tail_fit_status <- "not_needed"
    if (tail_needed) {
      ts <- fit_binary_auxiliary(tail_outcome[tr][idx_obs],X_Q_tr[,names(new_aux),drop=FALSE],new_aux,
                                 w_tr[idx_obs],cl_tr[idx_obs],A_tr[idx_obs],cfg,base_seed+v+42000L,"cap_tail",v)
      tb <- extract_pi_counterfactual_blocks(ts$prediction,n_te)
      tail_Q1W[te] <- tb$pi_1W; tail_Q0W[te] <- tb$pi_0W
      run_manifest_rows[[v]]$cap_tail_fit_status <- ts$status
    }
    if (isTRUE(cfg$diagnostics$persist_diagnostic_W_design)) {
      wall <- rbind(W_tr,W_te)[order(c(tr,te)),,drop=FALSE]
      rownames(wall) <- respondent_ids
      diagnostic_W_by_fold[[v]] <- list(W=wall,protected_columns=.SL_RUNTIME_ENV$h1fs_processed_columns,
                                        train_idx=tr,valid_idx=te,selected_vars=sel_vars)
    }
    
    # Store held-out nuisance estimates
    Qbar1W[te] <- Qbar1W_v; Qbar0W[te] <- Qbar0W_v; QbarAW[te] <- QbarAW_v
    gn[te]     <- g_te
    pi_AW[te]  <- pi_AW_v; pi_1W[te] <- pi_1W_v; pi_0W[te] <- pi_0W_v
    
    # Per-fold assertions
    stopifnot(all(is.finite(Qbar1W[te])), all(is.finite(Qbar0W[te])),
              all(is.finite(QbarAW[te])), all(is.finite(gn[te])),
              all(is.finite(pi_AW[te])), all(is.finite(pi_1W[te])),
              all(is.finite(pi_0W[te])))
    stopifnot(all(Qbar1W[te] > 0 & Qbar1W[te] < 1),
              all(Qbar0W[te] > 0 & Qbar0W[te] < 1))
    stopifnot(all(gn[te]    >= cfg$final_tmle$g_lower - 1e-10 &
                    gn[te]    <= cfg$final_tmle$g_upper + 1e-10))
    stopifnot(all(pi_AW[te] >= cfg$final_tmle$pi_lower - 1e-10 &
                    pi_AW[te] <= cfg$final_tmle$pi_upper + 1e-10))
    
    fold_times[v] <- proc.time()[3] - t0
    msg(sprintf("    [fold %d/%d DONE] total %.1fs.", v, V, fold_times[v]), cfg = cfg)
    
    # --- Per-fold SL log row -----------------------------------------------
    pack_named_metric <- function(nm, values, digits = 6L) {
      if (length(values) == 0L) return("")
      nm <- as.character(nm)
      if (length(nm) != length(values) || anyNA(nm) || any(!nzchar(nm)))
        nm <- paste0("learner", seq_along(values))
      fmt <- paste0("%.", as.integer(digits), "f")
      paste(paste0(nm, "=", sprintf(fmt, as.numeric(values))), collapse = ";")
    }
    weighted_loss <- function(y, p, w, family_name) {
      ww <- normalize_positive_weights(w, length(y), "outer validation loss")
      if (identical(family_name, "binomial")) {
        pc <- pmin(pmax(p, 1e-12), 1-1e-12)
        c(brier=sum(ww*(y-p)^2)/sum(ww), logloss=-sum(ww*(y*log(pc)+(1-y)*log(1-pc)))/sum(ww))
      } else c(mse=sum(ww*(y-p)^2)/sum(ww), logloss=NA_real_)
    }
    q_outer <- weighted_loss(Y_star[te][delta_response[te]==1L], QbarAW_v[delta_response[te]==1L], weights[te][delta_response[te]==1L],
                             if (identical(data_pack$outcome_type,"binary")) "binomial" else "gaussian")
    g_outer <- weighted_loss(A_te, g_te_preclip, weights[te], "binomial")
    epi <- eligibility[te]==1L
    pi_outer <- weighted_loss(delta_Y[te][epi], pi_AW_raw[te][epi], weights[te][epi], "binomial")
    g_outer_pre <- weighted_loss(A_te, gn_uncalibrated[te], weights[te], "binomial")
    pi_outer_pre <- weighted_loss(delta_Y[te][epi], pi_AW_uncalibrated[te][epi], weights[te][epi], "binomial")
    sl_log <- data.frame(
      fold = v,
      n_train = length(tr), n_valid = n_te,
      n_selected_vars = length(sel_vars),
      Q_fallback  = q_fallback,  Q_coef  = pack_named_metric(names(q_coef), q_coef, 3L),
      Q_cv_risk   = pack_named_metric(names(q_risk) %||% names(q_coef), q_risk, 6L),
      g_fallback  = g_fallback,  g_coef  = pack_named_metric(names(g_coef), g_coef, 3L),
      g_cv_risk   = pack_named_metric(names(g_risk) %||% names(g_coef), g_risk, 6L),
      pi_fallback = pi_fallback, pi_deterministic = pi_deterministic,
      pi_coef = pack_named_metric(names(pi_coef), pi_coef, 3L),
      pi_cv_risk  = pack_named_metric(names(pi_risk) %||% names(pi_coef), pi_risk, 6L),
      Q_outer_mse = unname(q_outer["mse"]), Q_outer_brier = unname(q_outer["brier"]),
      g_outer_brier = unname(g_outer["brier"]), g_outer_logloss = unname(g_outer["logloss"]),
      pi_outer_brier = unname(pi_outer["brier"]), pi_outer_logloss = unname(pi_outer["logloss"]),
      g_uncalibrated_outer_brier = unname(g_outer_pre["brier"]),
      g_uncalibrated_outer_logloss = unname(g_outer_pre["logloss"]),
      pi_uncalibrated_outer_brier = unname(pi_outer_pre["brier"]),
      pi_uncalibrated_outer_logloss = unname(pi_outer_pre["logloss"]),
      g_calibration = if (isTRUE(cfg$analysis$calibrate_g)) cfg$analysis$g_calibration_method else "none",
      pi_calibration = if (isTRUE(cfg$analysis$calibrate_pi)) cfg$analysis$pi_calibration_method else "none",
      fold_seconds = fold_times[v],
      stringsAsFactors = FALSE)
    per_fold_log[[v]] <- sl_log
    pooled_q_clip <- q_clip_log[[v]][q_clip_log[[v]]$prediction_set %in% c("pooled", "QAW_fallback"), , drop = FALSE]
    q_clip_fraction_fold <- if (nrow(pooled_q_clip)) max(pooled_q_clip$fraction_clipped) else 0
    run_manifest_rows[[v]]$q_clip_fraction <- q_clip_fraction_fold
    run_manifest_rows[[v]]$q_clip_review_required <-
      q_clip_fraction_fold >= (cfg$final_tmle$Q_clip_review_fraction %||% 0.05)
    if (q_clip_fraction_fold >= (cfg$final_tmle$Q_clip_warning_fraction %||% 0.01))
      warning(sprintf("Fold %d clipped %.2f%% of pooled held-out Q predictions.",
                      v, 100 * q_clip_fraction_fold), call. = FALSE)
    if (q_clip_fraction_fold >= (cfg$final_tmle$Q_clip_review_fraction %||% 0.05) &&
        isTRUE(cfg$safety$fail_on_q_clip_review_threshold %||% FALSE))
      stop(sprintf("Fold %d exceeded the configured Q-clipping review threshold.", v), call. = FALSE)
    if (isTRUE(cfg$final_tmle$fail_on_nuisance_fallback %||% FALSE) &&
        (isTRUE(q_fallback) || isTRUE(g_fallback) || isTRUE(pi_fallback))) {
      stop(sprintf("Fold %d used a nuisance fallback (Q=%s, g=%s, pi=%s). Set fail_on_nuisance_fallback=FALSE to allow this diagnostic run.",
                   v, q_fallback, g_fallback, pi_fallback), call. = FALSE)
    }
    
    if (isTRUE(cfg$final_tmle$use_fold_checkpoints)) {
      atomic_save_rds(list(
        S1W=S1W[te],S0W=S0W[te],tail_Q1W=tail_Q1W[te],tail_Q0W=tail_Q0W[te],
        diagnostic_W_design=diagnostic_W_by_fold[[v]],
        valid_idx = te, Qbar1W = Qbar1W_v, Qbar0W = Qbar0W_v, QbarAW = QbarAW_v,
        gn = g_te, pi_AW = pi_AW_v, pi_1W = pi_1W_v, pi_0W = pi_0W_v,
        gn_raw = g_te_preclip, pi_AW_raw = pi_AW_raw[te],
        gn_uncalibrated = gn_uncalibrated[te], pi_AW_uncalibrated = pi_AW_uncalibrated[te],
        calibration_audit = calibration_log[[v]] %||% NULL,
        calibration_training = calibration_training_by_fold[[v]],
        Q_core_predictions = Q_core_predictions[te,,drop=FALSE],
        broad_Q_audit = broad_Q_audit_by_fold[[v]],
        Q_without_residual_predictions = if(residual_Q_on) Q_without_residual_predictions[te,,drop=FALSE] else NULL,
        Q_residual_candidate_predictions = if(residual_Q_on) Q_residual_candidate_predictions[te,,drop=FALSE] else NULL,
        residual_Q_audit = if(residual_Q_on) residual_Q_audit_by_fold[[v]] else NULL,
        residual_Q_training = if(residual_Q_on) residual_Q_training_by_fold[[v]] else NULL,
        pi_1W_uncalibrated = pi_1W_uncalibrated[te],
        pi_0W_uncalibrated = pi_0W_uncalibrated[te],
        pi_1W_raw = pi_1W_raw[te], pi_0W_raw = pi_0W_raw[te],
        pi_AW_alt_raw = pi_AW_alt_raw[te], pi_1W_alt_raw = pi_1W_alt_raw[te],
        pi_0W_alt_raw = pi_0W_alt_raw[te], pi_alt_status = pi_alt_status[v],
        sl_log = sl_log, fold_time = fold_times[v],
        selected_vars = sel_vars,
        protected_raw_to_processed = protected_mapping_by_fold[[v]],
        selection_table = nested_selection_log[[v]],
        cluster_assignments = if (exists("rough_sel") && !is.null(rough_sel$cluster_assignments))
          rough_sel$cluster_assignments else NULL,
        outer_support = fold_support_log[[v]],
        run_manifest_row = run_manifest_rows[[v]],
        q_clip_log = q_clip_log[[v]],
        internal_support = {
          nm_int <- grep(paste0("^", v, "_"), names(internal_fold_support_log), value = TRUE)
          if (length(nm_int)) do.call(rbind, internal_fold_support_log[nm_int]) else NULL
        },
        fingerprint = current_fp), fold_ck, overwrite = TRUE)
    }
    if (isTRUE(cfg$final_tmle$gc_after_fold %||% TRUE)) {
      rm(list = intersect(c("W_tr", "W_te", "W_pack", "Q_fit", "Q_aug", "g_fit", "pi_fit",
                            "pi_alt_fit",
                            "X_Q_tr_AW", "X_Q_te_A1", "X_Q_te_A0", "X_Q_te_AA",
                            "X_g_tr", "X_g_te", "X_pi_tr", "X_pi_te_A1",
                            "X_pi_te_A0", "X_pi_te_AA"), ls()), inherits = FALSE)
      invisible(gc(verbose = FALSE))
    }
  }
  
  q_clip_df <- if (length(q_clip_log)) do.call(rbind, q_clip_log) else data.frame()
  q_clip_primary <- if (nrow(q_clip_df))
    q_clip_df[q_clip_df$prediction_set %in% c("pooled", "QAW_fallback"), , drop = FALSE]
  else data.frame()
  q_clip_overall_fraction <- if (nrow(q_clip_primary) &&
                                 sum(q_clip_primary$n_predictions) > 0L)
    sum(q_clip_primary$n_clipped) / sum(q_clip_primary$n_predictions) else NA_real_
  q_clip_max_fold_fraction <- if (nrow(q_clip_primary) &&
                                  any(is.finite(q_clip_primary$fraction_clipped)))
    max(q_clip_primary$fraction_clipped[is.finite(q_clip_primary$fraction_clipped)])
  else NA_real_
  q_clip_review_required <- is.finite(q_clip_max_fold_fraction) &&
    q_clip_max_fold_fraction >= (cfg$final_tmle$Q_clip_review_fraction %||% 0.05)
  if (nrow(q_clip_df) && isTRUE(cfg$global$save_stage_csvs))
    write_run_csv(q_clip_df, cfg,
                  cfg$diagnostics$q_prediction_clipping_csv %||%
                    "q_prediction_clipping.csv")
  msg(sprintf("\n  [TMLE] All %d outer folds complete. Total fold wall time: %.1fs (mean %.1fs/fold).",
              V, sum(fold_times), mean(fold_times)), cfg = cfg)
  
  # ==========================================================================
  # Save the actual outer-fold designs; no pooled fit or additional recipe.
  diagnostic_W_design <- NULL
  diagnostic_W_vars <- sort(unique(unlist(selected_by_fold,use.names=FALSE)))
  # Calibration has already been learned exclusively within outer training
  # folds. Collect its audit; there is no pooled fit to final-sample labels.
  # ==========================================================================
  g_calibration_audit <- if (length(calibration_log)) do.call(rbind, calibration_log) else NULL
  
  # ==========================================================================
  # TMLE fluctuation step on held-out predictions (whole-sample).
  # ==========================================================================
  # Keep eligible Q separate from marginal composite predictions.
  Qeligible1W <- Qbar1W; Qeligible0W <- Qbar0W
  QeligibleAW <- ifelse(A==1L,Qeligible1W,Qeligible0W)
  Qbar1W <- S1W*Qeligible1W+(1-S1W)*(0-y_lower)/y_range
  Qbar0W <- S0W*Qeligible0W+(1-S0W)*(0-y_lower)/y_range
  QbarAW <- ifelse(A==1L,Qbar1W,Qbar0W)
  w_norm <- weights/mean(weights)
  cap_D <- cap_inference$D
  attr(cap_D,"cap") <- data_pack$cap_value; attr(cap_D,"tail_outcome") <- tail_outcome
  target_here <- function(estimand,domain=rep(TRUE,n),r1=pi_1W,r0=pi_0W) {
    target_composite_means(A,eligibility,delta_Y,Y_bounded_orig,weights,gn,r1,r0,
                           Qeligible1W,Qeligible0W,S1W,S0W,y_lower,y_range,cfg,estimand,domain,
                           cap_D,tail_Q1W,tail_Q0W)
  }
  ate_fit <- target_here("ate")
  Qstar1W_orig <- ate_fit$M1; Qstar0W_orig <- ate_fit$M0
  Qstar1W <- (Qstar1W_orig-y_lower)/y_range; Qstar0W <- (Qstar0W_orig-y_lower)/y_range
  Qbar1W_orig <- Qbar1W*y_range+y_lower
  Qbar0W_orig <- Qbar0W*y_range+y_lower
  QbarAW_orig <- QbarAW*y_range+y_lower
  psi_hat <- ate_fit$estimate; psi_plugin_initial <- ate_fit$plugin
  psi_aipw_initial <- ate_fit$onestep
  eps_hat <- max(abs(c(ate_fit$epsilon1,ate_fit$epsilon0)))
  ate_target <- list(normalized_score=max(ate_fit$score1,ate_fit$score0))
  idx_up <- which(delta_response==1L)
  
  # ==========================================================================
  # Positivity remediation -- ATT and overlap-trimmed ATE.
  # The full-sample ATE above requires overlap across the entire covariate
  # space. At 9% prevalence with a rich W, ~50% of rows had g*pi1 < 0.05
  # (treated-arm non-overlap), so E[Y(1)|W] is extrapolated where no treated
  # units exist. The ATT and trimmed ATE are BETTER-IDENTIFIED estimands,
  # reported as SECONDARY columns by default. They become the headline only
  # if cfg$final_tmle$primary_estimand is set to "att" or "trimmed".
  # --------------------------------------------------------------------------
  # ==========================================================================
  # ATT estimation on the configured bounded outcome scale.
  # We report an initial one-step AIPTW comparator and a canonical joint-component
  # CV-TMLE. The CV-TMLE separately targets mu1 = E[Y(1)|A=1] and
  # mu0 = E[Y(0)|A=1]. The ATT and any configured ratio translations are
  # smooth functions of these same targeted component means.
  att_estimate <- att_se <- att_eif_mean <- att_eif_mean_scaled <- NA_real_
  att_nocens_check <- NA_real_; att_components <- NULL
  att_tmle_estimate <- att_tmle_se <- att_tmle_ci_lower <- att_tmle_ci_upper <- NA_real_
  att_tmle_p_value <- att_tmle_G_star <- att_tmle_cf_under_control <- NA_real_
  att_tmle_eif_mean <- att_tmle_eif_mean_scaled <- NA_real_
  att_onestep_estimate <- att_onestep_se <- NA_real_
  att_plugin_estimate <- NA_real_
  eps_att <- eps_att_mu1 <- eps_att_mu0 <- NA_real_
  target_score_mu1 <- target_score_mu0 <- NA_real_
  mu1_att <- mu0_att <- NA_real_
  mu1_att_se <- mu0_att_se <- NA_real_
  pct_depression_effect <- pct_prevention_gain <- NA_real_
  pct_depression_se <- pct_prevention_se <- NA_real_
  pct_depression_ci <- pct_prevention_ci <- c(NA_real_, NA_real_)
  pct_depression_p <- pct_prevention_p <- NA_real_
  D_mu1 <- D_mu0 <- D_pct_depression <- D_pct_prevention <- rep(NA_real_, length(weights))
  natural_course_mean <- natural_course_mean_se <- NA_real_
  treatment_prevalence <- treatment_prevalence_se <- NA_real_
  att_prevalence_elasticity <- att_prevalence_elasticity_se <- NA_real_
  att_prevalence_elasticity_ci <- c(NA_real_, NA_real_)
  att_prevalence_elasticity_p <- NA_real_
  gain_per_prevented_case <- gain_per_prevented_case_se <- NA_real_
  gain_per_one_percentage_point <- gain_per_one_percentage_point_se <- NA_real_
  D_natural_mean <- D_treat_prevalence <- D_att_prevalence_elasticity <- rep(NA_real_, length(weights))
  policy_translation_table <- NULL
  natural_course_target_score <- natural_course_eif_mean_scaled <- NA_real_
  treatment_prevalence_eif_mean <- att_prevalence_elasticity_eif_mean <- NA_real_
  pct_primary_name <- tolower(cfg$final_tmle$percentage_primary %||% "prevention_gain")
  pct_primary_estimate <- pct_primary_se <- pct_primary_p <- NA_real_
  pct_primary_ci <- c(NA_real_, NA_real_)
  att_headline_method <- "CV-TMLE joint component targeting"
  att_headline_tag <- "CVTMLE_JOINT"
  att_wt_ctrl_max <- att_wt_ctrl_p99 <- att_wt_ctrl_ess <- att_ctrl_odds_ess <- NA_real_
  att_wt_ctrl_n <- att_wt_ctrl_n_observed <- att_wt_trt_n_observed <- NA_integer_
  att_wt_trt_max <- att_wt_trt_ess <- att_g_ctrl_max <- NA_real_
  att_tmle_nocens <- att_onestep_nocens <- NA_real_
  
  if (isTRUE(cfg$final_tmle$report_att %||% FALSE)) {
    den_att <- sum(w_norm * A)
    p_treat_w <- den_att / length(weights)
    if (!is.finite(den_att) || den_att <= 0 || !is.finite(p_treat_w) || p_treat_w <= 0)
      stop("ATT undefined: no positive survey-weighted treated mass.", call. = FALSE)
    
    att_fit <- target_here("att")
    att_plugin_estimate <- att_fit$plugin
    att_onestep_estimate <- att_fit$onestep
    D_att_onestep <- att_fit$D_onestep
    inf_onestep <- infer_primary_eif(D_att_onestep,att_onestep_estimate)
    att_onestep_se <- inf_onestep$se
    nc_fit <- target_here("att",r1=rep(1,n),r0=rep(1,n))
    att_onestep_nocens <- nc_fit$onestep
    eps_att_mu1 <- max(abs(att_fit$epsilon1)); eps_att_mu0 <- max(abs(att_fit$epsilon0))
    eps_att <- max(eps_att_mu1,eps_att_mu0)
    target_score_mu1 <- att_fit$score1; target_score_mu0 <- att_fit$score0
    Qstar1W_att_orig <- att_fit$M1; Qstar0W_att_orig <- att_fit$M0
    QstarAW_att_orig <- att_fit$MA
    mu1_att <- att_fit$mu1; mu0_att <- att_fit$mu0
    att_tmle_estimate <- att_fit$estimate
    att_summand_tmle <- att_fit$M1-att_fit$M0
    # Legacy residual field is stored on the scale expected by decomposition:
    # resid_obs/pi is the FULL sequential residual, including eligibility.
    resid_obs_tmle <- pi_AW*att_fit$residual
    att_resid_tmle <- (A-(1-A)*gn/(1-gn))*att_fit$residual
    D_mu1 <- att_fit$D1; D_mu0 <- att_fit$D0
    D_att_tmle <- D_mu1-D_mu0
    D_att_direct <- att_fit$D_direct
    D_att_identity_error <- max(abs(D_att_direct-D_att_tmle))
    if (!is.finite(D_att_identity_error)||D_att_identity_error>1e-8)
      stop("ATT direct/component influence identity failed.",call.=FALSE)
    
    inf_mu1 <- infer_primary_eif(D_mu1, mu1_att)
    inf_mu0 <- infer_primary_eif(D_mu0, mu0_att)
    inf_att <- infer_primary_eif(D_att_tmle, att_tmle_estimate)
    mu1_att_se <- inf_mu1$se; mu0_att_se <- inf_mu0$se
    att_tmle_se <- inf_att$se
    att_tmle_ci_lower <- inf_att$ci[1]; att_tmle_ci_upper <- inf_att$ci[2]
    att_tmle_p_value <- inf_att$p; att_tmle_G_star <- inf_att$Gstar
    cl_eic_att_tmle <- inf_att$cluster_eic
    J_att <- inf_att$J; fsc_att <- inf_att$fsc
    
    # Scale-free centering checks. The dollar mean is retained for audit, but
    # the production gate uses the outcome-range-scaled mean.
    att_tmle_eif_mean <- sum(w_norm * D_att_tmle) / length(weights)
    att_tmle_eif_mean_scaled <- att_tmle_eif_mean / y_range
    mu1_eif_mean_scaled <- (sum(w_norm * D_mu1) / length(weights)) / y_range
    mu0_eif_mean_scaled <- (sum(w_norm * D_mu0) / length(weights)) / y_range
    center_tol <- cfg$final_tmle$att_eif_center_tol_scaled %||% 1e-8
    if (any(!is.finite(c(att_tmle_eif_mean_scaled, mu1_eif_mean_scaled, mu0_eif_mean_scaled))) ||
        max(abs(c(att_tmle_eif_mean_scaled, mu1_eif_mean_scaled, mu0_eif_mean_scaled))) > center_tol) {
      stop(sprintf(paste0("Joint ATT targeting failed scale-free EIF centering: ATT=%.3e, ",
                          "mu1=%.3e, mu0=%.3e; tolerance %.3e."),
                   att_tmle_eif_mean_scaled, mu1_eif_mean_scaled,
                   mu0_eif_mean_scaled, center_tol), call. = FALSE)
    }
    
    if (isTRUE(cfg$policy$enable_policy_components %||% TRUE)) {
      policy_component_error <- NULL
      policy_component_ok <- tryCatch({
        # Target the natural-course population mean under the observed exposure
        # distribution and the same outcome-response model. This is required for a
        # formal ATT-based elasticity with respect to depression prevalence.
        nat_fit <- target_here("natural")
        natural_course_mean <- nat_fit$mean
        D_natural_mean <- nat_fit$D
        t_nat <- list(normalized_score=nat_fit$score)
        inf_natural_mean <- infer_primary_eif(D_natural_mean, natural_course_mean)
        natural_course_mean_se <- inf_natural_mean$se
        natural_course_target_score <- t_nat$normalized_score
        natural_course_eif_mean_scaled <-
          (sum(w_norm * D_natural_mean) / length(weights)) / y_range
        
        treatment_prevalence <- p_treat_w
        D_treat_prevalence <- A - treatment_prevalence
        inf_treat_prevalence <- infer_primary_eif(D_treat_prevalence, treatment_prevalence)
        treatment_prevalence_se <- inf_treat_prevalence$se
        treatment_prevalence_eif_mean <-
          sum(w_norm * D_treat_prevalence) / length(weights)
        if (any(!is.finite(c(natural_course_target_score,
                             natural_course_eif_mean_scaled,
                             treatment_prevalence_eif_mean))) ||
            max(abs(c(natural_course_target_score,
                      natural_course_eif_mean_scaled,
                      treatment_prevalence_eif_mean))) > center_tol) {
          msg_txt <- sprintf(
            paste0("Policy-component targeting/centering failed: natural score=%.3e, ",
                   "natural EIF/range=%.3e, prevalence EIF=%.3e; tolerance %.3e."),
            natural_course_target_score, natural_course_eif_mean_scaled,
            treatment_prevalence_eif_mean, center_tol)
          stop(msg_txt, call. = FALSE)
        }
        
        if (isTRUE(cfg$policy$enable_att_prevalence_translation %||% TRUE) &&
            isTRUE(report_ratio_translations)) {
          translation_ready <- is.finite(natural_course_mean) && natural_course_mean > 0
          if (!translation_ready) {
            msg_txt <- "ATT prevalence elasticity requires a positive natural-course mean."
            stop(msg_txt, call. = FALSE)
          }
          if (translation_ready) {
            att_prevalence_elasticity <-
              treatment_prevalence * att_tmle_estimate / natural_course_mean
            D_att_prevalence_elasticity <-
              (treatment_prevalence / natural_course_mean) * D_att_tmle +
              (att_tmle_estimate / natural_course_mean) * D_treat_prevalence -
              (treatment_prevalence * att_tmle_estimate / natural_course_mean^2) * D_natural_mean
            inf_elasticity <- infer_primary_eif(
              D_att_prevalence_elasticity, att_prevalence_elasticity)
            att_prevalence_elasticity_se <- inf_elasticity$se
            att_prevalence_elasticity_ci <- inf_elasticity$ci
            att_prevalence_elasticity_p <- inf_elasticity$p
            att_prevalence_elasticity_eif_mean <-
              sum(w_norm * D_att_prevalence_elasticity) / length(weights)
            if (!is.finite(att_prevalence_elasticity_eif_mean) ||
                abs(att_prevalence_elasticity_eif_mean) > center_tol)
            {
              msg_txt <- sprintf(
                "ATT-based prevalence elasticity EIF failed centering (%.3e > %.3e).",
                att_prevalence_elasticity_eif_mean, center_tol)
              stop(msg_txt, call. = FALSE)
            }
            
            gain_per_prevented_case <- -att_tmle_estimate
            gain_per_prevented_case_se <- att_tmle_se
            D_gain_one_pp <- -0.01 * D_att_tmle
            gain_per_one_percentage_point <- -0.01 * att_tmle_estimate
            inf_gain_one_pp <- infer_primary_eif(
              D_gain_one_pp, gain_per_one_percentage_point)
            gain_per_one_percentage_point_se <- inf_gain_one_pp$se
            
            reductions <- sort(unique(as.numeric(
              cfg$policy$relative_prevalence_reductions %||% c(0.10, 0.25, 0.50))))
            policy_translation_table <- do.call(rbind, lapply(reductions, function(r) {
              gain <- -r * treatment_prevalence * att_tmle_estimate
              D_gain <- -r * (treatment_prevalence * D_att_tmle +
                                att_tmle_estimate * D_treat_prevalence)
              inf_gain <- infer_primary_eif(D_gain, gain)
              rel_gain <- gain / natural_course_mean
              D_rel_gain <- D_gain / natural_course_mean -
                gain * D_natural_mean / natural_course_mean^2
              inf_rel_gain <- infer_primary_eif(D_rel_gain, rel_gain)
              data.frame(
                relative_prevalence_reduction = r,
                baseline_depression_prevalence = treatment_prevalence,
                post_policy_depression_prevalence = treatment_prevalence * (1 - r),
                implied_population_mean_outcome_gain = gain,
                implied_population_mean_earnings_gain =
                  if (identical(cfg$outcome$family, "Compensation")) gain else NA_real_,
                gain_se = inf_gain$se,
                gain_ci_lower = inf_gain$ci[1L],
                gain_ci_upper = inf_gain$ci[2L],
                relative_population_outcome_gain = rel_gain,
                relative_population_earnings_gain =
                  if (identical(cfg$outcome$family, "Compensation")) rel_gain else NA_real_,
                relative_gain_se = inf_rel_gain$se,
                relative_gain_ci_lower = inf_rel_gain$ci[1L],
                relative_gain_ci_upper = inf_rel_gain$ci[2L],
                outcome_scale = cfg$policy$outcome_scale_label %||%
                  "configured bounded/capped outcome",
                outcome_transform = policy_outcome_transform,
                cap_quantile = if (identical(cfg$outcome$family, "Compensation"))
                  cfg$outcome$continuous_upper_quantile else NA_real_,
                assumption = paste0(
                  "Prevented cases have the current treated-population ATT; ",
                  "the translation applies to the configured bounded/capped outcome."),
                stringsAsFactors = FALSE)
            }))
            if (isTRUE(cfg$global$save_stage_csvs))
              write_run_csv(policy_translation_table, cfg,
                            cfg$policy$output_csv %||% "att_policy_translation.csv")
          }
        }
        TRUE
      }, error = function(e) {
        policy_component_error <<- conditionMessage(e)
        FALSE
      })
      if (!isTRUE(policy_component_ok)) {
        natural_course_mean <- natural_course_mean_se <- NA_real_
        treatment_prevalence <- treatment_prevalence_se <- NA_real_
        att_prevalence_elasticity <- att_prevalence_elasticity_se <- NA_real_
        att_prevalence_elasticity_ci <- c(NA_real_, NA_real_)
        att_prevalence_elasticity_p <- NA_real_
        gain_per_prevented_case <- gain_per_prevented_case_se <- NA_real_
        gain_per_one_percentage_point <- gain_per_one_percentage_point_se <- NA_real_
        D_natural_mean <- D_treat_prevalence <- D_att_prevalence_elasticity <-
          rep(NA_real_, length(weights))
        policy_translation_table <- NULL
        natural_course_target_score <- natural_course_eif_mean_scaled <- NA_real_
        treatment_prevalence_eif_mean <- att_prevalence_elasticity_eif_mean <- NA_real_
        msg_txt <- paste0(
          "Optional policy-component analysis failed and produced no policy outputs: ",
          policy_component_error)
        if (isTRUE(cfg$policy$fail_on_policy_component_checks %||% TRUE))
          stop(msg_txt, call. = FALSE) else warning(msg_txt, call. = FALSE)
      }
    }
    
    # Ratio translations with their own delta-method EIFs and the same
    # REGION-stratified PSU design inference used for the ATT. These are enabled
    # for every verified outcome on an identity scale with positive targeted
    # component means. Raw annual Compensation, binary probabilities, and
    # unconditional weekly hours all meet that scale requirement.
    if (isTRUE(report_ratio_translations)) {
      if (!is.finite(mu1_att) || !is.finite(mu0_att) || mu1_att <= 0 || mu0_att <= 0)
        stop("Ratio translation is undefined because a targeted ATT component mean is non-positive.", call. = FALSE)
      pct_depression_effect <- 100 * (mu1_att - mu0_att) / mu0_att
      pct_prevention_gain <- 100 * (mu0_att - mu1_att) / mu1_att
      D_pct_depression <- 100 * (D_mu1 / mu0_att - mu1_att * D_mu0 / mu0_att^2)
      D_pct_prevention <- 100 * (D_mu0 / mu1_att - mu0_att * D_mu1 / mu1_att^2)
      inf_pct_dep <- infer_primary_eif(D_pct_depression, pct_depression_effect)
      inf_pct_prev <- infer_primary_eif(D_pct_prevention, pct_prevention_gain)
      pct_depression_se <- inf_pct_dep$se; pct_depression_ci <- inf_pct_dep$ci; pct_depression_p <- inf_pct_dep$p
      pct_prevention_se <- inf_pct_prev$se; pct_prevention_ci <- inf_pct_prev$ci; pct_prevention_p <- inf_pct_prev$p
      if (identical(pct_primary_name, "depression_effect")) {
        pct_primary_estimate <- pct_depression_effect; pct_primary_se <- pct_depression_se
        pct_primary_ci <- pct_depression_ci; pct_primary_p <- pct_depression_p
      } else {
        pct_primary_name <- "prevention_gain"
        pct_primary_estimate <- pct_prevention_gain; pct_primary_se <- pct_prevention_se
        pct_primary_ci <- pct_prevention_ci; pct_primary_p <- pct_prevention_p
      }
    } else {
      pct_primary_name <- NA_character_
    }
    
    # Explicit retargeting with eligible response probability set to one.
    att_tmle_nocens <- nc_fit$estimate
    att_tmle_cf_under_control <- mu0_att
    
    # Canonical headline routing is fixed to joint-component CV-TMLE. The
    # one-step remains an explicitly labeled diagnostic comparator only.
    att_estimator_choice <- tolower(cfg$final_tmle$att_estimator %||% "tmle")
    if (!identical(att_estimator_choice, "tmle"))
      stop("Internal configuration error: ATT headline estimator must be 'tmle'.", call. = FALSE)
    att_estimate <- att_tmle_estimate; att_se <- att_tmle_se
    D_att <- D_att_tmle; cl_eic_att <- cl_eic_att_tmle
    att_eif_mean <- att_tmle_eif_mean; att_eif_mean_scaled <- att_tmle_eif_mean_scaled
    att_summand <- att_summand_tmle; att_resid <- att_resid_tmle; resid_obs <- resid_obs_tmle
    att_nocens_check <- att_tmle_nocens
    cf_treated_under_control <- mu0_att
    att_support_ok <- mu0_att >= y_lower - 1e-8 && mu0_att <= y_upper + 1e-8
    att_tmle_se_centered <- infer_primary_eif(
      D_att_tmle - att_tmle_eif_mean, att_tmle_estimate)$se
    att_se_centered <- att_tmle_se_centered
    
    ctrl_rows <- which(A == 0L); trt_rows <- which(A == 1L)
    ctrl_obs <- ctrl_rows[delta_response[ctrl_rows] == 1L]
    trt_obs <- trt_rows[delta_response[trt_rows] == 1L]
    att_ctrl_odds <- gn / (1 - gn)
    # Residual-weight summaries use only outcome-observed rows. These are
    # dispersion diagnostics, not information-equivalent ESSs for the full EIF.
    att_ctrl_wt <- weights[ctrl_obs] * att_ctrl_odds[ctrl_obs] / pi_AW[ctrl_obs]
    att_trt_wt <- weights[trt_obs] / pi_AW[trt_obs]
    att_wt_ctrl_max <- if (length(ctrl_obs)) max(att_ctrl_wt) else NA_real_
    att_wt_ctrl_p99 <- if (length(ctrl_obs)) as.numeric(stats::quantile(att_ctrl_wt, 0.99, names = FALSE, type = 8)) else NA_real_
    att_wt_ctrl_ess <- if (length(ctrl_obs)) kish_ess_safe(att_ctrl_wt) else NA_real_
    att_wt_ctrl_n <- length(ctrl_rows)
    att_wt_ctrl_n_observed <- length(ctrl_obs)
    att_wt_trt_n_observed <- length(trt_obs)
    att_wt_trt_max <- if (length(trt_obs)) max(att_trt_wt) else NA_real_
    att_wt_trt_ess <- if (length(trt_obs)) kish_ess_safe(att_trt_wt) else NA_real_
    att_g_ctrl_max <- if (length(ctrl_rows)) max(gn[ctrl_rows]) else NA_real_
    att_ctrl_odds_ess <- if (length(ctrl_rows)) kish_ess_safe(weights[ctrl_rows] * att_ctrl_odds[ctrl_rows]) else NA_real_
    
    if (isTRUE(is_raw_dollar_outcome)) {
      msg(sprintf("    ATT joint CV-TMLE: mu1=$%.2f, mu0=$%.2f, dollar ATT=$%.2f (SE $%.2f).",
                  mu1_att, mu0_att, att_tmle_estimate, att_tmle_se), cfg = cfg)
    } else {
      msg(sprintf("    ATT joint CV-TMLE: mu1=%.4f, mu0=%.4f, ATT=%.4f (SE %.4f) on the configured outcome scale.",
                  mu1_att, mu0_att, att_tmle_estimate, att_tmle_se), cfg = cfg)
    }
    if (isTRUE(report_ratio_translations)) {
      msg(sprintf("      Depression effect = %.2f%% [%.2f, %.2f]; prevention gain = %.2f%% [%.2f, %.2f].",
                  pct_depression_effect, pct_depression_ci[1], pct_depression_ci[2],
                  pct_prevention_gain, pct_prevention_ci[1], pct_prevention_ci[2]), cfg = cfg)
    }
    msg(sprintf("      Target scores: mu1 %.3e, mu0 %.3e; scaled EIF mean %.3e (tol %.1e).",
                target_score_mu1, target_score_mu0, att_eif_mean_scaled, center_tol), cfg = cfg)
    
    att_components <- list(
      psi_att = att_estimate, att_se = att_se, att_se_centered = att_se_centered,
      p_treat_w = p_treat_w, D_att = D_att, D_mu1 = D_mu1, D_mu0 = D_mu0,
      D_pct_depression = D_pct_depression, D_pct_prevention = D_pct_prevention,
      D_natural_mean = D_natural_mean, D_treat_prevalence = D_treat_prevalence,
      D_att_prevalence_elasticity = D_att_prevalence_elasticity,
      natural_course_mean = natural_course_mean,
      natural_course_target_score = natural_course_target_score,
      natural_course_eif_mean_scaled = natural_course_eif_mean_scaled,
      treatment_prevalence = treatment_prevalence,
      treatment_prevalence_eif_mean = treatment_prevalence_eif_mean,
      att_prevalence_elasticity = att_prevalence_elasticity,
      att_prevalence_elasticity_eif_mean = att_prevalence_elasticity_eif_mean,
      policy_translation_table = policy_translation_table,
      mu1_att = mu1_att, mu0_att = mu0_att,
      pct_depression_effect = pct_depression_effect,
      pct_prevention_gain = pct_prevention_gain,
      att_summand = att_summand, att_resid = att_resid, resid_obs = resid_obs,
      cl_eic_att = cl_eic_att, J_att = J_att, fsc_att = fsc_att,
      inference_method = inf_att$method, inference_df = inf_att$df,
      inference_design_n = inf_att$design_n, inference_domain_n = inf_att$domain_n,
      inference_design_psu_n = inf_att$design_psu_n,
      inference_design_strata_n = inf_att$design_strata_n,
      inference_ci = inf_att$ci, inference_p = inf_att$p,
      se_psu_only_sensitivity = inf_att$se_cluster_only,
      ci_psu_only_sensitivity = inf_att$ci_cluster_only,
      p_psu_only_sensitivity = inf_att$p_cluster_only,
      Gstar_diagnostic = inf_att$Gstar,
      eif_mean = att_eif_mean, eif_mean_scaled = att_eif_mean_scaled,
      center_tol_scaled = center_tol, nocens = att_nocens_check,
      target_score_mu1 = target_score_mu1, target_score_mu0 = target_score_mu0,
      eps_mu1 = eps_att_mu1, eps_mu0 = eps_att_mu0,
      att_tmle_estimate = att_tmle_estimate, att_tmle_se = att_tmle_se,
      cl_eic_att_tmle = cl_eic_att_tmle, att_tmle_eif_mean = att_tmle_eif_mean,
      att_tmle_cf_under_control = att_tmle_cf_under_control,
      att_onestep_estimate = att_onestep_estimate, att_onestep_se = att_onestep_se,
      eps_att = eps_att, att_headline_method = att_headline_method,
      cf_treated_under_control = cf_treated_under_control,
      support_ok = att_support_ok, y_lower = y_lower, y_upper = y_upper,
      A = A, Y_raw = Y_raw, Y_bounded_orig = Y_bounded_orig,
      hours_uncapped = main_df$.hours_uncapped,
      delta_Y = delta_Y, cluster = cluster, strata = strata, weights = weights, w_norm = w_norm,
      outer_fold = outer_fold, gn = gn, pi_AW = pi_AW, pi_1W = pi_1W, pi_0W = pi_0W,
      gn_raw = gn_raw, pi_AW_raw = pi_AW_raw, pi_1W_raw = pi_1W_raw, pi_0W_raw = pi_0W_raw,
      pi_AW_alt_raw = pi_AW_alt_raw, pi_1W_alt_raw = pi_1W_alt_raw,
      pi_0W_alt_raw = pi_0W_alt_raw, pi_alt_status = pi_alt_status,
      eligibility=eligibility,S1W=S1W,S0W=S0W,
      Qeligible1W_targeted_orig=att_fit$Q1*y_range+y_lower,
      Qeligible0W_targeted_orig=att_fit$Q0*y_range+y_lower,
      sequential_residual=att_fit$residual,
      cap_inference=cap_inference,cap_tail_means=att_fit$tail_means,
      structural_zero = structural_zero,
      structural_zero_source = structural_zero_source,
      g_calibration_audit = g_calibration_audit,
      gn_uncalibrated = gn_uncalibrated, pi_AW_uncalibrated = pi_AW_uncalibrated,
      Qbar0W_initial_orig = Qbar0W * (y_upper - y_lower) + y_lower,
      Qbar1W_orig = Qstar1W_att_orig, Qbar0W_orig = Qstar0W_att_orig,
      QbarAW_orig = QstarAW_att_orig)
  }
  
  # A secondary target conditional on the fitted support rule. Its rule is
  # held fixed for inference; it is not an independently specified population.
  trim_estimate <- trim_se <- n_trim <- NA_real_
  trim_ci <- c(NA_real_,NA_real_); trim_statistic <- trim_p <- trim_eps <- NA_real_
  inf_trim <- NULL; D_t <- rep(NA_real_,n)
  if (isTRUE(cfg$final_tmle$trim_enable)) {
    keep_t <- gn >= cfg$final_tmle$trim_g_lower & gn <= cfg$final_tmle$trim_g_upper
    n_trim <- sum(keep_t)
    if (n_trim>0L) {
      trimmed_fit <- target_here("ate",domain=keep_t)
      trim_estimate <- trimmed_fit$estimate; D_t <- trimmed_fit$D
      inf_trim <- infer_primary_eif(D_t,trim_estimate)
      trim_se <- inf_trim$se; trim_ci <- inf_trim$ci
      trim_statistic <- inf_trim$statistic; trim_p <- inf_trim$p
      trim_eps <- max(abs(c(trimmed_fit$epsilon1,trimmed_fit$epsilon0)))
    }
  }
  D <- ate_fit$D; D_orig <- D; D_w <- w_norm*D
  
  inf_ate <- infer_primary_eif(D, psi_hat)
  cluster_eic <- inf_ate$cluster_eic
  J <- inf_ate$J; fsc <- inf_ate$fsc
  se_hat <- inf_ate$se; ci <- inf_ate$ci
  z <- inf_ate$statistic; p_val <- inf_ate$p
  msg(sprintf("    Design-aware SE (%s; df=%.1f) = %.4f; PSU-only sensitivity SE = %.4f.",
              inf_ate$method, inf_ate$df, se_hat, inf_ate$se_cluster_only), cfg = cfg)
  
  # select which estimand is the HEADLINE. The full-sample ATE values
  # (psi_hat, se_hat, ci, z, p_val) are always retained as ate_tmle/se_full
  # etc. in the result row; this block only chooses what estimate/se/ci/p
  # point to. Default "ate" => no change. "trimmed"/"att" change the ESTIMAND.
  primary <- cfg$final_tmle$primary_estimand %||% "ate"
  ate_full_estimate <- psi_hat; ate_full_se <- se_hat
  ate_full_ci <- ci; ate_full_z <- z; ate_full_p <- p_val
  base_label <- if (outcome_type == "continuous") {
    if (identical(cfg$outcome$family, "HoursWorked"))
      sprintf("bounded_%s_fixed_%g", cfg$analysis$outcome_var,
              cfg$outcome$families$HoursWorked$cap_hours)
    else sprintf("bounded_%s_q%.3f", cfg$analysis$outcome_var,
                 cfg$outcome$continuous_upper_quantile)
  } else "binary"
  if (identical(primary, "trimmed")) {
    if (!is.finite(trim_estimate) || !is.finite(trim_se) || trim_se <= 0)
      stop("primary_estimand='trimmed' but the trimmed ATE is not available (trim_enable must be TRUE and yield a finite estimate).", call. = FALSE)
    head_est <- trim_estimate; head_se <- trim_se
    head_ci <- trim_ci; head_z <- trim_statistic; head_p <- trim_p
    estimand_label <- sprintf("TRIMMED_ATE_%s_g[%.2f,%.2f]", base_label,
                              cfg$final_tmle$trim_g_lower %||% 0.05,
                              cfg$final_tmle$trim_g_upper %||% 0.95)
    msg(sprintf("  [TMLE] PRIMARY ESTIMAND = overlap-trimmed ATE (%.4f, SE %.4f). Full-sample ATE retained as secondary (%.4f).",
                head_est, head_se, ate_full_estimate), cfg = cfg)
  } else if (identical(primary, "att")) {
    if (!is.finite(att_estimate) || !is.finite(att_se) || att_se <= 0)
      stop("primary_estimand='att' but the ATT is not available (report_att must be TRUE and yield a finite estimate).", call. = FALSE)
    # The ATT SE is the REGION-stratified, PSUSCID-clustered survey-design
    # EIF SE. Refuse to headline it
    # if the EIF centering self-check failed, since that indicates the
    # influence function was miscomputed and the SE would be invalid.
    center_tol <- cfg$final_tmle$att_eif_center_tol_scaled %||% 1e-8
    if (!is.finite(att_eif_mean_scaled) || abs(att_eif_mean_scaled) > center_tol) {
      stop(sprintf("primary_estimand='att' but the scale-free ATT EIF centering check failed (%.3e > %.3e).",
                   att_eif_mean_scaled, center_tol), call. = FALSE)
    }
    head_est <- att_estimate; head_se <- att_se
    head_z <- inf_att$statistic
    head_ci <- inf_att$ci
    head_p <- inf_att$p
    att_Gstar_h <- inf_att$Gstar
    att_dfeff_h <- inf_att$df
    estimand_label <- sprintf("ATT_%s_%s", att_headline_tag, base_label)
    if (isTRUE(is_raw_dollar_outcome)) {
      msg(sprintf("  [TMLE] PRIMARY DOLLAR ESTIMAND = ATT via %s ($%.2f, design-aware EIF SE $%.2f, t reference df=%.1f). Policy-facing primary percentage (%s) = %.2f%% [%.2f, %.2f].",
                  att_headline_method, head_est, head_se, att_dfeff_h,
                  pct_primary_name, pct_primary_estimate, pct_primary_ci[1], pct_primary_ci[2]), cfg = cfg)
    } else {
      msg(sprintf("  [TMLE] PRIMARY ESTIMAND = ATT via %s (%.4f, design-aware EIF SE %.4f, t reference df=%.1f) on the configured outcome scale.",
                  att_headline_method, head_est, head_se, att_dfeff_h), cfg = cfg)
    }
  } else {
    if (!identical(primary, "ate"))
      warning(sprintf("Unknown primary_estimand '%s'; defaulting to full-sample ATE.", primary))
    head_est <- ate_full_estimate; head_se <- ate_full_se
    head_ci  <- ate_full_ci; head_z <- ate_full_z; head_p <- ate_full_p
    estimand_label <- if (outcome_type == "continuous")
      sprintf("ATE_%s", base_label) else "ATE_binary"
  }
  
  # Nested rough-selection audit log
  sel_log_df <- if (length(nested_selection_log) > 0L) do.call(rbind, nested_selection_log) else NULL
  if (!is.null(sel_log_df) && isTRUE(cfg$global$save_stage_csvs)) {
    p_sel <- write_run_csv(sel_log_df, cfg, cfg$final_tmle$nested_rough_selection_log_csv)
    msg(sprintf("  [TMLE] Nested rough-selection log written: %s", basename(p_sel)), cfg = cfg)
  }
  
  # cluster-assignment diagnostic. Lets a reviewer verify the pre-score
  # correlation clustering did NOT over-collapse meaningful confounders (e.g. the
  # baseline mental-health H1FS block): each row is one member variable with its
  # cluster id, representative, cluster size, correlation to the representative,
  # and whether the cluster/representative was ultimately selected. Multi-member
  # clusters containing distinct substantive variables would be the warning sign.
  clu_log_df <- if (length(cluster_assignment_log) > 0L) do.call(rbind, cluster_assignment_log) else NULL
  if (!is.null(clu_log_df) && isTRUE(cfg$global$save_stage_csvs)) {
    p_clu <- write_run_csv(clu_log_df, cfg,
                           cfg$final_tmle$cluster_assignment_log_csv %||% "cluster_assignments.csv")
    msg(sprintf("  [TMLE] Cluster-assignment diagnostic written: %s (%d member rows, %d multi-member clusters).",
                basename(p_clu), nrow(clu_log_df),
                length(unique(clu_log_df$cluster_id[clu_log_df$cluster_size > 1L]))), cfg = cfg)
  }
  
  # Per-fold SL log
  sl_log_df <- do.call(rbind, per_fold_log)
  if (isTRUE(cfg$global$save_stage_csvs)) {
    p <- write_run_csv(sl_log_df, cfg, cfg$final_tmle$per_fold_sl_log_csv)
    msg(sprintf("  [TMLE] Per-fold SL log written: %s", basename(p)), cfg = cfg)
    if (length(fold_support_log) > 0L) {
      fs <- do.call(rbind, fold_support_log)
      p_fs <- write_run_csv(fs, cfg, cfg$final_tmle$fold_support_log_csv %||% "fold_support_log.csv")
      msg(sprintf("  [TMLE] Fold support log written: %s", basename(p_fs)), cfg = cfg)
    }
    if (length(internal_fold_support_log) > 0L) {
      ifs <- do.call(rbind, internal_fold_support_log)
      p_ifs <- write_run_csv(ifs, cfg, cfg$final_tmle$internal_fold_support_log_csv %||% "internal_fold_support_log.csv")
      msg(sprintf("  [TMLE] Internal fold support log written: %s", basename(p_ifs)), cfg = cfg)
    }
  }
  
  # Overlap diagnostics
  overlap_df <- data.frame(
    gn = gn, pi_AW = pi_AW,
    g_times_pi1 = gn * pi_1W,
    one_minus_g_times_pi0 = (1 - gn) * pi_0W,
    A = A, delta_Y = delta_Y)
  if (isTRUE(cfg$global$save_stage_csvs)) {
    p <- write_run_csv(overlap_df, cfg, cfg$final_tmle$overlap_diagnostics_csv)
    msg(sprintf("  [TMLE] Overlap diagnostics written: %s", basename(p)), cfg = cfg)
  }
  
  # Save the influence curve for the declared primary estimand. ATE influence
  # objects remain available under explicitly named secondary fields.
  primary_D <- if (identical(primary, "att")) D_att else if (identical(primary, "trimmed")) D_t else D
  primary_cluster_eic <- if (identical(primary, "att")) cl_eic_att else if (identical(primary, "trimmed")) inf_trim$cluster_eic else cluster_eic
  primary_inf <- if (identical(primary, "att")) inf_att else if (identical(primary, "trimmed")) inf_trim else inf_ate
  eic_path <- build_unique_path(cfg, cfg$final_tmle$cluster_eic_rds)
  atomic_save_rds(primary_cluster_eic, eic_path, overwrite = TRUE)
  msg(sprintf("  [TMLE] Cluster-level EIC saved: %s", basename(eic_path)), cfg = cfg)
  
  # Aggregate fold-specific design dimensions for transparent reporting.
  manifest_df_for_result <- if (length(run_manifest_rows)) do.call(rbind, run_manifest_rows) else NULL
  design_min <- function(nm) if (!is.null(manifest_df_for_result) && nm %in% names(manifest_df_for_result))
    min(manifest_df_for_result[[nm]], na.rm = TRUE) else NA_real_
  design_max <- function(nm) if (!is.null(manifest_df_for_result) && nm %in% names(manifest_df_for_result))
    max(manifest_df_for_result[[nm]], na.rm = TRUE) else NA_real_
  
  # Main results row
  res_df <- data.frame(
    run_id = cfg$global$run_id %||% NA_character_,
    pipeline_version = cfg$global$version %||% NA_character_,
    outcome_family = cfg$outcome$family,
    outcome_wave = as.integer(cfg$outcome$current_wave),
    outcome_family_member = cfg$outcome$family_member %||% NA_character_,
    outcome_primary = if (!is.null(cfg$outcome$family_member) &&
                          !is.null(family_cfg_current$members[[cfg$outcome$family_member]]))
      isTRUE(family_cfg_current$members[[cfg$outcome$family_member]]$primary) else TRUE,
    script_md5 = get_frozen_source_fingerprint(cfg)$md5,
    analysis_spec_md5 = get_frozen_config_hash(cfg, "analysis"),
    resolved_run_config_md5 = get_frozen_config_hash(cfg, "resolved"),
    R_version = cfg$provenance$runtime$R_version,
    runtime_platform = cfg$provenance$runtime$platform,
    package_versions = cfg$provenance$runtime$packages,
    q_clip_overall_fraction = q_clip_overall_fraction,
    q_clip_max_fold_fraction = q_clip_max_fold_fraction,
    q_clip_review_required = q_clip_review_required,
    estimand = estimand_label,
    estimate = head_est, se = head_se,
    ci_lower = head_ci[1], ci_upper = head_ci[2],
    test_statistic = head_z,
    reference_distribution = "t",
    z_legacy = head_z,
    p_value = head_p,
    primary_estimand = primary,
    inference_method = primary_inf$method,
    inference_df = primary_inf$df,
    inference_design_n = primary_inf$design_n,
    inference_domain_n = primary_inf$domain_n,
    inference_design_psu_n = primary_inf$design_psu_n,
    inference_design_strata_n = primary_inf$design_strata_n,
    primary_se_psu_only_sensitivity = primary_inf$se_cluster_only,
    primary_ci_lower_psu_only_sensitivity = primary_inf$ci_cluster_only[1],
    primary_ci_upper_psu_only_sensitivity = primary_inf$ci_cluster_only[2],
    cap_probability = if (identical(outcome_type, "continuous") &&
                          !identical(data_pack$cap_rule, "fixed"))
      cfg$outcome$continuous_upper_quantile else NA_real_,
    cap_value = data_pack$cap_value,
    cap_weighted = data_pack$cap_weighted,
    cap_weight_variable = if (identical(outcome_type, "continuous") && data_pack$cap_weighted)
      cfg$analysis$weight_var else NA_character_,
    cap_censoring_adjusted = if (identical(outcome_type, "continuous")) FALSE else NA,
    cap_quantile_rule = data_pack$cap_qrule,
    cap_population = if (identical(outcome_type, "continuous"))
      if (identical(data_pack$cap_rule, "fixed")) "fixed verified outcome support" else
        "pooled outcome-observed analytic sample" else NA_character_,
    cap_inference_interpretation = if (identical(outcome_type, "continuous"))
      if (identical(data_pack$cap_rule, "fixed")) "fixed_predefined_support" else
        if (identical(cap_inference$method,"fixed_or_uncapped")) "uncapped_outcome" else
          "estimated_observed_population_percentile_influence_included" else NA_character_,
    compensation_transform = if (identical(cfg$outcome$family, "Compensation"))
      compensation_transform else NA_character_,
    compensation_exact_only = if (identical(cfg$outcome$family, "Compensation"))
      isTRUE(cfg$outcome$compensation_exact_only) else NA,
    ate_tmle = ate_full_estimate,
    ate_se_full = ate_full_se,
    ate_ci_lower_full = ate_full_ci[1], ate_ci_upper_full = ate_full_ci[2],
    ate_p_full = ate_full_p,
    ate_plugin_initial = psi_plugin_initial,
    ate_aipw_initial = psi_aipw_initial,
    tmle_minus_plugin_initial = ate_full_estimate - psi_plugin_initial,
    tmle_minus_aipw_initial = ate_full_estimate - psi_aipw_initial,
    att_estimate = att_estimate, att_se = att_se,
    att_percentage_points = if (identical(outcome_type, "binary")) 100 * att_estimate else NA_real_,
    att_percentage_points_se = if (identical(outcome_type, "binary")) 100 * att_se else NA_real_,
    att_percentage_points_ci_lower = if (identical(outcome_type, "binary")) 100 * att_tmle_ci_lower else NA_real_,
    att_percentage_points_ci_upper = if (identical(outcome_type, "binary")) 100 * att_tmle_ci_upper else NA_real_,
    att_percentage_points_p = if (identical(outcome_type, "binary")) att_tmle_p_value else NA_real_,
    att_headline_method = att_headline_method,
    att_mu1 = mu1_att,
    att_mu0 = mu0_att,
    # Legacy Compensation-specific aliases retained only for Compensation.
    att_mu1_earnings_depressed = if (identical(cfg$outcome$family, "Compensation")) mu1_att else NA_real_,
    att_mu0_earnings_no_depression = if (identical(cfg$outcome$family, "Compensation")) mu0_att else NA_real_,
    att_mu1_se = mu1_att_se, att_mu0_se = mu0_att_se,
    pct_depression_effect = pct_depression_effect,
    pct_depression_effect_se = pct_depression_se,
    pct_depression_effect_ci_lower = pct_depression_ci[1],
    pct_depression_effect_ci_upper = pct_depression_ci[2],
    pct_depression_effect_p = pct_depression_p,
    pct_prevention_gain = pct_prevention_gain,
    pct_prevention_gain_se = pct_prevention_se,
    pct_prevention_gain_ci_lower = pct_prevention_ci[1],
    pct_prevention_gain_ci_upper = pct_prevention_ci[2],
    pct_prevention_gain_p = pct_prevention_p,
    policy_primary_percentage = pct_primary_name,
    policy_primary_pct_estimate = pct_primary_estimate,
    policy_primary_pct_se = pct_primary_se,
    policy_primary_pct_ci_lower = pct_primary_ci[1],
    policy_primary_pct_ci_upper = pct_primary_ci[2],
    policy_primary_pct_p = pct_primary_p,
    policy_components_enabled = isTRUE(cfg$policy$enable_policy_components %||% TRUE),
    policy_translation_enabled = isTRUE(
      cfg$policy$enable_att_prevalence_translation %||% TRUE) &&
      isTRUE(report_ratio_translations),
    mortality_sensitivity_enabled = mortality_enabled_for_wave(cfg, cfg$outcome$current_wave),
    mortality_composite_zero_at_death = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
      isTRUE(resolve_mortality_spec(cfg, cfg$outcome$current_wave)$composite_zero_at_death) else FALSE,
    mortality_source_variable = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
      resolve_mortality_spec(cfg, cfg$outcome$current_wave)$source_var else NA_character_,
    mortality_source_month_variable = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
      resolve_mortality_spec(cfg, cfg$outcome$current_wave)$source_month_var else NA_character_,
    mortality_timing_mode = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
      resolve_mortality_spec(cfg, cfg$outcome$current_wave)$timing_mode else NA_character_,
    mortality_timing_rule = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
      mortality_timing_rule_text(resolve_mortality_spec(cfg, cfg$outcome$current_wave)) else NA_character_,
    mortality_death_year_start = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
      resolve_mortality_spec(cfg, cfg$outcome$current_wave)$death_year_start else NA_integer_,
    mortality_death_year_end = if (mortality_enabled_for_wave(cfg, cfg$outcome$current_wave))
      resolve_mortality_spec(cfg, cfg$outcome$current_wave)$death_year_end else NA_integer_,
    bounded_natural_course_population_mean = natural_course_mean,
    bounded_natural_course_population_mean_se = natural_course_mean_se,
    natural_course_population_mean = natural_course_mean,
    natural_course_population_mean_se = natural_course_mean_se,
