    masks <- missing_masks_from_rule(values, rule)
    if (!identical(which(masks$general), as.integer(general)) ||
        !identical(which(masks$skip), as.integer(skip)))
      stop("Preflight FAILED: exact codebook rule for ", nm, call. = FALSE)
  }
