    cfg_h_nomort <- cfg_template
    cfg_h_nomort$outcome$family <- "HoursWorked"
    cfg_h_nomort$outcome$waves <- 4L
    h_nomort_sc <- filter_sensitivity_scenarios_for_outcome(
